package io.github.libtmux.junit5;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.jspecify.annotations.Nullable;

/** A command's flags and the words after them, read as tmux's argument parser reads them. */
record Flags(Map<String, String> values, Set<String> switches, List<String> positional) {

    /**
     * The flags that take a value, per command, since tmux decides that per command: {@code -f}
     * is a value to {@code new-session} and a switch to {@code split-window}, and {@code -b} names
     * a buffer to one and puts a pane before another.
     */
    private static final Map<String, Set<String>> VALUED = Map.ofEntries(
            Map.entry("new-session", Set.of("-t", "-s", "-n", "-c", "-x", "-y", "-F", "-e", "-f")),
            Map.entry("new-window", Set.of("-t", "-n", "-c", "-F", "-e")),
            Map.entry("split-window", Set.of("-t", "-l", "-c", "-F", "-e", "-s", "-S", "-R", "-m")),
            Map.entry("capture-pane", Set.of("-t", "-S", "-E", "-b")),
            Map.entry("select-pane", Set.of("-t", "-T")),
            Map.entry("if-shell", Set.of("-t")),
            Map.entry("set-environment", Set.of("-t")),
            Map.entry("show-environment", Set.of("-t")),
            Map.entry("list-sessions", Set.of("-F", "-f")),
            Map.entry("list-windows", Set.of("-t", "-F", "-f")),
            Map.entry("list-panes", Set.of("-t", "-F", "-f")));

    private static final Set<String> DEFAULT_VALUED = Set.of("-t", "-F", "-b", "-c");

    static Flags parse(List<String> argv) {
        Set<String> valued = VALUED.getOrDefault(argv.getFirst(), DEFAULT_VALUED);
        Map<String, String> values = new HashMap<>();
        java.util.Set<String> switches = new java.util.HashSet<>();
        int index = 1;
        while (index < argv.size()) {
            String word = argv.get(index);
            if (word.equals("--")) {
                index++;
                break;
            }
            if (!word.startsWith("-") || word.length() < 2) {
                break;
            }
            if (valued.contains(word) && index + 1 < argv.size()) {
                values.put(word, argv.get(index + 1));
                index += 2;
            } else {
                for (char flag : word.substring(1).toCharArray()) {
                    switches.add("-" + flag);
                }
                index++;
            }
        }
        return new Flags(values, switches, List.copyOf(argv.subList(index, argv.size())));
    }

    boolean has(String flag) {
        return switches.contains(flag) || values.containsKey(flag);
    }

    @Nullable
    String value(String flag) {
        return values.get(flag);
    }
}

package io.github.libtmux.junit5;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.function.Function;
import org.jspecify.annotations.Nullable;

/**
 * The part of tmux's format language the library sends: variables, comparisons, {@code &&} and
 * {@code ||}, {@code ?} conditionals, and the {@code W:} and {@code P:} loops.
 */
final class Formats {

    private Formats() {}

    /** What a format is expanded against: a row's variables, and the rows a loop visits. */
    interface Scope {
        @Nullable
        String get(String variable);

        /** The windows of this row's session, each at its active pane. */
        List<Scope> windows();

        /** The panes of this row's window. */
        List<Scope> panes();
    }

    /** Undoes {@code TmuxFormats.literal}: tmux reads {@code ##} in a format as one {@code #}. */
    static String literal(String value) {
        return value.replace("##", "#");
    }

    static String expand(String format, Function<String, @Nullable String> variables) {
        return expand(format, new Scope() {
            @Override
            public @Nullable String get(String variable) {
                return variables.apply(variable);
            }

            @Override
            public List<Scope> windows() {
                return List.of();
            }

            @Override
            public List<Scope> panes() {
                return List.of();
            }
        });
    }

    static String expand(String format, Scope variables) {
        StringBuilder out = new StringBuilder();
        int index = 0;
        while (index < format.length()) {
            if (format.startsWith("##", index)) {
                out.append('#');
                index += 2;
            } else if (format.startsWith("#{", index)) {
                int end = closing(format, index + 2);
                out.append(evaluate(format.substring(index + 2, end), variables));
                index = end + 1;
            } else {
                out.append(format.charAt(index));
                index++;
            }
        }
        return out.toString();
    }

    private static String evaluate(String inner, Scope variables) {
        if (inner.startsWith("?")) {
            List<String> branches = split(inner.substring(1));
            String condition = branches.get(0);
            boolean holds = truthy(
                    condition.startsWith("#{")
                            ? expand(condition, variables)
                            : Objects.requireNonNullElse(variables.get(condition), ""));
            int chosen = holds ? 1 : 2;
            return chosen < branches.size() ? expand(branches.get(chosen), variables) : "";
        }
        if (inner.startsWith("W:") || inner.startsWith("P:")) {
            String body = inner.substring(2);
            StringBuilder looped = new StringBuilder();
            for (Scope each : inner.charAt(0) == 'W' ? variables.windows() : variables.panes()) {
                looped.append(expand(body, each));
            }
            return looped.toString();
        }
        if (inner.startsWith("!:")) {
            return truthy(expand(inner.substring(2), variables)) ? "0" : "1";
        }
        for (String operator : List.of("e|<=|:", "e|>=|:", "e|<|:", "e|>|:")) {
            if (inner.startsWith(operator)) {
                List<String> operands = split(inner.substring(operator.length())).stream()
                        .map(operand -> expand(operand, variables))
                        .toList();
                int order = Long.compare(number(operands, 0), number(operands, 1));
                boolean result =
                        switch (operator) {
                            case "e|<=|:" -> order <= 0;
                            case "e|>=|:" -> order >= 0;
                            case "e|<|:" -> order < 0;
                            default -> order > 0;
                        };
                return result ? "1" : "0";
            }
        }
        for (String operator : List.of("==:", "!=:", "&&:", "||:")) {
            if (inner.startsWith(operator)) {
                List<String> operands = split(inner.substring(operator.length())).stream()
                        .map(operand -> expand(operand, variables))
                        .toList();
                String left = operands.isEmpty() ? "" : operands.get(0);
                String right = operands.size() < 2 ? "" : operands.get(1);
                boolean result =
                        switch (operator) {
                            case "==:" -> left.equals(right);
                            case "!=:" -> !left.equals(right);
                            case "&&:" -> truthy(left) && truthy(right);
                            default -> truthy(left) || truthy(right);
                        };
                return result ? "1" : "0";
            }
        }
        String value = variables.get(inner);
        return value == null ? "" : value;
    }

    /** tmux reads a missing or non-numeric operand as zero. */
    private static long number(List<String> operands, int index) {
        try {
            return index < operands.size() ? Long.parseLong(operands.get(index).strip()) : 0;
        } catch (NumberFormatException notANumber) {
            return 0;
        }
    }

    private static int closing(String format, int from) {
        int depth = 1;
        for (int index = from; index < format.length(); index++) {
            if (format.startsWith("#{", index)) {
                depth++;
                index++;
            } else if (format.charAt(index) == '}') {
                depth--;
                if (depth == 0) {
                    return index;
                }
            }
        }
        return format.length() - 1;
    }

    /** Splits operands at commas that are not inside a nested format. */
    private static List<String> split(String operands) {
        List<String> parts = new ArrayList<>();
        int depth = 0;
        int start = 0;
        for (int index = 0; index < operands.length(); index++) {
            if (operands.startsWith("#{", index)) {
                depth++;
                index++;
            } else if (operands.charAt(index) == '}') {
                depth--;
            } else if (operands.charAt(index) == ',' && depth == 0) {
                parts.add(operands.substring(start, index));
                start = index + 1;
            }
        }
        parts.add(operands.substring(start));
        return Collections.unmodifiableList(parts);
    }

    static boolean truthy(String value) {
        return !value.isEmpty() && !value.equals("0");
    }
}

package io.github.libtmux.junit5;

import java.util.ArrayList;
import java.util.List;

/**
 * Reads a command group the way tmux's command parser reads it: words in single quotes, a quote
 * spelled {@code '\''}, a line break spelled {@code "\n"}, commands separated by {@code ;}.
 */
final class Groups {

    private Groups() {}

    static List<List<String>> parse(String text) {
        List<List<String>> commands = new ArrayList<>();
        List<String> command = new ArrayList<>();
        StringBuilder word = null;
        int index = 0;
        while (index < text.length()) {
            char character = text.charAt(index);
            if (character == ' ') {
                if (word != null) {
                    command.add(word.toString());
                    word = null;
                }
                index++;
            } else if (character == ';' && word == null) {
                if (!command.isEmpty()) {
                    commands.add(command);
                }
                command = new ArrayList<>();
                index++;
            } else {
                if (word == null) {
                    word = new StringBuilder();
                }
                if (character == '\'') {
                    int end = text.indexOf('\'', index + 1);
                    word.append(text, index + 1, end);
                    index = end + 1;
                } else if (character == '"') {
                    int end = text.indexOf('"', index + 1);
                    word.append(
                            text.substring(index + 1, end).replace("\\n", "\n").replace("\\r", "\r"));
                    index = end + 1;
                } else if (character == '\\' && index + 1 < text.length()) {
                    word.append(text.charAt(index + 1));
                    index += 2;
                } else {
                    word.append(character);
                    index++;
                }
            }
        }
        if (word != null) {
            command.add(word.toString());
        }
        if (!command.isEmpty()) {
            commands.add(command);
        }
        return commands;
    }
}

package io.github.libtmux.junit5;

import io.github.libtmux.Server;
import io.github.libtmux.transport.CommandResult;
import java.io.IOException;
import java.nio.file.DirectoryNotEmptyException;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.attribute.BasicFileAttributes;
import java.time.Duration;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

/** Owns the safe teardown of a tmux server addressed by socket name. */
public final class NamedServerFixture implements AutoCloseable {

    private static final int UNIX_FILE_TYPE = 0170000;
    private static final int UNIX_SOCKET = 0140000;
    private static final Duration EXIT_TIMEOUT = Duration.ofSeconds(10);

    private final Server server;
    private final ProcessHandle process;
    private final Path quarantine;
    private final Path socket;
    private final Object fileKey;
    private boolean closed;

    private NamedServerFixture(Server server, ProcessHandle process, Path quarantine, Path socket, Object fileKey) {
        this.server = server;
        this.process = process;
        this.quarantine = quarantine;
        this.socket = socket;
        this.fileKey = fileKey;
    }

    /**
     * Authenticates a live named server and takes responsibility for ending it.
     *
     * @param server the server this test started
     * @param expectedName the exact socket name the test supplied to tmux
     * @param quarantine the {@code TMUX_TMPDIR} assigned to this test task
     * @return cleanup bound to the reported process, path, and socket inode
     * @throws IOException if the endpoint cannot be inspected
     */
    public static NamedServerFixture own(Server server, String expectedName, Path quarantine) throws IOException {
        Objects.requireNonNull(server, "server");
        Objects.requireNonNull(expectedName, "expectedName");
        Objects.requireNonNull(quarantine, "quarantine");
        return authenticate(
                server,
                candidate -> require(
                        expectedName.equals(candidate.getFileName().toString()),
                        "tmux reported another server's socket " + candidate),
                quarantine);
    }

    /**
     * Authenticates a live server at an exact socket path and takes responsibility for ending it.
     *
     * @param server the server this test started
     * @param expectedSocket the exact socket path the test supplied to tmux
     * @param quarantine the owned root that must contain the socket
     * @return cleanup bound to the reported process, path, and socket inode
     * @throws IOException if the endpoint cannot be inspected
     */
    public static NamedServerFixture own(Server server, Path expectedSocket, Path quarantine) throws IOException {
        Objects.requireNonNull(server, "server");
        Objects.requireNonNull(expectedSocket, "expectedSocket");
        Objects.requireNonNull(quarantine, "quarantine");
        // Resolved because tmux answers -S literally while a caller's own root may still be spelled
        // through an ancestor link (macOS's /tmp); authenticate() compares against the same form.
        Path expected = expectedSocket.toAbsolutePath().normalize().toRealPath();
        return authenticate(
                server,
                candidate -> require(expected.equals(candidate), "tmux reported another server's socket " + candidate),
                quarantine);
    }

    private static NamedServerFixture authenticate(
            Server server, SocketExpectation expectation, Path configuredQuarantine) throws IOException {
        List<String> identity =
                server.cmd("display-message", "-p", "#{pid}\t#{socket_path}").stdout();
        require(identity.size() == 1, "tmux reported identity rows " + identity);

        String row = identity.getFirst();
        String[] fields = row.split("\t", -1);
        require(fields.length == 2, "tmux reported a malformed identity row " + row);
        ProcessHandle process = ProcessHandle.of(Long.parseLong(fields[0]))
                .orElseThrow(() -> new AssertionError("the reported tmux process is already gone"));

        Path normalizedQuarantine = configuredQuarantine.toAbsolutePath().normalize();
        // macOS aliases /tmp into /private, so both spellings of the root are accepted below; a link
        // under the root still changes the tail against a same-root respelling and is refused.
        Path quarantine = normalizedQuarantine.toRealPath();
        Path reported = Path.of(fields[1]).toAbsolutePath().normalize();
        require(!Files.isSymbolicLink(reported), "refusing to reclaim a socket through a symbolic link");
        Path socket = reported.toRealPath();
        require(
                !socket.equals(quarantine) && socket.startsWith(quarantine),
                "refusing to reclaim a socket outside this port's quarantine");
        Path respelled = normalizedQuarantine.resolve(quarantine.relativize(socket));
        require(
                reported.equals(socket) || reported.equals(respelled),
                "refusing to reclaim a socket through a linked directory");
        expectation.verify(socket);
        BasicFileAttributes owned = Files.readAttributes(socket, BasicFileAttributes.class, LinkOption.NOFOLLOW_LINKS);
        require(isUnixSocket(socket), "tmux did not report a unix-domain socket inode");
        require(owned.fileKey() != null, "the filesystem cannot identify the socket inode");
        return new NamedServerFixture(server, process, quarantine, socket, owned.fileKey());
    }

    /** Returns the exact socket path authenticated when ownership was taken. */
    public Path socket() {
        return socket;
    }

    @Override
    public synchronized void close() throws IOException {
        if (closed) {
            return;
        }

        RuntimeException killFailure = null;
        try {
            killOwnedServer();
        } catch (RuntimeException failure) {
            killFailure = failure;
        }
        if (!awaitExit(process)) {
            AssertionError failure =
                    new AssertionError("the named tmux server did not exit; leaving " + socket + " in place");
            if (killFailure != null) {
                failure.addSuppressed(killFailure);
            }
            throw failure;
        }

        reclaimSocket();
        pruneEmptyParents(Objects.requireNonNull(socket.getParent()), quarantine);
        closed = true;
    }

    private void killOwnedServer() {
        long pid = process.pid();
        String stale = "libtmux-junit5-stale-owner-" + pid;
        CommandResult result = server.cmd("if-shell", "-F", "#{==:#{pid}," + pid + "}", "kill-server", stale);
        if (!result.succeeded() && result.stderr().stream().anyMatch(line -> line.contains(stale))) {
            throw new AssertionError("refusing to terminate a replacement tmux process at " + socket);
        }
    }

    private void reclaimSocket() throws IOException {
        Path currentQuarantine = quarantine.toRealPath();
        require(
                currentQuarantine.equals(quarantine),
                "refusing to reclaim a socket through a replaced quarantine path");
        if (Files.exists(socket, LinkOption.NOFOLLOW_LINKS)) {
            require(!Files.isSymbolicLink(socket), "refusing to remove a symbolic-link replacement");
            require(socket.equals(socket.toRealPath()), "refusing to remove a socket through a linked directory");
            require(
                    !socket.equals(quarantine) && socket.startsWith(quarantine),
                    "refusing to remove a socket outside this port's quarantine");
            BasicFileAttributes stale =
                    Files.readAttributes(socket, BasicFileAttributes.class, LinkOption.NOFOLLOW_LINKS);
            require(isUnixSocket(socket), "refusing to remove a non-socket replacement");
            require(fileKey.equals(stale.fileKey()), "refusing to remove a replacement socket inode");
            Files.delete(socket);
        }
        require(Files.notExists(socket, LinkOption.NOFOLLOW_LINKS), "the named tmux socket was not reclaimed");
    }

    private static boolean awaitExit(ProcessHandle process) {
        try {
            process.onExit().get(EXIT_TIMEOUT.toMillis(), TimeUnit.MILLISECONDS);
            return !process.isAlive();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return false;
        } catch (ExecutionException | TimeoutException e) {
            return !process.isAlive();
        }
    }

    private static boolean isUnixSocket(Path path) throws IOException {
        int mode = (Integer) Files.getAttribute(path, "unix:mode", LinkOption.NOFOLLOW_LINKS);
        return (mode & UNIX_FILE_TYPE) == UNIX_SOCKET;
    }

    private static void pruneEmptyParents(Path directory, Path quarantine) throws IOException {
        Path candidate = directory;
        while (candidate != null && !candidate.equals(quarantine)) {
            require(candidate.startsWith(quarantine), "refusing to prune outside the tmux quarantine");
            if (Files.notExists(candidate, LinkOption.NOFOLLOW_LINKS)) {
                candidate = candidate.getParent();
                continue;
            }
            require(
                    Files.isDirectory(candidate, LinkOption.NOFOLLOW_LINKS),
                    "refusing to prune a non-directory from the tmux quarantine");
            try {
                Files.delete(candidate);
            } catch (DirectoryNotEmptyException e) {
                return;
            }
            candidate = candidate.getParent();
        }
    }

    private static void require(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }

    @FunctionalInterface
    private interface SocketExpectation {
        void verify(Path socket);
    }
}

package io.github.libtmux.junit5;

import java.util.List;
import java.util.Optional;
import org.jspecify.annotations.Nullable;

/** A session, one of its windows, and one of that window's panes: what a command is scoped to. */
record Target(FakeSession session, FakeWindow window, FakePane pane) {

    static Optional<Target> active(List<FakeSession> sessions) {
        return sessions.stream().findFirst().map(session -> {
            FakeWindow window =
                    session.windows.stream().filter(w -> w.active).findFirst().orElse(session.windows.getFirst());
            return new Target(session, window, window.active());
        });
    }

    /** Resolves {@code $id}, {@code @id}, {@code %id} and {@code =name}, with any trailing separator. */
    static Optional<Target> resolve(List<FakeSession> sessions, @Nullable String spec) {
        if (spec == null) {
            return Optional.empty();
        }
        String wanted = spec.replaceAll("[:.]+$", "");
        for (FakeSession session : sessions) {
            if (wanted.equals(session.id) || wanted.equals("=" + session.name)) {
                FakeWindow window = session.windows.stream()
                        .filter(w -> w.active)
                        .findFirst()
                        .orElse(session.windows.getFirst());
                return Optional.of(new Target(session, window, window.active()));
            }
            for (FakeWindow window : session.windows) {
                if (wanted.equals(window.id)) {
                    return Optional.of(new Target(session, window, window.active()));
                }
                for (FakePane pane : window.panes) {
                    if (wanted.equals(pane.id)) {
                        return Optional.of(new Target(session, window, pane));
                    }
                }
            }
        }
        return Optional.empty();
    }
}

package io.github.libtmux.junit5;

import io.github.libtmux.Server;
import io.github.libtmux.ServerConfig;
import io.github.libtmux.ServerEndpoint;
import io.github.libtmux.transport.CommandResult;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Stream;
import org.jspecify.annotations.Nullable;
import org.junit.jupiter.api.extension.AfterEachCallback;
import org.junit.jupiter.api.extension.BeforeEachCallback;
import org.junit.jupiter.api.extension.ExtensionContext;
import org.junit.jupiter.api.extension.ParameterContext;
import org.junit.jupiter.api.extension.ParameterResolver;

/**
 * Gives each test its own tmux server and guarantees it is gone afterwards.
 *
 * <p>All state lives in the extension store, never in fields. JUnit reuses one declaratively
 * registered extension instance for every test in a class, so a field is shared state the moment
 * tests run in parallel, and one test's teardown then reaches another test's server.
 *
 * <p>The server is started eagerly, before the test body, and the aggregate that owns it is
 * registered before any process exists. Registering afterwards leaves a window in which a failure
 * partway through setup leaks a running tmux that nothing is left holding.
 *
 * <p>Teardown is driven from a lifecycle callback and the aggregate is also {@link AutoCloseable}
 * for the framework's own store handling. Relying on store auto-close alone is a silent dependency
 * on a configuration property: with it disabled that design releases nothing and reports nothing.
 * The aggregate closes exactly once, so either path alone is sufficient.
 */
public final class TmuxExtension implements ParameterResolver, BeforeEachCallback, AfterEachCallback {

    private static final ExtensionContext.Namespace NAMESPACE = ExtensionContext.Namespace.create(TmuxExtension.class);
    private static final String KEY = "fixture";

    private static final Path FIXTURE_ROOT = Path.of("/tmp/libtmux-java-test");

    /**
     * The directory a fixture is made in names the JVM that made it, which is the only durable record
     * of who owns the server inside. A registry cannot serve: the run that most needs reaping is the
     * one that was killed before it could write anything down.
     *
     * <p>The pid alone is not a stable owner: the OS recycles pids, and a fixture directory left by a
     * killed JVM can end up named for a pid a later, unrelated process now holds. The owning JVM's
     * start rules that out, so it rides along whenever the platform reports one.
     */
    private static final String PREFIX = prefix();

    private static String prefix() {
        ProcessHandle current = ProcessHandle.current();
        return "libtmux-" + current.pid()
                + startOf(current.pid()).map(start -> "-" + start).orElse("") + "-";
    }

    /** pid and start, the current naming: {@code k} and ticks since boot on Linux, epoch millis elsewhere. */
    private static final Pattern OWNER_WITH_START = Pattern.compile("libtmux-(\\d+)-(k?\\d+)-.*");

    /**
     * How far two JVMs' readings of one process's start instant may differ. Linux reports a start as
     * ticks since boot; the JDK adds the boot time it read once when it started, and that boot time
     * moves whenever the wall clock is stepped, by seconds under WSL2 in a few minutes. Only a
     * directory written before starts were recorded as ticks is compared this way.
     */
    private static final long START_SLACK_MILLIS = Duration.ofMinutes(1).toMillis();

    /** pid alone, written by a version of this extension that predates {@link #OWNER_WITH_START}. */
    private static final Pattern OWNER = Pattern.compile("libtmux-(\\d+)-.*");

    /** Every fixture this JVM currently holds a server for, so the shutdown hook knows what to end. */
    private static final Set<Fixture> LIVE = ConcurrentHashMap.newKeySet();

    /**
     * How long a signalled server is given to go. Generous because it is spent only on servers that
     * are already abandoned, and only once per JVM.
     */
    private static final Duration SHUTDOWN = Duration.ofSeconds(30);

    private static final AtomicBoolean SWEPT = new AtomicBoolean();

    static {
        // Covers the exits a lifecycle callback does not: a cancelled build, a SIGTERM, a
        // System.exit from something else in the JVM. The hook runs on termination and normal exit,
        // and does not run on SIGKILL — which is what the sweep is for. See
        // docs/decisions/0006-real-tmux-junit5-fixture-lifecycle.md.
        Runtime.getRuntime().addShutdownHook(new Thread(TmuxExtension::releaseAll, "libtmux-fixture-shutdown"));
    }

    private static void releaseAll() {
        for (Fixture fixture : LIVE) {
            try {
                fixture.close();
            } catch (RuntimeException e) {
                // Shutdown is not a place to report; the sweep is the backstop for whatever survives.
            }
        }
    }

    static Path fixtureRoot() {
        return FIXTURE_ROOT;
    }

    /**
     * Ends every tmux server under {@code root} whose owning JVM is gone, and answers how many
     * ended. Runs while other runs are using the same root, so it may only touch abandoned servers.
     */
    static int reapAbandoned(Path root) {
        Path resolved = root.toAbsolutePath().normalize();
        List<AbandonedServer> abandoned = ProcessHandle.allProcesses()
                .map(handle -> abandonedServer(handle, resolved))
                .flatMap(Optional::stream)
                .toList();

        // Asked together, waited for afterwards, so one slow server does not serialise the rest.
        abandoned.stream().map(AbandonedServer::process).forEach(ProcessHandle::destroy);

        int reaped = 0;
        for (AbandonedServer server : abandoned) {
            if (ended(server.process())) {
                deleteTree(server.directory());
                reaped++;
            }
        }
        return reaped;
    }

    /**
     * SIGTERM only asks: tmux destroys every session and reaps each pane's children before it goes,
     * so a signalled server is still alive for as long as that takes.
     */
    private static boolean ended(ProcessHandle handle) {
        try {
            handle.onExit().get(SHUTDOWN.toMillis(), TimeUnit.MILLISECONDS);
            return true;
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return false;
        } catch (ExecutionException | TimeoutException e) {
            return !handle.isAlive();
        }
    }

    /** Matched on the executable too: a shell whose command line mentions the socket is not a server. */
    private static Optional<AbandonedServer> abandonedServer(ProcessHandle handle, Path root) {
        ProcessHandle.Info info = handle.info();
        if (!info.command()
                .map(command -> Path.of(command).getFileName())
                .map(Path::toString)
                .filter("tmux"::equals)
                .isPresent()) {
            return Optional.empty();
        }
        String[] argv = info.arguments().orElse(NO_ARGUMENTS);
        for (int index = 0; index + 1 < argv.length; index++) {
            if ("-S".equals(argv[index])) {
                return abandonedDirectory(
                                Path.of(argv[index + 1]).toAbsolutePath().normalize(), root)
                        .map(directory -> new AbandonedServer(handle, directory));
            }
        }
        return Optional.empty();
    }

    private static final String[] NO_ARGUMENTS = {};

    /** A reused pid, or one whose live process started at a different instant, cannot spare this directory. */
    private static Optional<Path> abandonedDirectory(Path socket, Path root) {
        Path directory = socket.getParent();
        if (directory == null || !socket.startsWith(root)) {
            return Optional.empty();
        }
        String name = directory.getFileName().toString();
        Matcher withStart = OWNER_WITH_START.matcher(name);
        if (withStart.matches()) {
            long pid = Long.parseLong(withStart.group(1));
            return ownerChanged(pid, withStart.group(2)) ? Optional.of(directory) : Optional.empty();
        }
        Matcher named = OWNER.matcher(name);
        if (!named.matches()) {
            // Something else's socket, or one from before this scheme. Not this sweep's to judge.
            return Optional.empty();
        }
        return ProcessHandle.of(Long.parseLong(named.group(1))).isEmpty() ? Optional.of(directory) : Optional.empty();
    }

    /**
     * True when the pid is free, or a live process holds it but did not start when this directory
     * recorded. A live process whose start cannot be read is trusted rather than reaped: this
     * platform cannot tell a reused pid from the one that made the directory.
     */
    private static boolean ownerChanged(long pid, String recordedStart) {
        Optional<ProcessHandle> live = ProcessHandle.of(pid);
        if (live.isEmpty()) {
            return true;
        }
        if (recordedStart.startsWith("k")) {
            return linuxStartTicks(pid)
                    .map(ticks -> !recordedStart.equals("k" + ticks))
                    .orElse(false);
        }
        long recordedMillis = Long.parseLong(recordedStart);
        return live.get()
                .info()
                .startInstant()
                .map(instant -> Math.abs(instant.toEpochMilli() - recordedMillis) > START_SLACK_MILLIS)
                .orElse(false);
    }

    /**
     * When a process started, in a form every JVM on this machine reads the same way: the kernel's
     * own ticks since boot on Linux, and the platform's start instant elsewhere.
     */
    static Optional<String> startOf(long pid) {
        Optional<Long> ticks = linuxStartTicks(pid);
        if (ticks.isPresent()) {
            return Optional.of("k" + ticks.get());
        }
        return ProcessHandle.of(pid)
                .flatMap(process -> process.info().startInstant())
                .map(instant -> Long.toString(instant.toEpochMilli()));
    }

    /**
     * Field 22 of {@code /proc/<pid>/stat}. Counted after the command name's closing parenthesis,
     * since the name itself may hold spaces and parentheses.
     */
    private static Optional<Long> linuxStartTicks(long pid) {
        Path stat = Path.of("/proc", Long.toString(pid), "stat");
        try {
            String text = Files.readString(stat);
            String[] fields = text.substring(text.lastIndexOf(')') + 2).split(" ", -1);
            return Optional.of(Long.parseLong(fields[19]));
        } catch (IOException | RuntimeException unreadable) {
            return Optional.empty();
        }
    }

    private record AbandonedServer(ProcessHandle process, Path directory) {}

    static void deleteTree(Path root) {
        if (!Files.exists(root)) {
            return;
        }
        try (Stream<Path> paths = Files.walk(root)) {
            paths.sorted(Comparator.reverseOrder()).forEach(path -> {
                try {
                    Files.deleteIfExists(path);
                } catch (IOException e) {
                    // Best effort; a fixture directory is the operating system's to reclaim.
                }
            });
        } catch (IOException e) {
            throw new UncheckedIOException("could not remove a tmux fixture directory", e);
        }
    }

    @Override
    public void beforeEach(ExtensionContext context) {
        fixture(context);
    }

    @Override
    public boolean supportsParameter(ParameterContext parameter, ExtensionContext context) {
        Class<?> type = parameter.getParameter().getType();
        // Never claims a bare Path: another extension is entitled to resolve those.
        return type == Server.class || type == TmuxSocketPath.class;
    }

    @Override
    public Object resolveParameter(ParameterContext parameter, ExtensionContext context) {
        Fixture fixture = fixture(context);
        return parameter.getParameter().getType() == Server.class
                ? fixture.server()
                : new TmuxSocketPath(fixture.socket());
    }

    @Override
    public void afterEach(ExtensionContext context) {
        Fixture fixture = context.getStore(NAMESPACE).get(KEY, Fixture.class);
        if (fixture != null) {
            fixture.close();
        }
    }

    private static Fixture fixture(ExtensionContext context) {
        // The aggregate is stored while it still owns nothing, so a failure during startup is still
        // reachable by teardown.
        Fixture fixture = context.getStore(NAMESPACE).getOrComputeIfAbsent(KEY, key -> new Fixture(), Fixture.class);
        fixture.start();
        return fixture;
    }

    /** One test's server, socket and directory, released exactly once. */
    static final class Fixture implements AutoCloseable {

        private static final Duration PROBE = Duration.ofSeconds(5);
        private static final long EXIT_MILLIS = 10_000;

        private @Nullable Path directory;
        private @Nullable Path socket;
        private @Nullable Server server;
        private boolean started;
        private boolean closed;

        synchronized void start() {
            if (started) {
                return;
            }
            started = true;
            try {
                // Once per JVM, before this run makes its first server: whatever a killed run left
                // behind is holding a pty and answering to a name this one might choose.
                Path fixtureRoot = fixtureRoot();
                Files.createDirectories(fixtureRoot);
                if (SWEPT.compareAndSet(false, true)) {
                    reapAbandoned(fixtureRoot);
                }
                Path root = Files.createTempDirectory(fixtureRoot, PREFIX);
                directory = root;
                Path config = root.resolve("tmux.conf");
                Files.writeString(config, "");
                Path endpoint = root.resolve("s");
                socket = endpoint;
                server = Server.open(ServerConfig.builder()
                        // Lets one suite run against a matrix of tmux builds rather than whichever
                        // one happens to be on PATH.
                        .binary(System.getProperty("libtmux.tmux", "tmux"))
                        .endpoint(ServerEndpoint.socketPath(endpoint))
                        .configFile(config)
                        .build());
                LIVE.add(this);
            } catch (IOException e) {
                throw new UncheckedIOException("could not create a tmux fixture directory", e);
            }
            CommandResult created = server().cmd("new-session", "-d", "-s", "libtmux");
            if (!created.succeeded()) {
                throw new IllegalStateException("could not start the fixture tmux: " + created.stderr());
            }
            verifyPromisedSocket();
        }

        /** tmux has to agree about which socket it is listening on, and it has to physically exist. */
        private void verifyPromisedSocket() {
            Path promised = socket();
            List<String> reported =
                    server().cmd("display-message", "-p", "#{socket_path}").stdout();
            if (!List.of(promised.toString()).equals(reported)) {
                throw new IllegalStateException("tmux reports socket " + reported + ", not the promised one");
            }
            if (!Files.exists(promised)) {
                throw new IllegalStateException("tmux reported a socket that does not exist");
            }
        }

        Server server() {
            Server current = server;
            if (current == null) {
                throw new IllegalStateException("the fixture server was never started");
            }
            return current;
        }

        Path socket() {
            Path current = socket;
            if (current == null) {
                throw new IllegalStateException("the fixture socket was never chosen");
            }
            return current;
        }

        @Override
        public synchronized void close() {
            if (closed) {
                return;
            }
            closed = true;
            LIVE.remove(this);
            Server current = server;
            boolean exited = true;
            if (current != null) {
                try {
                    current.killServer(PROBE);
                } catch (RuntimeException e) {
                    // A server that already exited is the outcome teardown wanted.
                }
                exited = awaitExit(current);
                current.close();
            }
            if (!exited) {
                // Preserve the failure rather than unlinking a socket a live daemon still owns.
                throw new IllegalStateException("the fixture tmux did not exit; leaving " + directory + " in place");
            }
            Path root = directory;
            if (root != null) {
                deleteTree(root);
            }
        }

        /** Exit is proved by asking, not assumed from a kill that may have raced. */
        static boolean awaitExit(Server server) {
            return awaitExit(server, EXIT_MILLIS);
        }

        static boolean awaitExit(Server server, long timeoutMillis) {
            long deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(timeoutMillis);
            while (System.nanoTime() < deadline) {
                try {
                    // isAlive rather than list-sessions: the latter also fails on a live server
                    // that has no sessions left, which teardown must not read as an exit.
                    if (!server.isAlive(PROBE)) {
                        return true;
                    }
                } catch (RuntimeException e) {
                    return false;
                }
                try {
                    Thread.sleep(25);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return false;
                }
            }
            return false;
        }
    }
}

