package io.github.libtmux.workspace;

import java.util.List;

/**
 * One pane and what to run in it.
 *
 * @param commands the commands to send, in order; a pane with none is left at its shell
 */
public record PaneSpec(List<String> commands) {

    public PaneSpec {
        commands = List.copyOf(commands);
        for (int index = 0; index < commands.size(); index++) {
            if (commands.get(index).indexOf('\0') >= 0) {
                throw new IllegalArgumentException(
                        "pane command " + index + " contains NUL, which no process can carry");
            }
        }
    }
}

package io.github.libtmux.workspace;

import java.util.List;
import java.util.Optional;

/**
 * One window, its panes, and how they are arranged.
 *
 * @param name the window name
 * @param layout the tmux layout to apply once the panes exist, if the file asked for one
 * @param panes the panes to create, in order; a window always has at least one
 */
public record WindowSpec(String name, Optional<String> layout, List<PaneSpec> panes) {

    public WindowSpec {
        panes = List.copyOf(panes);
        if (panes.isEmpty()) {
            throw new IllegalArgumentException("window '" + name + "' has no panes");
        }
    }
}

package io.github.libtmux.workspace;

import java.util.List;

/**
 * A session described in a file, before anything has been built.
 *
 * @param sessionName the session to create
 * @param windows the windows to create, in order
 */
public record Workspace(String sessionName, List<WindowSpec> windows) {

    public Workspace {
        windows = List.copyOf(windows);
        if (sessionName.isEmpty()) {
            throw new IllegalArgumentException("the workspace has no session name");
        }
        if (sessionName.indexOf('.') >= 0 || sessionName.indexOf(':') >= 0) {
            throw new IllegalArgumentException("workspace session names cannot contain '.' or ':': " + sessionName);
        }
        if (windows.isEmpty()) {
            throw new IllegalArgumentException("the workspace has no windows");
        }
    }
}

package io.github.libtmux.workspace;

import io.github.libtmux.Layout;
import io.github.libtmux.Layouts;
import io.github.libtmux.Pane;
import io.github.libtmux.Server;
import io.github.libtmux.Session;
import io.github.libtmux.Window;
import io.github.libtmux.exception.CommandRejectedException;
import io.github.libtmux.transport.CommandResult;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.UUID;

/** Applies a validated workspace as one session and attempts to remove it after a failure. */
final class WorkspaceApplier {

    private WorkspaceApplier() {}

    static Session build(Server server, Workspace workspace) {
        validate(server, workspace);
        String staging = "libtmux-ws-" + UUID.randomUUID();
        Session session = null;
        try {
            session = server.newSession(staging);
            session = session.rename(workspace.sessionName());
            List<BuiltWindow> windows = createTopology(session, workspace.windows());
            runCommands(windows);
            return session.refresh();
        } catch (RuntimeException | Error failure) {
            if (session == null) {
                cleanupStaging(server, staging, failure);
            } else {
                try {
                    session.kill();
                } catch (RuntimeException cleanupFailure) {
                    failure.addSuppressed(cleanupFailure);
                }
            }
            throw failure;
        }
    }

    private static void validate(Server server, Workspace workspace) {
        for (WindowSpec window : workspace.windows()) {
            window.layout()
                    .ifPresent(value ->
                            Layouts.require(value, server, window.panes().size()));
        }
    }

    private static void cleanupStaging(Server server, String staging, Throwable failure) {
        try {
            // By name, not server.killSession: a lost new-session reply leaves no id to resolve, so
            // the generated name is the only handle. Safe as an exact match here specifically because
            // staging is always "libtmux-ws-" plus a UUID, which never holds ':' or '.'.
            CommandResult cleanup = server.cmd("kill-session", "-t", "=" + staging);
            if (!cleanup.succeeded() && cleanup.stderr().stream().noneMatch(WorkspaceApplier::alreadyAbsent)) {
                failure.addSuppressed(new CommandRejectedException(
                        "could not clean up staging session: " + String.join("; ", cleanup.stderr()),
                        "kill-session",
                        cleanup.exitCode(),
                        cleanup.stderr()));
            }
        } catch (RuntimeException cleanupFailure) {
            failure.addSuppressed(cleanupFailure);
        }
    }

    private static boolean alreadyAbsent(String message) {
        return message.contains("can't find session")
                || message.contains("no server running")
                || message.contains("server exited unexpectedly");
    }

    private static List<BuiltWindow> createTopology(Session session, List<WindowSpec> specs) {
        List<BuiltWindow> windows = new ArrayList<>(specs.size());
        for (int index = 0; index < specs.size(); index++) {
            WindowSpec spec = specs.get(index);
            Window window = index == 0 ? firstWindow(session, spec.name()) : session.newWindow(spec.name());
            for (int pane = 1; pane < spec.panes().size(); pane++) {
                window.split();
                // Halving each pane in turn runs out of rows before the fifth at a default terminal
                // size; rebalancing after every split reclaims them. The window's own layout, applied
                // below, still has the final say.
                window.selectLayout(Layout.TILED);
            }
            applyLayout(window, spec.layout(), spec.panes().size());
            List<Pane> panes = window.refresh().panes();
            requirePaneCount(panes, spec);
            windows.add(new BuiltWindow(spec, panes));
        }
        return List.copyOf(windows);
    }

    private static Window firstWindow(Session session, String name) {
        Window window = session.windows().getFirst();
        return name.isEmpty() ? window : window.rename(name);
    }

    private static void applyLayout(Window window, Optional<String> layout, int panes) {
        layout.map(value -> Layouts.require(value, window.server(), panes))
                .ifPresent(value -> Layout.byTmuxName(value)
                        .ifPresentOrElse(window::selectLayout, () -> window.applyLayout(value)));
    }

    private static void runCommands(List<BuiltWindow> windows) {
        for (BuiltWindow window : windows) {
            WindowSpec spec = window.specification();
            List<Pane> panes = window.panes();
            for (int paneIndex = 0; paneIndex < panes.size(); paneIndex++) {
                for (String command : spec.panes().get(paneIndex).commands()) {
                    panes.get(paneIndex).sendLine(command);
                }
            }
        }
    }

    private static void requirePaneCount(List<Pane> panes, WindowSpec spec) {
        if (panes.size() != spec.panes().size()) {
            throw new IllegalStateException("window '" + spec.name() + "' has " + panes.size() + " panes; expected "
                    + spec.panes().size());
        }
    }

    private record BuiltWindow(WindowSpec specification, List<Pane> panes) {}
}

package io.github.libtmux.workspace;

import io.github.libtmux.Server;
import io.github.libtmux.Session;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;

/**
 * Builds a tmux session from a written description.
 *
 * <p>Reads the shape of a tmuxp workspace file. Full runtime compatibility with tmuxp is not the
 * aim; starting from a file somebody already has is.
 *
 * <p>Reading and building are separate. A file that describes something tmux would refuse is
 * rejected while it is still text, before any session exists to leave half-built.
 *
 * <p>The {@code tmux-workspace} command is a separate implementation with a wider document
 * language and its own behaviour around building; see this package's documentation for what
 * differs. Code against this class for what this class does.
 */
public final class WorkspaceBuilder {

    private WorkspaceBuilder() {}

    /** Reads a workspace from a file. */
    public static Workspace read(Path file) {
        try {
            return parse(Files.readString(file));
        } catch (IOException e) {
            throw new UncheckedIOException("could not read the workspace file", e);
        }
    }

    /**
     * Reads a workspace from YAML text.
     *
     * @throws IllegalArgumentException if the description is one tmux could not build, including a
     *     layout name tmux would not recognise
     */
    public static Workspace parse(String yaml) {
        return WorkspaceParser.parse(yaml);
    }

    /**
     * Creates the described session on a server.
     *
     * @return the session, from a capture taken once everything exists
     */
    public static Session build(Server server, Workspace workspace) {
        return WorkspaceApplier.build(server, workspace);
    }
}

package io.github.libtmux.workspace;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.StreamReadFeature;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.MappingIterator;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory;
import io.github.libtmux.Layouts;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.Set;

/** Converts the supported YAML shape into immutable workspace values. */
final class WorkspaceParser {

    private static final ObjectMapper YAML = new ObjectMapper(YAMLFactory.builder()
            .enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION)
            .build());
    private static final Set<String> ROOT_FIELDS = Set.of("session_name", "windows");
    private static final Set<String> WINDOW_FIELDS = Set.of("window_name", "layout", "panes");
    private static final Set<String> PANE_FIELDS = Set.of("shell_command");

    private WorkspaceParser() {}

    static Workspace parse(String yaml) {
        List<JsonNode> documents;
        try (MappingIterator<JsonNode> values = YAML.readerFor(JsonNode.class).readValues(yaml)) {
            documents = values.readAll();
        } catch (JsonProcessingException e) {
            String detail = e.getOriginalMessage();
            if (detail.toLowerCase(Locale.ROOT).contains("duplicate")) {
                detail = "duplicate key: " + detail;
            }
            throw new IllegalArgumentException("the workspace is not readable YAML: " + detail, e);
        } catch (IOException e) {
            throw new IllegalArgumentException("the workspace is not readable YAML", e);
        }
        if (documents.size() != 1) {
            throw new IllegalArgumentException("the workspace must contain exactly one YAML document");
        }

        JsonNode root = object(documents.getFirst(), "$");
        rejectUnknown(root, ROOT_FIELDS, "$");
        String sessionName = text(root.get("session_name"), "$.session_name");
        JsonNode windowNodes = array(root.get("windows"), "$.windows");
        List<WindowSpec> windows = new ArrayList<>();
        for (int index = 0; index < windowNodes.size(); index++) {
            windows.add(window(windowNodes.get(index), "$.windows[" + index + "]"));
        }
        return new Workspace(sessionName, windows);
    }

    private static WindowSpec window(JsonNode node, String path) {
        JsonNode window = object(node, path);
        rejectUnknown(window, WINDOW_FIELDS, path);
        String name =
                optionalText(window.get("window_name"), path + ".window_name").orElse("");
        Optional<String> layout = optionalText(window.get("layout"), path + ".layout")
                .map(value -> Layouts.builtIn(value, new io.github.libtmux.TmuxVersion(3, 4, ""))
                                .isPresent()
                        ? value
                        : Layouts.require(value));

        JsonNode paneNodes = window.get("panes");
        List<PaneSpec> panes = new ArrayList<>();
        if (paneNodes == null) {
            panes.add(new PaneSpec(List.of()));
        } else {
            JsonNode paneArray = array(paneNodes, path + ".panes");
            for (int index = 0; index < paneArray.size(); index++) {
                panes.add(pane(paneArray.get(index), path + ".panes[" + index + "]"));
            }
            if (panes.isEmpty()) {
                panes.add(new PaneSpec(List.of()));
            }
        }
        return new WindowSpec(name, layout, panes);
    }

    private static PaneSpec pane(JsonNode node, String path) {
        if (node.isTextual()) {
            return new PaneSpec(List.of(node.textValue()));
        }
        if (node.isArray()) {
            return new PaneSpec(texts(node, path));
        }
        JsonNode pane = object(node, path);
        rejectUnknown(pane, PANE_FIELDS, path);
        JsonNode command = pane.get("shell_command");
        if (command == null) {
            throw malformed(path + ".shell_command", "is required");
        }
        if (command.isTextual()) {
            return new PaneSpec(List.of(command.textValue()));
        }
        return new PaneSpec(texts(array(command, path + ".shell_command"), path + ".shell_command"));
    }

    private static List<String> texts(JsonNode nodes, String path) {
        List<String> values = new ArrayList<>();
        for (int index = 0; index < nodes.size(); index++) {
            values.add(text(nodes.get(index), path + "[" + index + "]"));
        }
        return values;
    }

    private static JsonNode object(JsonNode node, String path) {
        if (node == null || !node.isObject()) {
            throw malformed(path, "must be a mapping");
        }
        return node;
    }

    private static JsonNode array(JsonNode node, String path) {
        if (node == null || !node.isArray()) {
            throw malformed(path, "must be a list");
        }
        return node;
    }

    private static String text(JsonNode node, String path) {
        if (node == null || !node.isTextual()) {
            throw malformed(path, "must be text");
        }
        return node.textValue();
    }

    private static Optional<String> optionalText(JsonNode node, String path) {
        if (node == null || node.isNull()) {
            return Optional.empty();
        }
        return Optional.of(text(node, path));
    }

    private static void rejectUnknown(JsonNode object, Set<String> allowed, String path) {
        object.fieldNames().forEachRemaining(field -> {
            if (!allowed.contains(field)) {
                throw malformed(path + "." + field, "is not supported");
            }
        });
    }

    private static IllegalArgumentException malformed(String path, String problem) {
        return new IllegalArgumentException(path + " " + problem);
    }
}

