package io.github.libtmux.batch;

import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import io.github.libtmux.format.Tokens;
import io.github.libtmux.internal.CommandStrings;
import io.github.libtmux.transport.CommandResult;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;

/**
 * Several tmux commands in one invocation, each with an outcome of its own.
 *
 * <p>tmux runs a group until a command fails and then discards the rest, so the number of replies
 * cannot say which command failed: an error in the first position and an error in the last both
 * come back as one nonzero exit. Counting replies is wrong in every position but one.
 *
 * <p>A marker is therefore interleaved after each operation. Markers are discarded along with
 * everything else after a failure, so the last marker seen is exactly the last operation tmux ran,
 * and the operations either side of that boundary are known rather than guessed.
 */
public final class Batch {

    private static final String MARKER = Tokens.perProcess();

    private final Function<List<List<String>>, CommandResult> dispatch;
    private final List<List<String>> operations = new ArrayList<>();

    /**
     * Collects operations to run together.
     *
     * @param dispatch runs the assembled commands in one invocation and returns tmux's raw reply
     */
    public Batch(Function<List<List<String>>, CommandResult> dispatch) {
        this.dispatch = dispatch;
    }

    /** Adds one tmux command, its arguments already separate elements. */
    @Operation(Kind.CAPTURED)
    public Batch add(String... argv) {
        return add(List.of(argv));
    }

    /** Adds one tmux command. */
    @Operation(Kind.CAPTURED)
    public Batch add(List<String> argv) {
        if (argv.isEmpty()) {
            throw new IllegalArgumentException("an operation has no command");
        }
        operations.add(List.copyOf(argv));
        return this;
    }

    /** How many operations have been collected. */
    @Operation(Kind.CAPTURED)
    public int size() {
        return operations.size();
    }

    /**
     * How many bytes the collected operations come to as the one command tmux parses.
     *
     * <p>tmux packs a command into MAX_IMSGSIZE, 16384 bytes, and refuses a longer one with
     * {@code command too long}; measured, it takes about 16300 of them. A batch taken from a handle
     * travels as this one string plus the guard that fences it, so it costs this and a little more.
     * One dispatched as separate arguments costs less, since nothing there is quoted.
     */
    @Operation(Kind.CAPTURED)
    public int length() {
        return CommandStrings.group(assemble()).getBytes(StandardCharsets.UTF_8).length;
    }

    /**
     * Runs every collected operation in one tmux invocation.
     *
     * @return one result per operation, in submission order
     */
    @Operation(Kind.MUTATION)
    public BatchResult run() {
        if (operations.isEmpty()) {
            return new BatchResult(List.of());
        }
        CommandResult reply = dispatch.apply(assemble());
        return attribute(reply);
    }

    /** {@code op0, marker0, op1, marker1, …}: each operation followed by the marker that closes it. */
    private List<List<String>> assemble() {
        List<List<String>> commands = new ArrayList<>(operations.size() * 2);
        for (int index = 0; index < operations.size(); index++) {
            commands.add(operations.get(index));
            commands.add(List.of("display-message", "-p", marker(index)));
        }
        return commands;
    }

    private static String marker(int index) {
        return MARKER + ":" + index;
    }

    private BatchResult attribute(CommandResult reply) {
        List<OperationResult> results = new ArrayList<>(operations.size());
        List<String> pending = new ArrayList<>();
        int completed = 0;
        for (String line : reply.stdout()) {
            if (completed < operations.size() && line.equals(marker(completed))) {
                results.add(
                        new OperationResult(operations.get(completed), OperationOutcome.COMPLETE, pending, List.of()));
                pending = new ArrayList<>();
                completed++;
            } else {
                pending.add(line);
            }
        }
        if (completed == operations.size()) {
            if (!reply.succeeded()) {
                // Every marker arrived and tmux still reported failure, so the last operation's
                // effect is not something this can vouch for.
                int last = results.size() - 1;
                OperationResult previous = results.get(last);
                results.set(
                        last,
                        new OperationResult(
                                previous.argv(), OperationOutcome.UNKNOWN, previous.stdout(), reply.stderr()));
            }
            return new BatchResult(results);
        }
        // The first operation without its marker is the one that failed; tmux discarded the rest.
        results.add(new OperationResult(operations.get(completed), OperationOutcome.FAILED, pending, reply.stderr()));
        for (int index = completed + 1; index < operations.size(); index++) {
            results.add(new OperationResult(operations.get(index), OperationOutcome.SKIPPED, List.of(), List.of()));
        }
        return new BatchResult(results);
    }
}

package io.github.libtmux.batch;

import java.util.List;
import java.util.Optional;
import kotlin.annotations.jvm.ReadOnly;

/**
 * What became of every operation in one batch.
 *
 * @param operations one result per submitted operation, in submission order
 */
public record BatchResult(@ReadOnly List<OperationResult> operations) {

    public BatchResult {
        operations = List.copyOf(operations);
    }

    /** Whether tmux ran every operation and all of them succeeded. */
    public boolean succeeded() {
        return operations.stream().allMatch(OperationResult::succeeded);
    }

    /** The operation that failed, if one did. Everything after it was discarded by tmux. */
    public Optional<OperationResult> failure() {
        return operations.stream()
                .filter(operation -> operation.outcome() == OperationOutcome.FAILED)
                .findFirst();
    }

    @Override
    public String toString() {
        return "BatchResult[operations=" + operations.size() + ", succeeded=" + succeeded() + "]";
    }
}

package io.github.libtmux.batch;

/** What became of one operation in a batch. */
public enum OperationOutcome {
    /** tmux ran it and it succeeded. */
    COMPLETE,
    /** tmux ran it and it failed. Everything after it was discarded. */
    FAILED,
    /** tmux never reached it, because an earlier operation failed. */
    SKIPPED,
    /** Whether tmux applied it cannot be determined. */
    UNKNOWN
}

package io.github.libtmux.batch;

import java.util.List;
import kotlin.annotations.jvm.ReadOnly;

/**
 * One operation's own result within a batch.
 *
 * @param argv the operation as it was submitted
 * @param outcome what became of it
 * @param stdout the lines this operation produced, separated from its neighbours'
 * @param stderr the error text, which tmux emits without saying which operation produced it, so it
 *     is attached to the one that failed
 */
public record OperationResult(
        @ReadOnly List<String> argv,
        OperationOutcome outcome,
        @ReadOnly List<String> stdout,
        @ReadOnly List<String> stderr) {

    public OperationResult {
        argv = List.copyOf(argv);
        stdout = List.copyOf(stdout);
        stderr = List.copyOf(stderr);
    }

    /** Whether tmux ran this operation and it succeeded. */
    public boolean succeeded() {
        return outcome == OperationOutcome.COMPLETE;
    }

    /** Counts only: argv and output carry pane content and socket paths. */
    @Override
    public String toString() {
        return "OperationResult[" + outcome + ", argumentCount=" + argv.size() + ", stdoutLines=" + stdout.size() + "]";
    }
}

package io.github.libtmux;

/**
 * One tmux paste buffer, as a listing described it.
 *
 * @param name the buffer name, which is how every other buffer command addresses it
 * @param size how many bytes it holds
 */
public record BufferInfo(String name, int size) {}

package io.github.libtmux;

import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import io.github.libtmux.exception.LibTmuxException;
import io.github.libtmux.exception.ServerUnavailableException;
import io.github.libtmux.exception.TargetGoneException;
import io.github.libtmux.exception.UnsupportedFeatureException;
import io.github.libtmux.format.RowFormat;
import io.github.libtmux.transport.CommandResult;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import kotlin.annotations.jvm.ReadOnly;

/**
 * The tmux server's paste buffers.
 *
 * <p>Buffers are the server's, not a session's: anything copied in one session can be pasted into
 * another. They are addressed by name rather than by the stack position tmux also accepts, because
 * a position moves whenever anything else is copied.
 */
public final class Buffers {

    private static final RowFormat LISTING = RowFormat.of("buffer_name", "buffer_size");

    /**
     * tmux's own history dates the fix to {@code 0f6227f4} ("When deleting or renaming a buffer and
     * a buffer name is specified, complain if the buffer doesn't exist instead of silently deleting
     * or renaming the most recent buffer", GitHub issue 3205); {@code git tag --contains} places it
     * on {@code 3.4} and nothing earlier, so 3.3 and 3.3a both have the bug. Confirmed on the matrix:
     * {@code set-buffer -b a x; set-buffer -b b y; delete-buffer -b nope} answers {@code unknown
     * buffer: nope} on 3.4 and leaves both buffers, but on 3.3a it exits 0 and takes {@code b}, the
     * one {@code delete-buffer} was never told to touch.
     */
    static final TmuxVersion EXACT_NAMED_DELETE = new TmuxVersion(3, 4, "");

    private final Server server;

    Buffers(Server server) {
        this.server = server;
    }

    /**
     * Captures every buffer the server holds, in tmux's order.
     *
     * @return an immutable list, empty if the live server holds no buffers
     * @throws LibTmuxException if the listing fails, including when no daemon is running
     */
    @ReadOnly
    @Operation(Kind.READ)
    public List<BufferInfo> list() {
        List<BufferInfo> buffers = new ArrayList<>();
        var result = server.run(List.of("list-buffers", "-F", LISTING.template()));
        for (String row : result.stdout()) {
            List<String> fields = LISTING.split(row);
            buffers.add(new BufferInfo(fields.get(0), Integer.parseInt(fields.get(1))));
        }
        return List.copyOf(buffers);
    }

    /**
     * Puts text in a named buffer, replacing whatever was there.
     *
     * <p>The contents end the options, because they are the one argument here tmux would otherwise
     * read as flags: {@code set("clip", "-nfoo")} used to rename the buffer to {@code foo} and write
     * nothing, and report success.
     */
    @Operation(Kind.MUTATION)
    public void set(String name, String contents) {
        server.run(List.of("set-buffer", "-b", name, "--", contents));
    }

    /**
     * What a buffer holds, without any line breaks it ends with.
     *
     * <p>tmux prints a buffer as it is, and the transport drops trailing blank lines, so {@code "a"}
     * and {@code "a\n"} read the same. A marker printed after it cannot keep them: tmux writes a
     * buffer through its file stream, which a second command in the same invocation interrupts.
     * {@link #save} writes the exact bytes.
     *
     * @throws TargetGoneException if the server has no buffer by that name
     * @throws ServerUnavailableException if no daemon is running
     */
    @Operation(Kind.READ)
    public String show(String name) {
        CommandResult result = server.cmd(List.of("show-buffer", "-b", name));
        if (!result.succeeded() && result.stderr().stream().anyMatch(line -> line.equals("no buffer " + name))) {
            throw new TargetGoneException("no buffer named '" + name + "'");
        }
        if (!result.succeeded()) {
            throw server.failed("show-buffer", result);
        }
        return String.join("\n", result.stdout());
    }

    /**
     * Removes a buffer by its exact name.
     *
     * @throws TargetGoneException if the server has no buffer by that name
     * @throws ServerUnavailableException if no daemon is running
     * @throws UnsupportedFeatureException before tmux 3.4, whose named deletion silently removes the top
     *     buffer when the name is absent
     */
    @Operation(Kind.MUTATION)
    public void delete(String name) {
        TmuxVersion running = server.version();
        if (!running.atLeast(EXACT_NAMED_DELETE)) {
            throw new UnsupportedFeatureException("deleting a buffer by exact name", EXACT_NAMED_DELETE, running);
        }
        CommandResult result = server.cmd(List.of("delete-buffer", "-b", name));
        if (!result.succeeded() && result.stderr().stream().anyMatch(line -> line.equals("unknown buffer: " + name))) {
            throw new TargetGoneException("no buffer named '" + name + "'");
        }
        if (!result.succeeded()) {
            throw server.failed("delete-buffer", result);
        }
    }

    /** Writes a buffer's contents to a file. */
    @Operation(Kind.MUTATION)
    public void save(String name, Path file) {
        server.run(List.of("save-buffer", "-b", name, "--", file.toString()));
    }

    /** Reads a file into a named buffer. */
    @Operation(Kind.MUTATION)
    public void load(String name, Path file) {
        server.run(List.of("load-buffer", "-b", name, "--", file.toString()));
    }
}

package io.github.libtmux;

import io.github.libtmux.exception.UnsupportedFeatureException;
import java.util.ArrayList;
import java.util.List;
import org.jspecify.annotations.Nullable;

/**
 * What part of a pane to read, and how.
 *
 * <p>The shape {@link SplitSpec} uses. A plain {@link Pane#capture()} reads what is on screen; this
 * is how to reach the scrollback above it, or to keep what tmux otherwise strips.
 *
 * <p>Lines are numbered from the top of the visible area, so {@code 0} is the first row on screen
 * and negatives climb into the history. {@code fromStartOfHistory()} is the whole of what tmux
 * kept.
 *
 * <pre>{@code
 * List<String> everything = pane.capture(c -> c.fromStartOfHistory());
 * List<String> lastTen = pane.capture(c -> c.from(-10));
 * }</pre>
 */
public final class CaptureSpec {

    /**
     * {@code -T} arrived in 3.4, {@code -M} in 3.6, and {@code -H} and {@code -L} in 3.7 - confirmed
     * against every matrix release's own {@code list-commands} output, not only the two adjacent to
     * each floor. Not converted to a probe reading that output: a flag's presence there is not always
     * trustworthy evidence on its own - {@code cmd-split-window.c}'s own args spec shows {@code -l}
     * both declared to take a value and also listed among the boolean cluster in the generated usage
     * line, so a prober that trusted the cluster's shape alone would be reading a line tmux itself
     * gets inconsistent.
     */
    private static final TmuxVersion TRIM_SINCE = new TmuxVersion(3, 4, "");

    private static final TmuxVersion MODE_SCREEN_SINCE = new TmuxVersion(3, 6, "");

    private static final TmuxVersion HYPERLINKS_SINCE = new TmuxVersion(3, 7, "");

    private final @Nullable String start;
    private final @Nullable String end;
    private final boolean escapeSequences;
    private final boolean escapeNonPrintable;
    private final boolean joinWrapped;
    private final boolean preserveTrailing;
    private final boolean trimTrailing;
    private final boolean alternateScreen;
    private final boolean pendingOnly;
    private final boolean modeScreen;
    private final boolean hyperlinks;
    private final boolean lineNumbers;

    private CaptureSpec(Builder builder) {
        this.start = builder.start;
        this.end = builder.end;
        this.escapeSequences = builder.escapeSequences;
        this.escapeNonPrintable = builder.escapeNonPrintable;
        this.joinWrapped = builder.joinWrapped;
        this.preserveTrailing = builder.preserveTrailing;
        this.trimTrailing = builder.trimTrailing;
        this.alternateScreen = builder.alternateScreen;
        this.pendingOnly = builder.pendingOnly;
        this.modeScreen = builder.modeScreen;
        this.hyperlinks = builder.hyperlinks;
        this.lineNumbers = builder.lineNumbers;
    }

    /** A builder that reads what is on screen and nothing else. */
    public static Builder builder() {
        return new Builder();
    }

    /**
     * The command that reads the pane.
     *
     * @throws UnsupportedFeatureException if the spec asks for something {@code running} does not have
     */
    List<String> argv(String target, TmuxVersion running) {
        require(trimTrailing, TRIM_SINCE, running, "trimming trailing space");
        require(modeScreen, MODE_SCREEN_SINCE, running, "capturing the mode screen");
        require(hyperlinks, HYPERLINKS_SINCE, running, "capturing hyperlinks");
        require(lineNumbers, HYPERLINKS_SINCE, running, "capturing line numbers");

        List<String> argv = new ArrayList<>(20);
        argv.add("capture-pane");
        argv.add("-p");
        if (start != null) {
            argv.add("-S");
            argv.add(start);
        }
        if (end != null) {
            argv.add("-E");
            argv.add(end);
        }
        flag(argv, escapeSequences, "-e");
        flag(argv, escapeNonPrintable, "-C");
        flag(argv, joinWrapped, "-J");
        flag(argv, preserveTrailing, "-N");
        flag(argv, trimTrailing, "-T");
        flag(argv, alternateScreen, "-a");
        flag(argv, pendingOnly, "-P");
        flag(argv, modeScreen, "-M");
        flag(argv, hyperlinks, "-H");
        flag(argv, lineNumbers, "-L");
        argv.add("-t");
        argv.add(target);
        return List.copyOf(argv);
    }

    private static void flag(List<String> argv, boolean wanted, String flag) {
        if (wanted) {
            argv.add(flag);
        }
    }

    private static void require(boolean wanted, TmuxVersion since, TmuxVersion running, String feature) {
        if (wanted && !running.atLeast(since)) {
            throw new UnsupportedFeatureException(feature, since, running);
        }
    }

    /** Collects the choices, each named for what it does rather than for the flag it sets. */
    public static final class Builder {

        private @Nullable String start;
        private @Nullable String end;
        private boolean escapeSequences;
        private boolean escapeNonPrintable;
        private boolean joinWrapped;
        private boolean preserveTrailing;
        private boolean trimTrailing;
        private boolean alternateScreen;
        private boolean pendingOnly;
        private boolean modeScreen;
        private boolean hyperlinks;
        private boolean lineNumbers;

        private Builder() {}

        /**
         * Starts at a line, counted from the top of the visible area.
         *
         * @param line {@code 0} is the first row on screen; negatives climb into the scrollback
         */
        public Builder from(int line) {
            start = Integer.toString(line);
            return this;
        }

        /** Starts at the oldest line tmux still has. */
        public Builder fromStartOfHistory() {
            start = "-";
            return this;
        }

        /** Ends at a line, counted the same way as {@link #from}. */
        public Builder to(int line) {
            end = Integer.toString(line);
            return this;
        }

        /** Ends at the newest line, including anything below the visible area. */
        public Builder toEndOfHistory() {
            end = "-";
            return this;
        }

        /** Keeps the escape sequences that colour and position the text. */
        public Builder withEscapeSequences() {
            escapeSequences = true;
            return this;
        }

        /** Writes anything unprintable as an octal escape rather than dropping it. */
        public Builder escapingNonPrintable() {
            escapeNonPrintable = true;
            return this;
        }

        /** Joins a line tmux wrapped back into the one line it was. */
        public Builder joiningWrappedLines() {
            joinWrapped = true;
            return this;
        }

        /** Keeps the spaces at the end of a line, which tmux otherwise drops. */
        public Builder preservingTrailingSpace() {
            preserveTrailing = true;
            return this;
        }

        /** Drops trailing space and the empty lines below the content. Requires tmux 3.4. */
        public Builder trimmingTrailingSpace() {
            trimTrailing = true;
            return this;
        }

        /** Reads the alternate screen, which is what a full-screen program draws on. */
        public Builder fromAlternateScreen() {
            alternateScreen = true;
            return this;
        }

        /** Reads only output tmux has not drawn yet. */
        public Builder pendingOnly() {
            pendingOnly = true;
            return this;
        }

        /** Reads what a mode is showing rather than the pane beneath it. Requires tmux 3.6. */
        public Builder fromModeScreen() {
            modeScreen = true;
            return this;
        }

        /** Keeps hyperlink markers. Requires tmux 3.7. */
        public Builder withHyperlinks() {
            hyperlinks = true;
            return this;
        }

        /** Prefixes each line with its number. Requires tmux 3.7. */
        public Builder withLineNumbers() {
            lineNumbers = true;
            return this;
        }

        /** The finished spec. */
        public CaptureSpec build() {
            return new CaptureSpec(this);
        }
    }
}

package io.github.libtmux.catalog;

import static java.lang.annotation.ElementType.METHOD;
import static java.lang.annotation.ElementType.TYPE;
import static java.lang.annotation.RetentionPolicy.RUNTIME;

import java.lang.annotation.Documented;
import java.lang.annotation.Retention;
import java.lang.annotation.Target;

/**
 * Public for orchestration across processes or clients, such as the MCP server's pane
 * reservations; not part of the surface a language facade mirrors.
 */
@Documented
@Retention(RUNTIME)
@Target({TYPE, METHOD})
public @interface Advanced {}

package io.github.libtmux.catalog;

/**
 * What shape a facade needs to give one operation of the core API.
 *
 * <p>A Kotlin or Scala wrapper, or a generated reference page, reads this off {@link Operation}
 * rather than guessing from a method's name or return type.
 */
public enum Kind {

    /**
     * No tmux I/O: answers from the handle's own capture, or collects a command to send later. Field
     * accessors, navigation within one capture, and building a batch or chain.
     */
    CAPTURED,

    /** Contacts tmux and changes nothing: listings, captures, {@code show-*}, expansion, liveness, lookups. */
    READ,

    /** Changes tmux state: sending keys, renaming, killing, splitting, setting options, pasting, resizing. */
    MUTATION,

    /** Blocks until something else happens; the waiting itself changes nothing. */
    WAIT,

    /** Returns a subscription, stream, or publisher of events. */
    STREAM,

    /** Opens, attaches, derives, or closes a resource. */
    LIFECYCLE
}

package io.github.libtmux.catalog;

import static java.lang.annotation.ElementType.METHOD;
import static java.lang.annotation.RetentionPolicy.RUNTIME;

import java.lang.annotation.Documented;
import java.lang.annotation.Retention;
import java.lang.annotation.Target;

/**
 * Classifies one public method of the core API as a tmux operation of a given {@link Kind}.
 *
 * <p>Every public method that performs or describes a tmux operation carries this, so a facade
 * never has to infer the shape of a call from its name or signature.
 */
@Documented
@Retention(RUNTIME)
@Target(METHOD)
public @interface Operation {

    /** What shape this operation gives a facade. */
    Kind value();

    /**
     * The first tmux release that has this operation, when it is newer than the supported floor,
     * 3.2a. Empty when the whole supported range has it.
     */
    String tmuxSince() default "";
}

package io.github.libtmux;

import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import java.time.Duration;
import java.util.Objects;

/**
 * One of tmux's wait-for channels, named once.
 *
 * <p>A channel is server-wide and shared by everything on it, including programs running in panes.
 * Nothing creates or destroys one: a name either has a signal remembered against it or does not.
 *
 * <p>tmux's own {@code wait-for} has two traps, and this exists to close both. It exits successfully
 * when the server dies under the waiter, which is indistinguishable from a real signal, so the
 * server is checked afterwards rather than believed. And a signal sent when nobody is waiting is
 * remembered, satisfying the next wait whenever that happens — possibly in a later run of a
 * different program — so {@link #drain()} is how a caller starts from a known state on a channel
 * whose history is not its own.
 */
public final class Channel {

    /** Long enough for a pending signal to come straight back, short enough not to be a wait. */
    private static final Duration DRAIN_TIMEOUT = Duration.ofMillis(250);

    private final Server server;
    private final String name;

    Channel(Server server, String name) {
        this.server = server;
        this.name = Objects.requireNonNull(name, "name");
    }

    /** The name this channel is known by on its server. */
    @Operation(Kind.CAPTURED)
    public String name() {
        return name;
    }

    /**
     * Signals the channel, waking one waiter, or being remembered until something waits.
     *
     * <p>{@code -S} takes no argument of its own — it says which of wait-for's three modes this is —
     * so the name that follows is a positional and needs the options ended before it, exactly as
     * the wait does.
     */
    @Operation(Kind.MUTATION)
    public void signal() {
        server.run(java.util.List.of("wait-for", "-S", "--", name));
    }

    /**
     * Waits for something to signal the channel.
     *
     * @param timeout how long to wait
     * @return why the wait ended, which is never simply "successfully"
     * @throws InterruptedException if the waiting thread is interrupted, which is a cancellation
     *     rather than a timeout and so is not reported as one
     */
    @Operation(Kind.WAIT)
    public WakeReason await(Duration timeout) throws InterruptedException {
        return server.awaitChannel(name, timeout, false);
    }

    /**
     * Waits while preserving process capacity for a call through this server that signals it.
     *
     * <p>Use this when the waiter and its release share a bounded transport. A wait released outside
     * that transport should use {@link #await}; reserving capacity for it only rejects useful
     * concurrency.
     *
     * @throws io.github.libtmux.exception.DispatchException if the wait could not be dispatched
     * @throws InterruptedException if the waiting thread is interrupted, which is a cancellation
     *     rather than a timeout and so is not reported as one
     */
    @Operation(Kind.WAIT)
    public WakeReason awaitReservingCapacity(Duration timeout) throws InterruptedException {
        return server.awaitChannel(name, timeout, true);
    }

    /**
     * Consumes a signal already waiting, so a stale one cannot satisfy a later wait.
     *
     * @return whether a signal was there to consume
     * @throws InterruptedException if the waiting thread is interrupted
     */
    @Operation(Kind.WAIT)
    public boolean drain() throws InterruptedException {
        return await(DRAIN_TIMEOUT) == WakeReason.SIGNALLED;
    }

    @Override
    public String toString() {
        return "Channel[" + name + "]";
    }
}

package io.github.libtmux;

import com.google.errorprone.annotations.CheckReturnValue;
import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import io.github.libtmux.exception.ServerUnavailableException;
import io.github.libtmux.exception.TargetGoneException;
import io.github.libtmux.snapshot.ClientState;
import io.github.libtmux.snapshot.ServerSnapshot;
import java.util.List;
import java.util.Objects;
import java.util.Optional;

/**
 * One attached tmux client, as one capture saw it.
 *
 * <p>Identity is the server and the client name, which is how tmux addresses it. What it is
 * attached to is state: a client can switch sessions without becoming a different client.
 *
 * <p>{@link #name()}, {@link #session()}, and {@link #attachment()} return what the capture holds
 * and do no I/O; {@link #refresh()} reads again. Every other method asks tmux now.
 */
public final class Client {

    private final Server server;
    private final ServerSnapshot snapshot;
    private final ClientState state;

    Client(Server server, ServerSnapshot snapshot, ClientState state) {
        this.server = server;
        this.snapshot = snapshot;
        this.state = state;
    }

    /** The client's terminal name, which is how tmux addresses it. */
    @Operation(Kind.CAPTURED)
    public String name() {
        return state.name();
    }

    /**
     * Detaches this client, leaving whatever it was attached to running.
     *
     * <p>Detaching is not killing: the session outlives the client, which is the reason tmux exists.
     */
    @Operation(Kind.MUTATION)
    public void detach() {
        server.run(snapshot, List.of("detach-client", "-t", state.name()));
    }

    /** Detaches every other client, leaving this one attached. */
    @Operation(Kind.MUTATION)
    public void detachOthers() {
        server.run(snapshot, List.of("detach-client", "-a", "-t", state.name()));
    }

    /**
     * Moves this client to another session.
     *
     * <p>The client keeps its identity: switching is a change of what it is looking at, not a
     * detach and a fresh attach.
     */
    @Operation(Kind.MUTATION)
    public void switchTo(Session session) {
        Objects.requireNonNull(session, "session");
        server.requireSameIncarnation(snapshot, session.server(), session.snapshot());
        server.run(
                snapshot,
                List.of("switch-client", "-c", state.name(), "-t", session.id().value()));
    }

    /**
     * Asks tmux to redraw this client.
     *
     * <p>Not {@link #refresh()}, which takes a new capture of what tmux knows. This one is tmux's
     * {@code refresh-client}, and it changes the terminal rather than this handle.
     */
    @Operation(Kind.MUTATION)
    public void redraw() {
        server.run(snapshot, List.of("refresh-client", "-t", state.name()));
    }

    /** The server this client is connected to. */
    @Operation(Kind.CAPTURED)
    public Server server() {
        return server;
    }

    ServerSnapshot snapshot() {
        return snapshot;
    }

    /** The session this client was attached to when captured. A pure read of the capture. */
    @Operation(Kind.CAPTURED)
    public Optional<Session> session() {
        return state.session().flatMap(snapshot::session).map(session -> new Session(server, snapshot, session));
    }

    /**
     * What this client was looking at when captured. A pure read: it issues no command.
     *
     * <p>Empty when the capture shows the client attached to nothing, or shows a session whose
     * active window or pane the capture did not include.
     */
    @Operation(Kind.CAPTURED)
    public Optional<ClientAttachment> attachment() {
        return session()
                .flatMap(session -> session.activeWindow()
                        .flatMap(window ->
                                window.activePane().map(pane -> new ClientAttachment(session, window, pane))));
    }

    /**
     * Takes a new capture and returns what this client is looking at now.
     *
     * <p>Named to say it dispatches, unlike {@link #attachment()}. Every call is one live capture.
     *
     * @throws TargetGoneException if this client has detached
     */
    @Operation(Kind.READ)
    public Optional<ClientAttachment> fetchAttachment() {
        return refresh().attachment();
    }

    /**
     * Takes a new capture and returns this client as it is now.
     *
     * <p>This handle remains unchanged, as every handle's does.
     *
     * @throws TargetGoneException if this client has detached, or a different daemon answers on the
     *     endpoint
     * @throws ServerUnavailableException if no daemon is running
     */
    @CheckReturnValue
    @Operation(Kind.READ)
    public Client refresh() {
        ServerSnapshot fresh = server.refresh(snapshot);
        return fresh.clients().stream()
                .filter(client -> client.name().equals(state.name()))
                .findFirst()
                .map(client -> new Client(server, fresh, client))
                .orElseThrow(() -> new TargetGoneException("client " + state.name() + " has detached"));
    }

    @Override
    public boolean equals(Object other) {
        return other instanceof Client that
                && server.identity(snapshot).equals(that.server.identity(that.snapshot))
                && state.name().equals(that.state.name());
    }

    @Override
    public int hashCode() {
        return Objects.hash(server.identity(snapshot), state.name());
    }

    @Override
    public String toString() {
        return "Client[" + state.name() + "]";
    }
}

package io.github.libtmux;

import io.github.libtmux.batch.Batch;
import io.github.libtmux.batch.BatchResult;
import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import io.github.libtmux.exception.UnsupportedFeatureException;
import java.util.List;
import java.util.Objects;
import java.util.function.Supplier;

/**
 * A sequence of tmux commands where each one acts on what the last one made.
 *
 * <p>tmux moves its own current target as a group runs: a {@code new-window} makes the new window
 * current, a following {@code split-window} splits that window, and a following {@code send-keys}
 * types into the pane that split produced. None of these steps names a target, and that is the
 * point — the alternative is a round trip per step to learn the id of the thing just created.
 *
 * <p>The whole chain is one tmux invocation, and every step is attributed individually, so a chain
 * that fails halfway says which step failed and which never ran.
 */
public final class CommandChain {

    private final Batch batch;
    private final Supplier<TmuxVersion> running;

    CommandChain(Batch batch, Supplier<TmuxVersion> running) {
        this.batch = batch;
        this.running = running;
    }

    /** Creates a window and makes it the one following steps act on. */
    @Operation(Kind.CAPTURED)
    public CommandChain newWindow(String name) {
        return then("new-window", "-n", name);
    }

    /** Renames the current window. */
    @Operation(Kind.CAPTURED)
    public CommandChain renameWindow(String name) {
        return then("rename-window", "--", name);
    }

    /**
     * Splits the current pane into a left and a right one.
     *
     * <p>Named for what it produces rather than for tmux's {@code -h}, which reads as though it
     * described the divider.
     */
    @Operation(Kind.CAPTURED)
    public CommandChain splitLeftRight() {
        return then("split-window", "-h");
    }

    /** Splits the current pane into a top and a bottom one. */
    @Operation(Kind.CAPTURED)
    public CommandChain splitTopBottom() {
        return then("split-window", "-v");
    }

    /** Types a line into the current pane and presses Enter, which is how a command gets run. */
    @Operation(Kind.CAPTURED)
    public CommandChain sendLine(String command) {
        return then("send-keys", "-l", "--", Objects.requireNonNull(command, "command") + "\r");
    }

    /**
     * Arranges the current window.
     *
     * @throws IllegalArgumentException if tmux would not recognise the layout, which on some
     *     versions ends the whole server rather than the command
     * @throws UnsupportedFeatureException if the layout name arrived after this release, which
     *     tmux cannot tell from any other name it does not know
     */
    @Operation(Kind.MUTATION)
    public CommandChain arrange(String layout) {
        return then("select-layout", Layouts.require(layout, running.get()));
    }

    /** Adds any tmux command, for whatever this class does not name. */
    @Operation(Kind.CAPTURED)
    public CommandChain then(String... argv) {
        batch.add(argv);
        return this;
    }

    /** Adds any tmux command. */
    @Operation(Kind.CAPTURED)
    public CommandChain then(List<String> argv) {
        batch.add(argv);
        return this;
    }

    /** Runs the whole chain in one tmux invocation, attributing each step. */
    @Operation(Kind.MUTATION)
    public BatchResult run() {
        return batch.run();
    }
}

package io.github.libtmux;

import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import java.util.List;
import kotlin.annotations.jvm.ReadOnly;

/** The commands this tmux knows, read without starting a server to answer. */
public final class Commands {

    private final Server server;

    Commands(Server server) {
        this.server = server;
    }

    /** Every command, as tmux prints it. */
    @ReadOnly
    @Operation(Kind.READ)
    public List<String> list() {
        return server.withoutStartingServer(List.of("list-commands")).stdout();
    }
}

package io.github.libtmux.control;

import io.github.libtmux.PaneId;
import io.github.libtmux.ServerConfig;
import io.github.libtmux.SessionId;
import io.github.libtmux.batch.OperationOutcome;
import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import io.github.libtmux.exception.CommandRejectedException;
import io.github.libtmux.exception.ControlEndedException;
import io.github.libtmux.exception.DispatchException;
import io.github.libtmux.exception.LibTmuxException;
import io.github.libtmux.exception.MalformedResponseException;
import io.github.libtmux.exception.TargetGoneException;
import io.github.libtmux.internal.ErrorText;
import io.github.libtmux.internal.ProcessTree;
import io.github.libtmux.internal.Utf8;
import io.github.libtmux.transport.ControlCarrier;
import io.github.libtmux.transport.DispatchOutcome;
import io.github.libtmux.transport.OperationObserver;
import io.github.libtmux.transport.OperationReport;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStreamWriter;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.OptionalInt;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;

/**
 * A tmux client that stays attached and answers one command at a time.
 *
 * <p>This is what a semicolon group cannot be. tmux discards a group after its first failure, so a
 * client has to infer which command failed; here each request is independent, so a failure
 * discards nothing behind it.
 *
 * <p>Replies arrive in request order, so the writer sends one request at a time and matches its
 * reply by position. A reply is the first block tmux writes for the request: an acknowledgement,
 * which work the command deferred may outlive. What that command queued, as {@code if-shell}
 * queues its branch, and what a hook ran, arrive as blocks of their own, and none of them is taken
 * for the next request's reply. A deadline before the writer picks a request writes nothing; a
 * deadline after that point ends the client because the next reply could no longer be attributed
 * safely.
 *
 * <p>The reader and writer are platform threads. A library does not own the virtual-thread
 * scheduler: a caller's CPU-bound task that never blocks keeps its carrier, and either thread
 * unable to run stops the client from making progress. The reader only
 * resolves replies and fills bounded subscription buffers; subscriber code runs on the thread that
 * pulls a value.
 *
 * <p><strong>Threads.</strong> {@link #send} may be called from several threads at once: requests
 * queue in the order they arrive and each caller gets its own reply. A subscription is read by one
 * thread at a time.
 *
 * <p><strong>Close it.</strong> The client holds an attached tmux client, which is what makes tmux
 * push output to it, and closing is what detaches that client and stops its threads. A client that
 * is forgotten does not hold the JVM open — its threads are daemons — and the attached tmux client
 * exits once the JVM does, because it reads its commands from a pipe that closes with it. Until then
 * it is listed among the session's clients like any other.
 */
public final class ControlClient implements AutoCloseable {

    private static final Duration DEFAULT_TIMEOUT = Duration.ofSeconds(30);

    private static final ControlCarrier LOCAL = command -> new ProcessBuilder(command).start();

    /** The same seam as the process transport's, since this client starts its own process. */
    private static final System.Logger LOG = System.getLogger(ControlClient.class.getName());

    private static final long EXIT_MILLIS = 5_000;

    private final Process process;
    private final ProcessTree processTree;
    private final InputStream standardOutput;
    private final InputStream standardError;
    private final ControlWriter writer;
    private final Thread reader;
    private final Thread errorReader;
    private final ControlProtocol protocol = new ControlProtocol();
    private final List<EventSubscription<PaneOutput>> outputSubscriptions = new CopyOnWriteArrayList<>();
    // Each pane's output decoded as one stream. Touched only by the reader thread.
    private final java.util.Map<PaneId, Utf8.Stream> paneText = new java.util.HashMap<>();
    private final List<EventSubscription<ControlEvent>> eventSubscriptions = new CopyOnWriteArrayList<>();
    private final AtomicBoolean closed = new AtomicBoolean();
    private final OperationObserver observer;
    private final AtomicLong ids = new AtomicLong();
    private volatile boolean failed;

    /** Set before subscribers hear of the end, so none of them can find this client alive after it. */
    private volatile boolean readerEnded;

    private volatile boolean subscriptionsClosed;
    private static final int STDERR_LIMIT = 4096;
    private final byte[] stderrBytes = new byte[STDERR_LIMIT];
    private int stderrLength;
    private boolean stderrTruncated;

    private ControlClient(Process process, OperationObserver observer) {
        this.process = process;
        this.observer = observer;
        this.processTree = new ProcessTree(process);
        this.standardOutput = process.getInputStream();
        this.standardError = process.getErrorStream();
        BufferedWriter requests =
                new BufferedWriter(new OutputStreamWriter(process.getOutputStream(), StandardCharsets.UTF_8));
        this.writer = new ControlWriter(requests, ControlWriter.DEFAULT_CAPACITY, this::terminate);
        // Daemons, unlike the process transport's drains. Those let go once idle, which is what
        // stops a forgotten transport holding the JVM; these are attached to a live tmux and are
        // never idle, so the same treatment would not help and a forgotten client kept the JVM alive
        // forever — for a command-line program, indistinguishable from a deadlock. Nothing is lost by
        // letting go at exit: send() blocks its caller until the reply arrives, so a call in flight
        // is held by the thread that made it.
        this.reader = new Thread(this::read, "libtmux-control");
        this.reader.setDaemon(true);
        this.errorReader = new Thread(this::drainErrors, "libtmux-control-stderr");
        this.errorReader.setDaemon(true);
        this.errorReader.start();
    }

    /**
     * Attaches a control client to whatever server now answers this endpoint.
     *
     * <p>Attaching is what makes tmux push {@code %output}: a control client that never attaches is
     * told about command replies and nothing else.
     *
     * <p>This does not check which tmux process answered. A socket can be taken over by a new
     * server that reuses the same session id. {@link io.github.libtmux.Server#control} attaches to
     * the process a capture already named; prefer it.
     *
     * @param config which tmux and which server
     * @param session the session to attach to
     */
    @Operation(Kind.LIFECYCLE)
    public static ControlClient attachUnfenced(ServerConfig config, SessionId session) {
        return attachUnfenced(config, session, DEFAULT_TIMEOUT);
    }

    /**
     * As {@link #attachUnfenced(ServerConfig, SessionId)}, waiting up to the supplied deadline for
     * the client's opening reply.
     *
     * @param config which tmux and which server
     * @param session the session to attach to
     * @param timeout how long to wait for the client to become ready
     */
    @Operation(Kind.LIFECYCLE)
    public static ControlClient attachUnfenced(ServerConfig config, SessionId session, Duration timeout) {
        ControlClient client = connect(LOCAL, config, session, timeout);
        client.finishAttach(session);
        return client;
    }

    /**
     * Attaches, then leaves unless the live server is still the process that was captured.
     *
     * <p>A pid can be reused, so the version tmux reports is part of the check. A mismatch detaches
     * before this client changes the server: layout refresh runs only after the check passes.
     *
     * @param serverPid the tmux process a capture recorded
     * @param serverVersion the version text that process reported, compared as text
     */
    @Operation(Kind.LIFECYCLE)
    public static ControlClient attach(
            ServerConfig config, SessionId session, long serverPid, String serverVersion, Duration timeout) {
        return attach(LOCAL, config, session, serverPid, java.util.OptionalLong.empty(), serverVersion, timeout);
    }

    /**
     * As {@link #attach(ServerConfig, SessionId, long, String, Duration)}, started by the carrier
     * that also starts this realm's commands, and checking the start time a capture recorded too.
     *
     * @param serverStartTime when the captured process started, as {@code #{start_time}} reported it;
     *     compared when present, since a restarted tmux can be given the same pid and version
     */
    @Operation(Kind.LIFECYCLE)
    public static ControlClient attach(
            ControlCarrier carrier,
            ServerConfig config,
            SessionId session,
            long serverPid,
            java.util.OptionalLong serverStartTime,
            String serverVersion,
            Duration timeout) {
        Objects.requireNonNull(serverVersion, "serverVersion");
        if (serverPid < 1) {
            throw new IllegalArgumentException("serverPid is not positive: " + serverPid);
        }
        ControlClient client = connect(carrier, config, session, timeout);
        try {
            client.confirmIncarnation(serverPid, serverStartTime, serverVersion);
        } catch (RuntimeException failure) {
            client.closeAfterFailure(failure);
            throw failure;
        }
        client.finishAttach(session);
        return client;
    }

    private static ControlClient connect(
            ControlCarrier carrier, ServerConfig config, SessionId session, Duration timeout) {
        Objects.requireNonNull(carrier, "carrier");
        Objects.requireNonNull(config, "config");
        Objects.requireNonNull(session, "session");
        Objects.requireNonNull(timeout, "timeout");
        if (timeout.isZero() || timeout.isNegative()) {
            throw new IllegalArgumentException("timeout is not positive");
        }
        List<String> command = new ArrayList<>(config.endpointCommand());
        command.addAll(List.of("-C", "attach-session", "-t", session.value()));
        // The same guard CommandRequest applies to every other process this library starts. A
        // control client's own commands travel as UTF-8 over its standard input and are unaffected,
        // but this argv is encoded by the JVM like any other.
        Utf8.requireEncodableArguments(command);
        Process process;
        try {
            process = carrier.start(command);
        } catch (IOException e) {
            throw new DispatchException.Failed("could not start a control client", DispatchOutcome.NOT_DISPATCHED, e);
        }
        ControlClient client = new ControlClient(process, config.observer());
        // Attaching produces a reply of its own. It is awaited like any other, which is also what
        // proves the client is up before the first command is written.
        ControlWriter.Request attached = client.writer.expectInitial(timeout);
        client.reader.start();
        ControlReply reply;
        try {
            reply = client.writer.await(attached);
        } catch (DispatchException e) {
            client.closeAfterFailure(e);
            throw e;
        }
        if (reply.outcome() != OperationOutcome.COMPLETE) {
            LibTmuxException failure = new CommandRejectedException(
                    "the control client did not become ready" + ErrorText.suffix(reply.lines()),
                    "attach-session",
                    -1,
                    reply.lines());
            client.closeAfterFailure(failure);
            throw failure;
        }
        client.writer.start();
        return client;
    }

    /** Reads the live server and detaches, via the caller, when it is not the one that was named. */
    private void confirmIncarnation(long expectedPid, java.util.OptionalLong expectedStart, String expectedVersion) {
        // The start time leads: it is a number, and the version, compared as text, may hold a space.
        ControlReply reply = send("display-message", "-p", "#{start_time} #{pid} #{version}");
        if (!reply.succeeded() || reply.lines().size() != 1) {
            throw new CommandRejectedException(
                    "could not read the control client's server" + ErrorText.suffix(reply.lines()),
                    "display-message",
                    -1,
                    reply.lines());
        }
        String[] reported = reply.lines().get(0).split(" ", 3);
        long started;
        long pid;
        try {
            started = Long.parseLong(reported[0]);
            pid = Long.parseLong(reported.length > 1 ? reported[1] : "");
        } catch (NumberFormatException e) {
            throw new MalformedResponseException("tmux reported a malformed server identity");
        }
        String version = reported.length > 2 ? reported[2] : "";
        if (pid != expectedPid
                || !version.equals(expectedVersion)
                || (expectedStart.isPresent() && started != expectedStart.getAsLong())) {
            throw new TargetGoneException("the tmux server this handle belonged to has ended");
        }
    }

    private void finishAttach(SessionId session) {
        requestJsonLayouts();
        LOG.log(System.Logger.Level.DEBUG, "tmux control client attached to session {0}", session.value());
    }

    /**
     * Asks tmux to report layouts as JSON on notifications this client receives, matching what a
     * plain client already gets from {@code #{window_layout}} on tmux 3.8+.
     *
     * <p>Without this, this client's own {@code %layout-change} carries the classic string even on a
     * server new enough to write JSON elsewhere: the same window's layout then disagrees depending
     * on which kind of client read it — the mismatch a {@code watch}ed layout format or a parsed
     * notification would otherwise hit. Measured harmless back to 3.2a: {@code refresh-client -f
     * new-layouts} completes with no error on every supported release, just with nothing to change
     * before 3.8, so this is sent unconditionally rather than gated on a version.
     */
    private void requestJsonLayouts() {
        ControlReply reply = send("refresh-client", "-f", "new-layouts");
        if (reply.outcome() != OperationOutcome.COMPLETE) {
            LibTmuxException failure = new CommandRejectedException(
                    "could not request JSON layouts on attach" + ErrorText.suffix(reply.lines()),
                    "refresh-client",
                    -1,
                    reply.lines());
            closeAfterFailure(failure);
            throw failure;
        }
    }

    /** Runs one command and waits for its reply. */
    @Operation(Kind.MUTATION)
    public ControlReply send(String... argv) {
        return send(List.of(argv), DEFAULT_TIMEOUT);
    }

    /** Runs one command and waits for its reply. */
    @Operation(Kind.MUTATION)
    public ControlReply send(List<String> argv) {
        return send(argv, DEFAULT_TIMEOUT);
    }

    /**
     * Runs one command and waits for its reply.
     *
     * @param argv the command, its arguments already separate elements
     * @param timeout how long to wait for tmux to answer
     * @return tmux's reply
     * @throws DispatchException if the request cannot complete; its {@link
     *     DispatchException#outcome() outcome} is {@link DispatchOutcome#NOT_DISPATCHED} until
     *     the writer picks the request and {@link DispatchOutcome#UNKNOWN} afterwards
     */
    @Operation(Kind.MUTATION)
    public ControlReply send(List<String> argv, Duration timeout) {
        if (argv.isEmpty()) {
            throw new IllegalArgumentException("a command has no words");
        }
        Objects.requireNonNull(timeout, "timeout");
        if (timeout.isZero() || timeout.isNegative()) {
            throw new IllegalArgumentException("timeout is not positive");
        }
        if (closed.get() || failed) {
            throw new IllegalStateException("control client is not usable");
        }
        long started = System.nanoTime();
        try {
            ControlReply reply = writer.exchange(line(argv), timeout);
            long[] timing = writer.takeTiming(System.nanoTime() - started);
            report(argv.get(0), reply, timing);
            if (LOG.isLoggable(System.Logger.Level.DEBUG)) {
                LOG.log(
                        System.Logger.Level.DEBUG,
                        "tmux control {0} {1} in {2} ms",
                        argv.get(0),
                        reply.outcome()
                                .name()
                                .toLowerCase(java.util.Locale.ROOT)
                                .replace('_', ' '),
                        TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - started));
            }
            return reply;
        } catch (RuntimeException failure) {
            long[] timing = writer.takeTiming(System.nanoTime() - started);
            DispatchOutcome certainty =
                    failure instanceof DispatchException transport ? transport.outcome() : DispatchOutcome.UNKNOWN;
            try {
                observer.accept(new OperationReport(
                        ids.incrementAndGet(),
                        List.of(argv.get(0)),
                        certainty,
                        OptionalInt.empty(),
                        0,
                        0,
                        "",
                        Duration.ofNanos(timing[0]),
                        Duration.ofNanos(timing[1])));
            } catch (RuntimeException observerFailure) {
                LOG.log(System.Logger.Level.WARNING, "operation observer failed", observerFailure);
            }
            throw failure;
        }
    }

    private void report(String verb, ControlReply reply, long[] timing) {
        int exit = reply.succeeded() ? 0 : 1;
        try {
            observer.accept(new OperationReport(
                    ids.incrementAndGet(),
                    List.of(verb),
                    DispatchOutcome.COMPLETE,
                    OptionalInt.of(exit),
                    reply.lines().size(),
                    0,
                    "",
                    Duration.ofNanos(timing[0]),
                    Duration.ofNanos(timing[1])));
        } catch (RuntimeException failure) {
            LOG.log(System.Logger.Level.WARNING, "operation observer failed", failure);
        }
    }

    /**
     * Whether the client is still running.
     *
     * <p>A control client is a client of the server it talks to, so it ends when that server does.
     * A carrier holding one needs to tell "this command failed" from "there is no longer anything
     * to send commands to", which are the same exception until this is asked.
     */
    @Operation(Kind.CAPTURED)
    public boolean isAlive() {
        return !closed.get() && !failed && !readerEnded && process.isAlive();
    }

    /**
     * Subscribes to terminal output tmux pushes.
     *
     * @param capacity how many values this subscriber can retain before its oldest value is dropped
     * @return a pull subscription owned by the caller
     * @throws IllegalArgumentException if {@code capacity} is not positive
     * @throws IllegalStateException if the client has ended
     */
    @Operation(Kind.STREAM)
    public EventSubscription<PaneOutput> subscribeOutput(int capacity) {
        return subscribe(outputSubscriptions, capacity);
    }

    /**
     * Subscribes to state changes tmux volunteers.
     *
     * @param capacity how many values this subscriber can retain before its oldest value is dropped
     * @return a pull subscription owned by the caller
     * @throws IllegalArgumentException if {@code capacity} is not positive
     * @throws IllegalStateException if the client has ended
     */
    @Operation(Kind.STREAM)
    public EventSubscription<ControlEvent> subscribeEvents(int capacity) {
        return subscribe(eventSubscriptions, capacity);
    }

    /**
     * Asks tmux to report a format whenever its value changes.
     *
     * <p>tmux re-expands the format about once a second and writes a {@code subscription-changed}
     * event only when the result differs from last time, so the comparison happens in the server and
     * a client that subscribes does nothing at all between changes. This is what makes watching a
     * server cost nothing while it is idle.
     *
     * @param name what to call it; registering the same name again replaces the old one
     * @param target {@code %*} for every pane, {@code @*} for every window, a specific {@code %id} or
     *     {@code @id}, or the attached session (pass {@code ""} - see below)
     * @param format a tmux format, such as {@code #{pane_current_command}}
     */
    @Operation(Kind.MUTATION)
    public ControlReply watch(String name, String target, String format) {
        return send("refresh-client", "-B", name + ":" + sessionScopeNormalized(target) + ":" + format);
    }

    /**
     * tmux(1) documents {@code refresh-client -B name:what:format}'s {@code what} as empty,
     * {@code %N}, {@code %*}, {@code @N} or {@code @*} only - a session id or an arbitrary word was
     * never a spelling the manual promises, even though 3.2a and 3.7c happen to accept one leniently
     * (confirmed against the matrix). On master the same non-empty, non-{@code %}/{@code @} target
     * is accepted by the parser but delivers nothing, silently. The empty string is the one
     * spelling confirmed to mean "the attached session" and to actually fire on every tested release,
     * so anything that does not name a pane or window is normalized to it rather than passed through.
     */
    private static String sessionScopeNormalized(String target) {
        return target.startsWith("%") || target.startsWith("@") ? target : "";
    }

    /** Stops a watch. tmux reads a name with no colon in it as one to remove. */
    @Operation(Kind.MUTATION)
    public ControlReply unwatch(String name) {
        return send("refresh-client", "-B", name);
    }

    /** Ends the client, rejecting queued requests and resolving picked requests as uncertain. */
    @Operation(Kind.LIFECYCLE)
    @Override
    public void close() {
        boolean closeOwner = closed.compareAndSet(false, true);
        if (closeOwner) {
            processTree.captureDescendants();
            writer.close();
            closeSubscriptions(null);
        }
        boolean reclaimed = processTree.terminate();
        if (!closeOwner) {
            if (!reclaimed) {
                throw new IllegalStateException("control process tree was not reclaimed");
            }
            return;
        }
        AtomicBoolean interrupted = new AtomicBoolean(Thread.interrupted());
        if (!Thread.currentThread().equals(reader)) {
            join(reader, EXIT_MILLIS, interrupted);
        }
        if (!Thread.currentThread().equals(errorReader)) {
            join(errorReader, EXIT_MILLIS, interrupted);
        }
        join(writer, EXIT_MILLIS, interrupted);
        if (interrupted.get()) {
            Thread.currentThread().interrupt();
        }
        if (!reclaimed) {
            throw new IllegalStateException("control process tree was not reclaimed");
        }
    }

    private void closeAfterFailure(RuntimeException failure) {
        try {
            close();
        } catch (RuntimeException cleanup) {
            failure.addSuppressed(cleanup);
        }
    }

    // -------------------------------------------------------------------------------- protocol

    /**
     * tmux parses a control-mode request as one line, so an argument has to survive its lexer.
     * Single quotes preserve everything except a single quote, which is closed, escaped and
     * reopened.
     */
    static String line(List<String> argv) {
        return ControlProtocol.line(argv);
    }

    private void read() {
        Throwable readerFailure = null;
        try (var lines = new ControlLineReader(standardOutput, ControlProtocol.DEFAULT_MAX_REPLY_BYTES)) {
            ControlLineReader.Line line;
            while ((line = lines.readLine()) != null) {
                ControlProtocol.Result result = protocol.accept(line.text(), line.encodedBytes());
                if (result instanceof ControlProtocol.Reply reply) {
                    complete(reply.outcome(), reply.lines(), reply.requested());
                } else if (result instanceof ControlProtocol.Notification notification) {
                    handleNotification(notification.line(), line.bytes());
                }
            }
        } catch (IOException | ControlProtocol.LimitExceeded e) {
            readerFailure = e;
        } finally {
            readerEnded = true;
            closeSubscriptions(
                    readerFailure == null && closed.get()
                            ? null
                            : new ControlEndedException(standardError(), stderrTruncated, readerFailure));
            writer.readerEnded();
        }
    }

    private void drainErrors() {
        try (standardError) {
            byte[] buffer = new byte[512];
            int read;
            while ((read = standardError.read(buffer)) >= 0) {
                synchronized (stderrBytes) {
                    int room = stderrBytes.length - stderrLength;
                    int take = Math.min(room, read);
                    if (take > 0) {
                        System.arraycopy(buffer, 0, stderrBytes, stderrLength, take);
                        stderrLength += take;
                    }
                    if (take < read) {
                        stderrTruncated = true;
                    }
                }
            }
        } catch (IOException e) {
            // Closing or ending the client closes this channel too.
        }
    }

    /**
     * The error text captured from this control process, at most 4096 bytes.
     *
     * <p>Empty when the process wrote none. {@link #standardErrorTruncated()} says the stream
     * continued past that bound. The text is whatever had been read when this is called.
     */
    @Operation(Kind.CAPTURED)
    public String standardError() {
        synchronized (stderrBytes) {
            return new String(stderrBytes, 0, stderrLength, StandardCharsets.UTF_8);
        }
    }

    /** Whether {@link #standardError()} stopped before the process finished writing it. */
    @Operation(Kind.CAPTURED)
    public boolean standardErrorTruncated() {
        synchronized (stderrBytes) {
            return stderrTruncated;
        }
    }

    private void handleNotification(String line, byte[] bytes) {
        if (line.startsWith("%output ")) {
            publish(bytes, "%output ".length());
        } else if (line.startsWith("%extended-output ")) {
            // What %output becomes once this client turns on tmux's flow control, pause-after:
            // the pane, how long the output waited, then the same escaped bytes after " : ".
            publish(bytes, "%extended-output ".length());
        } else if (line.startsWith("%")) {
            // Everything else tmux volunteers about its own state. A snapshot is still how state
            // is read; this only says when reading it again would be worth the trouble.
            ControlEvent.parse(line).ifPresent(this::announce);
        }
    }

    private void complete(OperationOutcome outcome, List<String> block, boolean requested) {
        writer.complete(outcome, block, requested);
    }

    private void terminate(DispatchException failure) {
        failed = true;
        closeSubscriptions(failure);
        if (!processTree.terminate()) {
            failure.addSuppressed(new IllegalStateException("control process tree was not reclaimed"));
        }
    }

    /**
     * One piece of a pane's output. tmux cuts pieces by byte count, so each pane's text is decoded
     * as one stream, and a character cut between two pieces arrives whole with the later one.
     */
    private void publish(byte[] line, int start) {
        int paneEnd = start;
        while (paneEnd < line.length && line[paneEnd] != ' ') {
            paneEnd++;
        }
        int data = start == "%output ".length() ? paneEnd + 1 : separatorEnd(line, paneEnd);
        if (paneEnd == line.length || data > line.length) {
            return;
        }
        PaneId pane = new PaneId(new String(line, start, paneEnd - start, StandardCharsets.US_ASCII));
        byte[] piece = unescape(line, data);
        String text =
                paneText.computeIfAbsent(pane, ignored -> new Utf8.Stream()).decode(piece);
        offer(outputSubscriptions, new PaneOutput(pane, text, ByteBuffer.wrap(piece)));
    }

    /** Where the bytes after the first {@code " : "} from {@code from} begin, or past the end. */
    private static int separatorEnd(byte[] line, int from) {
        for (int index = from; index + 2 < line.length; index++) {
            if (line[index] == ' ' && line[index + 1] == ':' && line[index + 2] == ' ') {
                return index + 3;
            }
        }
        return line.length + 1;
    }

    private <T> EventSubscription<T> subscribe(List<EventSubscription<T>> subscriptions, int capacity) {
        if (subscriptionsClosed) {
            throw new IllegalStateException("control client has ended");
        }
        EventSubscription<T> subscription = new EventSubscription<>(capacity, subscriptions::remove);
        subscriptions.add(subscription);
        if (subscriptionsClosed) {
            subscription.close();
            throw new IllegalStateException("control client has ended");
        }
        return subscription;
    }

    private static <T> void offer(List<EventSubscription<T>> subscriptions, T value) {
        for (EventSubscription<T> subscription : subscriptions) {
            subscription.offer(value);
        }
    }

    private synchronized void closeSubscriptions(@org.jspecify.annotations.Nullable Throwable cause) {
        if (subscriptionsClosed) {
            return;
        }
        subscriptionsClosed = true;
        for (EventSubscription<PaneOutput> subscription : outputSubscriptions) {
            subscription.end(cause);
        }
        for (EventSubscription<ControlEvent> subscription : eventSubscriptions) {
            subscription.end(cause);
        }
    }

    private void announce(ControlEvent event) {
        offer(eventSubscriptions, event);
    }

    private static void join(Thread thread, long millis, AtomicBoolean interrupted) {
        long deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(millis);
        while (thread.isAlive()) {
            long left = deadline - System.nanoTime();
            if (left <= 0) {
                return;
            }
            try {
                thread.join(Math.max(1, TimeUnit.NANOSECONDS.toMillis(left)));
            } catch (InterruptedException e) {
                interrupted.set(true);
            }
        }
    }

    private static void join(ControlWriter writer, long millis, AtomicBoolean interrupted) {
        long deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(millis);
        while (true) {
            long left = deadline - System.nanoTime();
            if (left <= 0) {
                return;
            }
            try {
                writer.join(Math.max(1, TimeUnit.NANOSECONDS.toMillis(left)));
                return;
            } catch (InterruptedException e) {
                interrupted.set(true);
            } catch (IllegalStateException e) {
                return;
            }
        }
    }

    /** tmux writes a control byte or a backslash as a three-digit octal escape, and the rest raw. */
    static byte[] unescape(byte[] line, int from) {
        java.io.ByteArrayOutputStream bytes = new java.io.ByteArrayOutputStream(line.length - from);
        for (int index = from; index < line.length; index++) {
            if (line[index] == '\\' && index + 3 < line.length && octal(line, index + 1)) {
                bytes.write(((line[index + 1] - '0') << 6) | ((line[index + 2] - '0') << 3) | (line[index + 3] - '0'));
                index += 3;
            } else {
                bytes.write(line[index]);
            }
        }
        return bytes.toByteArray();
    }

    private static boolean octal(byte[] line, int from) {
        for (int index = from; index < from + 3; index++) {
            if (line[index] < '0' || line[index] > '7') {
                return false;
            }
        }
        return true;
    }
}

package io.github.libtmux.control;

import io.github.libtmux.PaneId;
import io.github.libtmux.WindowId;
import java.util.List;
import java.util.Optional;
import kotlin.annotations.jvm.ReadOnly;

/**
 * Something tmux volunteered, rather than an answer to a request.
 *
 * <p>A control client is told about changes as they happen — a window appearing, a session being
 * renamed, a layout moving — without anything asking. That is the difference between watching a
 * server and polling one.
 *
 * <p>Two readings of one line. {@link #notification()} is typed, for matching on: a sealed set of
 * what tmux sends, with a {@link Notification.Unknown} case so that a notification a newer tmux adds
 * still arrives rather than being dropped. {@link #kind()}, {@link #fields()} and {@link #value()}
 * are what tmux wrote, word by word, for anything the typed reading does not cover.
 *
 * @param kind the notification name, such as {@code window-add} or {@code subscription-changed}
 * @param fields the words that followed it, before any {@code :} separator
 * @param value what followed a {@code :} separator, which only a subscription carries
 * @param notification the same notification, typed
 */
public record ControlEvent(
        String kind, @ReadOnly List<String> fields, Optional<String> value, Notification notification) {

    public ControlEvent {
        fields = List.copyOf(fields);
    }

    /**
     * An event from its words, with the typed reading taken from them.
     *
     * <p>A name is rejoined from the words with single spaces, so one tmux wrote with a run of them
     * reads back with one. {@link #parse} reads the line tmux wrote and has no such loss.
     */
    public ControlEvent(String kind, List<String> fields, Optional<String> value) {
        this(kind, fields, value, Notification.read(kind, String.join(" ", fields), value));
    }

    /**
     * Reads one notification line.
     *
     * @param line the line as tmux wrote it, leading {@code %} and all
     * @return the event, or empty when the line is not a notification
     */
    static Optional<ControlEvent> parse(String line) {
        if (!line.startsWith("%") || line.length() < 2) {
            return Optional.empty();
        }
        String body = line.substring(1);
        // Only a subscription separates a value with " : ". Anywhere else it is part of what tmux
        // wrote: a window, session, or buffer name may hold one, as may a message.
        int separator = body.startsWith("subscription-changed ") ? body.indexOf(" : ") : -1;
        String head = separator < 0 ? body : body.substring(0, separator);
        // A subscription's value is whatever the format expanded to, so it is taken whole rather than
        // split: it may contain spaces, and often does.
        Optional<String> value = separator < 0 ? Optional.empty() : Optional.of(body.substring(separator + 3));
        String[] words = head.trim().split("\\s+");
        if (words.length == 0 || words[0].isEmpty()) {
            return Optional.empty();
        }
        String kind = words[0];
        // The text after the name exactly as tmux wrote it, so a name holding a run of spaces is read
        // back as that name.
        String rest = head.length() > kind.length() ? head.substring(kind.length() + 1) : "";
        return Optional.of(new ControlEvent(
                kind, List.of(words).subList(1, words.length), value, Notification.read(kind, rest, value)));
    }

    /** The name a subscription was registered under, for an event that came from one. */
    public Optional<String> subscription() {
        return "subscription-changed".equals(kind) && !fields.isEmpty() ? Optional.of(fields.get(0)) : Optional.empty();
    }

    /** The first field naming a pane, which is how an event says which pane it is about. */
    public Optional<PaneId> paneId() {
        return fields.stream()
                .filter(field -> field.startsWith("%") && field.length() > 1)
                .findFirst()
                .map(PaneId::new);
    }

    /** The first field naming a window. */
    public Optional<WindowId> windowId() {
        return fields.stream()
                .filter(field -> field.startsWith("@") && field.length() > 1)
                .findFirst()
                .map(WindowId::new);
    }
}

package io.github.libtmux.control;

import io.github.libtmux.internal.Utf8;
import java.io.BufferedInputStream;
import java.io.ByteArrayOutputStream;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.util.Arrays;
import org.jspecify.annotations.Nullable;

/** Reads bounded physical lines from a control client's byte stream. */
final class ControlLineReader implements Closeable {

    private final BufferedInputStream source;
    private final int maxBytes;

    ControlLineReader(InputStream source, int maxBytes) {
        if (maxBytes < 1) {
            throw new IllegalArgumentException("maxBytes is not positive");
        }
        this.source = new BufferedInputStream(source);
        this.maxBytes = maxBytes;
    }

    /** A line as text, its length on the wire, and its bytes without the line ending. */
    @SuppressWarnings("ArrayRecordComponent") // Internal: read once by the thread that made it.
    record Line(String text, int encodedBytes, byte[] bytes) {}

    @Nullable
    Line readLine() throws IOException {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream(Math.min(maxBytes, 256));
        while (true) {
            int next = source.read();
            if (next < 0) {
                return bytes.size() == 0 ? null : line(bytes);
            }
            if (next == '\n') {
                return line(bytes);
            }
            if (bytes.size() == maxBytes) {
                throw new IOException("control line exceeded the " + maxBytes + " byte limit");
            }
            bytes.write(next);
        }
    }

    private static Line line(ByteArrayOutputStream bytes) {
        byte[] encoded = bytes.toByteArray();
        int textLength = encoded.length;
        if (textLength > 0 && encoded[textLength - 1] == '\r') {
            textLength--;
        }
        byte[] content = Arrays.copyOf(encoded, textLength);
        return new Line(Utf8.backslashReplace(content), encoded.length, content);
    }

    @Override
    public void close() throws IOException {
        source.close();
    }
}

package io.github.libtmux.control;

import io.github.libtmux.batch.OperationOutcome;
import io.github.libtmux.internal.CommandStrings;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import kotlin.annotations.jvm.ReadOnly;
import org.jspecify.annotations.Nullable;

/** Frames control-mode replies and encodes requests for tmux's command parser. */
final class ControlProtocol {

    static final int DEFAULT_MAX_REPLY_BYTES = 16 * 1024 * 1024;
    private static final Pattern GUARD = Pattern.compile("^%(begin|end|error) (-?\\d+) (\\d+) (-?\\d+)$");

    private final int maxReplyBytes;
    private @Nullable Guard opening;
    private List<String> lines = List.of();
    private long replyBytes;

    ControlProtocol() {
        this(DEFAULT_MAX_REPLY_BYTES);
    }

    ControlProtocol(int maxReplyBytes) {
        if (maxReplyBytes < 1) {
            throw new IllegalArgumentException("maxReplyBytes is not positive");
        }
        this.maxReplyBytes = maxReplyBytes;
    }

    sealed interface Result permits Awaiting, Notification, Reply {}

    enum Awaiting implements Result {
        INSTANCE
    }

    record Notification(String line) implements Result {}

    /**
     * One reply block. {@code requested} is tmux's guard flag: set for a command this client wrote,
     * and for any that command queued, and clear for what a hook ran.
     */
    record Reply(OperationOutcome outcome, @ReadOnly List<String> lines, boolean requested) implements Result {

        Reply {
            lines = List.copyOf(lines);
        }
    }

    Result accept(String line) {
        return accept(line, line.getBytes(StandardCharsets.UTF_8).length);
    }

    Result accept(String line, int encodedBytes) {
        if (encodedBytes < 0) {
            throw new IllegalArgumentException("encodedBytes is negative");
        }
        Matcher matcher = GUARD.matcher(line);
        if (opening == null) {
            if (matcher.matches() && matcher.group(1).equals("begin")) {
                opening = Guard.from(matcher);
                lines = new ArrayList<>();
                replyBytes = 0;
                return Awaiting.INSTANCE;
            }
            return new Notification(line);
        }

        if (matcher.matches() && opening.matches(matcher)) {
            OperationOutcome outcome =
                    switch (matcher.group(1)) {
                        case "end" -> OperationOutcome.COMPLETE;
                        case "error" -> OperationOutcome.FAILED;
                        default -> null;
                    };
            if (outcome != null) {
                Reply reply = new Reply(outcome, lines, !opening.flags().equals("0"));
                opening = null;
                lines = List.of();
                replyBytes = 0;
                return reply;
            }
        }

        long added = (long) encodedBytes + 1;
        if (replyBytes > maxReplyBytes - added) {
            throw new LimitExceeded(maxReplyBytes);
        }
        replyBytes += added;
        lines.add(line);
        return Awaiting.INSTANCE;
    }

    static String line(List<String> argv) {
        return CommandStrings.stringify(argv);
    }

    private record Guard(String time, String number, String flags) {

        static Guard from(Matcher matcher) {
            return new Guard(matcher.group(2), matcher.group(3), matcher.group(4));
        }

        boolean matches(Matcher matcher) {
            return time.equals(matcher.group(2)) && number.equals(matcher.group(3)) && flags.equals(matcher.group(4));
        }
    }

    static final class LimitExceeded extends RuntimeException {
        private static final long serialVersionUID = 1L;

        LimitExceeded(int limit) {
            super("control reply exceeded the " + limit + " byte limit");
        }
    }
}

package io.github.libtmux.control;

import io.github.libtmux.batch.OperationOutcome;
import java.util.List;
import kotlin.annotations.jvm.ReadOnly;

/**
 * One command's reply in control mode.
 *
 * @param outcome what tmux said became of it; never {@code SKIPPED}, because control-mode requests
 *     are independent and a failure discards nothing behind it
 * @param lines the lines tmux produced between the reply's own begin and end markers
 */
public record ControlReply(
        OperationOutcome outcome, @ReadOnly List<String> lines) {

    public ControlReply {
        lines = List.copyOf(lines);
    }

    /** Whether tmux ran the command and it succeeded. */
    public boolean succeeded() {
        return outcome == OperationOutcome.COMPLETE;
    }

    /** Counts only: reply lines carry pane content. */
    @Override
    public String toString() {
        return "ControlReply[" + outcome + ", lines=" + lines.size() + "]";
    }
}

package io.github.libtmux.control;

import io.github.libtmux.batch.OperationOutcome;
import io.github.libtmux.exception.DispatchException;
import io.github.libtmux.format.Tokens;
import io.github.libtmux.internal.CommandStrings;
import io.github.libtmux.transport.DispatchOutcome;
import java.io.BufferedWriter;
import java.io.IOException;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;
import org.jspecify.annotations.Nullable;

/**
 * Owns the process-pipe write and the FIFO that attributes replies to requests.
 *
 * <p>A request's reply is the first block tmux writes for it: an acknowledgement, which deferred
 * work may outlive. But tmux answers every command another one queues with a block of its own, as
 * {@code if-shell} queues its branch and {@code run-shell} reports its job, numbered like any other.
 * So each request line is followed by a second, {@code display-message -p} of a marker unique to it:
 * tmux runs that after everything the request queued, whether the request failed or not. Blocks
 * between a reply and its marker belong to the request already answered, and are not handed to
 * the next one.
 */
final class ControlWriter {

    static final int DEFAULT_CAPACITY = 64;

    private static final String MARKER = "libtmux-reply-" + Tokens.perProcess() + "-";

    private final BufferedWriter output;
    private final ArrayBlockingQueue<Request> waiting;
    private final AtomicReference<@Nullable Request> active = new AtomicReference<>();
    private final AtomicBoolean accepting = new AtomicBoolean(true);
    private final Consumer<DispatchException> failed;
    private final Thread thread;
    private final AtomicLong markers = new AtomicLong();
    // Markers of requests answered whose tails tmux may still be writing. Reader thread only.
    private final java.util.ArrayDeque<String> unanswered = new java.util.ArrayDeque<>();

    ControlWriter(BufferedWriter output, int capacity, Consumer<DispatchException> failed) {
        if (capacity < 1) {
            throw new IllegalArgumentException("control writer capacity is not positive");
        }
        this.output = output;
        this.waiting = new ArrayBlockingQueue<>(capacity, true);
        this.failed = failed;
        // A daemon for the reason the reader is one: this thread waits on a queue that a live client
        // never stops feeding, so it would hold the JVM forever if the client were forgotten.
        this.thread = new Thread(this::run, "libtmux-control-writer");
        this.thread.setDaemon(true);
    }

    /** Records the attach request dispatched by the process invocation. */
    Request expectInitial(Duration timeout) {
        // The attach command's reply is its only one, and tmux flags it as no command of the client's.
        Request initial = new Request("", timeout, Request.State.PICKED, null);
        if (!accepting.get() || !active.compareAndSet(null, initial)) {
            initial.fail(unknown("control client ended before becoming ready", null));
        }
        return initial;
    }

    void start() {
        thread.start();
    }

    ControlReply exchange(String line, Duration timeout) {
        Request request = new Request(line, timeout, Request.State.QUEUED, MARKER + markers.incrementAndGet());
        try {
            if (!accepting.get()) {
                throw notDispatched("control client is not accepting requests", null);
            }
            try {
                if (!waiting.offer(request, request.remainingNanos(), TimeUnit.NANOSECONDS)) {
                    request.cancel(
                            timeout("control request admission timed out", DispatchOutcome.NOT_DISPATCHED, null));
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                request.cancel(notDispatched("interrupted before control request dispatch", e));
            }
            if (!accepting.get() && request.cancel(notDispatched("control client closed before dispatch", null))) {
                waiting.remove(request);
            }
            ControlReply reply = await(request);
            TIMING.set(request.timing(System.nanoTime()));
            return reply;
        } catch (RuntimeException failure) {
            TIMING.set(request.timing(System.nanoTime()));
            throw failure;
        }
    }

    private static final ThreadLocal<long[]> TIMING = new ThreadLocal<>();

    /**
     * Queue time, then run time, for the last exchange on this thread; {@code elapsed} as run time
     * when this thread made none.
     */
    long[] takeTiming(long elapsed) {
        long[] timing = TIMING.get();
        TIMING.remove();
        return timing == null ? new long[] {0, elapsed} : timing;
    }

    /**
     * Called by the reader for each reply block, in the order tmux wrote them.
     *
     * @param requested tmux's guard flag: clear for a block a hook ran, which answers no request
     */
    void complete(OperationOutcome outcome, List<String> lines, boolean requested) {
        Request request = active.get();
        if (request != null && request.marker == null) {
            // The attach command's reply, which tmux flags as no command of the client's.
            if (active.compareAndSet(request, null)) {
                request.complete(new ControlReply(outcome, lines));
            }
            return;
        }
        if (!requested) {
            return;
        }
        String line = lines.size() == 1 ? lines.get(0) : "";
        if (line.startsWith(MARKER)) {
            unanswered.remove(line);
            return;
        }
        if (!unanswered.isEmpty()) {
            // Queued by a request already answered: its tail, not the next request's reply.
            return;
        }
        if (request != null && active.compareAndSet(request, null)) {
            unanswered.add(Objects.requireNonNull(request.marker));
            request.complete(new ControlReply(outcome, lines));
        }
    }

    void readerEnded() {
        stop(unknown("control client ended before answering", null), true);
    }

    void close() {
        stop(unknown("control client closed", null), false);
    }

    void join(long timeoutMillis) throws InterruptedException {
        if (Thread.currentThread().equals(thread)) {
            return;
        }
        if (thread.getState() == Thread.State.NEW) {
            closeOutput();
            return;
        }
        thread.join(timeoutMillis);
        if (thread.isAlive()) {
            throw new IllegalStateException("control writer did not stop");
        }
    }

    ControlReply await(Request request) {
        try {
            if (!request.await()) {
                expire(
                        request,
                        timeout("control request timed out", DispatchOutcome.NOT_DISPATCHED, null),
                        timeout("control request timed out", DispatchOutcome.UNKNOWN, null));
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            if (request.cancel(notDispatched("interrupted before control request dispatch", e))) {
                waiting.remove(request);
            } else if (!request.isDone()) {
                // The writer still owns the request and tmux still answers it in order, so only this
                // caller leaves. Ending the writer here would fail every other caller on the client.
                throw unknown("interrupted while awaiting a control reply; tmux may have run it", e);
            }
        }
        return request.answer();
    }

    private void expire(Request request, DispatchException beforeDispatch, DispatchException afterDispatch) {
        if (request.cancel(beforeDispatch)) {
            waiting.remove(request);
            return;
        }
        if (request.claimFailure()) {
            try {
                stop(afterDispatch, true);
            } finally {
                request.publishFailure(afterDispatch);
            }
        }
        request.awaitTerminal();
    }

    private void run() {
        try {
            while (accepting.get()) {
                Request request;
                try {
                    request = waiting.take();
                } catch (InterruptedException e) {
                    return;
                }
                if (!accepting.get()) {
                    request.cancel(notDispatched("control client closed before dispatch", null));
                    continue;
                }
                if (request.remainingNanos() == 0) {
                    request.cancel(
                            timeout("control request admission timed out", DispatchOutcome.NOT_DISPATCHED, null));
                    continue;
                }
                if (!request.pick()) {
                    continue;
                }
                if (!active.compareAndSet(null, request)) {
                    halt(request, unknown("control writer already has an active request", null));
                    return;
                }
                if (!accepting.get()) {
                    active.compareAndSet(request, null);
                    request.fail(unknown("control client closed after dispatch", null));
                    return;
                }
                try {
                    output.write(request.line);
                    output.newLine();
                    if (request.marker != null) {
                        output.write(CommandStrings.stringify(List.of("display-message", "-p", request.marker)));
                        output.newLine();
                    }
                    output.flush();
                } catch (IOException e) {
                    halt(request, unknown("could not write to the control client", e));
                    return;
                }
                try {
                    if (!request.await()) {
                        expire(
                                request,
                                timeout("control request timed out", DispatchOutcome.NOT_DISPATCHED, null),
                                timeout("control request timed out", DispatchOutcome.UNKNOWN, null));
                        return;
                    }
                } catch (InterruptedException e) {
                    if (!accepting.get()) {
                        return;
                    }
                    Thread.currentThread().interrupt();
                    halt(request, unknown("control writer interrupted after dispatch", e));
                    return;
                }
            }
        } finally {
            closeOutput();
        }
    }

    private void halt(Request request, DispatchException failure) {
        if (request.claimFailure()) {
            try {
                stop(failure, true);
            } finally {
                request.publishFailure(failure);
            }
        }
    }

    private void stop(DispatchException activeFailure, boolean notifyFailure) {
        if (!accepting.compareAndSet(true, false)) {
            return;
        }
        List<Request> queuedRequests = new ArrayList<>();
        Request queued;
        while ((queued = waiting.poll()) != null) {
            queuedRequests.add(queued);
        }
        Request dispatched = active.getAndSet(null);
        if (dispatched != null) {
            dispatched.claimFailure();
        }
        try {
            if (notifyFailure) {
                failed.accept(activeFailure);
            }
        } finally {
            thread.interrupt();
            for (Request request : queuedRequests) {
                request.cancel(notDispatched("control client closed before dispatch", null));
            }
            if (dispatched != null) {
                dispatched.publishFailure(activeFailure);
            }
        }
    }

    private void closeOutput() {
        try {
            output.close();
        } catch (IOException e) {
            // Ending the process normally closes this stream first.
        }
    }

    private static DispatchException notDispatched(String message, @Nullable Throwable cause) {
        return new DispatchException.Failed(message, DispatchOutcome.NOT_DISPATCHED, cause);
    }

    private static DispatchException unknown(String message, @Nullable Throwable cause) {
        return new DispatchException.Failed(message, DispatchOutcome.UNKNOWN, cause);
    }

    private static DispatchException.TimedOut timeout(
            String message, DispatchOutcome outcome, @Nullable Throwable cause) {
        return new DispatchException.TimedOut(message, outcome, cause);
    }

    static final class Request {

        private enum State {
            QUEUED,
            PICKED,
            FAILING,
            DONE
        }

        private final String line;
        private final @Nullable String marker;
        private final long started = System.nanoTime();
        private volatile long picked = started;
        private volatile boolean dispatched;
        private final long timeoutNanos;
        private final AtomicReference<State> state;
        private final CountDownLatch answered = new CountDownLatch(1);
        private volatile @Nullable Object answer;

        private Request(String line, Duration timeout, State state, @Nullable String marker) {
            this.line = line;
            this.marker = marker;
            this.timeoutNanos = timeoutNanos(timeout);
            this.state = new AtomicReference<>(state);
            this.dispatched = state == State.PICKED;
        }

        boolean pick() {
            if (!state.compareAndSet(State.QUEUED, State.PICKED)) {
                return false;
            }
            picked = System.nanoTime();
            dispatched = true;
            return true;
        }

        /** Queue time, then run time, up to now. A request never picked spent all of it queued. */
        long[] timing(long now) {
            if (!dispatched) {
                return new long[] {Math.max(0, now - started), 0};
            }
            return new long[] {Math.max(0, picked - started), Math.max(0, now - picked)};
        }

        boolean cancel(DispatchException reason) {
            return finish(State.QUEUED, reason);
        }

        void complete(ControlReply reply) {
            finish(State.PICKED, reply);
        }

        boolean fail(DispatchException reason) {
            if (!claimFailure()) {
                return false;
            }
            publishFailure(reason);
            return true;
        }

        boolean claimFailure() {
            return state.compareAndSet(State.PICKED, State.FAILING);
        }

        void publishFailure(DispatchException reason) {
            finish(State.FAILING, reason);
        }

        private boolean finish(State expected, Object result) {
            if (!state.compareAndSet(expected, State.DONE)) {
                return false;
            }
            answer = result;
            answered.countDown();
            return true;
        }

        boolean isDone() {
            return state.get() == State.DONE;
        }

        long remainingNanos() {
            long elapsed = System.nanoTime() - started;
            return Math.max(0, timeoutNanos - Math.max(0, elapsed));
        }

        boolean await() throws InterruptedException {
            return answered.await(remainingNanos(), TimeUnit.NANOSECONDS);
        }

        ControlReply answer() {
            Object result = answer;
            if (result instanceof DispatchException failure) {
                throw failure;
            }
            if (result instanceof ControlReply reply) {
                return reply;
            }
            throw new IllegalStateException("control request has no answer");
        }

        void awaitTerminal() {
            boolean interrupted = Thread.interrupted();
            while (answered.getCount() > 0) {
                try {
                    answered.await();
                } catch (InterruptedException e) {
                    interrupted = true;
                }
            }
            if (interrupted) {
                Thread.currentThread().interrupt();
            }
        }

        private static long timeoutNanos(Duration timeout) {
            try {
                return timeout.toNanos();
            } catch (ArithmeticException e) {
                return Long.MAX_VALUE;
            }
        }
    }
}

package io.github.libtmux.control;

/**
 * One step in a control subscription.
 *
 * <p>A {@link Gap} sits in the sequence where events were discarded, ahead of the events that
 * survived. It is not a side total: the next read is the gap, and the one after it is whatever
 * remains.
 *
 * @param <T> the event type
 */
public sealed interface Delivery<T> {

    /**
     * The event a strict reader kept. A gap fails the read.
     *
     * @param <T> the event type
     * @param step the subscription's next step
     * @return the event
     * @throws IllegalStateException if {@code step} is a gap
     */
    static <T> T kept(Delivery<T> step) {
        if (step instanceof Event<T> event) {
            return event.value();
        }
        throw new IllegalStateException("lost " + ((Gap<?>) step).missed());
    }

    /**
     * An event the subscription kept.
     *
     * @param value the event
     * @param <T> the event type
     */
    record Event<T>(T value) implements Delivery<T> {}

    /**
     * How many events were discarded since the previous read because the buffer was full.
     *
     * @param missed the number discarded, at least one
     * @param <T> the event type
     */
    record Gap<T>(long missed) implements Delivery<T> {

        public Gap {
            if (missed < 1) {
                throw new IllegalArgumentException("missed is not positive: " + missed);
            }
        }
    }
}

package io.github.libtmux.control;

import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import io.github.libtmux.exception.ControlEndedException;
import java.time.Duration;
import java.util.ArrayDeque;
import java.util.Objects;
import java.util.Optional;
import java.util.concurrent.CancellationException;
import java.util.concurrent.Executor;
import java.util.concurrent.Flow;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;
import java.util.function.Consumer;
import org.jspecify.annotations.Nullable;

/**
 * Pulls events volunteered by one control client.
 *
 * <p>Each subscription owns a fixed-capacity buffer. When that buffer is full, the next event
 * replaces its oldest event. The read that follows is a {@link Delivery.Gap} naming how many were
 * discarded since the previous read, and only then the events that remain. {@link #droppedCount()}
 * is the total across the subscription's life. Another subscription has its own buffer and its own
 * gaps. The control protocol reader only offers values to these buffers, and never runs subscriber
 * code beyond a {@link #onReady readiness callback}.
 *
 * <p>One reader at a time. Public operations are thread-safe, and reads from different threads one
 * after another are fine — a coroutine or a fiber moves between threads — but a read that overlaps
 * another, or any read once {@link #stream()} or {@link #publisher()} has taken the subscription, is
 * refused with {@link IllegalStateException}: two readers would split one sequence and its gaps
 * between them. For a second reader, subscribe again; each subscription gets every event.
 *
 * <p>{@link #next()} blocks. {@link #poll()} never does, and {@link #onReady(Runnable)} arms a
 * one-shot wakeup for when there is something to poll, so an event loop or a coroutine can read
 * without holding a thread while nothing arrives.
 *
 * <p>A subscription does not reconnect. When it ends, {@link #next()} returns empty. {@link
 * #cause()} is empty when the caller closed it, and set when the control client ended it. Attach
 * again from the captured session and read a snapshot; nothing already missed is replayed.
 *
 * <p>Ending is terminal and wakes threads blocked in {@link #next()}. A caller's {@link #close()}
 * discards buffered events: the caller has chosen not to read them, so they are not overflow and do
 * not increment the loss count. When the control client ends a subscription, what it had already
 * delivered stays readable, a pending gap first, and only then does a read return empty with
 * {@link #cause()} set.
 *
 * @param <T> the event type
 */
public final class EventSubscription<T> implements AutoCloseable {

    private static final System.Logger LOG = System.getLogger(EventSubscription.class.getName());

    private final int capacity;
    private final ArrayDeque<T> events = new ArrayDeque<>();
    private final ReentrantLock lock = new ReentrantLock();
    private final Condition available = lock.newCondition();
    private final Consumer<EventSubscription<T>> onClose;
    private long dropped;
    private long pendingGap;
    private boolean closed;
    private @Nullable Throwable cause;
    // A read is in progress, on a thread that may be waiting with the lock released.
    private boolean reading;
    // stream() or publisher() owns every read from now on.
    private boolean claimed;
    private @Nullable Runnable ready;
    // The owning publisher's wakeup when this subscription ends: a terminal signal needs no demand.
    private @Nullable Runnable ownerWake;

    EventSubscription(int capacity, Consumer<EventSubscription<T>> onClose) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("capacity must be positive");
        }
        this.capacity = capacity;
        this.onClose = onClose;
    }

    void offer(T event) {
        @Nullable Runnable wake = null;
        lock.lock();
        try {
            if (closed) {
                return;
            }
            boolean wasReadable = readable();
            if (events.size() == capacity) {
                events.removeFirst();
                dropped++;
                pendingGap++;
            }
            events.addLast(event);
            available.signal();
            if (!wasReadable) {
                wake = ready;
                ready = null;
            }
        } finally {
            lock.unlock();
        }
        if (wake != null) {
            fire(wake);
        }
    }

    private boolean readable() {
        return pendingGap > 0 || !events.isEmpty();
    }

    /**
     * Returns the exact number of events discarded because this subscription's buffer was full.
     *
     * @return the monotonic loss count
     */
    @Operation(Kind.CAPTURED)
    public long droppedCount() {
        lock.lock();
        try {
            return dropped;
        } finally {
            lock.unlock();
        }
    }

    /**
     * Why this subscription ended, when the control client ended it.
     *
     * <p>Empty when the subscription is still open, and empty when the caller closed it. A client
     * that died sets this before the read returns empty.
     */
    @Operation(Kind.CAPTURED)
    public Optional<Throwable> cause() {
        lock.lock();
        try {
            return Optional.ofNullable(cause);
        } finally {
            lock.unlock();
        }
    }

    /**
     * Waits until the next step arrives or this subscription closes.
     *
     * @return the next gap or event, or empty when the subscription has closed and no gap is waiting
     * @throws IllegalStateException if another read is in progress, or a stream or publisher owns
     *     this subscription
     * @throws InterruptedException if the waiting thread is interrupted
     */
    @Operation(Kind.WAIT)
    public Optional<Delivery<T>> next() throws InterruptedException {
        return read(false, -1);
    }

    /**
     * Waits up to a deadline for the next step.
     *
     * @param timeout how long to wait, zero to inspect the buffer without waiting
     * @return the next gap or event, or empty when none arrived before the deadline
     * @throws IllegalArgumentException if {@code timeout} is negative
     * @throws IllegalStateException if another read is in progress, or a stream or publisher owns
     *     this subscription
     * @throws InterruptedException if the waiting thread is interrupted
     */
    @Operation(Kind.WAIT)
    public Optional<Delivery<T>> next(Duration timeout) throws InterruptedException {
        if (timeout.isNegative()) {
            throw new IllegalArgumentException("timeout must not be negative");
        }
        long remaining;
        try {
            remaining = timeout.toNanos();
        } catch (ArithmeticException overflow) {
            remaining = Long.MAX_VALUE;
        }
        return read(false, remaining);
    }

    /**
     * Returns the next step if one is waiting, without blocking.
     *
     * @return the next gap or event, or empty when none is buffered; after the subscription has
     *     ended, empty once what it held is read
     * @throws IllegalStateException if another read is in progress, or a stream or publisher owns
     *     this subscription
     */
    @Operation(Kind.CAPTURED)
    public Optional<Delivery<T>> poll() {
        lock.lock();
        try {
            enter(false);
            try {
                return take();
            } finally {
                reading = false;
            }
        } finally {
            lock.unlock();
        }
    }

    /**
     * Arms a one-shot wakeup for when this subscription has something to read, or has ended.
     *
     * <p>Runs {@code callback} at once, on this thread, when a step is already waiting or the
     * subscription has ended. Otherwise it runs once, on the control client's reader thread, when the
     * first step arrives or the subscription ends, and is then disarmed: drain with {@link #poll()}
     * until it is empty, then arm again. Checking and arming happen under the lock that delivery
     * takes, so a step cannot slip between them unannounced.
     *
     * <p>The callback runs on the thread delivering events, so it must not block: resume a waiting
     * coroutine, complete a promise, and return. One that throws is logged and ignored, and delivery
     * continues.
     *
     * @throws IllegalStateException if a callback is already armed, or a stream or publisher owns
     *     this subscription
     */
    @Operation(Kind.CAPTURED)
    public void onReady(Runnable callback) {
        Objects.requireNonNull(callback, "callback");
        boolean now;
        lock.lock();
        try {
            if (claimed) {
                throw owned();
            }
            if (ready != null) {
                throw new IllegalStateException("a readiness callback is already armed; clearReady() first");
            }
            now = readable() || closed;
            if (!now) {
                ready = callback;
            }
        } finally {
            lock.unlock();
        }
        if (now) {
            fire(callback);
        }
    }

    /** Disarms the readiness callback, if one is armed. For a reader that stopped waiting. */
    @Operation(Kind.CAPTURED)
    public void clearReady() {
        lock.lock();
        try {
            ready = null;
        } finally {
            lock.unlock();
        }
    }

    private static void fire(Runnable callback) {
        try {
            callback.run();
        } catch (RuntimeException broken) {
            LOG.log(System.Logger.Level.WARNING, "a subscription's readiness callback failed", broken);
        }
    }

    /** One read, waiting up to {@code timeoutNanos}, or without limit when it is negative. */
    private Optional<Delivery<T>> read(boolean owner, long timeoutNanos) throws InterruptedException {
        lock.lockInterruptibly();
        try {
            enter(owner);
            try {
                long remaining = timeoutNanos;
                while (!readable() && !closed && (timeoutNanos < 0 || remaining > 0)) {
                    if (timeoutNanos < 0) {
                        available.await();
                    } else {
                        remaining = available.awaitNanos(remaining);
                    }
                }
                return take();
            } finally {
                reading = false;
            }
        } finally {
            lock.unlock();
        }
    }

    private void enter(boolean owner) {
        if (claimed && !owner) {
            throw owned();
        }
        if (reading) {
            throw new IllegalStateException(
                    "another thread is reading this subscription; read from one thread at a time, or"
                            + " subscribe again for a second reader");
        }
        reading = true;
    }

    /** Hands every future read to a stream or publisher, which becomes the only reader. */
    private void claim(@Nullable Runnable onEnd) {
        lock.lock();
        try {
            if (claimed || reading || ready != null) {
                throw new IllegalStateException(
                        "this subscription already has a reader; subscribe again for a second one");
            }
            claimed = true;
            ownerWake = onEnd;
        } finally {
            lock.unlock();
        }
    }

    /** Forgets the owning publisher's wakeup, so a cancelled subscriber is not kept reachable. */
    private void releaseOwner() {
        lock.lock();
        try {
            ownerWake = null;
        } finally {
            lock.unlock();
        }
    }

    /** Whether this subscription has ended and everything it held has been read. */
    private boolean exhausted() {
        lock.lock();
        try {
            return closed && !readable();
        } finally {
            lock.unlock();
        }
    }

    private static IllegalStateException owned() {
        return new IllegalStateException(
                "a stream or publisher owns this subscription's reads; subscribe again for another reader");
    }

    private Optional<Delivery<T>> take() {
        if (pendingGap > 0) {
            long missed = pendingGap;
            pendingGap = 0;
            return Optional.of(new Delivery.Gap<>(missed));
        }
        T value = events.pollFirst();
        return value == null ? Optional.empty() : Optional.of(new Delivery.Event<>(value));
    }

    /**
     * The steps still to come, in order, each read by the thread consuming the stream.
     *
     * <p>Pull-only: a step is read when the stream asks for one, and events that arrive meanwhile
     * wait in this subscription's buffer, so its capacity alone decides what becomes a {@link
     * Delivery.Gap}. The stream ends when this subscription closes. When the control client ended
     * it, the stream fails with {@link #cause()}. Closing the stream closes this subscription, and
     * closing this subscription from another thread ends a stream that is waiting.
     *
     * <pre>{@code
     * try (Stream<Delivery<PaneOutput>> steps = subscription.stream()) {
     *     steps.map(Delivery::kept).forEach(output -> System.out.print(output.data()));
     * }
     * }</pre>
     *
     * @throws io.github.libtmux.exception.LibTmuxException from the stream if the reading thread is
     *     interrupted; its interrupt status is set again
     */
    @Operation(Kind.STREAM)
    public java.util.stream.Stream<Delivery<T>> stream() {
        claim(null);
        java.util.Spliterator<Delivery<T>> steps =
                new java.util.Spliterators.AbstractSpliterator<>(
                        Long.MAX_VALUE, java.util.Spliterator.ORDERED | java.util.Spliterator.NONNULL) {
                    @Override
                    public boolean tryAdvance(java.util.function.Consumer<? super Delivery<T>> action) {
                        Optional<Delivery<T>> step;
                        try {
                            step = read(true, -1);
                        } catch (InterruptedException interrupted) {
                            Thread.currentThread().interrupt();
                            throw cancelled(interrupted);
                        }
                        if (step.isPresent()) {
                            action.accept(step.get());
                            return true;
                        }
                        Optional<Throwable> failure = cause();
                        if (failure.isPresent()) {
                            throw failure.get() instanceof RuntimeException unchecked
                                    ? unchecked
                                    : new ControlEndedException("", false, failure.get());
                        }
                        return false;
                    }
                };
        return java.util.stream.StreamSupport.stream(steps, false).onClose(this::close);
    }

    /**
     * A {@link Flow.Publisher} view of this subscription's steps, delivered as demand allows.
     *
     * <p>Reads that wait for the next step run on a fresh virtual thread, started only while a
     * subscriber has outstanding demand, so a subscriber that never asks never blocks anything. Use
     * {@link #publisher(Executor)} to read somewhere else instead.
     *
     * @see #publisher(Executor)
     */
    @Operation(Kind.STREAM)
    public Flow.Publisher<Delivery<T>> publisher() {
        return publisher(VIRTUAL_THREAD_PER_READ);
    }

    /**
     * A {@link Flow.Publisher} view of this subscription's steps, delivered as demand allows, its
     * reads run on {@code executor} rather than a virtual thread.
     *
     * <p>One subscriber per publisher, the way a {@link #stream()} is read by one consumer: {@link
     * Flow.Publisher#subscribe subscribe} never throws for a non-null subscriber, but a second one on
     * the same publisher is sent {@link Flow.Subscriber#onSubscribe onSubscribe} immediately followed
     * by {@link IllegalStateException} to {@link Flow.Subscriber#onError onError}, rather than sharing
     * this subscription's steps or silently missing them. The first subscriber takes this subscription
     * whole, so a subscriber to a second publisher from it, or one arriving after {@link #stream()},
     * is refused the same way. {@link Flow.Subscription#request request} of zero or less is answered the same way,
     * with {@link IllegalArgumentException}. {@link Long#MAX_VALUE} demand is unbounded. Every signal
     * to one subscriber comes from one thread at a time, never concurrently.
     *
     * <p>{@link Flow.Subscription#cancel cancel} closes this subscription, the same as {@link
     * #close()}, is idempotent, and no signal follows it, not even {@code onComplete}. Otherwise this
     * ends the same way {@link #next()} does: {@code onComplete} when the subscription closes
     * normally, {@code onError} with {@link #cause()} when the control client ended it. A {@link
     * Delivery.Gap} is delivered like any other step.
     *
     * <p>Demand only bounds what reaches the subscriber. tmux cannot be paused through this path —
     * that is {@code pause-after}, in the streaming guide — so this subscription's own bounded buffer
     * keeps filling regardless of demand, and a full buffer still reports its loss as a {@link
     * Delivery.Gap}, exactly as {@link #next()} does.
     *
     * @param executor where each blocking read for the subscriber runs; one that runs a task on the
     *     calling thread makes {@link Flow.Subscription#request request} block on tmux, which the
     *     Reactive Streams rules forbid
     */
    @Operation(Kind.STREAM)
    public Flow.Publisher<Delivery<T>> publisher(Executor executor) {
        Objects.requireNonNull(executor, "executor");
        return new EventPublisher(executor);
    }

    private static final Executor VIRTUAL_THREAD_PER_READ =
            task -> Thread.ofVirtual().name("libtmux-control-publisher").start(task);

    private static final Flow.Subscription NOOP_SUBSCRIPTION = new Flow.Subscription() {
        @Override
        public void request(long n) {}

        @Override
        public void cancel() {}
    };

    private final class EventPublisher implements Flow.Publisher<Delivery<T>> {

        private final Executor executor;
        private final AtomicBoolean claimed = new AtomicBoolean();

        EventPublisher(Executor executor) {
            this.executor = executor;
        }

        @Override
        public void subscribe(Flow.Subscriber<? super Delivery<T>> subscriber) {
            Objects.requireNonNull(subscriber, "subscriber");
            if (!claimed.compareAndSet(false, true)) {
                subscriber.onSubscribe(NOOP_SUBSCRIPTION);
                subscriber.onError(new IllegalStateException(
                        "this publisher already has a subscriber; subscribe to the control client again for another"));
                return;
            }
            DemandSubscription demand = new DemandSubscription(subscriber, executor);
            try {
                claim(demand::schedule);
            } catch (IllegalStateException taken) {
                subscriber.onSubscribe(NOOP_SUBSCRIPTION);
                subscriber.onError(taken);
                return;
            }
            // Rule 1.3: no signal may overlap onSubscribe, so a request made inside it waits for it.
            demand.wip.set(1);
            subscriber.onSubscribe(demand);
            demand.subscribed();
        }
    }

    /**
     * Turns requested demand into reads. A single-flight drain loop, one virtual thread or executor
     * task at a time, is what keeps every signal to {@code subscriber} serial: {@link #request} and
     * {@link #cancel} only ever flip flags and reschedule it, and {@link #drain} is the one place that
     * calls back into {@code subscriber}.
     */
    private final class DemandSubscription implements Flow.Subscription {

        private final Flow.Subscriber<? super Delivery<T>> subscriber;
        private final Executor executor;
        private final AtomicLong requested = new AtomicLong();
        private final AtomicInteger wip = new AtomicInteger();
        private final AtomicBoolean terminated = new AtomicBoolean();
        private volatile boolean cancelled;
        private volatile @Nullable Throwable protocolError;

        DemandSubscription(Flow.Subscriber<? super Delivery<T>> subscriber, Executor executor) {
            this.subscriber = subscriber;
            this.executor = executor;
        }

        @Override
        public void request(long n) {
            if (cancelled) {
                return;
            }
            if (n <= 0) {
                protocolError = new IllegalArgumentException("request must be positive: " + n);
                cancelled = true;
                EventSubscription.this.close();
                schedule();
                return;
            }
            addCap(n);
            schedule();
        }

        @Override
        public void cancel() {
            cancelled = true;
            // Rules 1.8 and 3.5: a cancelled subscriber is owed no end either. Taking the one
            // terminal signal here stops a drain that is mid-delivery, and finds the subscription
            // this cancel closed, from reporting that end as onComplete.
            terminated.set(true);
            EventSubscription.this.close();
            EventSubscription.this.releaseOwner();
        }

        private void addCap(long n) {
            for (; ; ) {
                long current = requested.get();
                if (current == Long.MAX_VALUE) {
                    return;
                }
                long next = current + n;
                if (next < 0) {
                    next = Long.MAX_VALUE;
                }
                if (requested.compareAndSet(current, next)) {
                    return;
                }
            }
        }

        /** Runs what arrived during onSubscribe, or looks once for an end that needs no demand. */
        private void subscribed() {
            if (wip.decrementAndGet() > 0) {
                start();
            } else {
                schedule();
            }
        }

        private void schedule() {
            if (wip.getAndIncrement() == 0) {
                start();
            }
        }

        private void start() {
            try {
                executor.execute(this::drain);
            } catch (RuntimeException rejected) {
                // Rule 3.4: request must not throw. No drain runs, so nothing else can signal.
                cancelled = true;
                EventSubscription.this.close();
                Throwable earlier = protocolError;
                signalError(earlier != null ? earlier : rejected);
            }
        }

        private void drain() {
            int missed = 1;
            for (; ; ) {
                if (cancelled) {
                    signalProtocolError();
                    return;
                }
                long r = requested.get();
                long emitted = 0;
                while (r == Long.MAX_VALUE || emitted < r) {
                    if (cancelled) {
                        signalProtocolError();
                        return;
                    }
                    Optional<Delivery<T>> step;
                    try {
                        step = EventSubscription.this.read(true, -1);
                    } catch (InterruptedException interrupted) {
                        Thread.currentThread().interrupt();
                        cancelled = true;
                        EventSubscription.this.close();
                        signalError(cancelled(interrupted));
                        return;
                    }
                    if (cancelled) {
                        signalProtocolError();
                        return;
                    }
                    if (step.isPresent()) {
                        try {
                            subscriber.onNext(step.get());
                        } catch (RuntimeException broken) {
                            // Rule 2.13: a subscriber that throws has cancelled. Release what it held,
                            // and signal nothing more to it.
                            cancelled = true;
                            EventSubscription.this.close();
                            return;
                        } catch (Error fatal) {
                            cancelled = true;
                            EventSubscription.this.close();
                            throw fatal;
                        }
                        emitted++;
                        continue;
                    }
                    cancelled = true;
                    signalEnd();
                    return;
                }
                if (emitted != 0 && r != Long.MAX_VALUE) {
                    requested.addAndGet(-emitted);
                }
                // Rules 1.4 and 1.5: an end is signalled without waiting for demand.
                if (EventSubscription.this.exhausted()) {
                    cancelled = true;
                    signalEnd();
                    return;
                }
                missed = wip.addAndGet(-missed);
                if (missed == 0) {
                    return;
                }
            }
        }

        private void signalProtocolError() {
            Throwable error = protocolError;
            if (error != null) {
                signalError(error);
            }
        }

        private void signalEnd() {
            // A bad request closes the subscription to release it, so a drain can see that end
            // before it sees the request. Rule 3.9 still wants the error.
            Throwable refused = protocolError;
            if (refused != null) {
                signalError(refused);
                return;
            }
            Optional<Throwable> failure = EventSubscription.this.cause();
            if (failure.isPresent()) {
                signalError(failure.get());
            } else if (terminated.compareAndSet(false, true)) {
                EventSubscription.this.releaseOwner();
                subscriber.onComplete();
            }
        }

        /** The one terminal signal, however many paths race to send it. */
        private void signalError(Throwable error) {
            if (terminated.compareAndSet(false, true)) {
                EventSubscription.this.releaseOwner();
                subscriber.onError(error);
            }
        }
    }

    /**
     * Whether this subscription has reached its terminal state.
     *
     * <p>This distinguishes a timed read that expired from one that returned empty because the
     * subscription ended. A pending gap can still be read after the subscription has closed.
     */
    @Operation(Kind.CAPTURED)
    public boolean isClosed() {
        lock.lock();
        try {
            return closed;
        } finally {
            lock.unlock();
        }
    }

    /** Discards buffered events, removes this subscriber, and wakes every waiting reader. */
    @Operation(Kind.LIFECYCLE)
    @Override
    public void close() {
        end(null);
    }

    /**
     * Ends this subscription as the control client saw it end, recording why. Unlike {@link
     * #close()}, events already delivered stay readable.
     */
    void end(@Nullable Throwable failure) {
        end(failure, failure == null);
    }

    /** Ends this subscription as a producer with nothing more to send: not a failure, and nothing is discarded. */
    void finish() {
        end(null, false);
    }

    private void end(@Nullable Throwable failure, boolean discard) {
        @Nullable Runnable wake;
        @Nullable Runnable owner;
        lock.lock();
        try {
            if (closed) {
                return;
            }
            cause = failure;
            closed = true;
            if (discard) {
                events.clear();
            }
            available.signalAll();
            wake = ready;
            ready = null;
            owner = ownerWake;
            ownerWake = null;
            onClose.accept(this);
        } finally {
            lock.unlock();
        }
        if (wake != null) {
            fire(wake);
        }
        if (owner != null) {
            fire(owner);
        }
    }

    /** An interrupt on a read that cannot throw {@link InterruptedException}: the wait was cancelled. */
    private static CancellationException cancelled(InterruptedException interrupted) {
        CancellationException cancelled = new CancellationException("interrupted waiting for the next event");
        cancelled.initCause(interrupted);
        return cancelled;
    }
}

package io.github.libtmux.control;

import io.github.libtmux.PaneId;
import io.github.libtmux.SessionId;
import io.github.libtmux.WindowId;
import io.github.libtmux.WindowLayout;
import java.util.Optional;

/**
 * What a control-mode notification says, typed, for matching on.
 *
 * <pre>{@code
 * switch (event.notification()) {
 *     case Notification.WindowRenamed(WindowId window, String name, boolean attached) -> relabel(window, name);
 *     case Notification.SessionsChanged changed -> refreshSessions();
 *     default -> {}
 * }
 * }</pre>
 *
 * <p>Sealed, with {@link Unknown} as the case for everything else. tmux adds notifications between
 * releases, and a closed set with nowhere to put a new one would drop it; here a notification this
 * library does not model yet still arrives, as {@code Unknown}, and {@link ControlEvent#kind()} and
 * {@link ControlEvent#fields()} still carry what tmux wrote.
 *
 * <p>The forms are tmux's own, from {@code control-notify.c}. A name — of a window, a session, a
 * client — is everything after the id, spaces included, as tmux writes it.
 */
public sealed interface Notification {

    /** {@code %window-add}: a window was created; {@code attached} is false for {@code unlinked-window-add}. */
    record WindowAdded(WindowId window, boolean attached) implements Notification {}

    /** {@code %window-close}: a window was destroyed; {@code attached} as for {@link WindowAdded}. */
    record WindowClosed(WindowId window, boolean attached) implements Notification {}

    /** {@code %window-renamed}: a window has a new name; {@code attached} as for {@link WindowAdded}. */
    record WindowRenamed(WindowId window, String name, boolean attached) implements Notification {}

    /** {@code %window-pane-changed}: a window's active pane changed. */
    record WindowPaneChanged(WindowId window, PaneId pane) implements Notification {}

    /** {@code %layout-change}: a window's layout changed, in whichever form tmux reports it. */
    record LayoutChanged(WindowId window, WindowLayout layout) implements Notification {}

    /** {@code %session-changed}: the attached client is now attached to this session. */
    record SessionChanged(SessionId session, String name) implements Notification {}

    /** {@code %session-renamed}: a session has a new name. */
    record SessionRenamed(SessionId session, String name) implements Notification {}

    /** {@code %sessions-changed}: a session was created or destroyed. */
    record SessionsChanged() implements Notification {}

    /** {@code %session-window-changed}: a session's current window changed. */
    record SessionWindowChanged(SessionId session, WindowId window) implements Notification {}

    /** {@code %client-session-changed}: another client is now attached to this session. */
    record ClientSessionChanged(String client, SessionId session, String name) implements Notification {}

    /** {@code %client-detached}: a client detached. */
    record ClientDetached(String client) implements Notification {}

    /** {@code %pane-mode-changed}: a pane entered or left a mode. */
    record PaneModeChanged(PaneId pane) implements Notification {}

    /** {@code %paste-buffer-changed}: a paste buffer was created or changed. */
    record PasteBufferChanged(String buffer) implements Notification {}

    /** {@code %paste-buffer-deleted}: a paste buffer was deleted. */
    record PasteBufferDeleted(String buffer) implements Notification {}

    /**
     * {@code %subscription-changed}: a watched format has a new value.
     *
     * @param name what the subscription was registered under
     * @param value what the format expanded to
     * @param session the session it is about, when tmux named one
     * @param window the window, when tmux named one
     * @param pane the pane, when tmux named one
     */
    record SubscriptionChanged(
            String name, String value, Optional<SessionId> session, Optional<WindowId> window, Optional<PaneId> pane)
            implements Notification {}

    /**
     * {@code %pause}: tmux stopped sending a pane's output to this client, which turned flow control
     * on with {@code refresh-client -f pause-after=N} and fell N seconds behind. {@code refresh-client
     * -A '%1:continue'} resumes it. tmux 3.2 and later.
     */
    record Pause(PaneId pane) implements Notification {}

    /** {@code %continue}: a paused pane's output flows to this client again. tmux 3.2 and later. */
    record Continue(PaneId pane) implements Notification {}

    /** {@code %message}: text another client showed on this one with {@code display-message -c}. tmux 3.4 and later. */
    record Message(String text) implements Notification {}

    /** {@code %config-error}: a configuration file tmux loaded for this client had an error. tmux 3.4 and later. */
    record ConfigError(String cause) implements Notification {}

    /** {@code %exit}: the client is exiting, with tmux's reason when it gave one. */
    record Exit(Optional<String> reason) implements Notification {}

    /** A notification this library does not model; {@link ControlEvent} still carries all of it. */
    record Unknown(String kind) implements Notification {}

    /**
     * Reads one notification from its kind and the text after it.
     *
     * @param kind the name without its {@code %}
     * @param rest what followed the name, as tmux wrote it, without any {@code " : "} value
     * @param value what followed {@code " : "}, which only a subscription carries
     */
    static Notification read(String kind, String rest, Optional<String> value) {
        String[] words = rest.isEmpty() ? new String[0] : rest.split(" ", -1);
        String first = words.length > 0 ? words[0] : "";
        String afterFirst = rest.indexOf(' ') < 0 ? "" : rest.substring(rest.indexOf(' ') + 1);
        String second = words.length > 1 ? words[1] : "";
        String afterSecond = afterFirst.indexOf(' ') < 0 ? "" : afterFirst.substring(afterFirst.indexOf(' ') + 1);
        Notification read =
                switch (kind) {
                    case "window-add", "unlinked-window-add" ->
                        window(first)
                                .map(w -> (Notification) new WindowAdded(w, kind.equals("window-add")))
                                .orElse(null);
                    case "window-close", "unlinked-window-close" ->
                        window(first)
                                .map(w -> (Notification) new WindowClosed(w, kind.equals("window-close")))
                                .orElse(null);
                    case "window-renamed", "unlinked-window-renamed" ->
                        window(first)
                                .map(w ->
                                        (Notification) new WindowRenamed(w, afterFirst, kind.equals("window-renamed")))
                                .orElse(null);
                    case "window-pane-changed" ->
                        window(first)
                                .flatMap(w -> pane(second).map(p -> (Notification) new WindowPaneChanged(w, p)))
                                .orElse(null);
                    case "layout-change" ->
                        window(first)
                                .map(w -> (Notification) new LayoutChanged(w, WindowLayout.of(second)))
                                .orElse(null);
                    case "session-changed" ->
                        session(first)
                                .map(s -> (Notification) new SessionChanged(s, afterFirst))
                                .orElse(null);
                    case "session-renamed" ->
                        session(first)
                                .map(s -> (Notification) new SessionRenamed(s, afterFirst))
                                .orElse(null);
                    case "sessions-changed" -> new SessionsChanged();
                    case "session-window-changed" ->
                        session(first)
                                .flatMap(s -> window(second).map(w -> (Notification) new SessionWindowChanged(s, w)))
                                .orElse(null);
                    case "client-session-changed" ->
                        session(second)
                                .map(s -> (Notification) new ClientSessionChanged(first, s, afterSecond))
                                .orElse(null);
                    case "client-detached" -> first.isEmpty() ? null : new ClientDetached(rest);
                    case "pane-mode-changed" ->
                        pane(first)
                                .map(p -> (Notification) new PaneModeChanged(p))
                                .orElse(null);
                    case "paste-buffer-changed" -> first.isEmpty() ? null : new PasteBufferChanged(rest);
                    case "paste-buffer-deleted" -> first.isEmpty() ? null : new PasteBufferDeleted(rest);
                    case "subscription-changed" ->
                        first.isEmpty()
                                ? null
                                : new SubscriptionChanged(
                                        first,
                                        value.orElse(""),
                                        words.length > 1 ? session(words[1]) : Optional.empty(),
                                        words.length > 2 ? window(words[2]) : Optional.empty(),
                                        words.length > 4 ? pane(words[4]) : Optional.empty());
                    case "pause" ->
                        pane(first).map(p -> (Notification) new Pause(p)).orElse(null);
                    case "continue" ->
                        pane(first).map(p -> (Notification) new Continue(p)).orElse(null);
                    case "message" -> new Message(rest);
                    case "config-error" -> new ConfigError(rest);
                    case "exit" -> new Exit(rest.isEmpty() ? Optional.empty() : Optional.of(rest));
                    default -> null;
                };
        return read == null ? new Unknown(kind) : read;
    }

    private static Optional<WindowId> window(String word) {
        return word.startsWith("@") && word.length() > 1 ? optional(() -> new WindowId(word)) : Optional.empty();
    }

    private static Optional<SessionId> session(String word) {
        return word.startsWith("$") && word.length() > 1 ? optional(() -> new SessionId(word)) : Optional.empty();
    }

    private static Optional<PaneId> pane(String word) {
        return word.startsWith("%") && word.length() > 1 ? optional(() -> new PaneId(word)) : Optional.empty();
    }

    /** An id tmux wrote in a form the library refuses is not an id this can report. */
    private static <T> Optional<T> optional(java.util.function.Supplier<T> id) {
        try {
            return Optional.of(id.get());
        } catch (IllegalArgumentException malformed) {
            return Optional.empty();
        }
    }
}

package io.github.libtmux.control;

import io.github.libtmux.PaneId;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.Objects;

/**
 * Terminal output tmux pushed without being asked.
 *
 * <p>tmux cuts a pane's output into pieces by byte count, not by character. {@code bytes} is
 * exactly what one piece carried, so a pane's pieces concatenate to what it wrote. {@code data} is
 * the same output as text, decoded per pane: a character cut between two pieces arrives whole with
 * the later one, and a byte that is not UTF-8 is written {@code \xHH}.
 *
 * @param pane the pane that produced it
 * @param data this piece as text
 * @param bytes this piece exactly, read-only
 */
public record PaneOutput(PaneId pane, String data, ByteBuffer bytes) {

    /** Copies {@code bytes}, from its position to its limit, so the record cannot change. */
    public PaneOutput {
        Objects.requireNonNull(pane, "pane");
        Objects.requireNonNull(data, "data");
        ByteBuffer copy =
                ByteBuffer.allocate(Objects.requireNonNull(bytes, "bytes").remaining());
        copy.put(bytes.duplicate()).flip();
        bytes = copy.asReadOnlyBuffer();
    }

    /** Output whose bytes are {@code data} in UTF-8. */
    public PaneOutput(PaneId pane, String data) {
        this(pane, data, ByteBuffer.wrap(data.getBytes(StandardCharsets.UTF_8)));
    }

    /** This piece's bytes, read-only, positioned at the first. */
    @Override
    public ByteBuffer bytes() {
        return bytes.duplicate();
    }

    /** Identifies the pane only: the data is terminal content. */
    @Override
    public String toString() {
        return "PaneOutput[" + pane + ", characters=" + data.length() + ", bytes=" + bytes.remaining() + "]";
    }
}

package io.github.libtmux;

/**
 * How big something is, in terminal cells.
 *
 * <p>A pair rather than two loose numbers, because width and height are only meaningful together and
 * a call site that takes them separately can transpose them without the compiler noticing.
 *
 * @param width columns
 * @param height rows
 */
public record Dimensions(int width, int height) {

    public Dimensions {
        if (width < 0 || height < 0) {
            throw new IllegalArgumentException("dimensions are negative: " + width + "x" + height);
        }
    }

    @Override
    public String toString() {
        return width + "x" + height;
    }
}

package io.github.libtmux;

/**
 * Which way to move or grow something.
 *
 * <p>An enum rather than tmux's {@code -U -D -L -R} flags, so a call site says which way it means
 * and a wrong direction cannot be spelled at all.
 */
public enum Direction {
    UP("-U"),
    DOWN("-D"),
    LEFT("-L"),
    RIGHT("-R");

    private final String flag;

    Direction(String flag) {
        this.flag = flag;
    }

    /** The tmux flag that selects this direction. */
    String flag() {
        return flag;
    }
}

package io.github.libtmux;

import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import io.github.libtmux.exception.LibTmuxException;
import io.github.libtmux.exception.ServerUnavailableException;
import io.github.libtmux.snapshot.ServerSnapshot;
import io.github.libtmux.transport.CommandResult;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import kotlin.annotations.jvm.ReadOnly;
import org.jspecify.annotations.Nullable;

/**
 * The environment tmux gives to processes it starts, at one scope.
 *
 * <p>tmux keeps one environment per server and one per session, and hands the result to every
 * process it spawns afterwards. That is what this is for: a pane opened later sees what is set here,
 * so it is how a program refreshes a value that goes stale in a long-lived session — {@code
 * SSH_AUTH_SOCK} after reconnecting, a token, a display.
 *
 * <p>A scope is chosen when the view is obtained rather than passed to every call, as {@link
 * Options} does, so a caller cannot read one scope and write another. There are only the two scopes,
 * because tmux has only those two.
 *
 * <p>A name is in one of three states, and they are not the same question. It can be <em>set</em> to
 * a value, which {@link #get} answers. It can be <em>removed</em>, which is tmux's way of saying a
 * new process should not inherit it even though the server's own environment has it — {@link
 * #isRemoved} answers that, and {@link #get} is empty for it. Or it can simply be absent, which is
 * both of those empty.
 */
public final class Environment {

    /**
     * tmux prints the environment as shell, and that is the only form of it that can be read back.
     *
     * <p>Its plain form puts one name per line, which is not a fact about the value: a value holding
     * a newline occupies several lines and nothing marks where it ends. A value of {@code
     * "first\nSECOND=injected\n-PATH"} read back as {@code first}, invented a variable called
     * {@code SECOND}, and reported {@code PATH} as one this session refuses to pass on. All three
     * from one read of a value tmux had stored perfectly.
     *
     * <p>{@code -s} is unambiguous instead: a value is quoted and its {@code $}, backtick, {@code "}
     * and {@code \} are escaped, so the only unescaped quote is the one that ends it. Present since
     * 3.2a, where the flag and the two format strings are already what they are now. One release
     * writes it differently — see {@link #repaired}.
     */
    private static final List<String> SHELL_FORM = List.of("-s");

    /** How tmux ends a value: the closing quote, then the export that makes it shell. */
    private static final String EXPORTED = "\"; export ";

    private final Server server;
    private final @Nullable ServerSnapshot snapshot;
    private final List<String> scope;

    private Environment(Server server, @Nullable ServerSnapshot snapshot, List<String> scope) {
        this.server = server;
        this.snapshot = snapshot;
        this.scope = scope;
    }

    static Environment global(Server server) {
        return new Environment(server, null, List.of("-g"));
    }

    static Environment session(Server server, ServerSnapshot snapshot, SessionId session) {
        return new Environment(server, snapshot, List.of("-t", session.value()));
    }

    /**
     * The value set for this name, or empty when it is removed or absent.
     *
     * @throws ServerUnavailableException if no daemon is running
     * @throws LibTmuxException if the read otherwise fails
     */
    @Operation(Kind.READ)
    public Optional<String> get(String name) {
        return entry(name).flatMap(Entry::value);
    }

    /**
     * Whether new processes are told not to inherit this name.
     *
     * @throws ServerUnavailableException if no daemon is running
     * @throws LibTmuxException if the read otherwise fails
     */
    @Operation(Kind.READ)
    public boolean isRemoved(String name) {
        return entry(name).filter(Entry::removed).isPresent();
    }

    /** Every name set at this scope, in tmux's order. Removed names are not values, so not here. */
    @ReadOnly
    @Operation(Kind.READ)
    public Map<String, String> all() {
        Map<String, String> values = new LinkedHashMap<>();
        for (Map.Entry<String, Entry> entry : listing().entrySet()) {
            entry.getValue().value().ifPresent(value -> values.put(entry.getKey(), value));
        }
        return Collections.unmodifiableMap(values);
    }

    /**
     * What a process started from this scope is actually handed, both scopes taken together.
     *
     * <p>{@link #all} answers for one scope, which is what a caller writing to it needs and not what
     * a pane opened later will see: tmux gives a new process the server's environment with the
     * session's laid over it, minus whatever the session marked as not to be inherited. At the
     * server scope the two are the same thing.
     *
     * <p>The counterpart to {@link Options#effective()}, and named after it.
     *
     * @throws ServerUnavailableException if no daemon is running
     * @throws LibTmuxException if a read otherwise fails
     */
    @ReadOnly
    @Operation(Kind.READ)
    public Map<String, String> effective() {
        if (snapshot == null) {
            return all();
        }
        Map<String, String> merged = new LinkedHashMap<>(server.environment().all());
        merged.keySet().removeAll(removed());
        merged.putAll(all());
        return Collections.unmodifiableMap(merged);
    }

    /** Every name this scope tells a new process not to inherit. */
    @ReadOnly
    @Operation(Kind.READ)
    public Set<String> removed() {
        Set<String> names = new LinkedHashSet<>();
        listing().forEach((name, entry) -> {
            if (entry.removed()) {
                names.add(name);
            }
        });
        return Collections.unmodifiableSet(names);
    }

    /**
     * Sets a name to a literal value.
     *
     * <p>The value is not expanded: a {@code #{...}} in it arrives as those characters. {@link
     * #setExpanded} is how to ask for the other thing.
     */
    @Operation(Kind.MUTATION)
    public void set(String name, String value) {
        run(argv(List.of("--", required(name), value)));
    }

    /** Sets a name to what a tmux format expands to now. */
    @Operation(Kind.MUTATION)
    public void setExpanded(String name, String format) {
        run(argv(List.of("-F", "--", required(name), format)));
    }

    /** Removes the name from this scope, so it is neither set nor marked. */
    @Operation(Kind.MUTATION)
    public void unset(String name) {
        run(argv(List.of("-u", "--", required(name))));
    }

    /**
     * Tells processes started after this not to inherit the name.
     *
     * <p>Different from {@link #unset}: the name is remembered, as removed, and tmux subtracts it
     * from what a new process is given rather than simply not adding it.
     */
    @Operation(Kind.MUTATION)
    public void remove(String name) {
        run(argv(List.of("-r", "--", required(name))));
    }

    /** What tmux holds for one name: a value, or the mark that says not to pass it on. */
    private record Entry(Optional<String> value, boolean removed) {}

    /**
     * What tmux holds for this name, or empty when it does not have the name at all.
     *
     * <p>tmux reports an absent name as a failure, which is the one failure here that is an answer;
     * anything else it says is a read that did not happen and is raised.
     */
    private Optional<Entry> entry(String name) {
        List<String> argv = new ArrayList<>(showArgv(SHELL_FORM));
        argv.addAll(List.of("--", required(name)));
        CommandResult result = cmd(argv);
        if (result.succeeded()) {
            return Optional.ofNullable(repaired(parse(result.stdout())).get(name));
        }
        if (result.stderr().stream().anyMatch(line -> line.contains("unknown variable"))) {
            return Optional.empty();
        }
        throw server.failed("show-environment", result);
    }

    private Map<String, Entry> listing() {
        return repaired(parse(run(showArgv(SHELL_FORM)).stdout()));
    }

    /**
     * Undoes the one release that writes a value differently.
     *
     * <p>tmux 3.4 puts a second backslash before a {@code $} that a name begins after, so unescaping
     * leaves one in the value and {@code $HOME} reads back as {@code \$HOME}. Measured: 3.3a, 3.5
     * and 3.7c write one backslash where 3.4 writes two, and all of them write one before a bare
     * {@code $}, a space or a digit. The encoding stays reversible — a value that really holds
     * {@code \$HOME} arrives with one backslash more again — so the extra one can be taken back off.
     *
     * <p>Nothing in the text says which release wrote it, so the version has to. It is only asked
     * when a value carries the shape at all, which is rare enough that an ordinary read never pays
     * for it.
     */
    private Map<String, Entry> repaired(Map<String, Entry> parsed) {
        boolean affected = parsed.values().stream()
                .anyMatch(entry -> entry.value()
                        .filter(value -> extraBackslash(value, 0) >= 0)
                        .isPresent());
        if (!affected) {
            return parsed;
        }
        TmuxVersion running = snapshot == null ? server.version() : server.version(snapshot);
        if (running.major() != 3 || running.minor() != 4) {
            return parsed;
        }
        Map<String, Entry> repaired = new LinkedHashMap<>(parsed.size());
        parsed.forEach((name, entry) -> repaired.put(
                name, new Entry(entry.value().map(Environment::withoutTheExtraBackslash), entry.removed())));
        return repaired;
    }

    /** Where a backslash stands before a {@code $} that a name begins after, or {@code -1}. */
    private static int extraBackslash(String value, int from) {
        for (int index = value.indexOf("\\$", from); index >= 0; index = value.indexOf("\\$", index + 1)) {
            int after = index + 2;
            if (after < value.length() && beginsAName(value.charAt(after))) {
                return index;
            }
        }
        return -1;
    }

    /**
     * What tmux 3.4 puts the extra backslash in front of, and the other releases do not.
     *
     * <p>ASCII letters only, because that is what tmux tests for: measured on 3.4, {@code $é} takes
     * one backslash where {@code $e} takes two. Reading it as any letter would take a backslash off
     * a value that really held {@code \$é}.
     */
    private static boolean beginsAName(char character) {
        return character == '_'
                || character == '{'
                || (character >= 'a' && character <= 'z')
                || (character >= 'A' && character <= 'Z');
    }

    private static String withoutTheExtraBackslash(String value) {
        StringBuilder plain = new StringBuilder(value.length());
        int at = 0;
        for (int found = extraBackslash(value, at); found >= 0; found = extraBackslash(value, at)) {
            plain.append(value, at, found);
            at = found + 1;
        }
        return plain.append(value, at, value.length()).toString();
    }

    /**
     * Reads tmux's shell form back into names and values.
     *
     * <p>A value runs from the quote after its name to the next unescaped quote, however many lines
     * that crosses. Nothing else can end it: tmux escapes every quote inside a value, so a value
     * carrying {@code "; export EVIL;} is quoted rather than obeyed.
     */
    private static Map<String, Entry> parse(List<String> lines) {
        Map<String, Entry> held = new LinkedHashMap<>();
        String open = null;
        StringBuilder value = new StringBuilder();
        for (String line : lines) {
            if (open == null) {
                if (line.startsWith("unset ") && line.endsWith(";")) {
                    held.put(line.substring("unset ".length(), line.length() - 1), new Entry(Optional.empty(), true));
                    continue;
                }
                int quoted = line.indexOf("=\"");
                if (quoted < 0) {
                    continue;
                }
                open = line.substring(0, quoted);
                value.setLength(0);
                value.append(line, quoted + 2, line.length());
            } else {
                value.append('\n').append(line);
            }
            String ended = ends(value.toString(), open);
            if (ended != null) {
                held.put(open, new Entry(Optional.of(unescape(ended)), false));
                open = null;
            }
        }
        return held;
    }

    /** The value without its terminator, or null while the value is still open. */
    private static @Nullable String ends(String sofar, String name) {
        String terminator = EXPORTED + name + ";";
        if (!sofar.endsWith(terminator)) {
            return null;
        }
        String body = sofar.substring(0, sofar.length() - terminator.length());
        // A quote tmux escaped is part of the value, not the end of it, and a backslash can itself be
        // escaped — so what decides is whether the run of backslashes before the quote is even.
        int backslashes = 0;
        for (int index = body.length() - 1; index >= 0 && body.charAt(index) == '\\'; index--) {
            backslashes++;
        }
        return backslashes % 2 == 0 ? body : null;
    }

    /** tmux escapes exactly {@code $}, a backtick, {@code "} and {@code \}, each with one backslash. */
    private static String unescape(String value) {
        StringBuilder plain = new StringBuilder(value.length());
        for (int index = 0; index < value.length(); index++) {
            char character = value.charAt(index);
            if (character == '\\' && index + 1 < value.length()) {
                plain.append(value.charAt(++index));
            } else {
                plain.append(character);
            }
        }
        return plain.toString();
    }

    /**
     * tmux splits a name at the first {@code =}, so one inside it would set a different name; and a
     * newline inside one would put the rest of it on a line of its own, where nothing says it is a
     * name rather than a value.
     */
    private static String required(String name) {
        if (name.isEmpty() || name.indexOf('=') >= 0 || name.indexOf('\n') >= 0) {
            throw new IllegalArgumentException("not a variable name: '" + name + "'");
        }
        return name;
    }

    private List<String> argv(List<String> tail) {
        return command("set-environment", tail);
    }

    private List<String> showArgv(List<String> tail) {
        return command("show-environment", tail);
    }

    private List<String> command(String command, List<String> tail) {
        List<String> argv = new java.util.ArrayList<>(1 + scope.size() + tail.size());
        argv.add(command);
        argv.addAll(scope);
        argv.addAll(tail);
        return argv;
    }

    private CommandResult cmd(List<String> argv) {
        return snapshot == null ? server.cmd(argv) : server.cmd(snapshot, argv);
    }

    private CommandResult run(List<String> argv) {
        return snapshot == null ? server.run(argv) : server.run(snapshot, argv);
    }
}

package io.github.libtmux.exception;

/**
 * A lookup that required exactly one match, or at most one, did not get it.
 *
 * <p>Loosen or tighten the filter, or handle the case explicitly.
 */
public abstract sealed class CardinalityException extends LibTmuxException
        permits CardinalityException.NoMatch, CardinalityException.MultipleMatches {

    private static final long serialVersionUID = 1L;

    CardinalityException(String message) {
        super(message, null);
    }

    /** Nothing matched where the caller required something. */
    public static final class NoMatch extends CardinalityException {
        private static final long serialVersionUID = 1L;

        public NoMatch(String message) {
            super(message);
        }
    }

    /** More than one thing matched where the caller required at most one. */
    public static final class MultipleMatches extends CardinalityException {
        private static final long serialVersionUID = 1L;

        private final int atLeast;

        /** @param atLeast how many matched, at least; never less than two */
        public MultipleMatches(String message, int atLeast) {
            super(message);
            if (atLeast < 2) {
                throw new IllegalArgumentException("multiple matches are at least two, not " + atLeast);
            }
            this.atLeast = atLeast;
        }

        /**
         * How many matched, at least.
         *
         * <p>Exact when the matches came from a capture this library holds, as a handle lookup's do.
         * {@link io.github.libtmux.query.Selections} stops at the second match, since its source may be
         * lazy or unbounded, so there it is two.
         */
        public int atLeast() {
            return atLeast;
        }
    }
}

package io.github.libtmux.exception;

import java.util.List;

/**
 * tmux ran a command to completion and refused it.
 *
 * <p>The request reached a live server and tmux answered no: a duplicate session name, a target it
 * cannot find, an option it does not know. Resending the same command gets the same answer, so read
 * {@link #errorLines()} and change the request.
 */
public final class CommandRejectedException extends LibTmuxException {
    private static final long serialVersionUID = 1L;

    public CommandRejectedException(String message) {
        super(message, null);
    }

    /** A refusal of {@code command}, with tmux's exit status and the lines it printed. */
    public CommandRejectedException(String message, String command, int exitCode, List<String> errorLines) {
        super(message, null, command, exitCode, errorLines);
    }
}

package io.github.libtmux.exception;

import org.jspecify.annotations.Nullable;

/**
 * The control client ended, and anything reading from it will not resume.
 *
 * <p>Attach again with {@link io.github.libtmux.Server#control} and read a snapshot: the events this
 * client did not deliver are not replayed, because tmux keeps no history of them. {@link
 * #standardError()} is what the tmux process wrote to its error stream, bounded, and empty when it
 * wrote nothing.
 */
public final class ControlEndedException extends LibTmuxException {
    private static final long serialVersionUID = 1L;

    private final String standardError;
    private final boolean standardErrorTruncated;

    public ControlEndedException(String standardError, boolean standardErrorTruncated, @Nullable Throwable cause) {
        super(message(standardError, standardErrorTruncated), cause);
        this.standardError = standardError;
        this.standardErrorTruncated = standardErrorTruncated;
    }

    /** The error text captured before the process ended, possibly truncated. */
    public String standardError() {
        return standardError;
    }

    /** Whether the error stream continued past the captured bound. */
    public boolean standardErrorTruncated() {
        return standardErrorTruncated;
    }

    private static String message(String standardError, boolean truncated) {
        if (standardError.isEmpty()) {
            return "control client ended";
        }
        return "control client ended: " + standardError + (truncated ? " (truncated)" : "");
    }
}

package io.github.libtmux.exception;

import io.github.libtmux.transport.DispatchOutcome;
import io.github.libtmux.transport.Idempotence;
import java.util.Objects;
import org.jspecify.annotations.Nullable;

/**
 * The request did not complete, with how certain it is that tmux applied it.
 *
 * <p>"tmux never started" and "tmux timed out halfway" call for opposite recovery, so the certainty
 * travels with the failure. {@link #safeToRetry()} answers the question a caller usually has: whether
 * sending the exact same request again can do harm.
 */
public abstract sealed class DispatchException extends LibTmuxException
        permits DispatchException.Failed, DispatchException.TimedOut {

    private static final long serialVersionUID = 1L;

    // Deliberately not transient: an outcome lost in serialization would read as NOT_DISPATCHED to a
    // null-checking caller, which is the one answer that invites retrying a command tmux already ran.
    private final DispatchOutcome outcome;
    private final Idempotence idempotence;

    DispatchException(String message, DispatchOutcome outcome, Idempotence idempotence, @Nullable Throwable cause) {
        super(message, cause);
        this.outcome = Objects.requireNonNull(outcome, "outcome");
        this.idempotence = Objects.requireNonNull(idempotence, "idempotence");
    }

    /** How certain the transport is that tmux applied the request. */
    public DispatchOutcome outcome() {
        return outcome;
    }

    /** Whether every command in the request only reads, so running it twice changes nothing. */
    public Idempotence idempotence() {
        return idempotence;
    }

    /**
     * Whether sending the exact same request again cannot apply it twice.
     *
     * @return {@link DispatchOutcome#canRetryVerbatim} for this failure's outcome and idempotence
     */
    public boolean safeToRetry() {
        return outcome.canRetryVerbatim(idempotence);
    }

    /** The transport failed for a reason other than a deadline: tmux could not start, or the channel broke. */
    public static final class Failed extends DispatchException {
        private static final long serialVersionUID = 1L;

        public Failed(String message, DispatchOutcome outcome, @Nullable Throwable cause) {
            this(message, outcome, Idempotence.NOT_IDEMPOTENT, cause);
        }

        public Failed(String message, DispatchOutcome outcome, Idempotence idempotence, @Nullable Throwable cause) {
            super(message, outcome, idempotence, cause);
        }
    }

    /** The deadline passed before the request finished. */
    public static final class TimedOut extends DispatchException {
        private static final long serialVersionUID = 1L;

        public TimedOut(String message, DispatchOutcome outcome, @Nullable Throwable cause) {
            this(message, outcome, Idempotence.NOT_IDEMPOTENT, cause);
        }

        public TimedOut(String message, DispatchOutcome outcome, Idempotence idempotence, @Nullable Throwable cause) {
            super(message, outcome, idempotence, cause);
        }
    }
}

package io.github.libtmux.exception;

import java.util.List;
import java.util.Optional;
import java.util.OptionalInt;
import kotlin.annotations.jvm.ReadOnly;
import org.jspecify.annotations.Nullable;

/**
 * The root of every operational failure this library raises.
 *
 * <p>Unchecked, because a tmux failure can arise from any call and forcing every caller to declare
 * it would say nothing. Sealed, with every branch abstract, so matching on the permitted subtypes is
 * exhaustive in Java, Kotlin and Scala alike.
 *
 * <p>A failure that came from a tmux command carries that command, its exit status when it has one,
 * and the error lines tmux printed. Those lines, and the message that quotes them, name what tmux
 * named — sessions, windows, panes and buffers included.
 */
public abstract sealed class LibTmuxException extends RuntimeException
        permits CardinalityException,
                CommandRejectedException,
                ControlEndedException,
                DispatchException,
                MalformedResponseException,
                ServerUnavailableException,
                TargetGoneException,
                UnencodableTextException,
                UnsupportedFeatureException {

    private static final long serialVersionUID = 1L;

    private final @Nullable String command;
    private final int exitCode;
    private final String[] errorLines;

    LibTmuxException(String message, @Nullable Throwable cause) {
        this(message, cause, null, -1, List.of());
    }

    LibTmuxException(
            String message,
            @Nullable Throwable cause,
            @Nullable String command,
            int exitCode,
            List<String> errorLines) {
        super(message, cause);
        this.command = command;
        this.exitCode = exitCode;
        this.errorLines = errorLines.toArray(String[]::new);
    }

    /** The command that failed, when this failure came from one. */
    public Optional<String> command() {
        return Optional.ofNullable(command);
    }

    /** The process exit status, when the failure has one. */
    public OptionalInt exitCode() {
        return exitCode < 0 ? OptionalInt.empty() : OptionalInt.of(exitCode);
    }

    /** The error lines tmux printed, in full. Empty when this failure has none. */
    @ReadOnly
    public List<String> errorLines() {
        return List.of(errorLines);
    }
}

package io.github.libtmux.exception;

/**
 * tmux answered, and the answer did not have the shape this library asked for.
 *
 * <p>A listing row with the wrong number of fields, a number that did not parse, an identity that
 * was not one row: this library's own template disagreed with what tmux sent. Check the tmux release
 * is inside the supported range, and report it if it is.
 */
public final class MalformedResponseException extends LibTmuxException {
    private static final long serialVersionUID = 1L;

    public MalformedResponseException(String message) {
