package io.github.libtmux.exception;

/**
 * Text this JVM cannot hand to tmux intact, with no route left to send it by.
 *
 * <p>A child process receives its arguments as bytes, and the JVM encodes them with the platform's
 * native encoding — which is the locale's, decided before {@code main} runs. In a locale that is
 * not UTF-8 that encoding cannot carry most of Unicode, so tmux would receive {@code ?} where a
 * caller wrote {@code é}. The process transport therefore sends such a command over tmux's standard
 * input instead, which this library encodes itself, and this is raised only when that route is
 * already taken — a command that reads standard input — or when the text is in the endpoint, the
 * binary or socket path, which nothing but an argument can carry.
 *
 * <p>Only the environment removes the limit: start the JVM with {@code LC_ALL} or {@code LANG}
 * naming a UTF-8 locale. {@code -Dsun.jnu.encoding} and {@code -Dfile.encoding} do not, because the
 * native encoding is read before either is applied.
 *
 * <p>ASCII text is unaffected on every locale, and so is everything tmux sends back: a reply is
 * decoded as the UTF-8 tmux wrote rather than through the platform's encoding.
 */
public final class UnencodableTextException extends LibTmuxException {

    private static final long serialVersionUID = 1L;

    public UnencodableTextException(String message) {
        super(message, null);
    }

    /** Text refused because of {@code cause}, such as a path the platform cannot represent. */
    public UnencodableTextException(String message, Throwable cause) {
        super(message, cause);
    }
}

package io.github.libtmux.exception;

import io.github.libtmux.TmuxVersion;

/**
 * The running tmux does not have something the call asked for.
 *
 * <p>Raised instead of dropping the option. The Python sibling warns and carries on, which returns a
 * pane that differs from the one described in a way nothing downstream can detect; a caller who
 * asked for an empty pane and got a shell has no way to notice before something runs in it. Skip the
 * feature, or require a newer tmux.
 *
 * <p>The feature and the versions are in the message and not in accessors: a throwable is
 * serializable, so exposing a {@link TmuxVersion} here would mean making that serializable too.
 */
public final class UnsupportedFeatureException extends LibTmuxException {
    private static final long serialVersionUID = 1L;

    /** A feature that needs {@code required} or newer, on a server running {@code running}. */
    public UnsupportedFeatureException(String feature, TmuxVersion required, TmuxVersion running) {
        super(feature + " requires tmux " + required + ", but this server runs " + running, null);
    }

    /**
     * For a capability that is missing from a range rather than from everything before a release.
     *
     * <p>Not every gap is a floor: {@code run-shell} reports its command's output on 3.2a, loses it
     * in 3.3a and 3.4, and reports it again from 3.5. "Requires 3.5" would be a lie to a 3.2a
     * caller, for whom it works.
     */
    public UnsupportedFeatureException(String message) {
        super(message, null);
    }
}

package io.github.libtmux.format;

import io.github.libtmux.exception.MalformedResponseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import kotlin.annotations.jvm.ReadOnly;

/**
 * A listing template and the reader for the rows it produces.
 *
 * <p>tmux returns a listing as plain lines, so what separates one field from the next is whatever
 * string the client put between them — and tmux gives no character a special meaning there. Any
 * fixed choice is therefore something a user can put in a window name. A window named with the
 * separator turns an n-field template into n+1 fields and shifts everything after it, so a pane id
 * arrives where a name belongs, and nothing downstream can tell.
 *
 * <p>The separator is generated once per process instead. Colliding with it means naming a window
 * with the exact token this process happened to produce.
 */
public final class RowFormat {

    private static final String SEPARATOR = Tokens.perProcess();

    private static final String TERMINATOR = Tokens.generate();

    private static final Pattern SPLITTER = Pattern.compile(Pattern.quote(SEPARATOR));

    private final List<String> fields;
    private final String template;

    private RowFormat(List<String> fields) {
        this.fields = fields;
        this.template = String.join(
                        SEPARATOR,
                        fields.stream().map(field -> "#{" + field + "}").toList())
                + TERMINATOR;
    }

    /**
     * A format over the given tmux format names, in the order rows will report them.
     *
     * @param fields tmux format names, without the surrounding {@code #{}}
     */
    public static RowFormat of(String... fields) {
        if (fields.length == 0) {
            throw new IllegalArgumentException("a row format has no fields");
        }
        return new RowFormat(List.of(fields));
    }

    /** The argument to pass to tmux's {@code -F}. */
    public String template() {
        return template;
    }

    /** The token this process separates fields with. */
    public String separator() {
        return SEPARATOR;
    }

    String terminator() {
        return TERMINATOR;
    }

    /** How many fields a row must have. */
    public int size() {
        return fields.size();
    }

    /** One row's values, addressed by the field name that asked for them. */
    public final class Row {

        private final List<String> values;

        private Row(List<String> values) {
            this.values = values;
        }

        /** The field's value as tmux printed it. */
        public String text(String field) {
            return values.get(indexOf(field));
        }

        /**
         * The field as a whole number.
         *
         * @throws MalformedResponseException if tmux did not print one
         */
        public int number(String field) {
            String value = text(field);
            try {
                return Integer.parseInt(value);
            } catch (NumberFormatException e) {
                throw new MalformedResponseException(field + " was not a number", e);
            }
        }

        /**
         * The field as a whole count.
         *
         * @throws MalformedResponseException if tmux did not print one
         */
        public long count(String field) {
            String value = text(field);
            try {
                return Long.parseLong(value);
            } catch (NumberFormatException e) {
                throw new MalformedResponseException(field + " was not a count", e);
            }
        }

        /**
         * The field as one of tmux's flags, which it prints as 0 or 1.
         *
         * @throws MalformedResponseException if tmux printed anything else
         */
        public boolean flag(String field) {
            return switch (text(field)) {
                case "0" -> false;
                case "1" -> true;
                default -> throw new MalformedResponseException(field + " was neither 0 nor 1");
            };
        }

        private int indexOf(String field) {
            int index = fields.indexOf(field);
            if (index < 0) {
                throw new IllegalArgumentException(field + " is not a field of this format");
            }
            return index;
        }
    }

    /**
     * Reads a whole listing back into rows.
     *
     * <p>tmux ends a row with a newline and frames it no other way, so a listing's lines are not its
     * rows: a value carrying a newline arrives as several. A working directory may contain one, and
     * anything running in a pane may change into it, so this is caller-reachable rather than
     * theoretical. A row is closed by carrying every separator, not by the line ending.
     *
     * @param lines the listing as tmux printed it
     * @throws MalformedResponseException if the listing ends mid-row, or a row does not have exactly the
     *     expected number of fields
     */
    @ReadOnly
    public List<Row> rows(List<String> lines) {
        if (lines.stream().noneMatch(line -> line.endsWith(TERMINATOR))) {
            return lines.stream().map(line -> new Row(split(line))).toList();
        }
        List<Row> rows = new ArrayList<>();
        StringBuilder pending = new StringBuilder();
        boolean open = false;
        for (String line : lines) {
            if (open) {
                pending.append('\n');
            }
            pending.append(line);
            open = true;
            if (line.endsWith(TERMINATOR)) {
                int end = pending.length() - TERMINATOR.length();
                rows.add(new Row(split(pending.substring(0, end))));
                pending.setLength(0);
                open = false;
            }
        }
        if (open) {
            throw new MalformedResponseException("a tmux listing ended before its last row did");
        }
        return List.copyOf(rows);
    }

    /**
     * Reads one row back into its fields.
     *
     * @throws MalformedResponseException if the row does not have exactly the expected number of fields,
     *     which is the only chance to notice that something shifted
     */
    @ReadOnly
    public List<String> split(String row) {
        if (row.endsWith(TERMINATOR)) {
            row = row.substring(0, row.length() - TERMINATOR.length());
        }
        List<String> values = List.of(SPLITTER.split(row, -1));
        if (values.size() != fields.size()) {
            // Counts only: a row carries names and pane content, and this message reaches logs.
            throw new MalformedResponseException(
                    "expected " + fields.size() + " fields in a tmux row, got " + values.size());
        }
        return values;
    }
}

package io.github.libtmux.format;

import java.security.SecureRandom;
import java.util.HexFormat;

/**
 * The token this process marks its own text with.
 *
 * <p>tmux gives no character a special meaning in a name or in output, so any fixed marker is
 * something a user can produce. One random token per process makes a collision mean naming a window
 * with the exact value this run generated.
 *
 * <p>Hexadecimal, because the token is spliced into tmux format templates and into regular
 * expressions and must be inert in both.
 */
public final class Tokens {

    private static final String PROCESS = generate();

    private Tokens() {}

    /** A token generated once per process, shared by everything that needs to mark its own text. */
    public static String perProcess() {
        return PROCESS;
    }

    static String generate() {
        byte[] token = new byte[16];
        new SecureRandom().nextBytes(token);
        return HexFormat.of().formatHex(token);
    }
}

package io.github.libtmux;

import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import io.github.libtmux.internal.CommandStrings;
import io.github.libtmux.snapshot.ServerSnapshot;
import io.github.libtmux.transport.CommandResult;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import kotlin.annotations.jvm.ReadOnly;
import org.jspecify.annotations.Nullable;

/**
 * The tmux hooks at one scope.
 *
 * <p>A hook binds a tmux command to an event, so tmux runs it without a client asking.
 *
 * <p>Every hook is an array: several commands can hang off one event, and tmux runs them in order.
 * That is why a listing answers with a list per event rather than a value — a hook set once is a
 * list of one, not a special case.
 *
 * <p>Each hook lives at a particular scope, and not every hook lives at every one.
 * {@code pane-focus-in} is a window hook, {@code alert-bell} a session hook. Setting one at a scope
 * it does not belong to is accepted and then silently discarded, on every supported release — so a
 * hook that never fires is worth checking against {@link #all()} before it is worth debugging.
 */
public final class Hooks {

    private final Server server;
    private final @Nullable ServerSnapshot snapshot;
    private final List<String> scope;

    private Hooks(Server server, @Nullable ServerSnapshot snapshot, List<String> scope) {
        this.server = server;
        this.snapshot = snapshot;
        this.scope = scope;
    }

    static Hooks global(Server server) {
        return new Hooks(server, null, List.of("-g"));
    }

    static Hooks session(Server server, ServerSnapshot snapshot, SessionId session) {
        return new Hooks(server, snapshot, List.of("-t", session.value()));
    }

    static Hooks window(Server server, ServerSnapshot snapshot, WindowId window) {
        return new Hooks(server, snapshot, List.of("-w", "-t", window.value()));
    }

    static Hooks pane(Server server, ServerSnapshot snapshot, PaneId pane) {
        return new Hooks(server, snapshot, List.of("-p", "-t", pane.value()));
    }

    /**
     * Binds a tmux command to an event at this scope, replacing anything already bound to it.
     *
     * <p>Replacing, not adding: tmux discards the whole array. {@link #append} is how a second
     * command joins the first.
     */
    @Operation(Kind.MUTATION)
    public void set(String event, String command) {
        run(argv("set-hook", List.of("--", event, command)));
    }

    /**
     * As {@link #set(String, String)}, with the command as words rather than a line tmux parses.
     *
     * <p>Each word reaches tmux as itself, quoted for its command parser here, so a caller never has
     * to: {@code set("after-new-window", List.of("display-message", "it's #{window_name}"))} binds
     * exactly that message.
     */
    @Operation(Kind.MUTATION)
    public void set(String event, List<String> command) {
        set(event, words(command));
    }

    /** As {@link #append(String, String)}, with the command as words. */
    @Operation(Kind.MUTATION)
    public void append(String event, List<String> command) {
        append(event, words(command));
    }

    private static String words(List<String> command) {
        if (command.isEmpty()) {
            throw new IllegalArgumentException("a hook command has no words");
        }
        return CommandStrings.stringify(command);
    }

    /** Binds another command to an event, after whatever is already bound to it. */
    @Operation(Kind.MUTATION)
    public void append(String event, String command) {
        run(argv("set-hook", List.of("-a", "--", event, command)));
    }

    /** Removes everything bound to an event at this scope. */
    @Operation(Kind.MUTATION)
    public void unset(String event) {
        run(argv("set-hook", List.of("-u", "--", event)));
    }

    /**
     * Runs what is bound to an event now, without waiting for the event.
     *
     * <p>tmux spells this {@code set-hook -R}, which reads as setting something. It runs the hook
     * and binds nothing.
     */
    @Operation(Kind.MUTATION)
    public void run(String event) {
        run(argv("set-hook", List.of("-R", "--", event)));
    }

    /**
     * Every hook at this scope, keyed by event, each with its commands in the order tmux runs them.
     *
     * <p>tmux prints one line per entry, subscripted — {@code after-new-window[0]}. The subscript is
     * a position in the list rather than part of the name, so it becomes the ordering here and the
     * key stays the event a caller would look up.
     */
    @ReadOnly
    @Operation(Kind.READ)
    public Map<String, List<String>> all() {
        Map<String, List<String>> hooks = new LinkedHashMap<>();
        for (String line : run(argv("show-hooks", List.of())).stdout()) {
            int split = line.indexOf(' ');
            if (split <= 0) {
                continue;
            }
            String subscripted = line.substring(0, split);
            int open = subscripted.indexOf('[');
            String event = open < 0 ? subscripted : subscripted.substring(0, open);
            hooks.computeIfAbsent(event, key -> new ArrayList<>()).add(line.substring(split + 1));
        }
        hooks.replaceAll((event, commands) -> List.copyOf(commands));
        return Collections.unmodifiableMap(hooks);
    }

    private CommandResult run(List<String> argv) {
        return snapshot == null ? server.run(argv) : server.run(snapshot, argv);
    }

    private List<String> argv(String command, List<String> tail) {
        List<String> argv = new ArrayList<>(1 + scope.size() + tail.size());
        argv.add(command);
        argv.addAll(scope);
        argv.addAll(tail);
        return argv;
    }
}

package io.github.libtmux;

import io.github.libtmux.exception.TargetGoneException;
import io.github.libtmux.internal.CommandStrings;
import io.github.libtmux.snapshot.ServerSnapshot;
import io.github.libtmux.snapshot.WindowContext;
import io.github.libtmux.transport.CommandResult;
import java.util.List;
import java.util.Objects;
import java.util.OptionalLong;

/**
 * Which tmux server incarnation a handle or batch may act on: the pid tmux reports, and its start
 * time when known, since a pid alone is reusable — a tmux started on the pid of one just probed, as
 * a container's first processes often are, would otherwise answer as if it were that server.
 *
 * <p>Every guarded command is sent as tmux's own {@code if-shell -F} test of this condition, so a
 * server that has been replaced under a stale handle is refused before anything runs, rather than
 * acting on the wrong incarnation.
 */
final class IncarnationFence {

    private final Server server;
    private final ServerIdentity identity;

    IncarnationFence(Server server, ServerIdentity identity) {
        this.server = server;
        this.identity = identity;
    }

    ServerIdentity identity() {
        return identity;
    }

    ServerIdentity identity(ServerSnapshot snapshot) {
        return snapshot.serverPid().isPresent()
                ? identity.at(snapshot.serverPid().orElseThrow(), snapshot.serverStartTime())
                : identity;
    }

    void requireSameServer(Server other) {
        Objects.requireNonNull(other, "other");
        if (!identity.equals(other.identity())) {
            throw new IllegalArgumentException("handles belong to different tmux servers");
        }
    }

    void requireSameIncarnation(ServerSnapshot snapshot, Server other, ServerSnapshot otherSnapshot) {
        requireSameServer(other);
        if (!identity(snapshot).equals(other.identity(otherSnapshot))) {
            throw new IllegalArgumentException("handles belong to different tmux server incarnations");
        }
    }

    /** A condition true only on the server a capture named: its pid, and its start time when known. */
    static String incarnation(long pid, OptionalLong startTime) {
        String samePid = "#{==:#{pid}," + pid + "}";
        return startTime.isPresent()
                ? "#{&&:" + samePid + ",#{==:#{start_time}," + startTime.getAsLong() + "}}"
                : samePid;
    }

    /** Refuses to reach a tmux server that is not the one this handle was made against. */
    CommandResult guarded(ServerSnapshot snapshot, String command) {
        return guarded(snapshot, command, "");
    }

    CommandResult guarded(ServerSnapshot snapshot, String command, String input) {
        long pid = snapshot.serverPid()
                .orElseThrow(() -> new IllegalStateException("a live handle has no server process identity"));
        return guarded(pid, incarnation(pid, snapshot.serverStartTime()), command, input);
    }

    CommandResult guarded(long pid, String condition, String command, String input) {
        String stale = "libtmux-stale-handle-" + pid;
        CommandResult result = server.cmd(
                List.of("if-shell", "-F", condition, command, stale),
                server.config().defaultTimeout(),
                input);
        if (!result.succeeded() && result.stderr().stream().anyMatch(line -> line.contains(stale))) {
            throw new TargetGoneException("the tmux server this handle belonged to has ended");
        }
        return result;
    }

    /** As {@link #guarded(ServerSnapshot, String, String)}, refused as well once the window has gone. */
    CommandResult run(ServerSnapshot snapshot, WindowContext expected, List<String> argv) {
        long pid = snapshot.serverPid()
                .orElseThrow(() -> new IllegalStateException("a live handle has no server process identity"));
        String target = expected.session().value() + ":" + expected.index().value();
        String stale = "libtmux-stale-winlink-" + pid + "-" + expected.window().value();
        String condition = "#{&&:" + incarnation(pid, snapshot.serverStartTime()) + ",#{==:#{window_id},"
                + expected.window().value() + "}}";
        CommandResult result =
                server.cmd(List.of("if-shell", "-F", "-t", target, condition, CommandStrings.stringify(argv), stale));
        if (!result.succeeded() && result.stderr().stream().anyMatch(line -> line.contains(stale))) {
            throw new TargetGoneException("window " + expected.window() + " no longer exists here");
        }
        if (!result.succeeded()) {
            throw server.failed(argv.get(0), result);
        }
        return result;
    }
}

package io.github.libtmux.internal;

import java.util.ArrayList;
import java.util.List;

/**
 * Encodes a tmux command for each of the two parsers tmux reads commands with.
 *
 * <p>Every argv this takes is literal: what a caller meant, with nothing escaped for either parser.
 */
public final class CommandStrings {

    private CommandStrings() {}

    /**
     * Several commands as the flat argv tmux's own argv parser reads.
     *
     * <p>tmux ends a command at an argument whose last byte is {@code ;}, and keeps the semicolon
     * instead when a backslash precedes it, so an argument ending in one is escaped here and a bare
     * {@code ;} separates commands.
     */
    public static List<String> arguments(List<List<String>> commands) {
        List<String> argv = new ArrayList<>();
        for (List<String> command : commands) {
            if (!argv.isEmpty()) {
                argv.add(";");
            }
            for (String argument : command) {
                argv.add(escape(argument));
            }
        }
        return List.copyOf(argv);
    }

    /** One command as the string tmux's command parser reads, which is what {@code if-shell} takes. */
    public static String stringify(List<String> argv) {
        StringBuilder text = new StringBuilder();
        for (String argument : argv) {
            if (text.length() > 0) {
                text.append(' ');
            }
            appendArgument(text, argument);
        }
        return text.toString();
    }

    /**
     * Several commands as the one string tmux's parser reads as a group.
     *
     * <p>Each argument is quoted, so a semicolon inside one stays part of it and only the separators
     * between commands end a command.
     */
    public static String group(List<List<String>> commands) {
        StringBuilder text = new StringBuilder();
        for (List<String> argv : commands) {
            if (text.length() > 0) {
                text.append(" ; ");
            }
            text.append(stringify(argv));
        }
        return text.toString();
    }

    private static String escape(String argument) {
        return argument.endsWith(";") ? argument.substring(0, argument.length() - 1) + "\\;" : argument;
    }

    private static void appendArgument(StringBuilder text, String argument) {
        text.append('\'');
        for (int index = 0; index < argument.length(); index++) {
            switch (argument.charAt(index)) {
                case '\0' -> throw new IllegalArgumentException("a tmux argument cannot contain NUL");
                case '\n' ->
                    text.append('\'').append('"').append("\\n").append('"').append('\'');
                case '\r' ->
                    text.append('\'').append('"').append("\\r").append('"').append('\'');
                case '\'' -> text.append("'\\''");
                default -> text.append(argument.charAt(index));
            }
        }
        text.append('\'');
    }
}

package io.github.libtmux.internal;

import io.github.libtmux.transport.OperationReport;
import java.util.List;
import java.util.stream.Collectors;

/** What tmux printed on its error stream, as it appears in a failure's message. */
public final class ErrorText {

    private ErrorText() {}

    /**
     * {@code ": "} and the non-blank lines joined by {@code "; "}, or nothing when tmux printed none.
     *
     * <p>Capped at {@link OperationReport#ERROR_LIMIT} characters: a message lands in every log line
     * that prints the failure, and the failure's own {@code errorLines()} keeps the text whole.
     */
    public static String suffix(List<String> stderr) {
        String reported = stderr.stream().filter(line -> !line.isBlank()).collect(Collectors.joining("; "));
        if (reported.isEmpty()) {
            return "";
        }
        return ": "
                + (reported.length() <= OperationReport.ERROR_LIMIT
                        ? reported
                        : reported.substring(0, OperationReport.ERROR_LIMIT) + "…");
    }
}

package io.github.libtmux.internal;

import java.io.Closeable;
import java.io.IOException;
import java.time.Duration;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.BooleanSupplier;
import java.util.function.Supplier;

/** Owns bounded, idempotent termination of one process and its observable descendants. */
public final class ProcessTree {

    private static final Duration GRACEFUL_WAIT = Duration.ofMillis(250);
    private static final Duration FORCIBLE_WAIT = Duration.ofSeconds(5);

    private final Process root;
    private final Set<ProcessHandle> descendants = new LinkedHashSet<>();
    private boolean captured;
    private boolean captureFailed;
    private boolean terminated;
    private boolean reclaimed;

    /** Takes ownership of terminating {@code root} and descendants visible from it. */
    public ProcessTree(Process root) {
        this.root = Objects.requireNonNull(root, "root");
    }

    /** Retains descendants before another cleanup step can make the root disappear. */
    public synchronized void captureDescendants() {
        if (!captured && !terminated) {
            rememberDescendants();
            captured = true;
        }
    }

    /** Terminates the known process tree, closes the root's streams, and reports reclamation. */
    public synchronized boolean terminate() {
        if (terminated) {
            return reclaimed;
        }
        AtomicBoolean interrupted = new AtomicBoolean(Thread.interrupted());
        try {
            if (!captured) {
                rememberDescendants();
                captured = true;
            }
            stopProcesses(interrupted);
            boolean streamsClosed = closeStreams();
            reclaimed = !captureFailed
                    && streamsClosed
                    && !isAlive(root)
                    && descendants.stream().noneMatch(ProcessTree::isAlive);
        } catch (RuntimeException e) {
            reclaimed = false;
        } finally {
            terminated = true;
            if (interrupted.get()) {
                Thread.currentThread().interrupt();
            }
        }
        return reclaimed;
    }

    private void stopProcesses(AtomicBoolean interrupted) {
        signal(descendants, false);
        signalRoot(false);
        if (!awaitExit(this::allExited, GRACEFUL_WAIT, interrupted)) {
            signal(descendants, true);
            signalRoot(true);
            awaitExit(this::allExited, FORCIBLE_WAIT, interrupted);
        }
    }

    private boolean allExited() {
        return !isAlive(root) && descendants.stream().noneMatch(ProcessTree::isAlive);
    }

    private static boolean awaitExit(BooleanSupplier exited, Duration timeout, AtomicBoolean interrupted) {
        long deadline = System.nanoTime() + timeout.toNanos();
        while (!exited.getAsBoolean()) {
            long left = deadline - System.nanoTime();
            if (left <= 0) {
                return false;
            }
            try {
                Thread.sleep(Math.max(1, Math.min(10, TimeUnit.NANOSECONDS.toMillis(left))));
            } catch (InterruptedException e) {
                interrupted.set(true);
            }
        }
        return true;
    }

    private void rememberDescendants() {
        try {
            root.descendants().forEach(descendants::add);
        } catch (UnsupportedOperationException | SecurityException e) {
            // The root remains reclaimable when the platform cannot expose descendants.
        } catch (RuntimeException e) {
            captureFailed = true;
        }
    }

    private static void signal(Iterable<ProcessHandle> descendants, boolean forcibly) {
        List<ProcessHandle> ordered = new ArrayList<>();
        descendants.forEach(ordered::add);
        for (int index = ordered.size() - 1; index >= 0; index--) {
            ProcessHandle descendant = ordered.get(index);
            if (!isAlive(descendant)) {
                continue;
            }
            try {
                if (forcibly) {
                    descendant.destroyForcibly();
                } else {
                    descendant.destroy();
                }
            } catch (RuntimeException ignored) {
                // The bounded wait and final live check decide whether reclamation succeeded.
            }
        }
    }

    private void signalRoot(boolean forcibly) {
        if (!isAlive(root)) {
            return;
        }
        try {
            if (forcibly) {
                root.destroyForcibly();
            } else {
                root.destroy();
            }
        } catch (RuntimeException ignored) {
            // The bounded wait and final live check decide whether reclamation succeeded.
        }
    }

    private boolean closeStreams() {
        boolean closed = close(root::getOutputStream);
        closed &= close(root::getInputStream);
        closed &= close(root::getErrorStream);
        return closed;
    }

    private static boolean close(Supplier<? extends Closeable> stream) {
        try {
            stream.get().close();
            return true;
        } catch (IOException | RuntimeException e) {
            return false;
        }
    }

    private static boolean isAlive(Process process) {
        try {
            return process.isAlive();
        } catch (RuntimeException e) {
            return true;
        }
    }

    private static boolean isAlive(ProcessHandle process) {
        try {
            return process.isAlive();
        } catch (RuntimeException e) {
            return true;
        }
    }
}

package io.github.libtmux.internal;

import io.github.libtmux.exception.UnencodableTextException;
import java.nio.ByteBuffer;
import java.nio.CharBuffer;
import java.nio.charset.Charset;
import java.nio.charset.CharsetDecoder;
import java.nio.charset.CoderResult;
import java.nio.charset.CodingErrorAction;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Locale;

/** The UTF-8 boundary shared by process and control transports, in both directions. */
public final class Utf8 {

    /**
     * What this JVM encodes a child process's arguments with.
     *
     * <p>{@code sun.jnu.encoding} is the one the process builder actually uses; {@code
     * native.encoding} is the documented name for the same choice and stands in when the internal
     * property is absent. Read once, because the locale that decides it is read before {@code main}
     * and cannot change afterwards.
     */
    private static final boolean ARGUMENTS_ARE_UTF8 =
            argumentsAreUtf8(System.getProperty("sun.jnu.encoding", System.getProperty("native.encoding", "")));

    private Utf8() {}

    /**
     * Refuses argument text this JVM would corrupt on the way to tmux.
     *
     * <p>Checked here rather than at each call site because every process this library starts is
     * built from one of these lists, and a value that reaches tmux mangled is indistinguishable
     * there from one the caller meant.
     *
     * @throws UnencodableTextException if an argument holds non-ASCII text and this JVM's native
     *     encoding is not UTF-8
     */
    public static void requireEncodableArguments(List<String> argv) {
        int refused = firstUnencodable(argv);
        if (refused >= 0) {
            throw unencodable(refused);
        }
    }

    /** Whether this JVM can hand every one of these to a child process intact. */
    public static boolean encodable(List<String> argv) {
        return firstUnencodable(argv) < 0;
    }

    /** The first code point this JVM would corrupt as an argument, or -1 when there is none. */
    private static int firstUnencodable(List<String> argv) {
        if (ARGUMENTS_ARE_UTF8) {
            return -1;
        }
        for (String argument : argv) {
            for (int index = 0; index < argument.length(); index++) {
                if (argument.charAt(index) > 0x7f) {
                    return argument.codePointAt(index);
                }
            }
        }
        return -1;
    }

    /**
     * The offending code point and nothing else. A tmux argument carries pane content, socket paths
     * and session names, none of which belongs in a message that reaches a log.
     */
    private static UnencodableTextException unencodable(int codePoint) {
        return new UnencodableTextException("this JVM encodes tmux arguments as "
                + System.getProperty("sun.jnu.encoding", System.getProperty("native.encoding", "an unnamed encoding"))
                + ", which cannot carry " + String.format(Locale.ROOT, "U+%04X", codePoint)
                + "; start the JVM in a UTF-8 locale (LC_ALL=C.UTF-8) to pass non-ASCII text to tmux");
    }

    static boolean argumentsAreUtf8(String encoding) {
        try {
            return StandardCharsets.UTF_8.equals(Charset.forName(encoding));
        } catch (RuntimeException unknown) {
            // An unsupported or malformed name is not UTF-8, and refusing is the safe reading.
            return false;
        }
    }

    /** Decodes valid UTF-8 and writes each malformed byte as a recoverable {@code \xNN} escape. */
    public static String backslashReplace(byte[] bytes) {
        CharsetDecoder decoder = StandardCharsets.UTF_8
                .newDecoder()
                .onMalformedInput(CodingErrorAction.REPORT)
                .onUnmappableCharacter(CodingErrorAction.REPORT);
        ByteBuffer in = ByteBuffer.wrap(bytes);
        CharBuffer out = CharBuffer.allocate(bytes.length);
        StringBuilder text = new StringBuilder(bytes.length);
        while (true) {
            CoderResult result = decoder.decode(in, out, true);
            drainInto(out, text);
            if (result.isUnderflow()) {
                break;
            }
            for (int offset = 0; offset < result.length(); offset++) {
                escape(text, in.get(in.position() + offset));
            }
            in.position(in.position() + result.length());
        }
        decoder.flush(out);
        drainInto(out, text);
        return text.toString();
    }

    /**
     * Decodes one byte stream that arrives in pieces cut anywhere, as {@link #backslashReplace}
     * decodes a whole one. A character cut between two pieces is held back and returned whole with
     * the later piece. One per stream, on one thread.
     */
    public static final class Stream {

        private final CharsetDecoder decoder = StandardCharsets.UTF_8
                .newDecoder()
                .onMalformedInput(CodingErrorAction.REPORT)
                .onUnmappableCharacter(CodingErrorAction.REPORT);
        private byte[] held = new byte[0];

        /** The text this piece completes, leaving a character it only starts for the next. */
        public String decode(byte[] piece) {
            byte[] bytes = piece;
            if (held.length > 0) {
                bytes = java.util.Arrays.copyOf(held, held.length + piece.length);
                System.arraycopy(piece, 0, bytes, held.length, piece.length);
            }
            ByteBuffer in = ByteBuffer.wrap(bytes);
            CharBuffer out = CharBuffer.allocate(bytes.length);
            StringBuilder text = new StringBuilder(bytes.length);
            decoder.reset();
            while (true) {
                // Not the end of input: an incomplete character at the end stays in the buffer.
                CoderResult result = decoder.decode(in, out, false);
                drainInto(out, text);
                if (result.isUnderflow()) {
                    break;
                }
                for (int offset = 0; offset < result.length(); offset++) {
                    escape(text, in.get(in.position() + offset));
                }
                in.position(in.position() + result.length());
            }
            held = java.util.Arrays.copyOfRange(bytes, in.position(), bytes.length);
            return text.toString();
        }
    }

    private static void escape(StringBuilder text, byte value) {
        text.append("\\x")
                .append(Character.forDigit((value >> 4) & 0xf, 16))
                .append(Character.forDigit(value & 0xf, 16));
    }

    private static void drainInto(CharBuffer out, StringBuilder text) {
        out.flip();
        text.append(out);
        out.clear();
    }
}

package io.github.libtmux;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.jspecify.annotations.Nullable;

/** tmux's restricted JSON grammar and layout cells, for pre-mutation workspace validation. */
final class JsonLayout {
    private final String text;
    private int at;

    private JsonLayout(String text) {
        this.text = text;
    }

    static int leaves(String text) {
        JsonLayout parser = new JsonLayout(text);
        Map<String, Object> root = parser.object(1);
        parser.peek();
        if (parser.at != text.length() || !Long.valueOf(2).equals(root.get("V"))) throw invalid();
        Object layout = root.get("L");
        if (layout == null) throw invalid();
        var pending = new ArrayDeque<Object>();
        pending.push(layout);
        Set<Long> indexes = new HashSet<>();
        Set<Long> last = new HashSet<>();
        Set<Long> floating = new HashSet<>();
        int active = 0;
        while (!pending.isEmpty()) {
            if (!(pending.pop() instanceof Map<?, ?> cell)) throw invalid();
            number(cell.get("w"), 1, 10_000);
            number(cell.get("h"), 1, 10_000);
            number(cell.get("x"), -10_000, 10_000);
            number(cell.get("y"), -10_000, 10_000);
            Object type = cell.get("t");
            if ("p".equals(type)) {
                if (cell.containsKey("c") || !indexes.add(number(cell.get("i"), 0, Integer.MAX_VALUE))) {
                    throw invalid();
                }
                if (cell.containsKey("a")) {
                    if (!(cell.get("a") instanceof Boolean selected)) throw invalid();
                    if (selected && ++active > 1) throw invalid();
                } else if (cell.containsKey("l") && !last.add(number(cell.get("l"), 0, Integer.MAX_VALUE))) {
                    throw invalid();
                }
                if (cell.containsKey("z") && !floating.add(number(cell.get("z"), 0, Integer.MAX_VALUE - 1L))) {
                    throw invalid();
                }
            } else if ("h".equals(type) || "v".equals(type)) {
                if (!(cell.get("c") instanceof List<?> children) || children.size() < 2) throw invalid();
                for (Object child : children) pending.push(child);
            } else throw invalid();
        }
        return indexes.size();
    }

    private static long number(@Nullable Object value, long minimum, long maximum) {
        if (!(value instanceof Long number) || number < minimum || number > maximum) throw invalid();
        return number;
    }

    private Map<String, Object> object(int depth) {
        if (depth > 200) throw invalid();
        expect('{');
        Map<String, Object> fields = new LinkedHashMap<>();
        if (take('}')) return fields;
        do {
            String key = string();
            expect(':');
            if (fields.putIfAbsent(key, value(depth)) != null) throw invalid();
        } while (take(','));
        expect('}');
        return fields;
    }

    private Object value(int depth) {
        return switch (peek()) {
            case '{' -> object(depth + 1);
            case '[' -> {
                expect('[');
                List<Map<String, Object>> members = new ArrayList<>();
                if (!take(']')) {
                    do {
                        members.add(object(depth + 1));
                    } while (take(','));
                    expect(']');
                }
                yield members;
            }
            case '"' -> string();
            case 't' -> literal("true", true);
            case 'f' -> literal("false", false);
            default -> integer();
        };
    }

    private boolean literal(String spelling, boolean value) {
        if (!text.startsWith(spelling, at)) throw invalid();
        at += spelling.length();
        return value;
    }

    private long integer() {
        int start = at;
        if (at < text.length() && text.charAt(at) == '-') at++;
        int digits = at;
        while (at < text.length() && text.charAt(at) >= '0' && text.charAt(at) <= '9') at++;
        if (digits == at || (text.charAt(digits) == '0' && at - digits > 1)) throw invalid();
        try {
            return Long.parseLong(text.substring(start, at));
        } catch (NumberFormatException invalidNumber) {
            throw invalid();
        }
    }

    // tmux validates escapes but keeps their spelling, including in keys.
    private String string() {
        expect('"');
        int start = at;
        while (at < text.length()) {
            char ch = text.charAt(at++);
            if (ch == '"') {
                if (at - 1 == start) throw invalid();
                return text.substring(start, at - 1);
            }
            if (ch < 0x20) throw invalid();
            if (ch == '\\') {
                if (at == text.length()) throw invalid();
                char escaped = text.charAt(at++);
                if (escaped == 'u') {
                    for (int digit = 0; digit < 4; digit++) {
                        if (at == text.length() || "0123456789abcdefABCDEF".indexOf(text.charAt(at++)) < 0)
                            throw invalid();
                    }
                } else if ("\"\\/bfnrt".indexOf(escaped) < 0) throw invalid();
            }
        }
        throw invalid();
    }

    private char peek() {
        while (at < text.length() && " \t\r\n".indexOf(text.charAt(at)) >= 0) at++;
        return at == text.length() ? '\0' : text.charAt(at);
    }

    private boolean take(char token) {
        if (peek() != token) return false;
        at++;
        return true;
    }

    private void expect(char token) {
        if (!take(token)) throw invalid();
    }

    private static IllegalArgumentException invalid() {
        return new IllegalArgumentException("not a tmux JSON layout");
    }
}

package io.github.libtmux;

import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import io.github.libtmux.exception.ServerUnavailableException;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import kotlin.annotations.jvm.ReadOnly;
import org.jspecify.annotations.Nullable;

/**
 * The server's key bindings, in one key table or across all of them.
 *
 * <p>tmux keeps bindings in named tables: {@code prefix}, pressed after the prefix key, is where a
 * binding goes unless another table is named; {@code root} is pressed without it; the copy-mode
 * tables belong to copy mode. {@link Server#keys()} answers for {@code prefix} when binding and for
 * every table when listing; {@link #in} names one.
 *
 * <pre>{@code
 * server.keys().bind("F12", List.of("display-message", "hello"));
 * server.keys().in("root").bind("F11", List.of("next-window"));
 * }</pre>
 */
public final class Keys {

    private final Server server;
    private final @Nullable String table;

    Keys(Server server, @Nullable String table) {
        this.server = server;
        this.table = table;
    }

    /** The same bindings, in one named table. */
    @Operation(Kind.CAPTURED)
    public Keys in(String table) {
        Objects.requireNonNull(table, "table");
        if (table.isEmpty()) {
            throw new IllegalArgumentException("a key table has a name");
        }
        return new Keys(server, table);
    }

    /**
     * Binds a key to a tmux command, given as its words.
     *
     * <p>Each word reaches tmux as itself: the command is passed as arguments, never as a line for
     * tmux to split.
     */
    @Operation(Kind.MUTATION)
    public void bind(String key, List<String> command) {
        Objects.requireNonNull(key, "key");
        if (command.isEmpty()) {
            throw new IllegalArgumentException("a key binding has no command");
        }
        List<String> argv = new ArrayList<>(List.of("bind-key"));
        argv.addAll(scope());
        argv.add("--");
        argv.add(key);
        argv.addAll(command);
        server.run(argv);
    }

    /** Removes a key's binding. */
    @Operation(Kind.MUTATION)
    public void unbind(String key) {
        Objects.requireNonNull(key, "key");
        List<String> argv = new ArrayList<>(List.of("unbind-key"));
        argv.addAll(scope());
        argv.add("--");
        argv.add(key);
        server.run(argv);
    }

    /**
     * The bindings as tmux lists them, one per line.
     *
     * <p>Every table unless one was named. Read without starting a daemon to answer, which tmux
     * would otherwise do for {@code list-keys}: its tables are compiled in, so it can answer an
     * endpoint nothing serves by serving it.
     *
     * @throws ServerUnavailableException if no daemon is running
     */
    @ReadOnly
    @Operation(Kind.READ)
    public List<String> list() {
        List<String> argv = new ArrayList<>(List.of("list-keys"));
        argv.addAll(scope());
        return server.withoutStartingServer(argv).stdout();
    }

    private List<String> scope() {
        return table == null ? List.of() : List.of("-T", table);
    }
}

package io.github.libtmux;

import io.github.libtmux.exception.UnsupportedFeatureException;
import java.util.Arrays;
import java.util.Map;
import java.util.Optional;
import java.util.function.Function;

/**
 * One of tmux's built-in pane arrangements.
 *
 * <p>An enum rather than a string, and not for tidiness: {@code select-layout} with a name tmux does
 * not recognise <em>ends the server</em> on 3.3a, taking every session on that socket with it —
 * including sessions this program never created. Every other supported release answers
 * {@code invalid layout} and carries on.
 *
 * <p>A name that cannot be misspelled cannot trigger that. {@link Window#applyLayout} covers the
 * other way in, a serialized layout string, by checking it before tmux sees it.
 */
public enum Layout {
    EVEN_HORIZONTAL("even-horizontal"),
    EVEN_VERTICAL("even-vertical"),
    MAIN_HORIZONTAL("main-horizontal"),
    MAIN_VERTICAL("main-vertical"),
    TILED("tiled"),

    /** Requires tmux 3.5. */
    MAIN_HORIZONTAL_MIRRORED("main-horizontal-mirrored"),

    /** Requires tmux 3.5. */
    MAIN_VERTICAL_MIRRORED("main-vertical-mirrored");

    private final String name;

    Layout(String name) {
        this.name = name;
    }

    /** The name tmux knows this by. */
    public String tmuxName() {
        return name;
    }

    private static final Map<String, Layout> BY_TMUX_NAME =
            Arrays.stream(values()).collect(java.util.stream.Collectors.toMap(Layout::tmuxName, Function.identity()));

    /**
     * The layout with this exact tmux name, or empty if none matches.
     *
     * <p>One map built once, so a caller that already has a canonical name does not repeat the scan
     * over {@link #values()} that resolving an abbreviation already did.
     */
    public static Optional<Layout> byTmuxName(String name) {
        return Optional.ofNullable(BY_TMUX_NAME.get(name));
    }

    /**
     * The first supported release that has this layout.
     *
     * <p>A switch rather than a field, so that adding a layout cannot compile until someone says
     * which release brought it — and so the enum holds nothing but its name.
     */
    TmuxVersion since() {
        return switch (this) {
            case MAIN_HORIZONTAL_MIRRORED, MAIN_VERTICAL_MIRRORED -> new TmuxVersion(3, 5, "");
            case EVEN_HORIZONTAL, EVEN_VERTICAL, MAIN_HORIZONTAL, MAIN_VERTICAL, TILED -> new TmuxVersion(3, 2, "a");
        };
    }

    /** Refuses this layout when the running tmux predates it. */
    public void requireSupported(TmuxVersion running) {
        if (!running.atLeast(since())) {
            throw new UnsupportedFeatureException("the " + this + " layout", since(), running);
        }
    }

    @Override
    public String toString() {
        return name;
    }
}

package io.github.libtmux;

import io.github.libtmux.exception.LibTmuxException;
import io.github.libtmux.exception.MalformedResponseException;
import io.github.libtmux.exception.UnsupportedFeatureException;
import java.util.Arrays;
import java.util.List;
import java.util.Optional;
import org.jspecify.annotations.Nullable;

/**
 * Which layout names are safe to hand to tmux.
 *
 * <p>Public because every path that can reach select-layout needs it, not only the one that reads
 * a workspace file. This check exists because an unrecognised layout name does not produce an error on every tmux:
 * on 3.3a it crashes the server, taking down every session on that socket, including ones this
 * program never created. A workspace file is user-supplied text, so the name has to be checked
 * before it is dispatched rather than after tmux has had it.
 *
 * <p>tmux accepts either one of its named layouts or a serialized layout tmux itself produced. Since
 * 3.8 that serialized form is either the classic checksummed grammar or JSON, and {@code
 * select-layout} takes either back - but only JSON round-trips exactly. The classic grammar
 * carries no pane identity, only shape, so which process lands in which cell can differ from
 * where it started; see {@link Window#applyLayout}. The classic checksum is verified here; a
 * four-hex-digit prefix alone does not make the rest safe for tmux to parse. JSON carries no such
 * signature, so a JSON-shaped string is only trusted once the running tmux is new enough to have
 * written it - see {@link #requireSerialized}.
 */
public final class Layouts {

    private static final int MAX_DEPTH = 256;
    private static final List<String> NAMED =
            Arrays.stream(Layout.values()).map(Layout::tmuxName).toList();

    /**
     * tmux 3.8 added the JSON (v2) layout format: {@code layout_dump} in {@code layout-custom.c}
     * writes {@code {"V":2,"L":...}} instead of the checksummed string from that release on. Landed
     * at {@code bf43fdc0} in tmux's own history, which {@code git tag --contains} places on {@code
     * 3.8-rc} and nothing earlier. Every release before it has no JSON parser at all: {@code
     * layout_construct} dispatches purely on whether the input opens with a curly brace, and
     * anything that branch cannot parse ends the server outright on 3.3a. A JSON-shaped string is
     * therefore only something *this* tmux could have written once it is at least this version.
     */
    private static final TmuxVersion JSON_LAYOUT_SINCE = new TmuxVersion(3, 8, "");

    private Layouts() {}

    /**
     * Returns the layout unchanged, having checked tmux will recognise it.
     *
     * <p>Accepts the classic checksummed form, a JSON layout (by shape only — a running version is
     * needed to say whether this server could have written it, which {@link #require(String,
     * TmuxVersion)} does), a built-in name, or an unambiguous prefix of exactly one built-in name
     * ({@code layout_set_lookup} is a prefix match, so {@code tile} and {@code even-h} apply on
     * every tmux release). Ambiguity is judged against every name this library knows, not only the
     * ones the eventual server will have — the version to narrow that with is not available here.
     *
     * @throws IllegalArgumentException if tmux would not recognise the name, which on some versions
     *     is not a recoverable error
     */
    public static String require(String layout) {
        if (isSerialized(layout) || isJsonShaped(layout)) {
            return layout;
        }
        List<Layout> candidates = resolve(layout, List.of(Layout.values()));
        if (candidates.size() == 1) {
            return layout;
        }
        if (candidates.size() > 1) {
            // tmux does know this prefix - a narrower running version might make it unique, but
            // nothing here says it does not know it at all, which is what "not a tmux layout" claims.
            throw ambiguous(layout, candidates);
        }
        throw unknown(layout);
    }

    /**
     * Refuses a layout tmux would not recognise, and a built-in name or JSON layout the running
     * tmux predates.
     *
     * <p>An unknown name reaches {@code layout_parse} exactly as a malformed string does, so a
     * mirrored preset on a release older than 3.5 ends the server on 3.3a rather than being
     * refused. The version is read lazily, because a chain is built before it runs.
     *
     * <p>A prefix is resolved against only the names {@code running} actually has: {@code
     * layout_set_lookup} is compiled from a fixed table, so {@code main-h} is unambiguous on a
     * release before 3.5 (no mirrored variant exists to collide with) and ambiguous from 3.5 on —
     * confirmed against the matrix. Resolving against every name this library knows regardless of
     * version would refuse a prefix the running tmux itself accepts.
     *
     * @throws IllegalArgumentException if tmux would not recognise the layout
     * @throws UnsupportedFeatureException if the name or the JSON format arrived after this
     *     release
     */
    public static String require(String layout, TmuxVersion running) {
        if (isJsonShaped(layout)) {
            if (!running.atLeast(JSON_LAYOUT_SINCE)) {
                throw new UnsupportedFeatureException("a JSON layout", JSON_LAYOUT_SINCE, running);
            }
            return layout;
        }
        if (isSerialized(layout)) {
            return layout;
        }
        List<Layout> candidates = resolve(layout, supported(running));
        if (candidates.size() == 1) {
            candidates.getFirst().requireSupported(running);
            return layout;
        }
        if (candidates.size() > 1) {
            throw ambiguous(layout, candidates);
        }
        throw unknown(layout);
    }

    /**
     * The built-in layout a name or an unambiguous prefix of one denotes, resolved against what
     * {@code running} actually supports — the same resolution {@link #require(String, TmuxVersion)}
     * applies, exposed so a caller that must choose between the enum path and a raw string (a
     * workspace file's own dispatch) makes the same choice the guard just validated.
     */
    public static Optional<Layout> builtIn(String layout, TmuxVersion running) {
        List<Layout> candidates = resolve(layout, supported(running));
        return candidates.size() == 1 ? Optional.of(candidates.getFirst()) : Optional.empty();
    }

    /**
     * Validates a layout for a window and resolves a built-in abbreviation to its full name.
     *
     * <p>Version-sensitive names use the running daemon, or the selected client only when no
     * daemon is listening. Classic geometry and JSON cell structure are checked along with pane
     * counts. JSON layouts require tmux 3.8 and are limited to 200 nested objects, as in tmux.
     * Call this before creating windows or running setup scripts.
     *
     * @param layout a built-in name, unique abbreviation or serialized tree
     * @param server the endpoint which will apply the layout
     * @param paneCount the number of panes which the layout must accommodate
     * @return a full built-in name or the unchanged serialized layout
     * @throws IllegalArgumentException if the layout is invalid or has too few pane cells
     * @throws UnsupportedFeatureException if an exact built-in name requires a newer daemon
     * @throws LibTmuxException if the daemon or client version cannot be read
     */
    public static String require(String layout, Server server, int paneCount) {
        if (paneCount < 1) throw new IllegalArgumentException("pane count must be positive");
        if (!isJsonShaped(layout) && named(layout, new TmuxVersion(3, 4, "")).isEmpty()) require(layout);
        if (isJsonShaped(layout)) {
            require(layout, version(server));
            if (JsonLayout.leaves(layout) < paneCount) {
                throw new IllegalArgumentException("layout has fewer cells than panes: " + layout);
            }
            return layout;
        }
        int cells = leaves(layout);
        if (cells > 0) {
            if (cells < paneCount) throw new IllegalArgumentException("layout has fewer cells than panes: " + layout);
            return layout;
        }
        Optional<Layout> before = named(layout, new TmuxVersion(3, 4, ""));
        Optional<Layout> after = named(layout, new TmuxVersion(3, 5, ""));
        if (before.equals(after)) return before.orElseThrow().tmuxName();
        TmuxVersion running = version(server);
        for (Layout candidate : Layout.values()) {
            if (candidate.tmuxName().equals(layout)) candidate.requireSupported(running);
        }
        return named(layout, running)
                .orElseThrow(() -> ambiguous(layout, running))
                .tmuxName();
    }

    private static Optional<Layout> named(String value, TmuxVersion version) {
        return builtIn(value, version).filter(layout -> version.atLeast(layout.since()));
    }

    /**
     * An abbreviation that used to resolve on its own and now matches more than one name, because a
     * later release added a layout that shares its prefix. Names every candidate and the release
     * that introduced the collision, rather than only saying the name did not resolve.
     */
    private static IllegalArgumentException ambiguous(String layout, TmuxVersion running) {
        List<Layout> matches = prefixed(layout, supported(running));
        if (matches.size() < 2) {
            return new IllegalArgumentException("not a unique layout for tmux " + running + ": " + layout);
        }
        String names = matches.stream().map(Layout::tmuxName).collect(java.util.stream.Collectors.joining(", "));
        TmuxVersion introduced =
                matches.stream().map(Layout::since).max(TmuxVersion::compareTo).orElseThrow();
        return new IllegalArgumentException("not a unique layout for tmux " + running + ": " + layout + "; matches "
                + names + ", ambiguous since tmux " + introduced + "; use the full name");
    }

    private static TmuxVersion version(Server server) {
        try {
            return SessionCreation.versionForCreation(server);
        } catch (IllegalArgumentException invalid) {
            throw new MalformedResponseException("could not read tmux version", invalid);
        }
    }

    private static List<Layout> supported(TmuxVersion running) {
        return Arrays.stream(Layout.values())
                .filter(candidate -> running.atLeast(candidate.since()))
                .toList();
    }

    /** An exact match against every name this library knows, or else an unambiguous prefix of one in {@code pool}. */
    private static List<Layout> resolve(String layout, List<Layout> pool) {
        for (Layout candidate : Layout.values()) {
            if (candidate.tmuxName().equals(layout)) {
                return List.of(candidate);
            }
        }
        return prefixed(layout, pool);
    }

    /** Every candidate {@code layout} is a prefix of. Empty text prefixes everything, so it is refused up front. */
    private static List<Layout> prefixed(String layout, List<Layout> candidates) {
        if (layout.isEmpty()) {
            return List.of();
        }
        return candidates.stream()
                .filter(candidate -> candidate.tmuxName().startsWith(layout))
                .toList();
    }

    private static IllegalArgumentException ambiguous(String layout, List<Layout> candidates) {
        return new IllegalArgumentException("ambiguous layout prefix: '" + layout + "'; matches "
                + candidates.stream().map(Layout::tmuxName).toList());
    }

    private static IllegalArgumentException unknown(String layout) {
        return new IllegalArgumentException(
                "not a tmux layout: '" + layout + "'; expected one of " + NAMED + " or a serialized layout");
    }

    /**
     * Requires an exact layout string rather than a built-in layout name.
     *
     * <p>The classic form answers "did tmux write this?" by its own checksum, without needing to
     * know what tmux is running. JSON carries nothing equivalent, so the only question left to ask
     * is "could this tmux have written it?" - which is a version, not a parse. Recognising the shape
     * is as far as this goes: a JSON body that passes the shape check but is not real is tmux's own
     * problem to refuse, and it does, safely, on every release that understands the format at all
     * (confirmed against next-3.9: malformed JSON answers an ordinary parse error, never a crash).
     *
     * @throws IllegalArgumentException if the string is not a layout tmux wrote
     * @throws UnsupportedFeatureException if it is JSON-shaped but {@code running} predates the
     *     format, so it cannot be one this server wrote
     */
    static String requireSerialized(String layout, TmuxVersion running) {
        if (isSerialized(layout)) {
            return layout;
        }
        if (isJsonShaped(layout)) {
            if (!running.atLeast(JSON_LAYOUT_SINCE)) {
                throw new UnsupportedFeatureException("a JSON layout", JSON_LAYOUT_SINCE, running);
            }
            return layout;
        }
        throw new IllegalArgumentException("not a layout tmux wrote: " + layout);
    }

    /**
     * Whether {@code layout} has the shape of tmux's JSON (v2) format - not whether it is one.
     *
     * <p>Mirrors {@code layout_construct}'s own dispatch in {@code layout-custom.c}: tmux decides
     * between the two grammars on nothing more than whether the first non-blank byte is an opening
     * curly brace. Matching that exactly, rather than inspecting the body, is deliberate - the
     * layout is an opaque token tmux hands back and forth, and parsing its structure is tmux's job.
     * A leading dash fails this the same way it fails {@link #isSerialized}, so it still falls
     * through to the refusal below rather than reaching {@code select-layout} as a flag.
     */
    private static boolean isJsonShaped(String layout) {
        String trimmed = layout.strip();
        return trimmed.length() >= 2 && trimmed.charAt(0) == '{' && trimmed.charAt(trimmed.length() - 1) == '}';
    }

    private static boolean isSerialized(String layout) {
        return leaves(layout) > 0;
    }

    private static int leaves(String layout) {
        if (layout.length() < 6 || layout.charAt(4) != ',') {
            return -1;
        }
        for (int index = 0; index < 4; index++) {
            char digit = layout.charAt(index);
            if (!((digit >= '0' && digit <= '9') || (digit >= 'a' && digit <= 'f') || (digit >= 'A' && digit <= 'F'))) {
                return -1;
            }
        }
        int declared;
        try {
            declared = Integer.parseInt(layout.substring(0, 4), 16);
        } catch (NumberFormatException notHex) {
            return -1;
        }
        int checksum = 0;
        for (int index = 5; index < layout.length(); index++) {
            checksum = ((checksum >> 1) + ((checksum & 1) << 15)) & 0xffff;
            checksum = (checksum + layout.charAt(index)) & 0xffff;
        }
        String body = layout.substring(5);
        if (checksum != declared) return -1;
        Serialized parser = new Serialized(body);
        return parser.valid() ? parser.leaves : -1;
    }

    /** The subset parsed by tmux's layout_construct, with layout_check's size invariants. */
    private static final class Serialized {

        private final String value;
        private int at;
        private int leaves;

        Serialized(String value) {
            this.value = value;
        }

        boolean valid() {
            return cell(0) != null && at == value.length();
        }

        private @Nullable Cell cell(int depth) {
            if (depth > MAX_DEPTH) {
                return null;
            }
            int width = number('x');
            int height = number(',');
            int x = number(',');
            int y = unsigned();
            if (width < 1 || height < 1 || x < 0 || y < 0) {
                return null;
            }
            skipPaneId();
            if (at == value.length() || delimiter(value.charAt(at))) {
                leaves++;
                return new Cell(width, height);
            }

            char open = value.charAt(at++);
            char close;
            if (open == '{') {
                close = '}';
            } else if (open == '[') {
                close = ']';
            } else {
                return null;
            }

            List<Cell> children = new java.util.ArrayList<>();
            @Nullable Cell child = cell(depth + 1);
            if (child == null) {
                return null;
            }
            children.add(child);
            while (at < value.length() && value.charAt(at) == ',') {
                at++;
                child = cell(depth + 1);
                if (child == null) {
                    return null;
                }
                children.add(child);
            }
            if (at >= value.length() || value.charAt(at++) != close) {
                return null;
            }
            return fits(open, width, height, children) ? new Cell(width, height) : null;
        }

        private int number(char terminator) {
            int number = unsigned();
            if (number < 0 || at >= value.length() || value.charAt(at++) != terminator) {
                return -1;
            }
            return number;
        }

        private int unsigned() {
            int start = at;
            long number = 0;
            while (at < value.length() && value.charAt(at) >= '0' && value.charAt(at) <= '9') {
                number = number * 10 + value.charAt(at++) - '0';
                if (number > Integer.MAX_VALUE) {
                    return -1;
                }
            }
            return at == start ? -1 : (int) number;
        }

        /** A comma followed by another width belongs to the parent, not to this cell's pane id. */
        private void skipPaneId() {
            if (at >= value.length() || value.charAt(at) != ',') {
                return;
            }
            int saved = at++;
            int id = unsigned();
            if (id < 0 || (at < value.length() && value.charAt(at) == 'x')) {
                at = saved;
            }
        }

        private static boolean delimiter(char character) {
            return character == ',' || character == '}' || character == ']';
        }

        private static boolean fits(char open, int width, int height, List<Cell> children) {
            long total = children.size() - 1L;
            if (open == '{') {
                for (Cell child : children) {
                    if (child.height() != height) {
                        return false;
                    }
                    total += child.width();
                }
                return total == width;
            }
            for (Cell child : children) {
                if (child.width() != width) {
                    return false;
                }
                total += child.height();
            }
            return total == height;
        }
    }

    private record Cell(int width, int height) {}
}

package io.github.libtmux;

import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import io.github.libtmux.exception.LibTmuxException;
import java.util.List;
import kotlin.annotations.jvm.ReadOnly;

/**
 * The server's own message log, newest last.
 *
 * <p>tmux before 3.6 answers {@code no current client} when nothing is attached. A gate would
 * refuse the case that works: with a client attached the log is readable on every supported
 * release. The failure tmux reports is left to reach the caller.
 */
public final class MessageLog {

    private final Server server;

    MessageLog(Server server) {
        this.server = server;
    }

    /**
     * The log lines.
     *
     * @throws LibTmuxException before 3.6 when no client is attached
     */
    @ReadOnly
    @Operation(Kind.READ)
    public List<String> lines() {
        return server.run(List.of("show-messages")).stdout();
    }
}

package io.github.libtmux;

import io.github.libtmux.exception.MalformedResponseException;
import java.util.Objects;
import java.util.function.Function;

/**
 * A tmux option and the Java type its value reads as.
 *
 * <pre>{@code
 * session.options().set(OptionKey.HISTORY_LIMIT, 50_000);
 * int kept = session.options().get(OptionKey.HISTORY_LIMIT).orElseThrow();   // → 50000
 *
 * OptionKey<Boolean> bell = OptionKey.flag("visual-bell");
 * }</pre>
 *
 * <p>Declared by the caller rather than catalogued here. tmux has hundreds of options, adds them
 * between releases and changes a few of their types, so a closed catalogue would be wrong somewhere
 * on every release it did not track. A key says how to read one option; the name-and-string methods
 * on {@link Options} remain for anything else.
 *
 * <p>The constants are the ones whose type is the same on every supported release, checked against
 * tmux's own option table from 3.2a to 3.7c. {@code status} is not among the flags for that reason:
 * tmux reads it as a choice of {@code off}, {@code on} and a line count.
 *
 * @param <T> what the value reads as
 */
public final class OptionKey<T> {

    /** Lines of scrollback a pane keeps. A session option. */
    public static final OptionKey<Integer> HISTORY_LIMIT = number("history-limit");

    /** The index a session's first window gets. A session option. */
    public static final OptionKey<Integer> BASE_INDEX = number("base-index");

    /** How long tmux waits after an escape to see whether a key sequence follows. A server option. */
    public static final OptionKey<Integer> ESCAPE_TIME = number("escape-time");

    /** Whether the mouse is captured. A session option. */
    public static final OptionKey<Boolean> MOUSE = flag("mouse");

    /** Whether a window renames itself after what its pane runs. A window option. */
    public static final OptionKey<Boolean> AUTOMATIC_RENAME = flag("automatic-rename");

    /** Whether keys typed into one pane go to every pane in the window. A window or pane option. */
    public static final OptionKey<Boolean> SYNCHRONIZE_PANES = flag("synchronize-panes");

    private final String name;
    private final Function<String, T> read;
    private final Function<T, String> write;

    private OptionKey(String name, Function<String, T> read, Function<T, String> write) {
        this.name = Objects.requireNonNull(name, "name");
        this.read = read;
        this.write = write;
    }

    /** An option read as the text tmux reports, which suits a string, a choice, a style or a colour. */
    public static OptionKey<String> text(String name) {
        return new OptionKey<>(name, Function.identity(), Function.identity());
    }

    /** An option tmux holds as a number. */
    public static OptionKey<Integer> number(String name) {
        return new OptionKey<>(name, reported -> parseNumber(name, reported), value -> Integer.toString(value));
    }

    /** An option tmux holds as a flag, which it reports as {@code on} or {@code off}. */
    public static OptionKey<Boolean> flag(String name) {
        return new OptionKey<>(name, reported -> parseFlag(name, reported), value -> value ? "on" : "off");
    }

    /** The option's name, as tmux spells it. */
    public String name() {
        return name;
    }

    T read(String reported) {
        return read.apply(reported);
    }

    String write(T value) {
        return write.apply(Objects.requireNonNull(value, "value"));
    }

    private static Integer parseNumber(String name, String reported) {
        try {
            return Integer.valueOf(reported.strip());
        } catch (NumberFormatException notANumber) {
            throw new MalformedResponseException(
                    "tmux reported option " + name + " as '" + reported + "', which is not a number", notANumber);
        }
    }

    private static Boolean parseFlag(String name, String reported) {
        return switch (reported.strip()) {
            case "on" -> true;
            case "off" -> false;
            default ->
                throw new MalformedResponseException(
                        "tmux reported option " + name + " as '" + reported + "', which is not on or off");
        };
    }

    @Override
    public String toString() {
        return "OptionKey[" + name + "]";
    }
}

package io.github.libtmux;

import io.github.libtmux.batch.Batch;
import io.github.libtmux.batch.OperationOutcome;
import io.github.libtmux.batch.OperationResult;
import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import io.github.libtmux.exception.CommandRejectedException;
import io.github.libtmux.exception.LibTmuxException;
import io.github.libtmux.exception.MalformedResponseException;
import io.github.libtmux.exception.ServerUnavailableException;
import io.github.libtmux.internal.ErrorText;
import io.github.libtmux.snapshot.ServerSnapshot;
import io.github.libtmux.transport.CommandResult;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import kotlin.annotations.jvm.ReadOnly;
import org.jspecify.annotations.Nullable;

/**
 * The tmux options at one scope.
 *
 * <p>tmux keeps options on the server, on a session, on a window and on a pane, and the same option
 * name can exist at more than one of them. A scope is therefore chosen when the view is obtained,
 * not passed to every call, so a caller cannot read one scope and write another.
 *
 * <p>Array options keep the subscript tmux prints — {@code command-alias[0]} — because that is what
 * addresses the individual entry when setting it back.
 *
 * <p>Every read asks the daemon its version in the same tmux invocation as the values, since how a
 * value is printed depends on that version: tmux 3.4 and 3.5 print a carriage return and a literal
 * {@code \r} alike under {@code -v}, so on those two the escaped listing is decoded instead.
 */
public final class Options {

    /** Under the ceiling {@link Batch#length()} describes, with room for the guard around it. */
    private static final int GROUP_BUDGET = 15_000;

    private final Server server;
    private final @Nullable ServerSnapshot snapshot;
    private final List<String> scope;

    private Options(Server server, @Nullable ServerSnapshot snapshot, List<String> scope) {
        this.server = server;
        this.snapshot = snapshot;
        this.scope = scope;
    }

    static Options server(Server server) {
        return new Options(server, null, List.of("-s"));
    }

    static Options global(Server server) {
        return new Options(server, null, List.of("-g"));
    }

    static Options session(Server server, ServerSnapshot snapshot, SessionId session) {
        return new Options(server, snapshot, List.of("-t", session.value()));
    }

    static Options window(Server server, ServerSnapshot snapshot, WindowId window) {
        return new Options(server, snapshot, List.of("-w", "-t", window.value()));
    }

    static Options pane(Server server, ServerSnapshot snapshot, PaneId pane) {
        return new Options(server, snapshot, List.of("-p", "-t", pane.value()));
    }

    /**
     * The value in effect at this scope, inherited from a parent scope when this one does not set it.
     *
     * <p>This is what tmux itself will act on. To ask the narrower question — whether this scope
     * sets the option at all — look for the name in {@link #all()}, which lists only what is set
     * here.
     *
     * @return empty only when tmux does not know the option, which it reports as an error; an option
     *     genuinely set to the empty string comes back as an empty value, not as absent. A value
     *     spanning several lines comes back whole
     * @throws ServerUnavailableException if no daemon is running
     * @throws LibTmuxException if the read otherwise fails, including a name tmux finds ambiguous —
     *     option names may be abbreviated, and a prefix matching several is a question tmux
     *     declined to answer rather than an option it does not have
     */
    @Operation(Kind.READ)
    public Optional<String> get(String name) {
        // Both spellings of the value, since which one reads back exactly depends on the version.
        List<OperationResult> read = withVersion(List.of(
                argv("show-options", List.of("-A", "-v", "--", name)),
                argv("show-options", List.of("-A", "--", name))));
        TmuxVersion version = version(read.get(0));
        OperationResult printed = read.get(1);
        if (printed.outcome() != OperationOutcome.COMPLETE) {
            // The documented meaning of empty, in tmux's own words on every supported release. Any
            // other failure is a failed read, and answering it with "tmux does not know that option"
            // makes this method say something it did not find out.
            if (printed.stderr().stream().anyMatch(line -> line.contains("invalid option"))) {
                return Optional.empty();
            }
            throw failed(printed);
        }
        if (!escapedListing(version)) {
            return Optional.of(String.join("\n", TmuxFormats.printed(printed.stdout(), version)));
        }
        List<String> values = new ArrayList<>();
        for (String line : completed(read.get(2)).stdout()) {
            int split = line.indexOf(' ');
            values.add(split < 0 ? "" : listedValue(line.substring(split + 1), version));
        }
        return Optional.of(String.join("\n", values));
    }

    /**
     * As {@link #get(String)}, read as the key's type.
     *
     * @throws LibTmuxException if tmux reports a value the key's type cannot hold, which means the
     *     key was declared with the wrong type
     */
    @Operation(Kind.READ)
    public <T> Optional<T> get(OptionKey<T> key) {
        Objects.requireNonNull(key, "key");
        return get(key.name()).map(key::read);
    }

    /** As {@link #set(String, String)}, written the way tmux reads the key's type. */
    @Operation(Kind.MUTATION)
    public <T> void set(OptionKey<T> key, T value) {
        Objects.requireNonNull(key, "key");
        set(key.name(), key.write(value));
    }

    /** Every option set at this scope, in tmux's order. Inherited values are not listed. */
    @ReadOnly
    @Operation(Kind.READ)
    public Map<String, String> all() {
        return read(List.of());
    }

    /**
     * Names from the listing, values from {@code -v}, in one further invocation.
     *
     * <p>A listed value is escaped with {@code vis(3)} and wrapped in whichever quotes that release
     * chose, and which characters it reaches changed inside the supported range — {@code a$b} prints
     * as {@code "a\$b"} on 3.2a and {@code "a\\$b"} on 3.4. {@code -v} output is ambiguous on 3.4
     * and 3.5, which print a carriage return and a literal {@code \r} alike, so those two read the
     * listing's quoted spelling; elsewhere {@code -v} prints the value itself, as {@link #get} reads it.
     */
    private Map<String, String> read(List<String> flags) {
        List<OperationResult> listing = withVersion(List.of(argv("show-options", flags)));
        TmuxVersion version = version(listing.get(0));
        List<String> listed = completed(listing.get(1)).stdout();
        if (escapedListing(version)) {
            Map<String, String> values = new LinkedHashMap<>();
            for (String line : listed) {
                int split = line.indexOf(' ');
                String name = inherited(split < 0 ? line : line.substring(0, split));
                values.put(name, split < 0 ? "" : listedValue(line.substring(split + 1), version));
            }
            return Collections.unmodifiableMap(values);
        }
        List<String> names = new ArrayList<>();
        for (String line : listed) {
            int split = line.indexOf(' ');
            names.add(inherited(split < 0 ? line : line.substring(0, split)));
        }
        if (names.isEmpty()) {
            return Map.of();
        }
        Map<String, String> options = new LinkedHashMap<>();
        for (int from = 0; from < names.size(); ) {
            int to = from;
            // -q keeps an option unset between the two requests from ending the batch.
            Batch batch = snapshot == null ? server.batch() : server.batch(snapshot);
            batch.add("display-message", "-p", "#{version}");
            do {
                List<String> arguments = new ArrayList<>(flags);
                arguments.addAll(List.of("-q", "-v", "--", names.get(to++)));
                batch.add(argv("show-options", arguments));
            } while (to < names.size() && batch.length() < GROUP_BUDGET);
            record(names.subList(from, to), batch, options);
            from = to;
        }
        return Collections.unmodifiableMap(options);
    }

    /**
     * The daemon's version, then these reads, in one tmux invocation: the version is the one that
     * printed them, whatever the client binary is, and a read costs no second process.
     */
    private List<OperationResult> withVersion(List<List<String>> reads) {
        Batch batch = snapshot == null ? server.batch() : server.batch(snapshot);
        batch.add("display-message", "-p", "#{version}");
        reads.forEach(batch::add);
        return batch.run().operations();
    }

    private TmuxVersion version(OperationResult reported) {
        List<String> stdout = completed(reported).stdout();
        try {
            return TmuxVersion.parse(String.join("\n", stdout));
        } catch (IllegalArgumentException invalid) {
            throw new MalformedResponseException("could not establish tmux option output encoding", invalid);
        }
    }

    /** The releases whose {@code -v} output loses raw-value boundaries, so their listing is decoded. */
    private static boolean escapedListing(TmuxVersion version) {
        return version.major() == 3 && (version.minor() == 4 || version.minor() == 5);
    }

    private OperationResult completed(OperationResult read) {
        if (read.outcome() != OperationOutcome.COMPLETE) {
            throw failed(read);
        }
        return read;
    }

    /** A read that did not complete, reported the way a lone {@code show-options} would be. */
    private LibTmuxException failed(OperationResult read) {
        return server.failed("show-options", read.outcome().toString(), read.stderr());
    }

    /** Inverts args_escape for the releases whose outer print pass loses raw-value boundaries. */
    private static String listedValue(String text, TmuxVersion version) {
        if (!text.isEmpty() && text.charAt(0) != '\'' && text.charAt(0) != '"' && text.indexOf(' ') >= 0) {
            // String options with spaces are quoted. Hook command lists retain their tmux syntax.
            return text;
        }
        if (version.minor() == 4) {
            text = text.replaceAll("\\\\(?=\\$[A-Za-z_{])", "");
        }
        int start = 0;
        int end = text.length();
        if (end > 0 && (text.charAt(0) == '\'' || text.charAt(0) == '"')) {
            if (end < 2 || text.charAt(end - 1) != text.charAt(0)) {
                throw new MalformedResponseException("tmux returned an unterminated quoted option value");
            }
            start++;
            end--;
        }
        StringBuilder value = new StringBuilder();
        for (int index = start; index < end; index++) {
            char ch = text.charAt(index);
            if (ch != '\\') {
                value.append(ch);
                continue;
            }
            if (++index == end) throw new MalformedResponseException("tmux returned an incomplete option escape");
            char escaped = text.charAt(index);
            if (escaped >= '0' && escaped <= '7') {
                int octal = escaped - '0';
                for (int digits = 1; digits < 3 && index + 1 < end; digits++) {
                    char next = text.charAt(index + 1);
                    if (next < '0' || next > '7') break;
                    octal = octal * 8 + next - '0';
                    index++;
                }
                if (octal > 255) throw new MalformedResponseException("tmux returned an invalid octal option escape");
                if (octal >= 128)
                    value.append("\\x").append(java.util.HexFormat.of().toHexDigits((byte) octal));
                else value.append((char) octal);
            } else {
                value.append(
                        switch (escaped) {
                            case 'a' -> '\u0007';
                            case 'b' -> '\b';
                            case 'f' -> '\f';
                            case 'n' -> '\n';
                            case 'r' -> '\r';
                            case 's' -> ' ';
                            case 't' -> '\t';
                            case 'v' -> '\u000b';
                            case '\\', '\'', '"', '$', '~', '#', ';', '{', '}', '%' -> escaped;
                            default -> throw new MalformedResponseException("tmux returned an unknown option escape");
                        });
            }
        }
        return value.toString();
    }

    /** The first operation in the batch reports the version, which decodes the values after it. */
    private static void record(List<String> names, Batch batch, Map<String, String> into) {
        List<OperationResult> read = batch.run().operations();
        TmuxVersion version = read.get(0).outcome() == OperationOutcome.COMPLETE
                        && read.get(0).stdout().size() == 1
                ? TmuxVersion.parse(read.get(0).stdout().get(0))
                : new TmuxVersion(0, 0, "");
        for (int index = 0; index < names.size(); index++) {
            OperationResult value = read.get(index + 1);
            if (value.outcome() != OperationOutcome.COMPLETE) {
                throw new CommandRejectedException(
                        "tmux could not read option " + names.get(index) + ErrorText.suffix(value.stderr()),
                        "show-options",
                        -1,
                        value.stderr());
            }
            into.put(names.get(index), String.join("\n", TmuxFormats.printed(value.stdout(), version)));
        }
    }

    /** Wide listings mark inherited built-ins; custom names retain every literal star. */
    private static String inherited(String name) {
        return !name.startsWith("@") && name.endsWith("*") ? name.substring(0, name.length() - 1) : name;
    }

    /**
     * Every option tmux lists at this scope, including inherited built-in values.
     *
     * <p>Inherited user-option names are not listed by tmux. {@link #get(String)} still reads their
     * effective values by name.
     */
    @ReadOnly
    @Operation(Kind.READ)
    public Map<String, String> effective() {
        return read(List.of("-A"));
    }

    /** Sets one option at this scope. */
    @Operation(Kind.MUTATION)
    public void set(String name, String value) {
        run(argv("set-option", List.of("--", name, value)));
    }

    /**
     * Sets one option only if this scope does not already set it.
     *
     * <p>tmux reports the already-set case as an error, which it is not: declining to overwrite is
     * the whole point of asking. The answer comes back as a value instead.
     *
     * @return whether the value was taken, false when this scope already set the option
     */
    @Operation(Kind.MUTATION)
    public boolean setIfAbsent(String name, String value) {
        return cmd(argv("set-option", List.of("-o", "--", name, value))).succeeded();
    }

    /**
     * Adds to the end of a string option, rather than replacing it.
     *
     * <p>Appending to an option this scope has not set simply sets it, which is what tmux does and
     * what a caller building a value up piece by piece wants.
     */
    @Operation(Kind.MUTATION)
    public void append(String name, String suffix) {
        run(argv("set-option", List.of("-a", "--", name, suffix)));
    }

    /**
     * Sets one option to what a tmux format comes to, rather than to the format itself.
     *
     * <p>{@code setExpanded("status-left", "in #{session_name}")} stores {@code in base}. The
     * expansion happens once, when this is called; the option does not stay live.
     *
     * <p>Because tmux expands the format when this is called, a {@code #(...)} in it runs a command
     * at that moment. Pass any interpolated value through {@link TmuxFormats#literal} unless you mean
     * it to be expanded.
     */
    @Operation(Kind.MUTATION)
    public void setExpanded(String name, String format) {
        run(argv("set-option", List.of("-F", "--", name, format)));
    }

    /** Removes one option at this scope, so it falls back to whatever it inherits. */
    @Operation(Kind.MUTATION)
    public void unset(String name) {
        run(argv("set-option", List.of("-u", "--", name)));
    }

    private CommandResult cmd(List<String> argv) {
        return snapshot == null ? server.cmd(argv) : server.cmd(snapshot, argv);
    }

    private CommandResult run(List<String> argv) {
        return snapshot == null ? server.run(argv) : server.run(snapshot, argv);
    }

    private List<String> argv(String command, List<String> tail) {
        List<String> argv = new ArrayList<>(1 + scope.size() + tail.size());
        argv.add(command);
        argv.addAll(scope);
        argv.addAll(tail);
        return argv;
    }
}

package io.github.libtmux;

import com.google.errorprone.annotations.CheckReturnValue;
import io.github.libtmux.batch.Batch;
import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import io.github.libtmux.exception.DispatchException;
import io.github.libtmux.exception.LibTmuxException;
import io.github.libtmux.exception.MalformedResponseException;
import io.github.libtmux.exception.ServerUnavailableException;
import io.github.libtmux.exception.TargetGoneException;
import io.github.libtmux.exception.UnencodableTextException;
import io.github.libtmux.exception.UnsupportedFeatureException;
import io.github.libtmux.format.RowFormat;
import io.github.libtmux.snapshot.PaneState;
import io.github.libtmux.snapshot.ServerSnapshot;
import io.github.libtmux.snapshot.WindowContext;
import io.github.libtmux.transport.DispatchOutcome;
import java.nio.file.InvalidPathException;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.OptionalInt;
import java.util.OptionalLong;
import java.util.UUID;
import java.util.function.Consumer;
import java.util.function.Predicate;
import kotlin.annotations.jvm.ReadOnly;

/**
 * One tmux pane, as one capture saw it.
 *
 * <p>Identity is the server and the pane id. An index is state: panes renumber as neighbours come
 * and go.
 *
 * <p>A method named for a captured field returns what {@link #info()} holds and does no I/O;
 * {@link #refresh()} reads again. Every other method asks tmux now.
 */
public final class Pane {

    private static final RowFormat BROKEN_OUT = RowFormat.of("session_id", "window_id", "window_index");

    private static final RowFormat CREATED = RowFormat.of("pane_id");

    /**
     * tmux 3.7 exactly gets break-pane's naming wrong twice: it ends the whole server — every
     * session on the socket — when it has to choose the name itself, and it silently discards a name
     * that is given. Both are one inverted check in {@code cmd-break-pane.c} — {@code if (name !=
     * NULL)} where it meant {@code == NULL} - fixed by {@code 84291b02}, which {@code git tag
     * --contains} places on 3.7a and nothing earlier, matching CHANGES' "3.7 TO 3.7a": "Fix crash in
     * break-pane when no name is provided." Not probeable: break-pane's args are unchanged across the
     * fix, so nothing in {@link Commands#list} distinguishes the two releases.
     */
    private static final TmuxVersion BREAK_PANE_NAMING_BROKEN = new TmuxVersion(3, 7, "");

    private final Server server;
    private final ServerSnapshot snapshot;
    private final PaneState state;

    Pane(Server server, ServerSnapshot snapshot, PaneState state) {
        this.server = server;
        this.snapshot = snapshot;
        this.state = state;
    }

    /** The fields this capture stored. A later title change is not visible here. */
    @Operation(Kind.CAPTURED)
    public PaneState info() {
        return state;
    }

    /** The pane's stable id. */
    @Operation(Kind.CAPTURED)
    public PaneId id() {
        return state.id();
    }

    /** The pane's position, which shifts as neighbours come and go. */
    @Operation(Kind.CAPTURED)
    public int index() {
        return state.index();
    }

    /** Whether this was its window's active pane when captured. */
    @Operation(Kind.CAPTURED)
    public boolean active() {
        return state.active();
    }

    /** The command tmux reported running here. */
    @Operation(Kind.CAPTURED)
    public String currentCommand() {
        return state.currentCommand();
    }

    /**
     * Whether this pane floats, or empty when the running tmux cannot say.
     *
     * <p>Empty is not "no". tmux before 3.7 expands the format to nothing, and answering {@code false}
     * there would be indistinguishable from a tmux that looked and found the pane was not floating.
     */
    @Operation(Kind.CAPTURED)
    public Optional<Boolean> floating() {
        return state.floating();
    }

    /** How large the pane was when captured, in terminal cells. */
    @Operation(Kind.CAPTURED)
    public Dimensions size() {
        return state.size();
    }

    /** Where the pane's top-left corner sat in its window when captured, in terminal cells. */
    @Operation(Kind.CAPTURED)
    public PanePosition position() {
        return state.position();
    }

    /** The pane title, which a program running inside it can change. */
    @Operation(Kind.CAPTURED)
    public String title() {
        return state.title();
    }

    /**
     * The working directory tmux reported for the pane.
     *
     * <p>Converted on request rather than when the pane was captured, because a directory name is
     * bytes to tmux and this JVM cannot always represent one: converting at capture time would lose
     * every pane on the server over a single pane's directory. {@link #currentPathText()} is the
     * value tmux actually reported, and never throws.
     *
     * @throws LibTmuxException if this JVM's encoding cannot represent the name, which a UTF-8
     *     locale fixes
     */
    @Operation(Kind.CAPTURED)
    public Path currentPath() {
        String reported = state.currentPath();
        try {
            return Path.of(reported);
        } catch (InvalidPathException unrepresentable) {
            throw new UnencodableTextException(
                    "this JVM cannot represent the directory of pane " + state.id()
                            + " as a path; start the JVM in a UTF-8 locale (LC_ALL=C.UTF-8), or read"
                            + " currentPathText()",
                    unrepresentable);
        }
    }

    /** The working directory tmux reported for the pane, exactly as tmux reported it. */
    @Operation(Kind.CAPTURED)
    public String currentPathText() {
        return state.currentPath();
    }

    /**
     * The process id of the program running in the pane, captured at the time of the read this
     * handle came from.
     *
     * <p>Empty means tmux reported no process — never a literal {@code 0}, which would be
     * indistinguishable from a real pid. That covers two different situations this capture cannot
     * tell apart: a pane that never ran one ({@link SplitSpec.Builder#empty()}) and, from tmux 3.8, a
     * pane that ran one and it has since died. Before 3.8 a dead pane still reports its stale pid.
     * {@link #dead()} is the live read that tells a caller which.
     */
    @Operation(Kind.CAPTURED)
    public OptionalLong pid() {
        return state.pid();
    }

    /**
     * Whether this pane's process has exited, read fresh rather than from the capture.
     *
     * <p>Dying is something that happens between reads, so a cached answer would report a pane that
     * died after this handle was captured as alive forever — the trap a snapshot-backed {@code
     * isDead()} would set, which is why there is no such accessor on the capture itself. This asks
     * tmux directly instead, every time.
     *
     * <p>A dead pane is not necessarily a gone one: {@code remain-on-exit} keeps it around, still
     * listed, to be read. A pane with no {@code remain-on-exit} is simply removed once its process
     * exits — {@link #refresh()} on this handle then throws {@link TargetGoneException}, and
     * this method throws too. Unlike every other command {@code Pane} sends, {@code display-message
     * -t} does not error on a target it cannot resolve — it exits 0 with nothing on stdout — so a
     * gone pane looks like a live one that answered nothing rather than like a failure. That empty
     * read, and not a "can't find pane" from tmux, is what this method throws on: a real pane always
     * answers {@code 0} or {@code 1} for this format, never nothing.
     *
     * @throws TargetGoneException if the pane is gone from a server that still answers
     */
    @Operation(Kind.READ)
    public boolean dead() {
        String value = expand("#{pane_dead}");
        if (value.isEmpty()) {
            throw new TargetGoneException("pane " + state.id() + " no longer exists");
        }
        return "1".equals(value);
    }

