    @Operation(Kind.MUTATION)
    public void respawnIn(Path directory) {
        Objects.requireNonNull(directory, "directory");
        server.run(snapshot, respawnArgv(state.id(), directory));
    }

    static List<String> respawnArgv(PaneId pane, Path directory) {
        return List.of(
                "respawn-pane",
                "-k",
                "-c",
                TmuxFormats.literal(directory.toAbsolutePath().toString()),
                "-t",
                pane.value());
    }

    /**
     * Kills whatever runs here and starts the given command instead.
     *
     * @param command the command and its arguments
     */
    @Operation(Kind.MUTATION)
    public void respawn(String... command) {
        if (command.length == 0) {
            throw new IllegalArgumentException("command is empty");
        }
        List<String> argv =
                new ArrayList<>(List.of("respawn-pane", "-k", "-t", state.id().value(), "--"));
        argv.addAll(List.of(command));
        server.run(snapshot, argv);
    }

    /**
     * Sends everything this pane prints to a shell command, until {@link #stopPiping}.
     *
     * <p>A second call replaces the first: tmux keeps one pipe per pane, not a list.
     *
     * @param shellCommand run by the user's shell, so it may redirect and pipe
     *
     * <p>tmux expands {@code #(...)} in this command before a shell sees it, and shell quoting does
     * not prevent that. Pass any interpolated value through {@link TmuxFormats#literal} unless you
     * mean it to be expanded.
     */
    @Operation(Kind.MUTATION)
    public void pipeTo(String shellCommand) {
        Objects.requireNonNull(shellCommand, "shellCommand");
        server.run(snapshot, List.of("pipe-pane", "-O", "-t", state.id().value(), "--", shellCommand));
    }

    /** Stops sending this pane's output anywhere. Doing so twice is not an error. */
    @Operation(Kind.MUTATION)
    public void stopPiping() {
        server.run(snapshot, List.of("pipe-pane", "-t", state.id().value()));
    }

    /** Moves this pane into a window of its own with the given name. */
    @Operation(Kind.MUTATION)
    public Window breakOut(String windowName) {
        Objects.requireNonNull(windowName, "windowName");
        return breakNamed(Optional.of(windowName), windowName);
    }

    /**
     * @param wanted the name the caller asked for, if they asked
     * @param supplied the name to hand tmux, which is never absent because 3.7 crashes without one
     */
    private Window breakNamed(Optional<String> wanted, String supplied) {
        List<String> argv = new ArrayList<>(List.of("break-pane", "-d", "-n", supplied));
        argv.addAll(List.of("-s", state.id().value(), "-P", "-F", BROKEN_OUT.template()));
        List<String> fields =
                BROKEN_OUT.split(server.run(snapshot, argv).stdout().get(0));
        WindowContext created = new WindowContext(
                new SessionId(fields.get(0)),
                new WindowIndex(Integer.parseInt(fields.get(2))),
                new WindowId(fields.get(1)));
        if (server.version(snapshot).equals(BREAK_PANE_NAMING_BROKEN)) {
            // 3.7 took the name and ignored it, so the caller's choice is applied afterwards.
            wanted.ifPresent(name -> server.run(
                    snapshot, List.of("rename-window", "-t", fields.get(1), "--", TmuxFormats.literal(name))));
        }
        ServerSnapshot fresh = server.refresh(snapshot);
        return fresh.window(created)
                .map(window -> new Window(server, fresh, window))
                .orElseThrow(() -> new TargetGoneException("the window just broken out is already gone"));
    }

    /**
     * Splits this pane in half, putting the new one below it.
     *
     * @return the pane that appeared
     */
    @Operation(Kind.MUTATION)
    public Pane split() {
        return split(SplitSpec.builder().build());
    }

    /**
     * Splits this pane as described.
     *
     * <pre>{@code
     * Pane side = pane.split(s -> s.toRight().percent(30));
     * Pane app = pane.split(s -> s.running("htop").in(project));
     * }</pre>
     *
     * @param configure receives a builder holding tmux's defaults
     * @return the pane that appeared
     * @throws UnsupportedFeatureException if the spec asks for something this server does not have
     * @throws TargetGoneException if a command with no {@link SplitSpec.Builder#keepOnExit}
     *     exits before the pane it ran in can be read back — see {@link SplitSpec.Builder#running}.
     *     tmux still made the pane and ran the command; only this confirming read lost the race.
     */
    @Operation(Kind.MUTATION)
    public Pane split(Consumer<SplitSpec.Builder> configure) {
        SplitSpec.Builder builder = SplitSpec.builder();
        configure.accept(builder);
        return split(builder.build());
    }

    /**
     * Splits this pane according to a spec, which may be reused across panes.
     *
     * @return the pane that appeared
     * @throws UnsupportedFeatureException if the spec asks for something this server does not have
     * @throws TargetGoneException if a command with no {@link SplitSpec.Builder#keepOnExit}
     *     exits before the pane it ran in can be read back — see {@link SplitSpec.Builder#running}.
     *     tmux still made the pane and ran the command; only this confirming read lost the race.
     */
    @Operation(Kind.MUTATION)
    public Pane split(SplitSpec spec) {
        return created(server, snapshot, spec.argv(state.id().value(), CREATED.template(), server.version(snapshot)));
    }

    /**
     * Runs a command that reports one new pane, and hands back a handle on it.
     *
     * <p>The creating command names the pane it made, so the result is exact rather than whichever
     * pane a fresh listing happens to put last — two splits racing would otherwise be
     * indistinguishable.
     */
    static Pane created(Server server, ServerSnapshot previous, List<String> argv) {
        List<String> reported = server.run(previous, argv).stdout();
        if (reported.isEmpty()) {
            throw new MalformedResponseException("tmux created a pane without reporting which");
        }
        PaneId id = new PaneId(CREATED.split(reported.get(0)).get(0));
        ServerSnapshot fresh = server.refresh(previous);
        return fresh.panes().stream()
                .filter(pane -> pane.id().equals(id))
                .findFirst()
                .map(pane -> new Pane(server, fresh, pane))
                .orElseThrow(() -> new TargetGoneException("the pane just created is already gone"));
    }

    /** The format a creating command reports its new pane through. */
    static String createdFormat() {
        return CREATED.template();
    }

    /** Pastes a named buffer into this pane, as though it had been typed. */
    @Operation(Kind.MUTATION)
    public void pasteBuffer(String name) {
        try (PaneInput.Lease input = PaneInput.hold(this)) {
            Objects.requireNonNull(input, "input");
            Objects.requireNonNull(name, "name");
            server.run(
                    snapshot,
                    List.of("paste-buffer", "-b", name, "-t", state.id().value()));
        }
    }

    /**
     * Pastes text into this pane as one block, leaving nothing behind on the server.
     *
     * <p>Nothing in the text is looked up as a key name, so a line containing {@code Enter} or a
     * bracket arrives as those characters. That is what an editor, a REPL, or anything reading a
     * here-document needs, and it is the difference from {@link #send}.
     *
     * <p>tmux needs a buffer to paste from, and this one travels in the same invocation as the paste
     * that consumes it. A caller that stops in between therefore cannot leave the text in the paste
     * history every session on the server can read.
     *
     * <p>The text goes to tmux on standard input rather than as an argument, so it is not bounded by
     * the size of a tmux command and never reaches tmux's parser.
     *
     * @throws IllegalArgumentException if the text contains NUL, which a terminal cannot receive and
     *     {@link #send} refuses too
     * @throws UnsupportedFeatureException before tmux 3.4, where deleting the buffer left by a failed
     *     paste can remove one this did not create
     */
    @Operation(Kind.MUTATION)
    public void paste(String text) {
        try (PaneInput.Lease input = PaneInput.hold(this)) {
            Objects.requireNonNull(input, "input");
            Objects.requireNonNull(text, "text");
            if (text.indexOf('\0') >= 0) {
                throw new IllegalArgumentException("pasted text cannot contain NUL");
            }
            TmuxVersion running = server.version(snapshot);
            if (!running.atLeast(Buffers.EXACT_NAMED_DELETE)) {
                throw new UnsupportedFeatureException("pasting text", Buffers.EXACT_NAMED_DELETE, running);
            }
            String buffer = "libtmux-paste-" + UUID.randomUUID();
            // Recorded before dispatch: a wait already watching this pane must never see the pasted
            // content on screen before the record that discounts it exists. Rolled back below if the
            // paste never lands.
            PaneEcho.Recorded recorded = server.echo().recordLiteral(identity(), state.id(), text);
            try {
                server.runTogether(
                        snapshot,
                        text,
                        List.of(
                                List.of("load-buffer", "-b", buffer, "-"),
                                // -d removes the buffer as it pastes, so the success path leaves nothing
                                // even when this is the last thing the caller manages to run.
                                List.of(
                                        "paste-buffer",
                                        "-d",
                                        "-b",
                                        buffer,
                                        "-t",
                                        state.id().value())));
            } catch (RuntimeException failure) {
                settleFailure(recorded, failure);
                try {
                    server.buffers().delete(buffer);
                } catch (RuntimeException ignored) {
                    // Already gone, or the server is; neither changes what the caller is told.
                }
                throw failure;
            }
            recorded.confirm();
        }
    }

    /**
     * As {@link #paste(String)}, after a caller rechecks state once its private buffer is ready.
     *
     * <p>If the check throws, the text is not pasted and the private buffer is removed.
     *
     * @param beforePaste runs after staging and immediately before the paste dispatch
     */
    @Operation(Kind.MUTATION)
    public void paste(String text, Runnable beforePaste) {
        try (PaneInput.Lease input = PaneInput.hold(this)) {
            Objects.requireNonNull(input, "input");
            Objects.requireNonNull(text, "text");
            Objects.requireNonNull(beforePaste, "beforePaste");
            if (text.indexOf('\0') >= 0) {
                throw new IllegalArgumentException("pasted text cannot contain NUL");
            }
            TmuxVersion running = server.version(snapshot);
            if (!running.atLeast(Buffers.EXACT_NAMED_DELETE)) {
                throw new UnsupportedFeatureException("pasting text", Buffers.EXACT_NAMED_DELETE, running);
            }
            String buffer = "libtmux-paste-" + UUID.randomUUID();
            try {
                server.runTogether(snapshot, text, List.of(List.of("load-buffer", "-b", buffer, "-")));
                beforePaste.run();
                PaneEcho.Recorded recorded = server.echo().recordLiteral(identity(), state.id(), text);
                try {
                    server.run(
                            snapshot,
                            List.of(
                                    "paste-buffer",
                                    "-d",
                                    "-b",
                                    buffer,
                                    "-t",
                                    state.id().value()));
                } catch (RuntimeException failure) {
                    settleFailure(recorded, failure);
                    throw failure;
                }
                recorded.confirm();
            } catch (RuntimeException failure) {
                try {
                    server.buffers().delete(buffer);
                } catch (RuntimeException ignored) {
                    // Already gone, or the server is; neither changes what the caller is told.
                }
                throw failure;
            }
        }
    }

    /** Discards this pane's scrollback. */
    @Operation(Kind.MUTATION)
    public void clearHistory() {
        server.run(snapshot, List.of("clear-history", "-t", state.id().value()));
    }

    /** Swaps this pane's position with another's. */
    @Operation(Kind.MUTATION)
    public void swapWith(Pane other) {
        Objects.requireNonNull(other, "other");
        server.requireSameIncarnation(snapshot, other.server(), other.snapshot());
        server.run(
                snapshot,
                List.of("swap-pane", "-s", state.id().value(), "-t", other.id().value()));
    }

    /** Moves this pane into another window, splitting it. */
    @Operation(Kind.MUTATION)
    public void joinTo(Window window) {
        Objects.requireNonNull(window, "window");
        server.requireSameIncarnation(snapshot, window.server(), window.snapshot());
        server.run(
                snapshot,
                List.of("join-pane", "-s", state.id().value(), "-t", window.id().value()));
    }

    /** Closes this pane. */
    @Operation(Kind.MUTATION)
    public void kill() {
        server.run(snapshot, List.of("kill-pane", "-t", state.id().value()));
        server.echo().forget(identity(), state.id());
    }

    /**
     * Takes a new capture and returns this pane as it is now.
     *
     * <p>This handle remains unchanged. Use the returned handle for subsequent state reads.
     *
     * @throws TargetGoneException if the pane is gone from a server that still answers
     * @throws ServerUnavailableException if no daemon is running
     */
    @CheckReturnValue
    @Operation(Kind.READ)
    public Pane refresh() {
        ServerSnapshot fresh = server.refresh(snapshot);
        return fresh.panes().stream()
                .filter(pane -> pane.id().equals(state.id()))
                .findFirst()
                .map(pane -> new Pane(server, fresh, pane))
                .orElseThrow(() -> new TargetGoneException("pane " + state.id() + " no longer exists"));
    }

    @Override
    public boolean equals(Object other) {
        return other instanceof Pane that
                && server.identity(snapshot).equals(that.server.identity(that.snapshot))
                && state.id().equals(that.state.id());
    }

    @Override
    public int hashCode() {
        return Objects.hash(server.identity(snapshot), state.id());
    }

    @Override
    public String toString() {
        return "Pane[" + state.id() + " " + state.currentCommand() + "]";
    }
}

package io.github.libtmux;

import io.github.libtmux.catalog.Advanced;
import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.List;
import java.util.OptionalInt;
import java.util.Set;
import java.util.StringJoiner;
import kotlin.annotations.jvm.ReadOnly;

/**
 * The line typed at a pane's shell to run one command to its end, and how its output is read back.
 *
 * <p>Completion is not inferred from the screen. The command runs in a subshell whose trap prints an
 * end marker carrying {@code $?} and then signals a private {@code wait-for} channel through the
 * same tmux binary and socket, so the wait is tmux's own and the status is the shell's. The trap
 * covers interrupt and terminate as well as exit, so a command someone stops with {@code C-c} ends
 * the run and reports the status it was stopped with — commonly 130 — rather than leaving a wait
 * with nothing to end it.
 *
 * <p>The output is cut out by framing: a start marker is printed before the command and the end
 * marker after it, and only lines strictly between them are returned. The shell echoes the whole
 * typed line, which contains both markers — but only inside quotes, never as a line of its own that
 * equals a marker, so matching complete marker lines tells plumbing from output even when the echo
 * wraps.
 *
 * <p>{@link Pane#run} is built on this, and it is public for a caller that needs the same framing
 * around orchestration of its own — the MCP server holds a pane for other clients while a run is
 * uncertain, which the library has no reason to.
 */
@Advanced
public final class PaneCommand {

    private static final SecureRandom RANDOM = new SecureRandom();

    /** Exit, interrupt and terminate: the ways the wrapper ends that it can still report from. */
    private static final String TRAPPED = "0 2 15";

    /** The shells whose syntax the typed line is written in. */
    private static final Set<String> POSIX_SHELLS = Set.of("sh", "ash", "bash", "dash", "ksh", "mksh", "pdksh", "zsh");

    private final String startMark;
    private final String endMark;
    private final String channel;

    private PaneCommand(String nonce) {
        this.startMark = nonce + "-s";
        this.endMark = nonce + "-e";
        this.channel = "ch_" + nonce;
    }

    /** A run with markers and a channel no other run shares. */
    public static PaneCommand fresh() {
        byte[] nonce = new byte[16];
        RANDOM.nextBytes(nonce);
        return new PaneCommand("lt" + HexFormat.of().formatHex(nonce));
    }

    /** The {@code wait-for} channel the typed line signals once the command has ended. */
    public String channel() {
        return channel;
    }

    /**
     * The line to type.
     *
     * <p>Typed at the pane's own interactive shell rather than a fresh one, so the command sees the
     * environment a person set up there — a virtualenv, a loaded module, a directory someone changed
     * into. The leading space asks bash ({@code HISTCONTROL=ignorespace}) and zsh ({@code
     * HIST_IGNORE_SPACE}) to keep the plumbing out of the history; a shell set to neither records it.
     * Builtins are called as {@code \\trap}, {@code \\eval} and {@code \\exit} so an alias of the same
     * name cannot take them over.
     *
     * <p>The line begins with that space; strip it to have the shell record the line like any other.
     *
     * @param tmux the client the pane's shell calls: an absolute binary and its {@code -S} socket
     */
    public String typed(List<String> tmux, String command) {
        String start = quoteAll(append(tmux, "display-message", "-p", startMark));
        String end = quoteAll(append(tmux, "display-message", "-p")) + " " + quote(endMark + ":") + "\"$?\"";
        String signal = quoteAll(append(tmux, "wait-for", "-S", channel));
        // Interrupt and terminate are trapped beside exit so a command someone stops still reports
        // what it ended as, rather than leaving a run that never ends. The handler prints before it
        // clears the traps, because reading {@code $?} has to come before anything overwrites it,
        // and clearing them stops the exit trap running the body a second time.
        String finish = end + "; \\trap - " + TRAPPED + "; " + signal + "; \\exit 0";
        return " ( \\trap " + quote(finish) + " " + TRAPPED + "; " + start + "; ( \\eval " + quote(command) + " ) )";
    }

    /**
     * What lies between the two markers, and the status the end marker carried.
     *
     * <p>The start marker is matched as a whole row after trimming, the end marker as the end of
     * one — never by containment, because the echo of the typed line holds both as substrings and
     * must not be mistaken for either. The asymmetry is the shell's: nothing can precede the start
     * marker on its row, since it prints before the command runs, while the command's own last line
     * precedes the end marker whenever it carried no closing newline. That line is output, and is
     * returned as such.
     */
    public Framed frame(List<String> lines) {
        int start = -1;
        for (int index = lines.size() - 1; index >= 0; index--) {
            if (lines.get(index).trim().equals(startMark)) {
                start = index;
                break;
            }
        }
        OptionalInt status = OptionalInt.empty();
        int end = -1;
        String last = "";
        for (int index = start + 1; index < lines.size(); index++) {
            // Trailing only: leading space is the command's indentation, while the trailing kind can
            // be padding tmux added when it rejoined the wrapped rows.
            String line = lines.get(index).stripTrailing();
            OptionalInt read = status(line);
            if (read.isPresent()) {
                end = index;
                status = read;
                last = ahead(line);
                break;
            }
        }
        if (start < 0) {
            // The frame is gone: output outgrew the history, or the command cleared the screen.
            // Everything that is not plumbing is better than nothing, and is said to be inexact.
            return new Framed(
                    kept(
                            lines.stream()
                                    .filter(line -> !line.contains(startMark) && !line.contains(endMark))
                                    .toList(),
                            last),
                    false,
                    status);
        }
        return new Framed(kept(lines.subList(start + 1, end < 0 ? lines.size() : end), last), end >= 0, status);
    }

    /**
     * What the command printed on the marker's own row: its last line, when that line carried no
     * newline to push the marker onto the next row. A terminal's interrupt echo sits between the two
     * and is the terminal's, not the command's, so a run of those is taken off the end.
     */
    private String ahead(String line) {
        String text = line.substring(0, line.lastIndexOf(endMark + ":"));
        while (text.length() >= 2 && text.charAt(text.length() - 2) == '^') {
            text = text.substring(0, text.length() - 2);
        }
        return text.stripTrailing();
    }

    /**
     * The framed rows, with anything the marker shared its row with kept as the last of them.
     *
     * <p>Each row loses its trailing space, because tmux's does not mean anything. Asking it to
     * rejoin wrapped rows also asks it to keep trailing spaces, and it pads the rows out to do so on
     * 3.2a though not on 3.7c — measured — so one command answered {@code built} on one release and
     * {@code built} followed by fifteen spaces on another. {@code -T} would ask tmux for less but
     * arrived in 3.4, below the range this supports. A terminal cannot tell a printed trailing space
     * from a cell nothing ever wrote, so dropping both is the only answer that is the same
     * everywhere.
     */
    private static List<String> kept(List<String> lines, String last) {
        List<String> all = new ArrayList<>(lines.size() + 1);
        lines.forEach(line -> all.add(line.stripTrailing()));
        if (!last.isEmpty()) {
            all.add(last);
        }
        return List.copyOf(all);
    }

    /** The exit status a row carries at its end, or empty when the row does not end in one. */
    public OptionalInt status(String line) {
        String prefix = endMark + ":";
        // The marker ends its row rather than starting it. A command whose last line carried no
        // newline leaves that line ahead of the marker, and a terminal writes its interrupt echo in
        // the same place; requiring the marker to start the row read both as no status at all. The
        // echo of the typed line cannot end this way: it writes "$?" after the colon, not digits.
        int at = line.lastIndexOf(prefix);
        if (at < 0) {
            return OptionalInt.empty();
        }
        String digits = line.substring(at + prefix.length());
        if (digits.isEmpty() || digits.length() > 3 || digits.chars().anyMatch(c -> c < '0' || c > '9')) {
            return OptionalInt.empty();
        }
        int value = Integer.parseInt(digits);
        return value <= 255 && Integer.toString(value).equals(digits) ? OptionalInt.of(value) : OptionalInt.empty();
    }

    /**
     * A run's output as read back from the screen.
     *
     * @param lines the command's output
     * @param exact whether both markers were found, so the lines are only the command's output
     * @param status the exit status, when the end marker was read
     */
    public record Framed(@ReadOnly List<String> lines, boolean exact, OptionalInt status) {

        public Framed {
            lines = List.copyOf(lines);
        }
    }

    /** Refuses a pane whose shell would not read the typed line as written. */
    static void requirePosixShell(String current) {
        int slash = current.lastIndexOf('/');
        String name = slash < 0 ? current : current.substring(slash + 1);
        if (name.startsWith("-")) {
            name = name.substring(1);
        }
        if (!POSIX_SHELLS.contains(name)) {
            throw new IllegalStateException("running a command to its end needs a POSIX shell in the pane, and it is"
                    + " running '" + name + "'; send keys to it instead if typing into that program is intended");
        }
    }

    /** One word, quoted so a POSIX shell reads it as exactly the text given. */
    static String quote(String word) {
        return "'" + word.replace("'", "'\\''") + "'";
    }

    private static String quoteAll(List<String> argv) {
        StringJoiner line = new StringJoiner(" ");
        argv.forEach(word -> line.add(quote(word)));
        return line.toString();
    }

    private static List<String> append(List<String> base, String... more) {
        List<String> argv = new ArrayList<>(base);
        argv.addAll(List.of(more));
        return argv;
    }
}

package io.github.libtmux;

import java.time.Duration;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;
import java.util.function.LongSupplier;
import java.util.regex.Pattern;
import kotlin.annotations.jvm.ReadOnly;
import org.jspecify.annotations.Nullable;

/** Tracks pending and recently submitted input under each server incarnation and pane id. */
final class PaneEcho {

    private static final Duration RECENT_TTL = Duration.ofSeconds(10);

    private static final Duration ABANDONED_AFTER = Duration.ofHours(1);

    private static final int KEPT_PER_PANE = 32;

    private static final int MAX_PENDING_CHARS = 4_096;

    private record Key(ServerIdentity identity, PaneId pane) {}

    private record Entry(String text, long recordedAtNanos) {}

    private record PaneEchoState(
            @ReadOnly List<String> pendingLines,
            boolean pendingCaptured,
            boolean trackable,
            @ReadOnly List<Entry> recent,
            long lastTouchedNanos,
            ReentrantLock dispatch) {
        static PaneEchoState fresh(long now) {
            return new PaneEchoState(List.of(), false, true, List.of(), now, new ReentrantLock());
        }
    }

    private static String currentLine(PaneEchoState state) {
        List<String> lines = state.pendingLines();
        return lines.isEmpty() ? "" : lines.get(lines.size() - 1);
    }

    record Live(@ReadOnly List<String> pending, @ReadOnly List<String> recent) {
        static final Live NONE = new Live(List.of(), List.of());
    }

    private record Plan(PaneEchoState eager, PaneEchoState confirmed) {}

    private static final List<String> SUBMIT_KEYS = List.of("C-m", "Enter", "KPEnter");
    private static final List<String> KILL_KEYS = List.of("C-c", "C-u");
    private static final List<String> ERASE_KEYS = List.of("BSpace", "C-h");
    private static final List<String> NOOP_KEYS = List.of("DC");

    private static final Pattern UNHANDLED_KEY_NAME = Pattern.compile(
            "^(?:BTab|Down|End|Escape|F(?:[1-9]|1[0-2])|Home|IC|Left|NPage|PPage|PageDown|PageUp" + "|Right|Tab|Up)$");

    private static final Pattern CONTROL_OR_META_COMBO = Pattern.compile("^(?:C|M|S)(?:-(?:C|M|S))*-.");

    private enum Kind {
        SUBMIT,
        KILL,
        ERASE,
        NOOP,
        UNKNOWN,
        TEXT
    }

    private record KeyEffect(Kind kind, String text) {
        static final KeyEffect SUBMIT = new KeyEffect(Kind.SUBMIT, "");
        static final KeyEffect KILL = new KeyEffect(Kind.KILL, "");
        static final KeyEffect ERASE = new KeyEffect(Kind.ERASE, "");
        static final KeyEffect NOOP = new KeyEffect(Kind.NOOP, "");
        static final KeyEffect UNKNOWN = new KeyEffect(Kind.UNKNOWN, "");

        static KeyEffect text(String text) {
            return new KeyEffect(Kind.TEXT, text);
        }
    }

    private static KeyEffect classifyKey(String key) {
        if (SUBMIT_KEYS.contains(key)) {
            return KeyEffect.SUBMIT;
        }
        if (KILL_KEYS.contains(key)) {
            return KeyEffect.KILL;
        }
        if (ERASE_KEYS.contains(key)) {
            return KeyEffect.ERASE;
        }
        if (NOOP_KEYS.contains(key)) {
            return KeyEffect.NOOP;
        }
        if (key.equals("Space")) {
            return KeyEffect.text(" ");
        }
        if (key.codePointCount(0, key.length()) == 1) {
            return KeyEffect.text(key);
        }
        if (UNHANDLED_KEY_NAME.matcher(key).matches()
                || CONTROL_OR_META_COMBO.matcher(key).find()) {
            return KeyEffect.UNKNOWN;
        }
        return KeyEffect.text(key);
    }

    private static String dropLastCodePoint(String text) {
        if (text.isEmpty()) {
            return text;
        }
        int cut = text.offsetByCodePoints(text.length(), -1);
        return text.substring(0, cut);
    }

    private static List<Entry> pushRecent(List<Entry> recent, String text, long now) {
        if (text.isEmpty() || text.length() > MAX_PENDING_CHARS) {
            return recent;
        }
        List<Entry> kept = new ArrayList<>(recent);

        if (!kept.isEmpty() && kept.get(kept.size() - 1).text().equals(text)) {
            kept.set(kept.size() - 1, new Entry(text, now));
        } else {
            kept.add(new Entry(text, now));
        }
        return List.copyOf(kept.subList(Math.max(0, kept.size() - KEPT_PER_PANE), kept.size()));
    }

    private static Plan planKeys(PaneEchoState current, List<String> keys, long now) {
        List<KeyEffect> effects = new ArrayList<>();
        for (String key : keys) {
            KeyEffect effect = classifyKey(key);
            if (effect.kind() == Kind.TEXT) {
                effects.addAll(literalEffects(effect.text()));
            } else {
                effects.add(effect);
            }
        }
        return planEffects(current, effects, now);
    }

    private static Plan planEffects(PaneEchoState current, List<KeyEffect> effects, long now) {
        String line = currentLine(current);
        boolean captured = current.pendingCaptured();
        boolean trackable = current.trackable();
        List<Entry> recent = current.recent();
        List<String> settling = new ArrayList<>();
        for (KeyEffect effect : effects) {
            switch (effect.kind()) {
                case TEXT -> {
                    String grown = trackable ? line + effect.text() : "";
                    trackable &= grown.length() <= MAX_PENDING_CHARS;

                    line = grown.length() > MAX_PENDING_CHARS ? "" : grown;
                    captured = false;
                }
                case NOOP -> {}
                case UNKNOWN -> {
                    trackable = false;

                    line = "";
                    captured = false;
                }
                case ERASE -> {
                    // Shell redraws can leave the pre-erase text visible; retain it once per edit run.

                    if (!captured) {
                        if (!line.isEmpty()) {
                            settling.add(line);
                        }
                        recent = pushRecent(recent, line, now);
                    }
                    captured = true;

                    line = dropLastCodePoint(line);
                }
                case SUBMIT, KILL -> {
                    trackable = true;
                    if (!line.isEmpty()) {
                        settling.add(line);
                    }
                    recent = pushRecent(recent, line, now);
                    line = "";
                    captured = false;
                }
            }
        }
        PaneEchoState confirmed = new PaneEchoState(
                line.isEmpty() ? List.of() : List.of(line), captured, trackable, recent, now, current.dispatch());
        if (settling.isEmpty()) {
            return new Plan(confirmed, confirmed);
        }
        List<String> eagerLines =
                new ArrayList<>(settling.subList(Math.max(0, settling.size() - KEPT_PER_PANE), settling.size()));
        if (!line.isEmpty()) {
            eagerLines.add(line);
        }
        PaneEchoState eager = new PaneEchoState(
                List.copyOf(eagerLines),
                current.pendingCaptured(),
                trackable,
                current.recent(),
                now,
                current.dispatch());
        return new Plan(eager, confirmed);
    }

    private static Plan planLiteral(PaneEchoState current, String text, long now) {
        return text.isEmpty() ? new Plan(current, current) : planEffects(current, literalEffects(text), now);
    }

    private static List<KeyEffect> literalEffects(String text) {
        List<KeyEffect> effects = new ArrayList<>();
        int from = 0;
        for (int at = 0; at < text.length(); at++) {
            char character = text.charAt(at);
            KeyEffect effect =
                    switch (character) {
                        case '\r', '\n' -> KeyEffect.SUBMIT;
                        case '\b', '\u007f' -> KeyEffect.ERASE;
                        case '\u0003', '\u0015' -> KeyEffect.KILL;
                        default -> Character.isISOControl(character) ? KeyEffect.UNKNOWN : null;
                    };
            if (effect != null) {
                if (at > from) {
                    effects.add(KeyEffect.text(text.substring(from, at)));
                }
                effects.add(effect);
                from = at + 1;
            }
        }
        if (from < text.length()) {
            effects.add(KeyEffect.text(text.substring(from)));
        }
        return effects;
    }

    private final Map<Key, PaneEchoState> states = new ConcurrentHashMap<>();

    private final LongSupplier nanoTime;

    PaneEcho() {
        this(System::nanoTime);
    }

    PaneEcho(LongSupplier nanoTime) {
        this.nanoTime = nanoTime;
    }

    final class Recorded {
        private final Key key;
        private final @Nullable PaneEchoState before;
        private final PaneEchoState eager;
        private final PaneEchoState confirmed;
        private boolean settled;

        private Recorded(Key key, @Nullable PaneEchoState before, PaneEchoState eager, PaneEchoState confirmed) {
            this.key = key;
            this.before = before;
            this.eager = eager;
            this.confirmed = confirmed;
        }

        // Only confirmed submissions enter a wait's persistent discount set.
        void confirm() {
            if (settled) {
                return;
            }
            settled = true;
            try {
                long now = nanoTime.getAsLong();
                List<Entry> recent = confirmed.recent().stream()
                        .map(entry -> entry.recordedAtNanos() == confirmed.lastTouchedNanos()
                                ? new Entry(entry.text(), now)
                                : entry)
                        .toList();
                states.replace(
                        key,
                        eager,
                        new PaneEchoState(
                                confirmed.pendingLines(),
                                confirmed.pendingCaptured(),
                                confirmed.trackable(),
                                recent,
                                now,
                                confirmed.dispatch()));
            } finally {
                eager.dispatch().unlock();
            }
        }

        // An older transaction must not overwrite a newer dispatch's state.
        void rollback() {
            if (settled) {
                return;
            }
            settled = true;
            try {
                if (before == null) {
                    states.remove(key, eager);
                } else {
                    states.replace(key, eager, before);
                }
            } finally {
                eager.dispatch().unlock();
            }
        }
    }

    private Recorded mutate(ServerIdentity identity, PaneId pane, PlannedMutation planner) {
        long now = nanoTime.getAsLong();
        sweep(now);
        Key key = new Key(identity, pane);
        while (true) {
            PaneEchoState observed = states.computeIfAbsent(key, ignored -> PaneEchoState.fresh(now));
            // Serialize dispatches to one pane without blocking captures or unrelated panes.
            observed.dispatch().lock();
            PaneEchoState current = states.get(key);
            if (current == null || !current.dispatch().equals(observed.dispatch())) {
                observed.dispatch().unlock();
                continue;
            }
            try {
                Plan plan = planner.plan(current, nanoTime.getAsLong());
                states.put(key, plan.eager());
                PaneEchoState before = current.trackable()
                                && current.pendingLines().isEmpty()
                                && current.recent().isEmpty()
                        ? null
                        : current;
                return new Recorded(key, before, plan.eager(), plan.confirmed());
            } catch (RuntimeException | Error failure) {
                observed.dispatch().unlock();
                throw failure;
            }
        }
    }

    private interface PlannedMutation {
        Plan plan(PaneEchoState current, long now);
    }

    private void sweep(long now) {
        states.forEach((key, state) -> {
            boolean expired = now - state.lastTouchedNanos() > ABANDONED_AFTER.toNanos()
                    || (state.trackable()
                            && state.pendingLines().isEmpty()
                            && state.recent().stream()
                                    .allMatch(entry -> now - entry.recordedAtNanos() > RECENT_TTL.toNanos()));
            if (expired && !state.dispatch().isLocked() && state.dispatch().tryLock()) {
                try {
                    if (!state.dispatch().hasQueuedThreads()) {
                        states.remove(key, state);
                    }
                } finally {
                    state.dispatch().unlock();
                }
            }
        });
    }

    Recorded recordLiteral(ServerIdentity identity, PaneId pane, String text) {
        return mutate(identity, pane, (state, now) -> planLiteral(state, text, now));
    }

    Recorded recordKeys(ServerIdentity identity, PaneId pane, List<String> keys) {
        return mutate(identity, pane, (state, now) -> planKeys(state, keys, now));
    }

    int size() {
        return states.size();
    }

    void forget(ServerIdentity identity, PaneId pane) {
        states.remove(new Key(identity, pane));
    }

    Live liveFor(ServerIdentity identity, PaneId pane) {
        long now = nanoTime.getAsLong();
        sweep(now);
        PaneEchoState state = states.get(new Key(identity, pane));
        if (state == null) {
            return Live.NONE;
        }
        List<String> fresh = state.recent().stream()
                .filter(entry -> now - entry.recordedAtNanos() <= RECENT_TTL.toNanos())
                .map(Entry::text)
                .toList();
        return new Live(state.pendingLines(), fresh);
    }

    static List<String> withoutEcho(List<String> lines, List<String> echoes) {
        List<String> shown = lines;
        for (String echo : echoes.stream()
                .sorted(Comparator.comparingInt(String::length).reversed())
                .toList()) {
            shown = withoutEcho(shown, echo);
        }
        return shown;
    }

    static List<String> withoutEcho(List<String> lines, String echo) {
        if (echo.isEmpty() || lines.isEmpty()) {
            return lines;
        }
        int[] lineStart = new int[lines.size() + 1];
        StringBuilder joined = new StringBuilder();
        for (int index = 0; index < lines.size(); index++) {
            lineStart[index] = joined.length();
            joined.append(lines.get(index));
        }
        lineStart[lines.size()] = joined.length();
        String text = joined.toString();
        boolean[] echoed = new boolean[text.length()];
        boolean any = false;
        int from = 0;
        int at;
        while ((at = text.indexOf(echo, from)) >= 0) {
            int end = at + echo.length();
            if (standsAsAnEcho(text, at, end, echo, lineStart)) {
                for (int position = at; position < end; position++) {
                    echoed[position] = true;
                }
                any = true;
                from = end;
            } else {
                from = at + 1;
            }
        }
        if (!any) {
            return lines;
        }
        List<String> kept = new ArrayList<>(lines.size());
        StringBuilder row = new StringBuilder();
        for (int index = 0; index < lines.size(); index++) {
            row.setLength(0);
            for (int position = lineStart[index]; position < lineStart[index + 1]; position++) {
                if (!echoed[position]) {
                    row.append(text.charAt(position));
                }
            }
            kept.add(row.toString());
        }
        return kept;
    }

    private static boolean standsAsAnEcho(String text, int at, int end, String echo, int[] lineStart) {
        boolean opens = at == 0
                || startsARow(lineStart, at)
                || !isWordCharacter(text.charAt(at - 1))
                || !isWordCharacter(echo.charAt(0));
        boolean closes = end == text.length()
                || startsARow(lineStart, end)
                || !isWordCharacter(text.charAt(end))
                || !isWordCharacter(echo.charAt(echo.length() - 1));
        return opens && closes;
    }

    private static boolean startsARow(int[] lineStart, int position) {
        return Arrays.binarySearch(lineStart, position) >= 0;
    }

    private static boolean isWordCharacter(char character) {
        return Character.isLetterOrDigit(character) || character == '_';
    }
}

