package io.github.libtmux;

import java.util.List;
import java.util.OptionalInt;
import kotlin.annotations.jvm.ReadOnly;

/**
 * How a command run in a pane with {@link Pane#run} ended, and what it printed.
 *
 * @param outcome why the wait ended
 * @param exitStatus the command's exit status, present once it finished and its end was read
 * @param output what the command printed, one element per line, without the plumbing around it.
 *     Lines tmux wrapped are rejoined
 * @param exact whether the output was cut out between both of its markers, so it is the command's
 *     and nothing else. False when the output outgrew the pane's history or the command cleared the
 *     screen, or when the command had not finished by the deadline
 */
public record PaneRun(
        Outcome outcome, OptionalInt exitStatus, @ReadOnly List<String> output, boolean exact) {

    public PaneRun {
        output = List.copyOf(output);
    }

    /** Why a run's wait ended. */
    public enum Outcome {
        /** The command ended; its status is in {@link #exitStatus()}. */
        FINISHED,
        /** The deadline passed with the command still running. The output is what it had printed. */
        TIMED_OUT,
        /** The server went away underneath the command, so nothing about it can be relied on. */
        SERVER_GONE
    }

    /** Whether the command finished with status zero. */
    public boolean succeeded() {
        return outcome == Outcome.FINISHED && exitStatus.orElse(-1) == 0;
    }
}

package io.github.libtmux;

/**
 * How big a new pane should be.
 *
 * <p>One value with two spellings, not a size and a percentage. tmux takes both through {@code -l},
 * so there is no pair of fields to hold consistent and no "both were given" error to raise — the
 * Python sibling's {@code size}/{@code percentage} pair and the {@code ValueError} guarding it both
 * disappear.
 *
 * <p>tmux's own {@code -p} flag is never emitted. It is broken in 3.4, which reads the {@code -l}
 * argument while handling {@code -p} and fails with {@code size missing}; {@code -l 25%} produces the
 * same pane on every supported release.
 */
public sealed interface PaneSize {

    /** A size in terminal cells. */
    record Cells(int count) implements PaneSize {
        public Cells {
            if (count < 1) {
                throw new IllegalArgumentException("cells is not positive: " + count);
            }
        }
    }

    /** A share of what is being split. */
    record Percent(int share) implements PaneSize {
        public Percent {
            if (share < 1 || share > 100) {
                throw new IllegalArgumentException("percent outside 1..100: " + share);
            }
        }
    }

    /** A size in terminal cells. */
    static PaneSize cells(int count) {
        return new Cells(count);
    }

    /** A share of what is being split, between 1 and 100. */
    static PaneSize percent(int share) {
        return new Percent(share);
    }

    /** What follows {@code -l}. */
    default String flagValue() {
        return switch (this) {
            case Cells cells -> Integer.toString(cells.count());
            case Percent percent -> percent.share() + "%";
        };
    }
}

package io.github.libtmux;

import java.util.List;
import kotlin.annotations.jvm.ReadOnly;

/**
 * What runs in a new pane.
 *
 * <p>One choice rather than a command field beside an emptiness flag. tmux refuses the pair —
 * {@code command cannot be given for empty pane} — and refuses it before spawning anything, so the
 * combination is not a state the server will ever be in. Sealing it means no value can carry both.
 */
public sealed interface PaneStart {

    /** Whatever the session's {@code default-command} or shell is. */
    record Shell() implements PaneStart {}

    /**
     * A command, which closes the pane when it exits unless the pane is kept.
     *
     * @param argv the command and its arguments
     */
    record Command(@ReadOnly List<String> argv) implements PaneStart {
        public Command {
            argv = List.copyOf(argv);
            if (argv.isEmpty()) {
                throw new IllegalArgumentException("command is empty");
            }
        }
    }

    /** No process at all. Requires tmux 3.7. */
    record Empty() implements PaneStart {}

    /** Whatever the session's shell is. */
    static PaneStart shell() {
        return new Shell();
    }

    /** A command, which closes the pane when it exits unless the pane is kept. */
    static PaneStart command(String... argv) {
        return new Command(List.of(argv));
    }

    /** No process at all. Requires tmux 3.7. */
    static PaneStart empty() {
        return new Empty();
    }
}

package io.github.libtmux;

import io.github.libtmux.exception.DispatchException;
import io.github.libtmux.exception.LibTmuxException;
import java.time.Duration;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.TimeUnit;
import java.util.function.Predicate;

/** Polls a pane on a timer for {@link Pane#awaitText} and {@link Pane#await}. */
final class PaneWait {

    /**
     * How often a wait looks again.
     *
     * <p>Short enough that a wait reports promptly, long enough that a wait held open for minutes
     * is not thousands of tmux invocations. A caller who needs an exact moment wants a signal on a
     * {@link Channel}, not a shorter interval here.
     */
    static final Duration POLL = Duration.ofMillis(50);

    private static final Duration SHORTEST_POLL = Duration.ofMillis(10);

    /**
     * The least a wait's first read is given, and the budget for telling a dead server from a read
     * that failed.
     *
     * <p>A quarter of a second, what {@link Channel#drain} gives a pending signal to come straight
     * back: long enough for tmux to answer, short enough not to be a wait.
     */
    private static final Duration SHORTEST_READ = Duration.ofMillis(250);

    private PaneWait() {}

    /** {@link Pane#awaitText(String, Duration, Duration)}'s implementation. */
    static TextOutcome awaitText(Pane pane, String text, Duration timeout, Duration every) throws InterruptedException {
        TypedText typed = TypedText.in(pane);
        boolean[] reading = {true, false};
        WakeReason ended = awaitCondition(
                pane,
                bounded -> {
                    boolean found = shown(bounded, typed).stream().anyMatch(line -> line.contains(text));
                    if (reading[0]) {
                        reading[0] = false;
                        reading[1] = found;
                    }
                    return found;
                },
                timeout,
                every);
        return switch (ended) {
            case SIGNALLED -> reading[1] ? TextOutcome.PRESENT_AT_ENTRY : TextOutcome.APPEARED;
            case TIMED_OUT -> TextOutcome.TIMED_OUT;
            case SERVER_GONE -> TextOutcome.SERVER_GONE;
        };
    }

    /** {@link Pane#await(Predicate, Duration, Duration)}'s implementation. */
    static WakeReason await(Pane pane, Predicate<Pane> settled, Duration timeout, Duration every)
            throws InterruptedException {
        return awaitCondition(pane, bounded -> settled.test(bounded.refresh().through(pane.server())), timeout, every);
    }

    /**
     * One deadline for both public waits, applied to the reads as well as to the gaps between them.
     *
     * <p>Each read goes through {@link Server#within} with what is left of the deadline, so a read
     * cannot outlast the wait. A read that runs out of that budget has reached the wait's own
     * deadline, and is a timeout. Once the deadline has passed no further read starts, which is what
     * keeps text that arrives late from being reported.
     *
     * <p>An ordinary timeout asks tmux nothing more. The last read answered, so the server was there
     * a poll interval ago, and a liveness probe after the deadline would only spend time the caller
     * did not give. A read that <em>failed</em> is different: tmux reports "no server" and "no such
     * pane" the same way, so that one gets a second look to tell {@link WakeReason#SERVER_GONE} from a
     * failure that belongs to the caller.
     */
    private static WakeReason awaitCondition(Pane pane, Predicate<Pane> poll, Duration timeout, Duration every)
            throws InterruptedException {
        Objects.requireNonNull(timeout, "timeout");
        Objects.requireNonNull(every, "every");
        if (every.compareTo(SHORTEST_POLL) < 0) {
            throw new IllegalArgumentException("looking more often than every " + SHORTEST_POLL.toMillis()
                    + " ms spends a tmux process per look for no reading a person could tell apart: " + every);
        }
        if (timeout.isNegative()) {
            throw new IllegalArgumentException("timeout is negative: " + timeout);
        }
        long deadline = System.nanoTime() + timeout.toNanos();
        boolean first = true;
        while (true) {
            if (Thread.interrupted()) {
                throw new InterruptedException(
                        "interrupted while waiting on pane " + pane.id().value());
            }
            Duration left = Duration.ofNanos(Math.max(1, deadline - System.nanoTime()));
            Duration budget = first && left.compareTo(SHORTEST_READ) < 0 ? SHORTEST_READ : left;
            first = false;
            try {
                if (poll.test(pane.through(pane.server().within(budget)))) {
                    return WakeReason.SIGNALLED;
                }
            } catch (DispatchException.TimedOut expired) {
                return WakeReason.TIMED_OUT;
            } catch (LibTmuxException unreadable) {
                return afterFailedRead(pane, unreadable);
            }
            long remaining = deadline - System.nanoTime();
            if (remaining <= 0) {
                return WakeReason.TIMED_OUT;
            }
            TimeUnit.NANOSECONDS.sleep(Math.min(every.toNanos(), remaining));
            if (System.nanoTime() >= deadline) {
                return WakeReason.TIMED_OUT;
            }
        }
    }

    /**
     * Tells a server that went away from a read that failed for a reason of the caller's.
     *
     * <p>A probe that cannot get an answer in time proves nothing either way, so the original failure
     * is what the caller sees, carrying the probe's.
     */
    private static WakeReason afterFailedRead(Pane pane, LibTmuxException unreadable) {
        boolean alive;
        try {
            alive = pane.server().isAlive(SHORTEST_READ);
        } catch (DispatchException.TimedOut unanswered) {
            unreadable.addSuppressed(unanswered);
            throw unreadable;
        }
        if (alive) {
            throw unreadable;
        }
        return WakeReason.SERVER_GONE;
    }

    /**
     * What a wait has to read, and different from {@link Pane#capture()} twice over. Wrapped rows are
     * rejoined, because a terminal breaks a long line wherever the pane happens to end and text split
     * across that break is in no single row — a wait watching for it would never see it while it sits
     * in plain view. And an echo of what this library just typed is taken out, because a terminal
     * shows the caller's own command back and a wait for something that command's text contains would
     * otherwise be answered by the question.
     */
    private static List<String> shown(Pane pane, TypedText typed) {
        return typed.withoutEcho(pane.capture(CaptureSpec.Builder::joiningWrappedLines));
    }
}

package io.github.libtmux;

import io.github.libtmux.format.Tokens;
import io.github.libtmux.transport.CommandResult;
import java.util.ArrayList;
import java.util.List;

/**
 * Decodes tmux's printed output against the version the server actually reports, framed with
 * process-local markers so a reply is read back exactly whatever quirks that version's own printing
 * has.
 */
final class PrintedText {

    private PrintedText() {}

    private static final String VERSION_MARK = Tokens.perProcess() + "-version";

    /**
     * Printed after what a command printed. tmux ends its output with a line break and the transport
     * drops trailing blank lines, so text that itself ends in line breaks would lose them; with this
     * after it, nothing trailing is blank.
     */
    static final String END_MARK = Tokens.perProcess() + "-end";

    /** A format for {@code display-message -p} that {@link #printed(List)} reads back exactly. */
    static String expansion(String format) {
        return versioned(format) + END_MARK;
    }

    /**
     * This format with the server's version expanded ahead of it, so the reply can be decoded
     * without another tmux process. See {@link TmuxFormats#printed(String, TmuxVersion)}.
     */
    static String versioned(String format) {
        return "#{version}" + VERSION_MARK + format;
    }

    /** The expansion of a {@link #versioned} format, as tmux held the text. */
    static String printed(List<String> reported) {
        String all = String.join("\n", reported);
        int mark = all.indexOf(VERSION_MARK);
        String text = mark < 0 ? all : all.substring(mark + VERSION_MARK.length());
        if (mark >= 0) {
            try {
                text = TmuxFormats.printed(text, TmuxVersion.parse(all.substring(0, mark)));
            } catch (RuntimeException notAVersion) {
                // Not tmux's own answer, as from a test double; keep what came back.
            }
        }
        // After the decoding, not before: 3.4 escapes a $ that a letter follows, and the mark may
        // begin with one, so a value ending in $ is only whole once that escape is undone.
        return text.endsWith(END_MARK) ? text.substring(0, text.length() - END_MARK.length()) : text;
    }

    /** As {@link #printed(List)}, for a listing whose every row began with {@link #versioned}. */
    static List<String> printedRows(List<String> rows) {
        List<String> text = new ArrayList<>(rows.size());
        for (String row : rows) {
            text.add(printed(List.of(row)));
        }
        return text;
    }

    /** The three commands {@link Server#printed(io.github.libtmux.snapshot.ServerSnapshot, List)} sends as one group. */
    static List<List<String>> framed(List<String> argv) {
        return List.of(
                List.of("display-message", "-p", "#{version}"), argv, List.of("display-message", "-p", END_MARK));
    }

    /** Strips the version line and end mark {@link #framed} added, decoding what is left. */
    static CommandResult unwrap(CommandResult result) {
        if (result.stdout().isEmpty()) {
            return result;
        }
        List<String> output = result.stdout().subList(1, result.stdout().size());
        if (!output.isEmpty() && output.getLast().equals(END_MARK)) {
            output = output.subList(0, output.size() - 1);
        }
        try {
            output = TmuxFormats.printed(
                    output, TmuxVersion.parse(result.stdout().get(0)));
        } catch (RuntimeException notAVersion) {
            // Not tmux's own answer, as from a test double; keep what came back.
        }
        return new CommandResult(result.exitCode(), List.copyOf(output), result.stderr());
    }
}

package io.github.libtmux;

import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import io.github.libtmux.exception.UnsupportedFeatureException;
import java.util.List;
import kotlin.annotations.jvm.ReadOnly;

/**
 * The server's command-prompt history.
 *
 * <p>Whether the commands exist is asked of the daemon, not inferred from a version string.
 */
public final class Prompt {

    /** The release a refusal names. The daemon's command list is what actually decides. */
    private static final TmuxVersion SINCE = new TmuxVersion(3, 3, "");

    private final Server server;

    Prompt(Server server) {
        this.server = server;
    }

    /**
     * What has been typed at the prompt, oldest first.
     *
     * @throws UnsupportedFeatureException if this tmux has no such command
     */
    @ReadOnly
    @Operation(Kind.READ)
    public List<String> history() {
        require();
        return server.run(List.of("show-prompt-history")).stdout();
    }

    /**
     * Forgets what has been typed at the prompt.
     *
     * @throws UnsupportedFeatureException if this tmux has no such command
     */
    @Operation(Kind.MUTATION)
    public void clear() {
        require();
        server.run(List.of("clear-prompt-history"));
    }

    private void require() {
        if (server.commands().list().stream().anyMatch(line -> named(line, "show-prompt-history"))) {
            return;
        }
        throw new UnsupportedFeatureException("the command prompt's history", SINCE, server.version());
    }

    /** Whether a {@code list-commands} line names this command, not one of its aliases. */
    private static boolean named(String line, String name) {
        int space = line.indexOf(' ');
        return (space < 0 ? line : line.substring(0, space)).equals(name);
    }
}

package io.github.libtmux.query;

/**
 * The value kind a field reads.
 *
 * <p>Carried explicitly because exactness must not rest on the operand's runtime class. A number
 * field's operand happens to box to {@code Integer}, and reading the kind off that accident would
 * silently pick tmux's lexical comparison where the caller meant arithmetic.
 */
public enum FieldKind {
    TEXT,
    NUMBER,
    FLAG
}

package io.github.libtmux.query;

import java.util.Objects;
import java.util.function.Function;

/**
 * A named, kinded accessor.
 *
 * <p>The name makes a built expression printable; the kind makes consumers independent of the
 * operand's runtime class. A serializer or compiler must bind the exact handle against its own
 * model before trusting the name to describe what the accessor reads.
 */
public final class FieldRef<T, V> {

    private final String id;
    private final FieldKind kind;
    private final Function<T, V> accessor;

    FieldRef(String id, FieldKind kind, Function<T, V> accessor) {
        this.id = requireId(id);
        this.kind = Objects.requireNonNull(kind, "kind");
        this.accessor = Objects.requireNonNull(accessor, "accessor");
    }

    static String requireId(String id) {
        Objects.requireNonNull(id, "id");
        if (id.isBlank()) {
            throw new IllegalArgumentException("id must not be blank");
        }
        return id;
    }

    public String id() {
        return id;
    }

    public FieldKind kind() {
        return kind;
    }

    public Function<T, V> accessor() {
        return accessor;
    }
}

package io.github.libtmux.query;

import java.util.Collection;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.function.Function;
import java.util.regex.Pattern;

/**
 * Typed field handles.
 *
 * <p>A caller supplies each accessor, so no backend may trust the name without matching this exact
 * handle against a model it owns.
 *
 * <p>Each kind exposes only the operators its type supports, so {@code Pane_.index().startsWith(..)}
 * is a compile error rather than a runtime class cast. This is the half of the metamodel that has to
 * exist by hand or by generator; the generator only writes the accessors, never the semantics.
 */
public final class Fields {

    private Fields() {}

    public static <T> TextField<T> text(String id, Function<T, String> accessor) {
        return new TextField<>(new FieldRef<>(id, FieldKind.TEXT, accessor));
    }

    public static <T> NumberField<T> number(String id, Function<T, Integer> accessor) {
        return new NumberField<>(new FieldRef<>(id, FieldKind.NUMBER, accessor));
    }

    public static <T> FlagField<T> flag(String id, Function<T, Boolean> accessor) {
        return new FlagField<>(new FieldRef<>(id, FieldKind.FLAG, accessor));
    }

    public static <T, R> ToManyRef<T, R> toMany(String id, Function<T, List<R>> navigate) {
        return new ToManyRef<>(id, navigate);
    }

    public static <T, R> ToOneRef<T, R> toOne(String id, Function<T, Optional<R>> navigate) {
        return new ToOneRef<>(id, navigate);
    }

    /** String-valued field. */
    public record TextField<T>(FieldRef<T, String> ref) {

        public FilterExpr<T> is(String value) {
            return new FilterExpr.Compare<>(ref, Operator.EQUALS, value);
        }

        public FilterExpr<T> isNot(String value) {
            return new FilterExpr.Compare<>(ref, Operator.NOT_EQUALS, value);
        }

        public FilterExpr<T> contains(String value) {
            return new FilterExpr.Compare<>(ref, Operator.CONTAINS, value);
        }

        public FilterExpr<T> startsWith(String value) {
            return new FilterExpr.Compare<>(ref, Operator.STARTS_WITH, value);
        }

        public FilterExpr<T> endsWith(String value) {
            return new FilterExpr.Compare<>(ref, Operator.ENDS_WITH, value);
        }

        public FilterExpr<T> matches(Pattern value) {
            return new FilterExpr.Compare<>(ref, Operator.MATCHES, value);
        }

        public FilterExpr<T> in(Collection<String> values) {
            return new FilterExpr.Compare<>(ref, Operator.IN, List.copyOf(values));
        }
    }

    /** Integer-valued field. No text operators reach it. */
    public record NumberField<T>(FieldRef<T, Integer> ref) {

        public FilterExpr<T> is(int value) {
            return new FilterExpr.Compare<>(ref, Operator.EQUALS, value);
        }

        public FilterExpr<T> isNot(int value) {
            return new FilterExpr.Compare<>(ref, Operator.NOT_EQUALS, value);
        }

        public FilterExpr<T> lessThan(int value) {
            return new FilterExpr.Compare<>(ref, Operator.LESS_THAN, value);
        }

        public FilterExpr<T> atMost(int value) {
            return new FilterExpr.Compare<>(ref, Operator.AT_MOST, value);
        }

        public FilterExpr<T> greaterThan(int value) {
            return new FilterExpr.Compare<>(ref, Operator.GREATER_THAN, value);
        }

        public FilterExpr<T> atLeast(int value) {
            return new FilterExpr.Compare<>(ref, Operator.AT_LEAST, value);
        }
    }

    /** Boolean-valued field. */
    public record FlagField<T>(FieldRef<T, Boolean> ref) {

        public FilterExpr<T> is(boolean value) {
            return new FilterExpr.Compare<>(ref, Operator.EQUALS, value);
        }

        public FilterExpr<T> isNot(boolean value) {
            return new FilterExpr.Compare<>(ref, Operator.NOT_EQUALS, value);
        }

        public FilterExpr<T> isTrue() {
            return is(true);
        }

        public FilterExpr<T> isFalse() {
            return is(false);
        }
    }

    /** To-many relation. Quantifiers are the only way in, so an unquantified relation cannot compile. */
    public static final class ToManyRef<T, R> {

        private final String id;
        private final Function<T, List<R>> navigate;

        private ToManyRef(String id, Function<T, List<R>> navigate) {
            this.id = FieldRef.requireId(id);
            this.navigate = Objects.requireNonNull(navigate, "navigate");
        }

        public String id() {
            return id;
        }

        public Function<T, List<R>> navigate() {
            return navigate;
        }

        public FilterExpr.ToMany<T, R> any(FilterExpr<R> predicate) {
            return new FilterExpr.ToMany<>(this, FilterExpr.Quantifier.ANY, predicate);
        }

        public FilterExpr.ToMany<T, R> all(FilterExpr<R> predicate) {
            return new FilterExpr.ToMany<>(this, FilterExpr.Quantifier.ALL, predicate);
        }

        public FilterExpr.ToMany<T, R> none(FilterExpr<R> predicate) {
            return new FilterExpr.ToMany<>(this, FilterExpr.Quantifier.NONE, predicate);
        }
    }

    /** To-one relation. */
    public static final class ToOneRef<T, R> {

        private final String id;
        private final Function<T, Optional<R>> navigate;

        private ToOneRef(String id, Function<T, Optional<R>> navigate) {
            this.id = FieldRef.requireId(id);
            this.navigate = Objects.requireNonNull(navigate, "navigate");
        }

        public String id() {
            return id;
        }

        public Function<T, Optional<R>> navigate() {
            return navigate;
        }

        public FilterExpr.ToOne<T, R> is(FilterExpr<R> predicate) {
            return new FilterExpr.ToOne<>(this, predicate);
        }
    }
}

package io.github.libtmux.query;

import java.util.Collection;
import java.util.List;
import java.util.Locale;
import java.util.Objects;
import java.util.function.Predicate;
import java.util.regex.Pattern;
import kotlin.annotations.jvm.ReadOnly;

/**
 * A filter that is both runnable and readable.
 *
 * <p>It extends {@link Predicate}, so {@code stream().filter(expr)} works with no adapter, and it is
 * a sealed tree of records, so the same value can be printed, serialized, or later compiled into a
 * tmux {@code -f} filter. A lambda can do the first of those and none of the rest, which is why
 * named expressions are built from these nodes instead.
 *
 * <p>Evaluation is a total function over the tree: every consumer switches exhaustively, so adding a
 * node breaks compilation at each site that has to learn about it rather than at runtime.
 */
public sealed interface FilterExpr<T> extends Predicate<T> {

    /** Renders the expression as inspectable text. Deliberately not {@code toString} on records. */
    String describe();

    // ---------------------------------------------------------------------------------------

    static <T> FilterExpr<T> and(List<FilterExpr<T>> operands) {
        return new And<>(operands);
    }

    static <T> FilterExpr<T> or(List<FilterExpr<T>> operands) {
        return new Or<>(operands);
    }

    default FilterExpr<T> and(FilterExpr<T> other) {
        return new And<>(List.of(this, other));
    }

    default FilterExpr<T> or(FilterExpr<T> other) {
        return new Or<>(List.of(this, other));
    }

    /**
     * Negation, narrowed to an expression.
     *
     * <p>{@code and} and {@code or} below are deliberately <em>overloads</em> of the inherited
     * {@link Predicate} methods rather than overrides: their parameter is a {@code FilterExpr}, so
     * combining two expressions stays an expression, while passing a bare lambda selects the
     * inherited method and yields a plain predicate. That is the intended boundary — a lambda cannot
     * be printed or serialized, so an expression built from one must not claim to be inspectable.
     */
    @Override
    default FilterExpr<T> negate() {
        return new Not<>(this);
    }

    // ---------------------------------------------------------------------------------------

    /** Conjunction. An empty conjunction is true, which is what makes it a safe identity. */
    record And<T>(@ReadOnly List<FilterExpr<T>> operands) implements FilterExpr<T> {

        public And {
            operands = List.copyOf(operands);
        }

        @Override
        public boolean test(T value) {
            for (FilterExpr<T> operand : operands) {
                if (!operand.test(value)) {
                    return false;
                }
            }
            return true;
        }

        @Override
        public String describe() {
            return operands.isEmpty()
                    ? "true"
                    : "("
                            + String.join(
                                    " and ",
                                    operands.stream().map(FilterExpr::describe).toList()) + ")";
        }
    }

    /** Disjunction. An empty disjunction is false. */
    record Or<T>(@ReadOnly List<FilterExpr<T>> operands) implements FilterExpr<T> {

        public Or {
            operands = List.copyOf(operands);
        }

        @Override
        public boolean test(T value) {
            for (FilterExpr<T> operand : operands) {
                if (operand.test(value)) {
                    return true;
                }
            }
            return false;
        }

        @Override
        public String describe() {
            return operands.isEmpty()
                    ? "false"
                    : "("
                            + String.join(
                                    " or ",
                                    operands.stream().map(FilterExpr::describe).toList()) + ")";
        }
    }

    record Not<T>(FilterExpr<T> operand) implements FilterExpr<T> {

        @Override
        public boolean test(T value) {
            return !operand.test(value);
        }

        @Override
        public String describe() {
            return "not " + operand.describe();
        }
    }

    /** One scalar field compared to one operand. */
    record Compare<T, V>(FieldRef<T, V> field, Operator operator, Object operand) implements FilterExpr<T> {

        public Compare {
            Objects.requireNonNull(field, "field");
            Objects.requireNonNull(operator, "operator");
            operator.requireOperand(field.kind(), operand);
            if (operand instanceof Collection<?> values) {
                operand = List.copyOf(values);
            }
        }

        @Override
        public boolean test(T value) {
            return operator.matches(field.accessor().apply(value), operand);
        }

        @Override
        public String describe() {
            return field.id() + " " + operator.symbol() + " " + operand;
        }

        @Override
        public boolean equals(Object other) {
            return other instanceof Compare<?, ?> that
                    && field.equals(that.field)
                    && operator == that.operator
                    && operandEquals(operand, that.operand);
        }

        @Override
        public int hashCode() {
            return operand instanceof Pattern pattern
                    ? Objects.hash(field, operator, pattern.pattern(), pattern.flags())
                    : Objects.hash(field, operator, operand);
        }

        private static boolean operandEquals(Object left, Object right) {
            if (left instanceof Pattern first && right instanceof Pattern second) {
                return first.flags() == second.flags() && first.pattern().equals(second.pattern());
            }
            return left.equals(right);
        }
    }

    /**
     * A quantified filter over a to-many relation.
     *
     * <p>{@code ALL} over an empty relation is true. That is the standard vacuous reading and it is
     * the one tmux users expect: a session with no windows does not fail "all windows are zoomed".
     */
    record ToMany<T, R>(Fields.ToManyRef<T, R> relation, Quantifier quantifier, FilterExpr<R> predicate)
            implements FilterExpr<T> {

        public ToMany {
            Objects.requireNonNull(relation, "relation");
            Objects.requireNonNull(quantifier, "quantifier");
            Objects.requireNonNull(predicate, "predicate");
        }

        @Override
        public boolean test(T value) {
            List<R> related = relation.navigate().apply(value);
            return switch (quantifier) {
                case ANY -> related.stream().anyMatch(predicate);
                case ALL -> related.stream().allMatch(predicate);
                case NONE -> related.stream().noneMatch(predicate);
            };
        }

        @Override
        public String describe() {
            return relation.id() + " " + quantifier.name().toLowerCase(Locale.ROOT) + " (" + predicate.describe() + ")";
        }
    }

    /** A to-one relation. An absent target does not satisfy the filter. */
    record ToOne<T, R>(Fields.ToOneRef<T, R> relation, FilterExpr<R> predicate) implements FilterExpr<T> {

        public ToOne {
            Objects.requireNonNull(relation, "relation");
            Objects.requireNonNull(predicate, "predicate");
        }

        @Override
        public boolean test(T value) {
            return relation.navigate().apply(value).filter(predicate).isPresent();
        }

        @Override
        public String describe() {
            return relation.id() + " is (" + predicate.describe() + ")";
        }
    }

    enum Quantifier {
        ANY,
        ALL,
        NONE
    }
}

package io.github.libtmux.query;

import java.util.Collection;
import java.util.Objects;
import java.util.regex.Pattern;

/** The scalar comparisons an expression can hold. Evaluation stays a total switch. */
public enum Operator {
    EQUALS("=="),
    NOT_EQUALS("!="),
    CONTAINS("contains"),
    STARTS_WITH("starts-with"),
    ENDS_WITH("ends-with"),
    MATCHES("matches"),
    LESS_THAN("<"),
    AT_MOST("<="),
    GREATER_THAN(">"),
    AT_LEAST(">="),
    IN("in");

    private final String symbol;

    Operator(String symbol) {
        this.symbol = symbol;
    }

    public String symbol() {
        return symbol;
    }

    void requireOperand(FieldKind kind, Object operand) {
        Objects.requireNonNull(kind, "kind");
        if (!supports(kind)) {
            throw new IllegalArgumentException(name() + " does not support " + kind + " fields");
        }
        boolean valid =
                switch (this) {
                    case MATCHES -> operand instanceof Pattern;
                    case IN ->
                        operand instanceof Collection<?> values
                                && values.stream().allMatch(value -> scalar(kind, value));
                    default -> scalar(kind, operand);
                };
        if (!valid) {
            throw new IllegalArgumentException(name() + " has an invalid operand for a " + kind + " field");
        }
    }

    private boolean supports(FieldKind kind) {
        return switch (this) {
            case EQUALS, NOT_EQUALS -> true;
            case CONTAINS, STARTS_WITH, ENDS_WITH, MATCHES, IN -> kind == FieldKind.TEXT;
            case LESS_THAN, AT_MOST, GREATER_THAN, AT_LEAST -> kind == FieldKind.NUMBER;
        };
    }

    private static boolean scalar(FieldKind kind, Object operand) {
        return switch (kind) {
            case TEXT -> operand instanceof String;
            case NUMBER -> operand instanceof Integer;
            case FLAG -> operand instanceof Boolean;
        };
    }

    @SuppressWarnings("unchecked")
    boolean matches(Object actual, Object operand) {
        return switch (this) {
            case EQUALS -> Objects.equals(actual, operand);
            case NOT_EQUALS -> !Objects.equals(actual, operand);
            case CONTAINS -> text(actual).contains((String) operand);
            case STARTS_WITH -> text(actual).startsWith((String) operand);
            case ENDS_WITH -> text(actual).endsWith((String) operand);
            case MATCHES -> ((Pattern) operand).matcher(text(actual)).find();
            case IN -> ((Collection<?>) operand).contains(actual);
            case LESS_THAN -> compare(actual, operand) < 0;
            case AT_MOST -> compare(actual, operand) <= 0;
            case GREATER_THAN -> compare(actual, operand) > 0;
            case AT_LEAST -> compare(actual, operand) >= 0;
        };
    }

    private static String text(Object actual) {
        return actual == null ? "" : actual.toString();
    }

    @SuppressWarnings({"unchecked", "rawtypes"})
    private static int compare(Object actual, Object operand) {
        return ((Comparable) actual).compareTo(operand);
    }
}

package io.github.libtmux.query;

import io.github.libtmux.exception.CardinalityException;
import java.util.Iterator;
import java.util.Optional;

/**
 * Cardinality with the ambiguity removed.
 *
 * <p>"No session matched" and "several sessions matched" are different bugs in a caller's code, so
 * they get different exceptions. {@code findFirst} stays on {@link java.util.stream.Stream} where it
 * already belongs; only the strict shapes need helpers.
 */
public final class Selections {

    private Selections() {}

    /**
     * The single match, or a failure naming which way the count was wrong.
     *
     * @throws CardinalityException.NoMatch if nothing matched
     * @throws CardinalityException.MultipleMatches if more than one did; the scan stops at the
     *     second match, so its count is two
     */
    public static <T> T exactlyOne(Iterable<T> matches) {
        Iterator<T> iterator = matches.iterator();
        if (!iterator.hasNext()) {
            throw new CardinalityException.NoMatch("expected exactly one match, found none");
        }
        T first = iterator.next();
        if (iterator.hasNext()) {
            throw multiple("exactly one", first, iterator.next());
        }
        return first;
    }

    /**
     * The single match if there is one, empty if there is none — but still a failure for several.
     *
     * <p>Returning the first of many would make a caller's ambiguous query look answered.
     *
     * @throws CardinalityException.MultipleMatches if more than one matched
     */
    public static <T> Optional<T> oneOrEmpty(Iterable<T> matches) {
        Iterator<T> iterator = matches.iterator();
        if (!iterator.hasNext()) {
            return Optional.empty();
        }
        T first = iterator.next();
        if (iterator.hasNext()) {
            throw multiple("at most one", first, iterator.next());
        }
        return Optional.of(first);
    }

    /** A single pass never reads past the second match, however large or lazy the source is. */
    private static CardinalityException.MultipleMatches multiple(String wanted, Object first, Object second) {
        return new CardinalityException.MultipleMatches(
                "expected " + wanted + " match, found more than one, starting with " + first + " and " + second, 2);
    }
}

package io.github.libtmux.query;

import java.util.Optional;

/**
 * Lowers a {@link FilterExpr} to a tmux {@code -f} format when every node is one tmux can apply.
 *
 * <p>Relations, a Java regular expression, and any operand containing {@code ,}, <code>#</code>,
 * <code>{</code>, <code>}</code>, {@code :}, or a backslash, are refused. Those stay a local filter over a capture. tmux
 * compiles {@code #{m/r:}} with its own dialect, so a pattern Java would match can select nothing.
 * A compiled format is a hint to tmux, not a promise that the local reading would differ: callers
 * still apply the expression to the rows that come back.
 */
public final class TmuxFilters {

    private TmuxFilters() {}

    /**
     * A tmux format for {@code -f}, or empty when this expression is not a safe subset.
     */
    public static Optional<String> format(FilterExpr<?> expression) {
        try {
            return Optional.of(compile(expression));
        } catch (UnsupportedFilter unsupported) {
            return Optional.empty();
        }
    }

    /**
     * Whether this text can sit inside a tmux format argument without changing its shape. A
     * backslash escapes the next character in a format, so a trailing one swallows the closing brace.
     */
    public static boolean literal(String value) {
        return value.indexOf(',') < 0
                && value.indexOf('\\') < 0
                && value.indexOf('#') < 0
                && value.indexOf('{') < 0
                && value.indexOf('}') < 0
                && value.indexOf(':') < 0;
    }

    private static String compile(FilterExpr<?> expression) {
        return switch (expression) {
            case FilterExpr.And<?> and ->
                join("&&", and.operands().stream().map(TmuxFilters::compile).toList(), "1");
            case FilterExpr.Or<?> or ->
                join("||", or.operands().stream().map(TmuxFilters::compile).toList(), "0");
            case FilterExpr.Not<?> not -> "#{!:" + compile(not.operand()) + "}";
            case FilterExpr.Compare<?, ?> compare -> compare(compare);
            case FilterExpr.ToMany<?, ?> ignored -> refuse();
            case FilterExpr.ToOne<?, ?> ignored -> refuse();
        };
    }

    private static String join(String operator, java.util.List<String> parts, String identity) {
        if (parts.isEmpty()) {
            return identity;
        }
        String combined = parts.get(parts.size() - 1);
        for (int index = parts.size() - 2; index >= 0; index--) {
            combined = "#{" + operator + ":" + parts.get(index) + "," + combined + "}";
        }
        return combined;
    }

    private static String compare(FilterExpr.Compare<?, ?> compare) {
        String field = "#{" + compare.field().id() + "}";
        return switch (compare.operator()) {
            case EQUALS -> "#{==:" + field + "," + scalar(compare.operand()) + "}";
            case NOT_EQUALS -> "#{!=:" + field + "," + scalar(compare.operand()) + "}";
            case CONTAINS -> "#{m:*" + glob(text(compare.operand())) + "*," + field + "}";
            case STARTS_WITH -> "#{m:" + glob(text(compare.operand())) + "*," + field + "}";
            case ENDS_WITH -> "#{m:*" + glob(text(compare.operand())) + "," + field + "}";
            case MATCHES -> refuse();
            // #{<:} compares text, so 9 would sort after 10; #{e|<|:} compares numbers.
            case LESS_THAN -> "#{e|<|:" + field + "," + compare.operand() + "}";
            case AT_MOST -> "#{e|<=|:" + field + "," + compare.operand() + "}";
            case GREATER_THAN -> "#{e|>|:" + field + "," + compare.operand() + "}";
            case AT_LEAST -> "#{e|>=|:" + field + "," + compare.operand() + "}";
            case IN -> in(field, compare.operand());
        };
    }

    private static String scalar(Object operand) {
        if (operand instanceof Boolean flag) {
            return flag ? "1" : "0";
        }
        String text = String.valueOf(operand);
        if (!literal(text)) {
            refuse();
        }
        return text;
    }

    private static String text(Object operand) {
        String value = (String) operand;
        if (!literal(value)) {
            refuse();
        }
        return value;
    }

    /** fnmatch metacharacters in the caller's text stay literal. */
    private static String glob(String value) {
        StringBuilder escaped = new StringBuilder();
        for (int index = 0; index < value.length(); index++) {
            char character = value.charAt(index);
            if (character == '*' || character == '?' || character == '[' || character == '\\') {
                escaped.append('\\');
            }
            escaped.append(character);
        }
        return escaped.toString();
    }

    @SuppressWarnings("unchecked")
    private static String in(String field, Object operand) {
        java.util.Collection<?> values = (java.util.Collection<?>) operand;
        java.util.List<String> parts = new java.util.ArrayList<>();
        for (Object value : values) {
            parts.add("#{==:" + field + "," + scalar(value) + "}");
        }
        return join("||", parts, "0");
    }

    private static String refuse() {
        throw new UnsupportedFilter();
    }

    private static final class UnsupportedFilter extends RuntimeException {
        private static final long serialVersionUID = 1L;
    }
}

