     * @return empty only when a successful capture contains no match
     * @throws ServerUnavailableException if no daemon is running
     * @throws LibTmuxException if the capture otherwise fails
     */
    @Operation(Kind.READ)
    public Optional<Session> session(SessionId id) {
        Objects.requireNonNull(id, "id");
        return one(id.value(), "session_id");
    }

    private Optional<Session> one(String target, String field) {
        if (!TmuxFilters.literal(target)) {
            ServerSnapshot captured = snapshot();
            return field.equals("session_id")
                    ? captured.session(new SessionId(target)).map(session -> new Session(this, captured, session))
                    : captured.session(target).map(session -> new Session(this, captured, session));
        }
        return capture.oneSession(target, field)
                .flatMap(captured -> field.equals("session_id")
                        ? captured.session(new SessionId(target)).map(session -> new Session(this, captured, session))
                        : captured.session(target).map(session -> new Session(this, captured, session)));
    }

    /**
     * The pane with this id, captured now.
     *
     * @return empty only when a successful capture contains no match
     * @throws ServerUnavailableException if no daemon is running
     * @throws LibTmuxException if the capture otherwise fails
     */
    @Operation(Kind.READ)
    public Optional<Pane> pane(PaneId id) {
        Objects.requireNonNull(id, "id");
        if (!TmuxFilters.literal(id.value())) {
            return paneFrom(snapshot(), id);
        }
        return capture.sessionsHolding(id).flatMap(captured -> paneFrom(captured, id));
    }

    private Optional<Pane> paneFrom(ServerSnapshot captured, PaneId id) {
        return captured.panes().stream()
                .filter(pane -> pane.id().equals(id))
                .findFirst()
                .map(pane -> new Pane(this, captured, pane));
    }

    /**
     * The winlink at this exact position, captured now.
     *
     * @return empty only when a successful capture contains no match
     * @throws ServerUnavailableException if no daemon is running
     * @throws LibTmuxException if the capture otherwise fails
     */
    @Operation(Kind.READ)
    public Optional<Window> window(WindowContext context) {
        Objects.requireNonNull(context, "context");
        ServerSnapshot captured = snapshot();
        return captured.window(context).map(window -> new Window(this, captured, window));
    }

    /**
     * Every winlink of the window with this id, captured now.
     *
     * <p>A list, not an {@link Optional}, and that is the whole point. One window can be linked into
     * several sessions, and each link is a separate handle with its own index and its own active
     * flag. A finder that answered with the first would quietly act on whichever link tmux happened
     * to list first — so this hands back all of them and lets the caller say which it meant, or use
     * {@link #window(WindowContext)} to name one exactly.
     *
     * @return an immutable list in tmux order, empty if the window was not found
     * @throws ServerUnavailableException if no daemon is running
     * @throws LibTmuxException if the capture otherwise fails
     */
    @ReadOnly
    @Operation(Kind.READ)
    public List<Window> windows(WindowId id) {
        Objects.requireNonNull(id, "id");
        ServerSnapshot captured = snapshot();
        return captured.windows().stream()
                .filter(window -> window.context().window().equals(id))
                .map(window -> new Window(this, captured, window))
                .toList();
    }

    /**
     * Captures every attached client.
     *
     * @return an immutable list in tmux order
     * @throws ServerUnavailableException if no daemon is running
     * @throws LibTmuxException if the capture otherwise fails
     */
    @ReadOnly
    @Operation(Kind.READ)
    public List<Client> clients() {
        ServerSnapshot captured = snapshot();
        return captured.clients().stream()
                .map(client -> new Client(this, captured, client))
                .toList();
    }

    /**
     * Captures every session a client is attached to.
     *
     * @return an immutable list in tmux order
     * @throws ServerUnavailableException if no daemon is running
     * @throws LibTmuxException if the capture otherwise fails
     */
    @ReadOnly
    @Operation(Kind.READ)
    public List<Session> attachedSessions() {
        return sessions().stream().filter(Session::attached).toList();
    }

    /**
     * Runs a command that is expected to work, and raises when it did not.
     *
     * <p>The counterpart to {@link #cmd}: use this when a nonzero exit means the thing you asked for
     * did not happen, and {@code cmd} when a nonzero exit is an answer you want to inspect. tmux
     * reports an ordinary miss and a real problem the same way, so only the caller knows which it is.
     *
     * @throws LibTmuxException if tmux reported a nonzero exit
     */
    @Operation(Kind.MUTATION)
    public CommandResult run(List<String> argv) {
        CommandResult result = cmd(argv);
        if (!result.succeeded()) {
            throw failed(argv.get(0), result);
        }
        return result;
    }

    CommandResult cmd(ServerSnapshot snapshot, List<String> argv) {
        return fence.guarded(snapshot, CommandStrings.stringify(argv));
    }

    /** A batch whose every command is refused once this handle's server has been replaced. */
    Batch batch(ServerSnapshot snapshot) {
        return new Batch(commands -> fence.guarded(snapshot, CommandStrings.group(commands), ""));
    }

    /**
     * As {@link #batch(ServerSnapshot)}, fenced against an identity read separately.
     *
     * <p>Both halves, because a pid alone is reusable: a tmux started on the pid of the one just
     * probed, as a container's first processes often are, would answer as if it were the server the
     * rows are being read from. Its start time is not the same.
     */
    Batch batch(long pid, long startTime) {
        String condition = IncarnationFence.incarnation(pid, java.util.OptionalLong.of(startTime));
        return new Batch(commands -> fence.guarded(pid, condition, CommandStrings.group(commands), ""));
    }

    CommandResult run(ServerSnapshot snapshot, List<String> argv) {
        CommandResult result = cmd(snapshot, argv);
        if (!result.succeeded()) {
            throw failed(argv.get(0), result);
        }
        return result;
    }

    /**
     * Runs several commands in one invocation, so nothing of this caller's happens between them.
     *
     * <p>tmux carries a group to its server as one message and runs it there, so a caller that stops
     * partway cannot leave the group half applied. That is what an operation whose second command
     * cleans up after its first needs.
     */
    CommandResult runTogether(ServerSnapshot snapshot, List<List<String>> commands) {
        return runTogether(snapshot, "", commands);
    }

    /** As {@link #runTogether}, with {@code input} on tmux's standard input for the group to read. */
    CommandResult runTogether(ServerSnapshot snapshot, String input, List<List<String>> commands) {
        CommandResult result = fence.guarded(snapshot, CommandStrings.group(commands), input);
        if (!result.succeeded()) {
            String verbs = commands.stream().map(argv -> argv.get(0)).collect(Collectors.joining(" then "));
            throw failed(verbs, result);
        }
        return result;
    }

    /** As {@link #run(ServerSnapshot, List)}, refused as well once the window has been replaced. */
    CommandResult run(ServerSnapshot snapshot, WindowContext expected, List<String> argv) {
        return fence.run(snapshot, expected, argv);
    }

    ServerSnapshot refresh(ServerSnapshot previous) {
        ServerSnapshot fresh = snapshot();
        if (!identity(previous).equals(identity(fresh))) {
            throw new TargetGoneException("the tmux server this handle belonged to has ended");
        }
        return fresh;
    }

    /** A builder holding every configuration and ownership choice this server made. */
    @Operation(Kind.CAPTURED)
    public Builder toBuilder() {
        // An owned transport is not shared: this server will close it, so a derived server gets its own.
        return new Builder(config.toBuilder(), owned ? null : transport);
    }

    /** Releases an owned transport. Idempotent, and never kills tmux. */
    @Operation(Kind.LIFECYCLE)
    @Override
    public void close() {
        if (!closed.compareAndSet(false, true)) {
            return;
        }
        if (owned) {
            transport.close();
        }
    }

    /** Collects configuration and the ownership choice, then builds a server. */
    public static final class Builder {

        private final ServerConfig.Builder config;
        private @Nullable TmuxTransport transport;

        private Builder(ServerConfig.Builder config, @Nullable TmuxTransport transport) {
            this.config = config;
            this.transport = transport;
        }

        /** Sets the tmux executable. */
        public Builder binary(String binary) {
            config.binary(binary);
            return this;
        }

        /** Sets which server to talk to. */
        public Builder endpoint(ServerEndpoint endpoint) {
            config.endpoint(endpoint);
            return this;
        }

        /** Pins the config file tmux reads. */
        public Builder configFile(Path configFile) {
            config.configFile(configFile);
            return this;
        }

        /** Sets the deadline a request gets when the caller does not supply one. */
        public Builder defaultTimeout(Duration defaultTimeout) {
            config.defaultTimeout(defaultTimeout);
            return this;
        }

        /** Forces 256-color client support; false preserves terminal detection. */
        public Builder force256Colors(boolean force256Colors) {
            config.force256Colors(force256Colors);
            return this;
        }

        /** Borrows a caller-owned transport, which the built server will never close. */
        public Builder transport(TmuxTransport transport) {
            this.transport = Objects.requireNonNull(transport, "transport");
            return this;
        }

        /** Builds the server, owning a new transport unless one was borrowed. */
        public Server build() {
            ServerConfig built = config.build();
            return transport == null ? open(built) : using(built, transport);
        }
    }
}

package io.github.libtmux;

import io.github.libtmux.transport.OperationObserver;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import kotlin.annotations.jvm.ReadOnly;
import org.jspecify.annotations.Nullable;

/**
 * What a server needs to know before it runs anything: which tmux, which server, which config.
 *
 * <p>Deliberately a builder-built class rather than a record. tmux keeps growing flags, and a
 * record's canonical constructor is public API: every field added later would break both source and
 * binary compatibility for anyone who had constructed one.
 *
 * <p>Nothing here contacts tmux. A config can be built, stored and compared on a machine that has
 * no tmux installed.
 */
public final class ServerConfig {

    private static final Duration DEFAULT_TIMEOUT = Duration.ofSeconds(30);
    private static final int DEFAULT_CONCURRENT_COMMANDS = 4;

    private final String binary;
    private final ServerEndpoint endpoint;
    private final @Nullable Path configFile;
    private final Duration defaultTimeout;
    private final boolean force256Colors;
    private final OperationObserver observer;
    private final int maxConcurrentCommands;

    private ServerConfig(Builder builder) {
        this.binary = builder.binary;
        this.endpoint = builder.endpoint;
        this.configFile = builder.configFile;
        this.defaultTimeout = builder.defaultTimeout;
        this.force256Colors = builder.force256Colors;
        this.observer = builder.observer;
        this.maxConcurrentCommands = builder.maxConcurrentCommands;
    }

    /** A builder holding the documented defaults. */
    public static Builder builder() {
        return new Builder();
    }

    /** The tmux executable, resolved on {@code PATH} unless it is an absolute path. */
    public String binary() {
        return binary;
    }

    /**
     * The binary as a path, resolved the way this process resolves it.
     *
     * <p>What to write into a command a pane will run. A pane resolves a bare name against the
     * user's {@code PATH} rather than this process's, and a tmux client built from a different
     * release than the server it reaches is dropped rather than served. Falls back to the name when
     * nothing on {@code PATH} matches, which leaves the caller no worse off.
     */
    public String binaryPath() {
        if (binary.contains(File.separator)) {
            return binary;
        }
        String search = System.getenv("PATH");
        if (search == null) {
            return binary;
        }
        for (String entry : search.split(File.pathSeparator, -1)) {
            if (entry.isEmpty()) {
                continue;
            }
            Path candidate = Path.of(entry, binary);
            if (Files.isExecutable(candidate)) {
                return candidate.toString();
            }
        }
        return binary;
    }

    /** Which tmux server to talk to. */
    public ServerEndpoint endpoint() {
        return endpoint;
    }

    /** The config file tmux should read, if the caller pinned one. */
    public Optional<Path> configFile() {
        return Optional.ofNullable(configFile);
    }

    /** How long a request waits when the caller does not say. */
    public Duration defaultTimeout() {
        return defaultTimeout;
    }

    /** Whether tmux clients advertise 256-color support regardless of terminal detection. */
    public boolean force256Colors() {
        return force256Colors;
    }

    /** Where each command's report goes. {@link OperationObserver#NONE} until a caller sets one. */
    public OperationObserver observer() {
        return observer;
    }

    /**
     * The argv prefix every command on this server begins with: the binary, {@code -u}, optional color flag, the server
     * selection, and the config file if one was pinned.
     *
     * <p>{@code -u} says this client reads UTF-8. Without it tmux decides from {@code LC_ALL},
     * {@code LC_CTYPE} and {@code LANG}, and a client it judges not to be UTF-8 has every non-ASCII
     * character in every reply replaced with {@code _} before it is sent — so a session named
     * {@code café} reads back as {@code caf_}, and a pane's directory becomes a path that does not
     * exist. The flag is in tmux's option string on every supported release.
     *
     * <p>Deliberately the flag rather than {@code LC_ALL} in the child's environment, which would
     * reach the same conclusion and then be inherited by every pane the server spawns from this
     * client.
     */
    @ReadOnly
    public List<String> endpointCommand() {
        List<String> command = new ArrayList<>(7);
        command.add(binary);
        command.add("-u");
        if (force256Colors) command.add("-2");
        command.addAll(endpoint.flags());
        if (configFile != null) {
            command.add("-f");
            command.add(configFile.toString());
        }
        return Collections.unmodifiableList(command);
    }

    /**
     * How many tmux commands {@link Server#open} lets run at once; more wait their turn.
     *
     * <p>A coroutine dispatcher or effect pool that runs blocking calls for this server gains nothing
     * from more threads than this: the rest would only wait for admission.
     */
    public int maxConcurrentCommands() {
        return maxConcurrentCommands;
    }

    /** A builder holding every choice this config made. */
    public Builder toBuilder() {
        Builder builder = new Builder();
        builder.binary = binary;
        builder.endpoint = endpoint;
        builder.configFile = configFile;
        builder.defaultTimeout = defaultTimeout;
        builder.force256Colors = force256Colors;
        builder.observer = observer;
        builder.maxConcurrentCommands = maxConcurrentCommands;
        return builder;
    }

    /** Collects the choices; {@link #build()} checks them. */
    public static final class Builder {

        private String binary = "tmux";
        private ServerEndpoint endpoint = ServerEndpoint.defaultSocket();
        private @Nullable Path configFile;
        private Duration defaultTimeout = DEFAULT_TIMEOUT;
        private boolean force256Colors;
        private OperationObserver observer = OperationObserver.NONE;
        private int maxConcurrentCommands = DEFAULT_CONCURRENT_COMMANDS;

        private Builder() {}

        /** Sets the tmux executable. */
        public Builder binary(String binary) {
            this.binary = Objects.requireNonNull(binary, "binary");
            return this;
        }

        /** Sets which server to talk to. */
        public Builder endpoint(ServerEndpoint endpoint) {
            this.endpoint = Objects.requireNonNull(endpoint, "endpoint");
            return this;
        }

        /** Pins the config file tmux reads, which is how a test isolates itself from a user's own. */
        public Builder configFile(Path configFile) {
            this.configFile = Objects.requireNonNull(configFile, "configFile");
            return this;
        }

        /** Sets the deadline a request gets when the caller does not supply one. */
        public Builder defaultTimeout(Duration defaultTimeout) {
            this.defaultTimeout = Objects.requireNonNull(defaultTimeout, "defaultTimeout");
            return this;
        }

        /** Forces 256-color client support with tmux's {@code -2}; false uses terminal detection. */
        public Builder force256Colors(boolean force256Colors) {
            this.force256Colors = force256Colors;
            return this;
        }

        /** Receives a report after each command. The report names verbs, not arguments. */
        public Builder observer(OperationObserver observer) {
            this.observer = Objects.requireNonNull(observer, "observer");
            return this;
        }

        /**
         * Sets how many tmux commands {@link Server#open} lets run at once, four unless set.
         *
         * @throws IllegalArgumentException if {@code maxConcurrentCommands} is not positive
         */
        public Builder maxConcurrentCommands(int maxConcurrentCommands) {
            if (maxConcurrentCommands < 1) {
                throw new IllegalArgumentException("maxConcurrentCommands is not positive: " + maxConcurrentCommands);
            }
            this.maxConcurrentCommands = maxConcurrentCommands;
            return this;
        }

        /**
         * Builds an immutable config, rejecting choices that could only fail later.
         *
         * @throws IllegalArgumentException if a choice would only fail later
         */
        public ServerConfig build() {
            if (binary.isEmpty()) {
                throw new IllegalArgumentException("binary is empty");
            }
            if (defaultTimeout.isZero() || defaultTimeout.isNegative()) {
                throw new IllegalArgumentException("defaultTimeout is not positive");
            }
            return new ServerConfig(this);
        }
    }
}

package io.github.libtmux;

import java.nio.file.Path;
import java.util.List;
import java.util.Objects;
import kotlin.annotations.jvm.ReadOnly;

/**
 * Which tmux server to talk to.
 *
 * <p>A value, decided and comparable before any process runs. Two endpoints are equal when they name
 * the same server lexically; nothing here resolves symlinks, contacts the filesystem, or opens a
 * socket. That matters because an endpoint is routinely built, logged and compared while the socket
 * it names does not exist yet.
 *
 * <p>Validation that needs tmux — above all whether a socket path fits the platform's
 * {@code sun_path} — happens at dispatch, where the error can carry the command that hit it.
 */
public sealed interface ServerEndpoint {

    /** The flags that select this server, in argv order. */
    @ReadOnly
    List<String> flags();

    /** tmux's own default server, wherever tmux decides that is. */
    static ServerEndpoint defaultSocket() {
        return new Default();
    }

    /** A server named with {@code -L}, resolved by tmux under its own socket directory. */
    static ServerEndpoint namedSocket(String name) {
        return new NamedSocket(name);
    }

    /** A server at an exact socket path, selected with {@code -S}. */
    static ServerEndpoint socketPath(Path path) {
        return new SocketPath(path);
    }

    /** Adds no flags, so tmux applies its own default socket resolution. */
    record Default() implements ServerEndpoint {
        @Override
        @ReadOnly
        public List<String> flags() {
            return List.of();
        }
    }

    /**
     * A server tmux locates by name under its own socket directory.
     *
     * @param name a bare name, with no path separator
     */
    record NamedSocket(String name) implements ServerEndpoint {

        public NamedSocket {
            Objects.requireNonNull(name, "name");
            if (name.isEmpty()) {
                throw new IllegalArgumentException("socket name is empty");
            }
            if (name.indexOf('/') >= 0) {
                // tmux resolves -L under its own socket directory, so a separator here cannot mean
                // what it looks like. Silently reinterpreting it would point at the wrong server.
                throw new IllegalArgumentException("socket name contains a path separator: " + name);
            }
        }

        @Override
        @ReadOnly
        public List<String> flags() {
            return List.of("-L", name);
        }
    }

    /**
     * A server at an exact socket path.
     *
     * @param path the socket path, anchored and lexically normalized so equal sockets compare equal
     */
    record SocketPath(Path path) implements ServerEndpoint {

        public SocketPath {
            Objects.requireNonNull(path, "path");
            if (path.toString().isEmpty()) {
                throw new IllegalArgumentException("socket path is empty");
            }
            path = path.toAbsolutePath().normalize();
        }

        @Override
        @ReadOnly
        public List<String> flags() {
            return List.of("-S", path.toString());
        }
    }
}

package io.github.libtmux;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.Objects;
import java.util.OptionalLong;

/**
 * Which tmux server a handle belongs to.
 *
 * <p>Two entities with the same id are the same entity only if they came from the same server. The
 * realm exists because socket text alone is not enough: two unrelated execution realms — a local
 * process and a container, say — can both hold a server at {@code /tmp/s}, and entities from them
 * must not compare equal.
 *
 * <p>The server is identified by a digest of its endpoint rather than by the endpoint itself, so an
 * identity can be logged, compared and embedded in a message without carrying a socket path.
 */
public final class ServerIdentity {

    private final String realm;
    private final String server;
    private final long processId;
    // -1 when not known; tmux reports seconds since the epoch.
    private final long startTime;

    private ServerIdentity(String realm, String server, long processId, long startTime) {
        this.realm = realm;
        this.server = server;
        this.processId = processId;
        this.startTime = startTime;
    }

    static ServerIdentity of(String realm, ServerEndpoint endpoint) {
        return new ServerIdentity(Objects.requireNonNull(realm, "realm"), digest(endpoint), 0, -1);
    }

    /** This server as one process: a pid alone can be reused, so its start time is part of it. */
    ServerIdentity at(long pid, OptionalLong startTime) {
        if (pid < 1) {
            throw new IllegalArgumentException("pid is not positive: " + pid);
        }
        return new ServerIdentity(realm, server, pid, startTime.orElse(-1));
    }

    /** The execution realm the transport reaches tmux through. */
    public String realm() {
        return realm;
    }

    /** A stable opaque key for the server, carrying no socket path. */
    public String server() {
        return server;
    }

    /** The live tmux process, present on an identity bound to a captured handle. */
    public OptionalLong processId() {
        return processId == 0 ? OptionalLong.empty() : OptionalLong.of(processId);
    }

    @Override
    public boolean equals(Object other) {
        return other instanceof ServerIdentity that
                && realm.equals(that.realm)
                && server.equals(that.server)
                && processId == that.processId
                && startTime == that.startTime;
    }

    @Override
    public int hashCode() {
        return Objects.hash(realm, server, processId, startTime);
    }

    @Override
    public String toString() {
        return "ServerIdentity[" + realm + ":" + server + (processId == 0 ? "" : "@" + processId)
                + (startTime < 0 ? "" : "+" + startTime) + "]";
    }

    private static String digest(ServerEndpoint endpoint) {
        try {
            byte[] hash = MessageDigest.getInstance("SHA-256")
                    .digest(String.join("\0", endpoint.flags()).getBytes(StandardCharsets.UTF_8));
            // 128 bits: equal keys mean one server, and a shorter digest invites a collision.
            return HexFormat.of().formatHex(hash, 0, 16);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 is required of every Java platform", e);
        }
    }
}

package io.github.libtmux;

import com.google.errorprone.annotations.CheckReturnValue;
import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import io.github.libtmux.exception.LibTmuxException;
import io.github.libtmux.exception.ServerUnavailableException;
import io.github.libtmux.exception.TargetGoneException;
import io.github.libtmux.format.RowFormat;
import io.github.libtmux.snapshot.ServerSnapshot;
import io.github.libtmux.snapshot.SessionState;
import io.github.libtmux.snapshot.WindowContext;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.function.Consumer;
import kotlin.annotations.jvm.ReadOnly;

/**
 * One tmux session, as one capture saw it.
 *
 * <p>Identity is the server and the session id. A name is state: a user can rename a session at any
 * time, and a handle whose equality included the name would stop matching itself the moment they
 * did.
 *
 * <p>{@link #windows()} reads the capture this handle came from and issues no command. To see newer
 * state, take a new capture.
 *
 * <p>A method named for a captured field returns what {@link #info()} holds and does no I/O;
 * {@link #refresh()} reads again. Every other method asks tmux now.
 */
public final class Session {

    private static final RowFormat CREATED = RowFormat.of("session_id", "window_id", "window_index");

    private final Server server;
    private final ServerSnapshot snapshot;
    private final SessionState state;

    Session(Server server, ServerSnapshot snapshot, SessionState state) {
        this.server = server;
        this.snapshot = snapshot;
        this.state = state;
    }

    /** The fields this capture stored. A later rename is not visible here. */
    @Operation(Kind.CAPTURED)
    public SessionState info() {
        return state;
    }

    /** The session's stable id. */
    @Operation(Kind.CAPTURED)
    public SessionId id() {
        return state.id();
    }

    /** The session name, which a user may change at any time. */
    @Operation(Kind.CAPTURED)
    public String name() {
        return state.name();
    }

    /** Whether a client was attached when this was captured. */
    @Operation(Kind.CAPTURED)
    public boolean attached() {
        return state.attached();
    }

    /** The server this session lives on. */
    @Operation(Kind.CAPTURED)
    public Server server() {
        return server;
    }

    ServerSnapshot snapshot() {
        return snapshot;
    }

    /** The window tmux had active in this session. A pure read of the capture. */
    @Operation(Kind.CAPTURED)
    public Optional<Window> activeWindow() {
        return windows().stream().filter(Window::active).findFirst();
    }

    /** The active pane of the active window. A pure read of the capture. */
    @Operation(Kind.CAPTURED)
    public Optional<Pane> activePane() {
        return activeWindow().flatMap(Window::activePane);
    }

    /** Makes a window of this session the active one. */
    @Operation(Kind.MUTATION)
    public void selectWindow(Window window) {
        Objects.requireNonNull(window, "window");
        server.requireSameIncarnation(snapshot, window.server(), window.snapshot());
        if (!state.id().equals(window.context().session())) {
            throw new IllegalArgumentException("window does not belong to session " + state.id());
        }
        server.run(
                snapshot,
                window.context(),
                List.of(
                        "select-window",
                        "-t",
                        state.id().value() + ":" + window.index().value()));
    }

    /** Moves to the next window in this session, wrapping at the end. */
    @Operation(Kind.MUTATION)
    public void nextWindow() {
        server.run(snapshot, List.of("next-window", "-t", state.id().value()));
    }

    /** Moves to the previous window in this session, wrapping at the start. */
    @Operation(Kind.MUTATION)
    public void previousWindow() {
        server.run(snapshot, List.of("previous-window", "-t", state.id().value()));
    }

    /**
     * Returns to the window that was active before this one.
     *
     * @throws LibTmuxException if nothing else has been active yet, which tmux reports rather than
     *     silently staying put
     */
    @Operation(Kind.MUTATION)
    public void lastWindow() {
        server.run(snapshot, List.of("last-window", "-t", state.id().value()));
    }

    /** Detaches every client attached to this session, leaving the session running. */
    @Operation(Kind.MUTATION)
    public void detachClients() {
        server.run(snapshot, List.of("detach-client", "-s", state.id().value()));
    }

    /** This session's own options. */
    @Operation(Kind.CAPTURED)
    public Options options() {
        return Options.session(server, snapshot, state.id());
    }

    /**
     * This session's own environment, which a process started in it is given on top of the
     * server's.
     */
    @Operation(Kind.CAPTURED)
    public Environment environment() {
        return Environment.session(server, snapshot, state.id());
    }

    /** This session's own hooks. */
    @Operation(Kind.CAPTURED)
    public Hooks hooks() {
        return Hooks.session(server, snapshot, state.id());
    }

    /** Sets the scrollback retained by panes created in this session. */
    @Operation(Kind.MUTATION)
    public void setHistoryLimit(int lines) {
        if (lines < 0) {
            throw new IllegalArgumentException("history limit is negative: " + lines);
        }
        options().set("history-limit", Integer.toString(lines));
    }

    /** This session's windows, in tmux's order. A pure read of the capture. */
    @ReadOnly
    @Operation(Kind.CAPTURED)
    public List<Window> windows() {
        return snapshot.windowsOf(state.id()).stream()
                .map(window -> new Window(server, snapshot, window))
                .toList();
    }

    /**
     * Creates a window in this session and returns that exact window.
     *
     * <p>The creating command reports which window it made, rather than the name being looked up
     * afterwards: two windows may share a name, and then a lookup cannot say which one is new.
     *
     * @param name the window name
     * @return a handle on the created window, from a fresh capture
     */
    @Operation(Kind.MUTATION)
    public Window newWindow(String name) {
        return newWindow(WindowSpec.builder().named(name).build());
    }

    /**
     * Creates a window in this session as described.
     *
     * <pre>{@code
     * Window logs = session.newWindow(w -> w.named("logs").running("journalctl", "-f"));
     * }</pre>
     *
     * @param configure receives a builder holding tmux's defaults
     * @return a handle on the created window, from a fresh capture
     */
    @Operation(Kind.MUTATION)
    public Window newWindow(Consumer<WindowSpec.Builder> configure) {
        WindowSpec.Builder builder = WindowSpec.builder();
        configure.accept(builder);
        return newWindow(builder.build());
    }

    /**
     * Creates a window in this session according to a spec, which may be reused across sessions.
     *
     * @return a handle on the created window, from a fresh capture
     */
    @Operation(Kind.MUTATION)
    public Window newWindow(WindowSpec spec) {
        List<String> reported = server.run(snapshot, spec.argv(state.id().value(), CREATED.template()))
                .stdout();
        ServerSnapshot fresh = server.refresh(snapshot);
        if (reported.isEmpty()) {
            // Only reuseExisting gets here: tmux selects the window it already had and reports
            // nothing, so the answer has to come from a lookup. See docs/internals/tmux-behaviour.md.
            return spec.name()
                    .flatMap(wanted -> new Session(server, fresh, state)
                            .windows().stream()
                                    .filter(window -> wanted.equals(window.name()))
                                    .findFirst())
                    .orElseThrow(() -> new TargetGoneException("tmux reported no window and none carries that name"));
        }
        List<String> fields = CREATED.split(reported.get(0));
        WindowContext created = new WindowContext(
                new SessionId(fields.get(0)),
                new WindowIndex(Integer.parseInt(fields.get(2))),
                new WindowId(fields.get(1)));
        return fresh.window(created)
                .map(window -> new Window(server, fresh, window))
                .orElseThrow(() -> new TargetGoneException("the window just created is already gone"));
    }

    /**
     * Expands a tmux format in this session's context, and answers with what it came to.
     *
     * <p>The same escape hatch {@link Pane#expand} gives, resolved against this session.
     *
     * @param format a tmux format, usually of the shape {@code #{name}}
     * @return the expansion, whole when it spans lines and empty when the format expanded to
     *     nothing
     */
    @Operation(Kind.READ)
    public String expand(String format) {
        Objects.requireNonNull(format, "format");
        return PrintedText.printed(server.run(
                        snapshot,
                        List.of("display-message", "-p", "-t", state.id().value(), "--", PrintedText.expansion(format)))
                .stdout());
    }

    /**
     * Renames this session and returns its replacement capture.
     *
     * <p>Retain the result to read the changed name. This handle keeps its original captured state.
     */
    @CheckReturnValue
    @Operation(Kind.MUTATION)
    public Session rename(String name) {
        server.run(snapshot, List.of("rename-session", "-t", state.id().value(), "--", TmuxFormats.literal(name)));
        return refresh();
    }

    /** Ends this session. Every window in it goes with it. */
    @Operation(Kind.MUTATION)
    public void kill() {
        server.run(snapshot, List.of("kill-session", "-t", state.id().value()));
    }

    /**
     * Takes a new capture and returns this session as it is now.
     *
     * <p>This handle remains unchanged. Use the returned handle for subsequent state reads.
     *
     * @throws TargetGoneException if the session is gone from a server that still answers
     * @throws ServerUnavailableException if no daemon is running
     */
    @CheckReturnValue
    @Operation(Kind.READ)
    public Session refresh() {
        ServerSnapshot fresh = server.refresh(snapshot);
        return fresh.session(state.id())
                .map(session -> new Session(server, fresh, session))
                .orElseThrow(() -> new TargetGoneException("session " + state.id() + " no longer exists"));
    }

    @Override
    public boolean equals(Object other) {
        return other instanceof Session that
                && server.identity(snapshot).equals(that.server.identity(that.snapshot))
                && state.id().equals(that.state.id());
    }

    @Override
    public int hashCode() {
        return Objects.hash(server.identity(snapshot), state.id());
    }

    @Override
    public String toString() {
        return "Session[" + state.id() + " " + state.name() + "]";
    }
}

package io.github.libtmux;

import io.github.libtmux.exception.LibTmuxException;
import io.github.libtmux.exception.MalformedResponseException;
import io.github.libtmux.exception.ServerUnavailableException;
import io.github.libtmux.internal.ErrorText;
import io.github.libtmux.transport.CommandResult;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

/** Assembles the pieces {@link Server#newSession(SessionSpec)} needs before tmux has a session yet. */
final class SessionCreation {

    private SessionCreation() {}

    /**
     * tmux exits 0 even when nothing was created: an explicit {@code -S} under a directory that does
     * not exist prints its own {@code error creating ...} and still returns success, and a binary
     * that is not tmux at all can exit 0 with nothing on stdout the same way {@code run} cannot tell
     * apart from a real session id. Reads tmux's own words when it spoke and names the configured
     * binary when it did not, rather than letting an empty list reach {@code SessionId} and throw
     * an unchecked collection exception with neither in it.
     *
     * <p>tmux 3.2a says nothing at all when it cannot create its socket: the server queues the
     * error and tells the client to exit at once, and the client leaves before the error reaches
     * it. So a silent exit checks the one cause this client can see for itself.
     */
    static String failureMessage(ServerConfig config, CommandResult result) {
        if (!result.stderr().isEmpty()) {
            return "tmux new-session failed: " + String.join("; ", result.stderr());
        }
        if (config.endpoint() instanceof ServerEndpoint.SocketPath(Path socket)) {
            Path directory = socket.toAbsolutePath().getParent();
            if (directory != null && !Files.isDirectory(directory)) {
                return "tmux created no session: the socket's directory " + directory + " does not exist";
            }
        }
        return config.binary() + " exited 0 and reported no session id; is it tmux?";
    }

    /**
     * The version to gate a session-creation spec against.
     *
     * <p>{@code new-session} may be the first command said to a fresh socket, where {@link
     * Server#version()} fails for want of a daemon. So this asks a running daemon when one answers,
     * since it may be a different build than the configured binary, and otherwise asks the binary
     * through {@link #binaryVersion}.
     *
     * <p>Reads {@link SnapshotCapture#processForCreation()} rather than {@link Server#version()}: a
     * daemon too old to talk to fails the identity probe as one never started does ("server exited
     * unexpectedly"), and {@link ServerUnavailableException} does not keep that distinction.
     * Falling back to {@code binaryVersion} for such a daemon would report the binary's version as
     * the daemon's.
     */
    static TmuxVersion versionForCreation(Server server) {
        return server.capture()
                .processForCreation()
                .map(SnapshotCapture.ServerProcess::version)
                .orElseGet(() -> binaryVersion(server));
    }

    /**
     * Which tmux the configured binary is, without asking any server.
     *
     * <p>{@code -V} is handled before tmux touches a socket at all, so it answers even against an
     * endpoint nothing is listening on yet, with or without a {@code -f} pointed at a config file
     * that does not exist.
     *
     * @throws LibTmuxException if the binary could not be run or did not report a version
     */
    private static TmuxVersion binaryVersion(Server server) {
        CommandResult result = server.cmd(List.of("-V"));
        if (!result.succeeded() || result.stdout().isEmpty()) {
            throw new MalformedResponseException(
                    "tmux -V did not report a version" + ErrorText.suffix(result.stderr()));
        }
        String reported = result.stdout().get(0);
        int space = reported.indexOf(' ');
        if (space < 0) {
            throw new MalformedResponseException("tmux -V reported an unexpected line: " + reported);
        }
        return TmuxVersion.parse(reported.substring(space + 1));
    }
}

package io.github.libtmux;

/**
 * A tmux session id, such as {@code $0}.
 *
 * <p>Stable for the life of the session, unlike a session name, which a user can change at any
 * time. A separate type from {@link WindowId} and {@link PaneId} because tmux accepts any of them
 * as {@code -t} syntax: passing the wrong one is not an error tmux reports, it simply addresses
 * nothing.
 *
 * @param value the id including its {@code $} sigil
 */
public record SessionId(String value) {

    public SessionId {
        TargetIds.require(value, '$', "session");
    }

    @Override
    public String toString() {
        return value;
    }
}

package io.github.libtmux;

import io.github.libtmux.format.RowFormat;
import io.github.libtmux.transport.CommandResult;
import java.util.List;
import java.util.Optional;

/** Resolves a caller-given session name to the id tmux keeps it under. */
final class SessionLookup {

    private SessionLookup() {}

    /**
     * The id of the session tmux keeps under this name, read from one listing.
     *
     * <p>Not a {@code -t =name} target: tmux reads {@code .} and {@code :} in a target as window and
     * pane separators, and it may have stored the name differently from how it was given.
     */
    static Optional<SessionId> named(Server server, String name) {
        RowFormat format = RowFormat.of("session_id", "session_name", "version");
        CommandResult result = server.cmd("list-sessions", "-F", format.template());
        if (!result.succeeded()) {
            // A live server with no sessions lists nothing and exits 0, on 3.2a and 3.7d alike, so
            // any failure is not an answer: no daemon, a socket this user cannot open, or a binary
            // that is not tmux. failed() tells the first apart.
            throw server.failed("list-sessions", result);
        }
        List<RowFormat.Row> rows = format.rows(result.stdout());
        if (rows.isEmpty()) {
            return Optional.empty();
        }
        TmuxVersion version = TmuxVersion.parse(rows.get(0).text("version"));
        rows = format.rows(TmuxFormats.printed(result.stdout(), version));
        for (String stored : TmuxFormats.storedNames(name, version)) {
            for (RowFormat.Row row : rows) {
                if (row.text("session_name").equals(stored)) {
                    return Optional.of(new SessionId(row.text("session_id")));
                }
            }
        }
        return Optional.empty();
    }
}

package io.github.libtmux;

import io.github.libtmux.exception.UnsupportedFeatureException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.function.Supplier;
import kotlin.annotations.jvm.ReadOnly;
import org.jspecify.annotations.Nullable;

/**
 * How a session should be made.
 *
 * <p>The shape {@link SplitSpec} and {@link WindowSpec} use. tmux's {@code -A}, which attaches when
 * the name is taken, is deliberately absent: attaching needs a terminal, and it fails with
 * {@code open terminal failed} on every supported release when there is none. Asking
 * {@link Server#hasSession} first does the same job from a process that has no tty, which is where a
 * library usually runs.
 *
 * <pre>{@code
 * Session build = server.newSession(s -> s.named("build").sized(new Dimensions(120, 40)));
 * }</pre>
 */
public final class SessionSpec {

    /**
     * 3.2a accepts {@code -x}/{@code -y} for a detached session and then ignores them; upstream's
     * {@code df3fe2aa} ("Only use client for sizing when not detached") is the fix, and it is
     * already in tag 3.3 - absent from 3.2a, and {@code git log 3.3..3.3a} touches nothing under
     * {@code spawn.c} or {@code cmd-new-session.c} - so the floor is 3.3, not 3.3a.
     */
    private static final TmuxVersion SIZE_SINCE = new TmuxVersion(3, 3, "");

    private final @Nullable String name;
    private final @Nullable Path directory;
    private final Map<String, String> environment;
    private final @Nullable String windowName;
    private final @Nullable Dimensions size;
    private final boolean withoutSize;
    private final boolean detachOthers;
    private final List<String> clientFlags;
    private final List<String> command;

    private SessionSpec(Builder builder) {
        this.name = builder.name;
        this.directory = builder.directory;
        this.environment = Collections.unmodifiableMap(new LinkedHashMap<>(builder.environment));
        this.windowName = builder.windowName;
        this.size = builder.size;
        this.withoutSize = builder.withoutSize;
        this.detachOthers = builder.detachOthers;
        this.clientFlags = List.copyOf(builder.clientFlags);
        this.command = List.copyOf(builder.command);
    }

    /** A builder holding tmux's own defaults: a detached session tmux names itself. */
    public static Builder builder() {
        return new Builder();
    }

    /** The session name, or empty to let tmux number it. */
    public Optional<String> name() {
        return Optional.ofNullable(name);
    }

    /** Where the session's first pane starts, or empty to inherit. */
    public Optional<Path> directory() {
        return Optional.ofNullable(directory);
    }

    /** Variables set for the new session, in the order they were given. */
    @ReadOnly
    public Map<String, String> environment() {
        return environment;
    }

    /**
     * Always true, and not a choice.
     *
     * <p>{@code new-session} attaches unless told not to, and attaching needs a terminal — from a
     * process without one it fails with {@code open terminal failed}. A library is usually called
     * from something that has no tty, so the session is always created detached. {@link WindowSpec}
     * and {@link SplitSpec} default the other way, because their commands need no terminal.
     */
    public boolean detached() {
        return true;
    }

    /** The name of the session's first window, or empty for tmux's choice. */
    public Optional<String> windowName() {
        return Optional.ofNullable(windowName);
    }

    /** How big the session is, or empty for tmux's default. Requires tmux 3.3. */
    public Optional<Dimensions> size() {
        return Optional.ofNullable(size);
    }

    /** Whether tmux is told not to give the session a size at all. */
    public boolean withoutSize() {
        return withoutSize;
    }

    /** Whether other clients on this session are detached. */
    public boolean detachOthers() {
        return detachOthers;
    }

    /** Client flags, which tmux takes as one comma-separated list. */
    @ReadOnly
    public List<String> clientFlags() {
        return clientFlags;
    }

    /** What the session's first pane runs, empty for the default shell. */
    @ReadOnly
    public List<String> command() {
        return command;
    }

    /**
     * The command that makes this session, reporting it through {@code format}.
     *
     * <p>The version arrives as a supplier because this is the one creating call that may run when
     * there is no server yet, and asking a socket with nothing behind it for its version fails.
     * Nothing asks unless the spec depends on the answer.
     *
     * @param format the row format the caller will read the result back with
     * @param running what the server about to run this is, asked only if it matters
     * @throws UnsupportedFeatureException if the spec asks for something {@code running} does not have
     */
    List<String> argv(String format, Supplier<TmuxVersion> running) {
        if (size != null) {
            TmuxVersion version = running.get();
            if (!version.atLeast(SIZE_SINCE)) {
                throw new UnsupportedFeatureException("a size for a detached session", SIZE_SINCE, version);
            }
        }
        List<String> argv = new ArrayList<>(24);
        argv.add("new-session");
        // Always: without -d, tmux tries to attach and fails outright with no terminal.
        argv.add("-d");
        if (detachOthers) {
            argv.add("-D");
        }
        if (withoutSize) {
            argv.add("-X");
        }
        if (name != null) {
            argv.add("-s");
            argv.add(TmuxFormats.literal(name));
        }
        if (windowName != null) {
            argv.add("-n");
            argv.add(TmuxFormats.literal(windowName));
        }
        if (size != null) {
            argv.add("-x");
            argv.add(Integer.toString(size.width()));
            argv.add("-y");
            argv.add(Integer.toString(size.height()));
        }
        if (directory != null) {
            argv.add("-c");
            argv.add(TmuxFormats.literal(directory.toAbsolutePath().toString()));
        }
        if (!clientFlags.isEmpty()) {
            // tmux reads -f as one comma-separated list, not as a flag that may repeat.
            argv.add("-f");
            argv.add(String.join(",", clientFlags));
        }
        for (Map.Entry<String, String> variable : environment.entrySet()) {
            argv.add("-e");
            argv.add(variable.getKey() + "=" + variable.getValue());
        }
        argv.add("-P");
        argv.add("-F");
        argv.add(format);
        // Last, because everything after the command belongs to the command.
        if (!command.isEmpty()) {
            argv.add("--");
            argv.addAll(command);
        }
        return List.copyOf(argv);
    }

    @Override
    public String toString() {
        return "SessionSpec[" + (name == null ? "unnamed" : name) + (size == null ? "" : " " + size) + "]";
    }

    /** Collects the choices, each named for what it does rather than for the field it sets. */
    public static final class Builder {

        private @Nullable String name;
        private @Nullable Path directory;
        private final Map<String, String> environment = new LinkedHashMap<>();
        private @Nullable String windowName;
        private @Nullable Dimensions size;
        private boolean withoutSize;
        private boolean detachOthers;
        private List<String> clientFlags = List.of();
        private List<String> command = List.of();

        private Builder() {}

        /** Names the session, where tmux would otherwise number it. */
        public Builder named(String name) {
            this.name = Objects.requireNonNull(name, "name");
            return this;
        }

        /** Names the session's first window. */
        public Builder firstWindowNamed(String windowName) {
            this.windowName = Objects.requireNonNull(windowName, "windowName");
            return this;
        }

        /**
         * Runs a command instead of the default shell. tmux reports the session before the command
         * has started, so wait for its pane's command with {@link Pane#await(java.util.function.Predicate, java.time.Duration)} rather than reading it at once.
         */
        public Builder running(String... argv) {
            List<String> given = List.of(argv);
            if (given.isEmpty()) {
                throw new IllegalArgumentException("command is empty");
            }
            command = given;
            return this;
        }

        /** Starts the session in this directory, resolved against this process's when relative. */
        public Builder in(Path directory) {
            this.directory = Objects.requireNonNull(directory, "directory");
            return this;
        }

        /** Sets one variable in the new session's environment. */
        public Builder env(String name, String value) {
            environment.put(Objects.requireNonNull(name, "name"), Objects.requireNonNull(value, "value"));
            return this;
        }

        /** Adds several variables to the new session's environment, keeping any already set. */
        public Builder environment(Map<String, String> variables) {
            variables.forEach(this::env);
            return this;
        }

        /** Gives the session a size, which a detached session has no client to take one from. */
        public Builder sized(Dimensions size) {
            this.size = Objects.requireNonNull(size, "size");
            return this;
        }

        /** Asks tmux not to give the session a size at all. */
        public Builder withoutSize() {
            withoutSize = true;
            return this;
        }

        /** Detaches any other client already on this session. */
        public Builder detachOthers() {
            detachOthers = true;
            return this;
        }

        /** Sets the client flags tmux applies, which it reads as one comma-separated list. */
        public Builder clientFlags(String... flags) {
            clientFlags = List.of(flags);
            return this;
        }

        /** The finished spec. */
        public SessionSpec build() {
            return new SessionSpec(this);
        }
    }
}

package io.github.libtmux;

import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import io.github.libtmux.exception.UnsupportedFeatureException;
import java.util.List;
import java.util.Objects;
import kotlin.annotations.jvm.ReadOnly;

/**
 * A shell command run by tmux, and a tmux command chosen by a shell command's exit status.
 *
 * <p>tmux expands {@code #(...)} in these strings before a shell sees them. Pass an interpolated
 * value through {@link TmuxFormats#literal} unless that expansion is what you want.
 */
public final class Shell {

    /**
     * tmux lost {@code run-shell}'s output in 3.3a and found it again in 3.5. The command exists on
     * every release, so {@code list-commands} cannot tell the gap from the working releases.
     */
    private static final TmuxVersion OUTPUT_LOST = new TmuxVersion(3, 3, "");

    private static final TmuxVersion OUTPUT_FOUND = new TmuxVersion(3, 5, "");

    private final Server server;

    Shell(Server server) {
        this.server = server;
    }

    /** Runs a shell command for its effect. Nothing is claimed about what it printed. */
    @Operation(Kind.MUTATION)
    public void run(String command) {
        Objects.requireNonNull(command, "command");
        server.run(List.of("run-shell", "--", command));
    }

    /**
     * Runs a shell command and answers with what it printed.
     *
     * @throws UnsupportedFeatureException on tmux 3.3a and 3.4, which run the command and report
     *     nothing
     */
    @ReadOnly
    @Operation(Kind.MUTATION)
    public List<String> capturing(String command) {
        Objects.requireNonNull(command, "command");
        TmuxVersion running = server.version();
        if (running.atLeast(OUTPUT_LOST) && !running.atLeast(OUTPUT_FOUND)) {
            throw new UnsupportedFeatureException(
                    "reading what run-shell printed is broken between tmux 3.3a and 3.4, and this server runs "
                            + running);
        }
        return server.run(List.of("run-shell", "--", command)).stdout();
    }

    /**
     * Runs one tmux command when a shell command succeeds.
     *
     * @param condition a shell command, judged by its exit status
     * @param whenTrue the tmux command to run when the condition succeeds
     */
    @Operation(Kind.MUTATION)
    public void choose(String condition, String whenTrue) {
        Objects.requireNonNull(condition, "condition");
        Objects.requireNonNull(whenTrue, "whenTrue");
        server.run(List.of("if-shell", "--", condition, whenTrue));
    }

    /**
     * Runs one tmux command or another, according to whether a shell command succeeds.
     *
     * @param whenFalse the tmux command to run when the condition does not succeed
     */
    @Operation(Kind.MUTATION)
    public void choose(String condition, String whenTrue, String whenFalse) {
        Objects.requireNonNull(condition, "condition");
        Objects.requireNonNull(whenTrue, "whenTrue");
        Objects.requireNonNull(whenFalse, "whenFalse");
        server.run(List.of("if-shell", "--", condition, whenTrue, whenFalse));
    }
}

package io.github.libtmux.snapshot;

import io.github.libtmux.SessionId;
import java.util.Optional;

/**
 * A client as one capture saw it.
 *
 * @param name the client's terminal name, which is how tmux addresses it
 * @param session the session it was attached to, if any
 */
public record ClientState(String name, Optional<SessionId> session) {}

package io.github.libtmux.snapshot;

import io.github.libtmux.Server;
import io.github.libtmux.Session;
import io.github.libtmux.SessionId;
import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import io.github.libtmux.control.ControlClient;
import io.github.libtmux.control.ControlEvent;
import io.github.libtmux.control.Delivery;
import io.github.libtmux.control.EventSubscription;
import io.github.libtmux.exception.TargetGoneException;
import java.time.Duration;
import java.util.Objects;
import java.util.Optional;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;
import org.jspecify.annotations.Nullable;

/**
 * A live copy of one tmux server's sessions, windows, panes and clients, rebuilt whenever tmux
 * announces a change.
 *
 * <p>A control client attached through an anchor session hears what tmux announces. Any
 * announcement, or a {@link Delivery.Gap} in them, starts a fresh {@link Server#snapshot()} — never
 * a patch of the last one, since an announcement says that something changed, not everything that
 * did. Announcements that arrive while a snapshot is being taken collapse into one more rebuild, and
 * a rebuild that finds nothing different publishes nothing. Each published {@link View} carries an
 * epoch one above the last, counted by this mirror; it is not a number tmux keeps.
 *
 * <p>tmux keeps no history of what it announced. When the control client ends, the mirror finds
 * the anchor session again by its id and attaches through it with a fresh snapshot; if the session
 * has gone, the mirror ends with {@link TargetGoneException}, and if the server has, with the
 * failure that said so. A change tmux does not announce to this client, such as a pane retitled in
 * another session, is seen at the next rebuild, or within {@code refreshEvery} when one is given.
 *
 * <p>Thread-safe. One virtual thread per mirror listens and rebuilds; {@link #close()} ends it and
 * the control client with it.
 */
public final class ServerMirror implements AutoCloseable {

    /**
     * One published state of the server.
     *
     * @param epoch how many views this mirror published before this one
     * @param snapshot the server as the rebuild captured it
     */
    public record View(long epoch, ServerSnapshot snapshot) {
        public View {
            Objects.requireNonNull(snapshot, "snapshot");
        }
    }

    private static final int EVENTS = 256;

    private final Server server;
    private final SessionId anchor;
    private final Duration refreshEvery;
    private final ReentrantLock lock = new ReentrantLock();
    private final Condition published = lock.newCondition();
    private final Thread listener;

    // Guarded by lock.
    private View view;
    private boolean ended;
    private @Nullable Throwable cause;
    private @Nullable Runnable waiter;
    private long waiterEpoch;

    // Owned by the listener thread, and by close() once it has stopped the listener.
    private @Nullable ControlClient control;
    private @Nullable EventSubscription<ControlEvent> events;
    private volatile boolean closing;

    private ServerMirror(Session anchor, Duration refreshEvery) {
        this.server = anchor.server();
        this.anchor = anchor.id();
        this.refreshEvery = refreshEvery;
        attach(anchor);
        try {
            this.view = new View(0, server.snapshot());
        } catch (RuntimeException failure) {
            detach();
            throw failure;
        }
        this.listener = Thread.ofVirtual().name("libtmux-mirror").unstarted(this::listen);
    }

    /**
     * Mirrors the server {@code anchor} belongs to, listening through a control client attached to
     * {@code anchor}.
     *
     * @throws TargetGoneException if the anchor session or its server has gone
     */
    @Operation(Kind.LIFECYCLE)
    public static ServerMirror open(Session anchor) {
        return open(anchor, Duration.ZERO);
    }

    /**
     * As {@link #open(Session)}, also rebuilding when nothing has been announced for {@code
     * refreshEvery}, so a change tmux does not announce to this client is seen within that long.
     *
     * @param refreshEvery how long a quiet mirror waits before rebuilding anyway; zero never does
     * @throws IllegalArgumentException if {@code refreshEvery} is negative
     */
    @Operation(Kind.LIFECYCLE)
    public static ServerMirror open(Session anchor, Duration refreshEvery) {
        Objects.requireNonNull(anchor, "anchor");
        Objects.requireNonNull(refreshEvery, "refreshEvery");
        if (refreshEvery.isNegative()) {
            throw new IllegalArgumentException("refreshEvery is negative: " + refreshEvery);
        }
        ServerMirror mirror = new ServerMirror(anchor, refreshEvery);
        mirror.listener.start();
        return mirror;
    }

    /** The latest published view. */
    @Operation(Kind.CAPTURED)
    public View current() {
        lock.lock();
        try {
            return view;
        } finally {
            lock.unlock();
        }
    }

    /**
     * Waits for a view newer than {@code epoch}.
     *
     * @return the newer view, or empty when {@code timeout} passed first or the mirror ended; {@link
     *     #isEnded()} and {@link #cause()} tell those apart
     * @throws InterruptedException if the waiting thread is interrupted
     */
    @Operation(Kind.WAIT)
    public Optional<View> awaitNewer(long epoch, Duration timeout) throws InterruptedException {
        long remaining = timeout.isNegative() ? 0 : nanos(timeout);
        lock.lockInterruptibly();
        try {
            while (view.epoch() <= epoch && !ended && remaining > 0) {
                remaining = published.awaitNanos(remaining);
            }
            return view.epoch() > epoch ? Optional.of(view) : Optional.empty();
        } finally {
            lock.unlock();
        }
    }

    /**
     * Arms a one-shot wakeup for when a view newer than {@code epoch} is published or the mirror ends.
     *
     * <p>Runs {@code callback} at once, on this thread, when such a view already exists or the mirror
     * has ended; otherwise once, on the mirror's own thread. The callback must not block.
     *
     * @throws IllegalStateException if a callback is already armed
     */
    @Operation(Kind.CAPTURED)
    public void onNewer(long epoch, Runnable callback) {
        Objects.requireNonNull(callback, "callback");
        boolean now;
        lock.lock();
        try {
            if (waiter != null) {
                throw new IllegalStateException("a callback is already armed; clearNewer() first");
            }
            now = view.epoch() > epoch || ended;
            if (!now) {
                waiter = callback;
                waiterEpoch = epoch;
            }
        } finally {
            lock.unlock();
        }
        if (now) {
            callback.run();
        }
    }

    /** Disarms the callback {@link #onNewer} armed, if one is armed. */
    @Operation(Kind.CAPTURED)
    public void clearNewer() {
        lock.lock();
        try {
            waiter = null;
        } finally {
            lock.unlock();
        }
    }

    /** Whether this mirror has stopped publishing, because it was closed or its anchor has gone. */
    @Operation(Kind.CAPTURED)
    public boolean isEnded() {
        lock.lock();
        try {
            return ended;
        } finally {
            lock.unlock();
        }
    }

    /** Why this mirror ended, when something other than {@link #close()} ended it. */
    @Operation(Kind.CAPTURED)
    public Optional<Throwable> cause() {
        lock.lock();
        try {
            return Optional.ofNullable(cause);
        } finally {
            lock.unlock();
        }
    }

    /** Stops listening and detaches the control client. The last view stays readable. Idempotent. */
    @Override
    @Operation(Kind.LIFECYCLE)
    public void close() {
        closing = true;
        listener.interrupt();
        try {
            listener.join(TimeUnit.SECONDS.toMillis(10));
        } catch (InterruptedException interrupted) {
            Thread.currentThread().interrupt();
        }
        detach();
        end(null);
    }

    private void listen() {
        try {
            while (!closing) {
                EventSubscription<ControlEvent> heard = Objects.requireNonNull(events);
                Optional<Delivery<ControlEvent>> step = refreshEvery.isZero() ? heard.next() : heard.next(refreshEvery);
                if (closing) {
                    return;
                }
                if (step.isEmpty() && heard.isClosed()) {
                    reattach();
                    continue;
                }
                // What else is already waiting is covered by the same rebuild.
                while (heard.poll().isPresent()) {}
                publish(server.snapshot());
            }
        } catch (InterruptedException stopped) {
            Thread.currentThread().interrupt();
        } catch (RuntimeException failure) {
            if (!closing) {
                detach();
                end(failure);
            }
        }
    }

    /** The control client ended; tmux has forgotten what it announced, so start from a new capture. */
    private void reattach() {
        detach();
        Session session = server.session(anchor)
                .orElseThrow(() -> new TargetGoneException(
                        "session " + anchor.value() + ", which this mirror listened through, has gone"));
        attach(session);
        publish(server.snapshot());
    }

    private void attach(Session session) {
        ControlClient attached = server.control(session);
        try {
            events = attached.subscribeEvents(EVENTS);
        } catch (RuntimeException failure) {
            attached.close();
            throw failure;
        }
        control = attached;
    }

    private void detach() {
        EventSubscription<ControlEvent> heard = events;
        if (heard != null) {
            heard.close();
        }
        ControlClient attached = control;
        if (attached != null) {
            attached.close();
        }
    }

    private void publish(ServerSnapshot fresh) {
        @Nullable Runnable wake = null;
        lock.lock();
        try {
            if (ended || sameState(view.snapshot(), fresh)) {
                return;
            }
            view = new View(view.epoch() + 1, fresh);
            published.signalAll();
            if (waiter != null && view.epoch() > waiterEpoch) {
                wake = waiter;
                waiter = null;
            }
        } finally {
            lock.unlock();
        }
        if (wake != null) {
            wake.run();
        }
    }

    private void end(@Nullable Throwable failure) {
        @Nullable Runnable wake;
        lock.lock();
        try {
            if (ended) {
                return;
            }
            ended = true;
            cause = failure;
            published.signalAll();
            wake = waiter;
            waiter = null;
        } finally {
            lock.unlock();
        }
        if (wake != null) {
            wake.run();
        }
    }

    /** The same server state, whenever it was captured. */
    private static boolean sameState(ServerSnapshot before, ServerSnapshot after) {
        return before.sessions().equals(after.sessions())
                && before.windows().equals(after.windows())
                && before.panes().equals(after.panes())
                && before.clients().equals(after.clients())
                && before.serverPid().equals(after.serverPid())
                && before.serverStartTime().equals(after.serverStartTime());
    }

    private static long nanos(Duration timeout) {
        try {
            return timeout.toNanos();
        } catch (ArithmeticException overflow) {
            return Long.MAX_VALUE;
        }
    }
}

package io.github.libtmux.snapshot;

import io.github.libtmux.PaneId;
import io.github.libtmux.SessionId;
import io.github.libtmux.TmuxVersion;
import io.github.libtmux.WindowId;
import io.github.libtmux.WindowIndex;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.OptionalLong;
import java.util.function.Function;
import kotlin.annotations.jvm.ReadOnly;

/**
 * One tmux hierarchy, as it was at one moment.
 *
 * <p>Every question below is answered from what was captured, so traversing a snapshot issues no
 * commands and cannot observe a half-changed server. It claims a moment rather than current truth:
 * tmux offers no transaction across separate listings, and pretending otherwise would be a promise
 * this cannot keep.
 */
public final class ServerSnapshot {

    private final Instant capturedAt;
    private final OptionalLong serverPid;
    private final OptionalLong serverStartTime;
    private final Optional<TmuxVersion> serverVersion;
    private final List<SessionState> sessions;
    private final List<WindowState> windows;
    private final List<PaneState> panes;
    private final List<ClientState> clients;

    private final Map<SessionId, SessionState> sessionsById;
    private final Map<SessionId, List<WindowState>> windowsBySession;
    private final Map<WindowContext, WindowState> windowsByContext;
    private final Map<WindowContext, List<PaneState>> panesByContext;

    private ServerSnapshot(
            Instant capturedAt,
            OptionalLong serverPid,
            OptionalLong serverStartTime,
            Optional<TmuxVersion> serverVersion,
            List<SessionState> sessions,
            List<WindowState> windows,
            List<PaneState> panes,
            List<ClientState> clients) {
        this.capturedAt = capturedAt;
        this.serverPid = serverPid;
        this.serverStartTime = serverStartTime;
        this.serverVersion = serverVersion;
        this.sessions = sessions;
        this.windows = windows;
        this.panes = panes;
        this.clients = clients;

        this.sessionsById = unique(sessions, SessionState::id, "session");
        this.windowsBySession = group(windows, window -> window.context().session());
        this.windowsByContext = unique(windows, WindowState::context, "window context");
        unique(
                windows,
                window -> new WindowSlot(
                        window.context().session(), window.context().index()),
                "window slot");
        this.panesByContext = group(panes, PaneState::context);
        unique(panes, pane -> new PaneKey(pane.context(), pane.id()), "pane context");
        unique(panes, pane -> new PaneSlot(pane.context(), pane.index()), "pane slot");
        requirePaneOwnership(panes);
    }

    /**
     * Assembles a capture with no server identity, checking that the listings agree with each other.
     *
     * <p>Package-private: a handle built from an identity-less snapshot fails the moment it tries to
     * act, so nothing in production can use one. The only caller is this package's own consistency
     * tests, which do not need an identity to check that a hierarchy is internally coherent.
     *
     * @throws IllegalArgumentException if the listings contain duplicate identities or disagree on
     *     the captured hierarchy
     */
    static ServerSnapshot of(
            Instant capturedAt,
            List<SessionState> sessions,
            List<WindowState> windows,
            List<PaneState> panes,
            List<ClientState> clients) {
        return of(
                capturedAt,
                OptionalLong.empty(),
                OptionalLong.empty(),
                Optional.empty(),
                sessions,
                windows,
                panes,
                clients);
    }

    /**
     * Assembles a capture tied to the live tmux process and version that produced it, with no start
     * time: a handle made from it is fenced by the process id alone.
     */
    public static ServerSnapshot of(
            Instant capturedAt,
            long serverPid,
            TmuxVersion serverVersion,
            List<SessionState> sessions,
            List<WindowState> windows,
            List<PaneState> panes,
            List<ClientState> clients) {
        return of(capturedAt, serverPid, OptionalLong.empty(), serverVersion, sessions, windows, panes, clients);
    }

    /**
     * Assembles a capture tied to the live tmux process that produced it: its id, when it started,
     * and its version. A process id can be reused; the pair with the start time names one server.
     */
    public static ServerSnapshot of(
            Instant capturedAt,
            long serverPid,
            long serverStartTime,
            TmuxVersion serverVersion,
            List<SessionState> sessions,
            List<WindowState> windows,
            List<PaneState> panes,
            List<ClientState> clients) {
        if (serverStartTime < 0) {
            throw new IllegalArgumentException("serverStartTime is negative: " + serverStartTime);
        }
        return of(
                capturedAt,
                serverPid,
                OptionalLong.of(serverStartTime),
                serverVersion,
                sessions,
                windows,
                panes,
                clients);
    }

    private static ServerSnapshot of(
            Instant capturedAt,
            long serverPid,
            OptionalLong serverStartTime,
            TmuxVersion serverVersion,
            List<SessionState> sessions,
            List<WindowState> windows,
            List<PaneState> panes,
            List<ClientState> clients) {
        if (serverPid < 1) {
            throw new IllegalArgumentException("serverPid is not positive: " + serverPid);
        }
        return of(
                capturedAt,
                OptionalLong.of(serverPid),
                serverStartTime,
                Optional.of(Objects.requireNonNull(serverVersion, "serverVersion")),
                sessions,
                windows,
                panes,
                clients);
    }

    private static ServerSnapshot of(
            Instant capturedAt,
            OptionalLong serverPid,
            OptionalLong serverStartTime,
            Optional<TmuxVersion> serverVersion,
            List<SessionState> sessions,
            List<WindowState> windows,
            List<PaneState> panes,
            List<ClientState> clients) {
        Objects.requireNonNull(capturedAt, "capturedAt");
        ServerSnapshot snapshot = new ServerSnapshot(
                capturedAt,
                serverPid,
                serverStartTime,
                serverVersion,
                List.copyOf(sessions),
                List.copyOf(windows),
                List.copyOf(panes),
                List.copyOf(clients));
        snapshot.requireClosed();
        return snapshot;
    }

    /**
     * Rejects a capture whose listings do not describe one hierarchy.
     *
     * <p>Each refusal names what was orphaned and what it wanted, because this fires on a race
     * between four listings and the ids are the only way to tell which listing was the stale one.
     */
    private void requireClosed() {
        for (PaneState pane : panes) {
            if (!windowsByContext.containsKey(pane.context())) {
                throw new IllegalArgumentException("pane %s was captured under window %s, which no listing saw"
                        .formatted(pane.id(), pane.context().window()));
            }
        }
        for (WindowState window : windows) {
            if (!sessionsById.containsKey(window.context().session())) {
                throw new IllegalArgumentException("window %s was captured under session %s, which no listing saw"
                        .formatted(window.context().window(), window.context().session()));
            }
            int capturedPanes =
                    panesByContext.getOrDefault(window.context(), List.of()).size();
            if (window.panes() != capturedPanes) {
                throw new IllegalArgumentException("window %s reported %d panes but the listing captured %d"
                        .formatted(window.context().window(), window.panes(), capturedPanes));
            }
        }
        for (SessionState session : sessions) {
            int capturedWindows =
                    windowsBySession.getOrDefault(session.id(), List.of()).size();
            if (session.windows() != capturedWindows) {
                throw new IllegalArgumentException("session %s reported %d windows but the listing captured %d"
                        .formatted(session.id(), session.windows(), capturedWindows));
            }
        }
        for (ClientState client : clients) {
            client.session().ifPresent(session -> {
                if (!sessionsById.containsKey(session)) {
                    throw new IllegalArgumentException("client %s was captured under session %s, which no listing saw"
                            .formatted(client.name(), session));
                }
            });
        }
    }

    /** When this capture was taken. */
    public Instant capturedAt() {
        return capturedAt;
    }

    /** The tmux process that produced this capture, absent when assembled from detached state. */
    public OptionalLong serverPid() {
        return serverPid;
    }

    /**
     * When the tmux process that produced this capture started, in seconds since the epoch, as
     * {@code #{start_time}} reports it. Absent when the capture was assembled without it.
     */
    public OptionalLong serverStartTime() {
        return serverStartTime;
    }

    /** The tmux version that produced this capture, absent when assembled from detached state. */
    public Optional<TmuxVersion> serverVersion() {
        return serverVersion;
    }

    /** Every session, in tmux's order. */
    @ReadOnly
    public List<SessionState> sessions() {
        return sessions;
    }

    /** Every winlink, in tmux's order, including a window linked into more than one session twice. */
    @ReadOnly
    public List<WindowState> windows() {
        return windows;
    }

    /** Every pane, in tmux's order. */
    @ReadOnly
    public List<PaneState> panes() {
        return panes;
    }

    /** Every attached client. */
    @ReadOnly
    public List<ClientState> clients() {
        return clients;
    }

    /** The session with this id, if the capture saw it. */
    public Optional<SessionState> session(SessionId id) {
        return Optional.ofNullable(sessionsById.get(id));
    }

    /** The first session with this name, if the capture saw one. */
    public Optional<SessionState> session(String name) {
        return sessions.stream().filter(session -> session.name().equals(name)).findFirst();
    }

    /** The winlink at this exact position, if the capture saw it. */
    public Optional<WindowState> window(WindowContext context) {
        return Optional.ofNullable(windowsByContext.get(context));
    }

    /** The winlinks in one session, in order. Empty when the capture never saw that session. */
    @ReadOnly
    public List<WindowState> windowsOf(SessionId session) {
        return windowsBySession.getOrDefault(session, List.of());
    }

    /** The panes under one winlink, in order. Empty when the capture never saw that winlink. */
    @ReadOnly
    public List<PaneState> panesOf(WindowContext context) {
        return panesByContext.getOrDefault(context, List.of());
    }

    @Override
    public String toString() {
        return "ServerSnapshot[capturedAt=" + capturedAt + ", serverPid=" + serverPid + ", sessions="
                + sessions.size() + ", windows=" + windows.size() + ", panes=" + panes.size() + ", clients="
                + clients.size() + "]";
    }

    private static <K, V> Map<K, List<V>> group(List<V> values, Function<V, K> key) {
        Map<K, List<V>> grouped = new LinkedHashMap<>();
        for (V value : values) {
            grouped.computeIfAbsent(key.apply(value), _ -> new ArrayList<>()).add(value);
        }
        grouped.replaceAll((_, group) -> Collections.unmodifiableList(group));
        return Collections.unmodifiableMap(grouped);
    }

    private static <K, V> Map<K, V> unique(List<V> values, Function<V, K> key, String kind) {
        Map<K, V> indexed = new LinkedHashMap<>();
        for (V value : values) {
            K identity = key.apply(value);
            if (indexed.putIfAbsent(identity, value) != null) {
                throw new IllegalArgumentException("duplicate " + kind + " '" + identity + "'");
            }
        }
        return Collections.unmodifiableMap(indexed);
    }

    private static void requirePaneOwnership(List<PaneState> panes) {
        Map<PaneId, WindowId> windows = new LinkedHashMap<>();
        for (PaneState pane : panes) {
            WindowId window = pane.context().window();
            WindowId previous = windows.putIfAbsent(pane.id(), window);
            if (previous != null && !previous.equals(window)) {
                throw new IllegalArgumentException(
                        "pane %s was captured under both window %s and %s".formatted(pane.id(), previous, window));
            }
        }
    }

    private record PaneKey(WindowContext context, PaneId id) {}

    private record PaneSlot(WindowContext context, int index) {}

    private record WindowSlot(SessionId session, WindowIndex index) {}
}

package io.github.libtmux.snapshot;

import io.github.libtmux.SessionId;

/**
 * A session as one capture saw it.
 *
 * @param id the session's stable id
 * @param name the session name, which a user may change at any time
 * @param attached whether a client was attached to it
 * @param windows how many windows it contained
 */
public record SessionState(SessionId id, String name, boolean attached, int windows) {}

package io.github.libtmux.snapshot;

import io.github.libtmux.SessionId;
import io.github.libtmux.WindowId;
import io.github.libtmux.WindowIndex;

/**
 * One tmux winlink: a window as it appears in one session, at one index.
 *
 * <p>The unit relations are keyed on. A window linked into two sessions has one {@link WindowId}
 * and two contexts, and tmux treats those two positions as distinct.
 *
 * @param session the session this link belongs to
 * @param index where the window sits in that session
 * @param window the underlying window, shared across links
 */
public record WindowContext(SessionId session, WindowIndex index, WindowId window) {}

package io.github.libtmux;

import io.github.libtmux.batch.Batch;
import io.github.libtmux.batch.OperationOutcome;
import io.github.libtmux.batch.OperationResult;
import io.github.libtmux.exception.MalformedResponseException;
import io.github.libtmux.exception.ServerUnavailableException;
import io.github.libtmux.exception.TargetGoneException;
import io.github.libtmux.format.RowFormat;
import io.github.libtmux.query.TmuxFilters;
import io.github.libtmux.snapshot.ClientState;
import io.github.libtmux.snapshot.PaneState;
import io.github.libtmux.snapshot.ServerSnapshot;
import io.github.libtmux.snapshot.SessionState;
import io.github.libtmux.snapshot.WindowContext;
import io.github.libtmux.snapshot.WindowState;
import io.github.libtmux.transport.CommandResult;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.OptionalLong;
import java.util.function.Predicate;

/**
 * Reads a whole tmux server into one snapshot.
 *
 * <p>One server-wide listing per kind of object, so ordering and membership stay tmux's decision
 * rather than being re-derived from another listing's rows.
 *
 * <p>Two commands: who the server is, then the listings as one group fenced against both halves of
 * that answer, its pid and its version. tmux runs a group in the server, so rows cannot come from
 * two of them, and a server that is not the one probed is refused before a listing runs rather than
 * detected afterwards. Retrying is {@link Server#snapshot()}'s decision, not this one's.
 */
final class SnapshotCapture {

    private static final RowFormat SESSIONS =
            RowFormat.of("session_id", "session_name", "session_attached", "session_windows");
    private static final RowFormat WINDOWS = RowFormat.of(
            "session_id",
            "window_id",
            "window_index",
            "window_name",
            "window_active",
            "window_panes",
            "window_linked",
            "window_width",
            "window_height",
            "window_layout");
    private static final String[] PANE_FIELDS = {
        "session_id",
        "window_id",
        "window_index",
        "pane_id",
        "pane_index",
        "pane_active",
        "pane_current_command",
        "pane_width",
        "pane_height",
        "pane_left",
        "pane_top",
        "pane_title",
        "pane_current_path",
        "pane_pid",
        "pane_at_top",
        "pane_at_bottom",
        "pane_at_left",
        "pane_at_right"
    };

    private static final RowFormat PANES = RowFormat.of(PANE_FIELDS);

    /**
     * tmux gained {@code pane_floating_flag} at {@code 87aaff5f} ("Bring some new formats from the
     * floating panes work"), which {@code git tag --contains} places on 3.7 and nothing earlier;
     * before that the format expands to nothing, indistinguishable from a real pane answering false.
     * Not probeable: an unknown format variable and a false one both expand empty, and {@link
     * Commands#list} lists commands, not the format variables a running tmux understands.
     */
    private static final TmuxVersion FLOATING_SINCE = new TmuxVersion(3, 7, "");

    private static final String FLOATING = "pane_floating_flag";

    private static final RowFormat PANES_WITH_FLOATING = RowFormat.of(withFloating());

    private static final RowFormat CLIENTS = RowFormat.of("client_name", "session_id");
    private static final RowFormat PROCESS = RowFormat.of("pid", "version", "start_time");

    private final Server server;

    SnapshotCapture(Server server) {
        this.server = server;
    }

    /** One attempt, empty when the server was replaced under it. */
    Optional<ServerSnapshot> attempt() {
        ServerProcess process = process()
                .orElseThrow(() -> new ServerUnavailableException("no tmux server is answering on this endpoint"));
        try {
            return Optional.of(capture(process));
        } catch (TargetGoneException replaced) {
            // The fence answered: this is no longer the server the identity came from.
            return Optional.empty();
        } catch (RuntimeException failure) {
            Optional<ServerProcess> current;
            try {
                current = process();
            } catch (RuntimeException probeFailure) {
                probeFailure.addSuppressed(failure);
                throw probeFailure;
            }
            if (Optional.of(process).equals(current)) {
                throw failure;
            }
            return Optional.empty();
        }
    }

    /** Reads process identity and version together so neither can come from a different server. */
    Optional<ServerProcess> process() {
        return identity(Server::serverAbsent);
    }

    /**
     * As {@link #process}, except a live daemon this client cannot actually talk to is never folded
     * into "no daemon" - used only by {@link SessionCreation#versionForCreation}, the one caller for which
     * that distinction matters.
     *
     * <p>tmux reports both the same way from a client's side: "no server running"/"(No such file or
     * directory)" for a socket nothing is listening on, and "server exited unexpectedly" for a
     * daemon that refused this client's handshake - confirmed against the matrix, a 3.2a client
     * against a 3.7c daemon on the same socket fails the second way, rc 1. {@link #process} still
     * folds both into "no daemon" for every other caller, which asks "is there a server I can read
     * from" and for which a daemon this client cannot use is no more usable than none at all.
     */
    Optional<ServerProcess> processForCreation() {
        return identity(SnapshotCapture::daemonGenuinelyAbsent);
    }

    private Optional<ServerProcess> identity(Predicate<String> absent) {
        CommandResult result = server.cmd("display-message", "-p", PROCESS.template());
        if (!result.succeeded()) {
            if (result.stderr().stream().anyMatch(absent)) {
                return Optional.empty();
            }
            throw server.failed("display-message", result);
        }
        List<RowFormat.Row> reported = PROCESS.rows(result.stdout());
        if (reported.isEmpty()) {
            throw new MalformedResponseException(
                    server.config().binary() + " exited 0 and reported nothing for tmux's own identity; is it tmux?");
        }
        if (reported.size() != 1) {
            throw new MalformedResponseException("tmux did not report exactly one server identity row: " + reported);
        }
        RowFormat.Row row = reported.get(0);
        long pid = row.count("pid");
        if (pid <= 0) {
            throw new MalformedResponseException("tmux reported a malformed server pid: " + pid);
        }
        String version = row.text("version");
        long started = row.count("start_time");
        if (started < 0) {
            throw new MalformedResponseException("tmux reported a malformed server start time: " + started);
        }
        return Optional.of(new ServerProcess(pid, TmuxVersion.parse(version), started));
    }

    private static boolean daemonGenuinelyAbsent(String message) {
        return message.contains("no server running") || message.contains("(No such file or directory)");
    }

    /** The whole hierarchy in one invocation, fenced against the identity just read. */
    private ServerSnapshot capture(ServerProcess process) {
        boolean floatingKnown = process.version().atLeast(FLOATING_SINCE);
        RowFormat paneFormat = floatingKnown ? PANES_WITH_FLOATING : PANES;
        Batch listings = server.batch(process.pid(), process.startTime());
        listings.add(listing(SESSIONS, "list-sessions"));
        listings.add(listing(WINDOWS, "list-windows", "-a"));
        listings.add(listing(paneFormat, "list-panes", "-a"));
        listings.add(listing(CLIENTS, "list-clients"));
        List<OperationResult> answered = listings.run().operations();

        return consistent(() -> {
            List<SessionState> sessions =
                    sessionStates(rows(SESSIONS, answered.get(0), "list-sessions", process.version()));
            if (sessions.isEmpty()) {
                // A server with no sessions has no current target, so tmux refuses the rest of the
                // group. An empty sessions listing is the whole hierarchy, so there is nothing to read.
                return snapshotOf(process, sessions, List.of(), List.of(), List.of());
            }
            return snapshotOf(
                    process,
                    sessions,
                    windowStates(rows(WINDOWS, answered.get(1), "list-windows", process.version())),
                    paneStates(rows(paneFormat, answered.get(2), "list-panes", process.version()), floatingKnown),
                    clientStates(rows(CLIENTS, answered.get(3), "list-clients", process.version())));
        });
    }

    /**
     * Rows that parse but do not form one valid snapshot are tmux's failure. Only this conversion is
     * made: anything else thrown while reading is reported as itself.
     */
    private static <T> T consistent(java.util.function.Supplier<T> assembly) {
        try {
            return assembly.get();
        } catch (IllegalArgumentException inconsistent) {
            throw new MalformedResponseException(
                    "tmux returned listings that do not form one snapshot: " + inconsistent.getMessage(), inconsistent);
        }
    }

    /**
     * One session, its windows, and its panes. Empty when that session is absent. Other sessions are
     * not read.
     *
     * @param target the session name or id passed to {@code -t}
     * @param field {@code session_name} or {@code session_id}
     */
    Optional<ServerSnapshot> oneSession(String target, String field) {
        ServerProcess process = process()
                .orElseThrow(() -> new ServerUnavailableException("no tmux server is answering on this endpoint"));
        return hydrate(
                process,
                "#{==:#{" + field + "}," + target + "}",
                session -> field.equals("session_id")
                        ? session.id().value().equals(target)
                        : session.name().equals(target));
    }

    /**
     * The sessions stored under any name tmux may keep for this one, read in one fenced call, and
     * an empty capture when there are none. Empty when a candidate cannot sit inside a format, and
     * the caller reads the whole server instead.
     */
    Optional<ServerSnapshot> sessionsNamed(String name) {
        ServerProcess process = process()
                .orElseThrow(() -> new ServerUnavailableException("no tmux server is answering on this endpoint"));
        List<String> names = TmuxFormats.storedNames(name, process.version());
        if (!names.stream().allMatch(TmuxFilters::literal)) {
            return Optional.empty();
        }
        String any = "0";
        for (String stored : names) {
            any = "#{||:#{==:#{session_name}," + stored + "}," + any + "}";
        }
        return Optional.of(hydrate(process, any, session -> names.contains(session.name()))
                .orElseGet(() -> snapshotOf(process, List.of(), List.of(), List.of(), List.of())));
    }

    /**
     * The sessions holding a row that {@code format} selects in this listing, read in full in one
     * fenced call, and a capture holding nothing when none does.
     *
     * <p>Nothing is a real answer: every operator {@link io.github.libtmux.query.TmuxFilters} writes
     * exists from the oldest supported tmux, so a format it lowers is never one tmux cannot evaluate.
     * A window or pane format is lifted to its session by looping that session's windows and panes,
     * so the one call that reads the sessions also decides which ones to read.
     *
     * @param command {@code list-sessions}, {@code list-windows -a}, or {@code list-panes -a}
     */
    ServerSnapshot sessionsWhere(String format, String... command) {
        ServerProcess process = process()
                .orElseThrow(() -> new ServerUnavailableException("no tmux server is answering on this endpoint"));
        String holding =
                switch (command[0]) {
                    case "list-sessions" -> format;
                    case "list-windows" -> "#{W:#{?" + format + ",1,}}";
                    case "list-panes" -> "#{W:#{P:#{?" + format + ",1,}}}";
                    default -> throw new IllegalArgumentException("not a hierarchy listing: " + command[0]);
                };
        return hydrate(process, holding, session -> true)
                .orElseGet(() -> snapshotOf(process, List.of(), List.of(), List.of(), List.of()));
    }

    /**
     * The sessions this filter selects, with their windows and panes, in one call fenced to {@code
     * process}. Every row tmux returns is validated before {@code keep} narrows them, so a malformed
     * or inconsistent row fails the read instead of hiding behind a miss.
     */
    private Optional<ServerSnapshot> hydrate(
            ServerProcess process, String filter, java.util.function.Predicate<SessionState> keep) {
        boolean floatingKnown = process.version().atLeast(FLOATING_SINCE);
        RowFormat paneFormat = floatingKnown ? PANES_WITH_FLOATING : PANES;
        Batch batch = server.batch(process.pid(), process.startTime());
        batch.add(listing(SESSIONS, "list-sessions", "-f", filter));
        batch.add(listing(WINDOWS, "list-windows", "-a", "-f", filter));
        batch.add(listing(paneFormat, "list-panes", "-a", "-f", filter));
        List<OperationResult> answered = batch.run().operations();
        return consistent(() -> kept(process, answered, paneFormat, floatingKnown, keep));
    }

    private Optional<ServerSnapshot> kept(
            ServerProcess process,
            List<OperationResult> answered,
            RowFormat paneFormat,
            boolean floatingKnown,
            java.util.function.Predicate<SessionState> keep) {
        List<SessionState> listed = sessionStates(rows(SESSIONS, answered.get(0), "list-sessions", process.version()));
        if (listed.isEmpty()) {
            // As in a full capture: with no session there is no current target, and tmux refuses
            // the rest of the group.
            return Optional.empty();
        }
        List<WindowState> windows = windowStates(rows(WINDOWS, answered.get(1), "list-windows", process.version()));
        List<PaneState> panes =
                paneStates(rows(paneFormat, answered.get(2), "list-panes", process.version()), floatingKnown);
        snapshotOf(process, listed, windows, panes, List.of());
        List<SessionState> sessions = listed.stream().filter(keep).toList();
        if (sessions.isEmpty()) {
            return Optional.empty();
        }
        java.util.Set<SessionId> ids =
                sessions.stream().map(SessionState::id).collect(java.util.stream.Collectors.toSet());
        return Optional.of(snapshotOf(
                process,
                sessions,
                windows.stream()
                        .filter(window -> ids.contains(window.context().session()))
                        .toList(),
                panes.stream()
                        .filter(pane -> ids.contains(pane.context().session()))
                        .toList(),
                List.of()));
    }

    /**
     * The sessions holding this pane, with their windows and panes, in one fenced call. Empty when no
     * session holds it.
     *
     * <p>The filter loops each listed row's own session, so every listing keeps whole sessions, and a
     * window linked into two sessions brings both. tmux evaluates this loop inside {@code -f} the same
     * way on every release from 3.2a; see {@code docs/decisions/0005-pushdown-lowering-is-exact-or-refused.md}.
     */
    Optional<ServerSnapshot> sessionsHolding(PaneId id) {
        ServerProcess process = process()
                .orElseThrow(() -> new ServerUnavailableException("no tmux server is answering on this endpoint"));
        return hydrate(process, "#{W:#{P:#{?#{==:#{pane_id}," + id.value() + "},1,}}}", session -> true);
    }

    private static List<SessionState> sessionStates(List<RowFormat.Row> rows) {
        List<SessionState> sessions = new ArrayList<>();
        for (RowFormat.Row row : rows) {
            sessions.add(new SessionState(
                    new SessionId(row.text("session_id")),
                    row.text("session_name"),
                    row.count("session_attached") > 0,
                    row.number("session_windows")));
        }
        return sessions;
    }

    private static List<WindowState> windowStates(List<RowFormat.Row> rows) {
        List<WindowState> windows = new ArrayList<>();
        for (RowFormat.Row row : rows) {
            windows.add(new WindowState(
                    context(row),
                    row.text("window_name"),
                    row.flag("window_active"),
                    row.number("window_panes"),
                    row.flag("window_linked"),
                    new Dimensions(row.number("window_width"), row.number("window_height")),
                    row.text("window_layout")));
        }
        return windows;
    }

    private static List<PaneState> paneStates(List<RowFormat.Row> rows, boolean floatingKnown) {
        List<PaneState> panes = new ArrayList<>();
        for (RowFormat.Row row : rows) {
            panes.add(new PaneState(
                    context(row),
                    new PaneId(row.text("pane_id")),
                    row.number("pane_index"),
                    row.flag("pane_active"),
                    row.text("pane_current_command"),
                    new Dimensions(row.number("pane_width"), row.number("pane_height")),
                    new PanePosition(row.number("pane_left"), row.number("pane_top")),
                    row.text("pane_title"),
                    row.text("pane_current_path"),
                    panePid(row),
                    new PaneEdges(
                            row.flag("pane_at_top"),
                            row.flag("pane_at_bottom"),
                            row.flag("pane_at_left"),
                            row.flag("pane_at_right")),
                    floatingKnown ? Optional.of(row.flag(FLOATING)) : Optional.empty()));
        }
        return panes;
    }

    private static List<ClientState> clientStates(List<RowFormat.Row> rows) {
        List<ClientState> clients = new ArrayList<>();
        for (RowFormat.Row row : rows) {
            String session = row.text("session_id");
            clients.add(new ClientState(
                    row.text("client_name"),
                    session.isEmpty() ? Optional.empty() : Optional.of(new SessionId(session))));
        }
        return clients;
    }

    /**
     * A pane with no process reports {@code pane_pid} as {@code 0} on every released tmux through
     * 3.7c, and as an empty string on the built development tmux this port has no CI lane for. That
     * development tmux reports the same empty string for a pane that ran a real process and then
     * died with {@code remain-on-exit} — the two are indistinguishable from this field alone there;
     * {@link Pane#dead()} is the live read that tells them apart. Either raw form collapses to
     * {@link OptionalLong#empty()} rather than a literal {@code 0}, so a caller cannot mistake the
     * sentinel for a real pid.
     */
    private static OptionalLong panePid(RowFormat.Row row) {
        if (row.text("pane_pid").isEmpty()) {
            return OptionalLong.empty();
        }
        long pid = row.count("pane_pid");
        return pid == 0 ? OptionalLong.empty() : OptionalLong.of(pid);
    }

    private static List<String> listing(RowFormat format, String... command) {
        List<String> argv = new ArrayList<>(command.length + 2);
        argv.addAll(List.of(command));
        argv.add("-F");
        argv.add(format.template());
        return argv;
    }

    /** Reads one listing's rows, insisting tmux actually ran it. */
    private List<RowFormat.Row> rows(RowFormat format, OperationResult operation, String command, TmuxVersion version) {
        if (operation.outcome() != OperationOutcome.COMPLETE) {
            throw server.failed(
                    command, operation.outcome().name().toLowerCase(Locale.ROOT).replace('_', ' '), operation.stderr());
        }
        return format.rows(TmuxFormats.printed(operation.stdout(), version));
    }

    private static WindowContext context(RowFormat.Row row) {
        return new WindowContext(
                new SessionId(row.text("session_id")),
                new WindowIndex(row.number("window_index")),
                new WindowId(row.text("window_id")));
    }

    private static String[] withFloating() {
        String[] fields = Arrays.copyOf(PANE_FIELDS, PANE_FIELDS.length + 1);
        fields[PANE_FIELDS.length] = FLOATING;
        return fields;
    }

    /** The server a capture reads, named by its process and when that process started. */
    record ServerProcess(long pid, TmuxVersion version, long startTime) {}

    private static ServerSnapshot snapshotOf(
            ServerProcess process,
            List<SessionState> sessions,
            List<WindowState> windows,
            List<PaneState> panes,
            List<ClientState> clients) {
        return ServerSnapshot.of(
                Instant.now(),
                process.pid(),
                process.startTime(),
                process.version(),
                sessions,
                windows,
                panes,
                clients);
    }
}

package io.github.libtmux;

import java.util.List;

/**
 * Where a new pane goes relative to the one being split.
 *
 * <p>Separate from {@link Direction}, which moves and grows existing panes with {@code -U -D -L -R}.
 * Splitting speaks a different dialect: an axis, and whether the new pane comes first.
 */
public enum SplitDirection {
    /** Below the target, which is what tmux does when asked for nothing. */
    BELOW("-v", false),
    ABOVE("-v", true),
    RIGHT("-h", false),
    LEFT("-h", true);

    private final String axis;
    private final boolean first;

    SplitDirection(String axis, boolean first) {
        this.axis = axis;
        this.first = first;
    }

    /** The tmux flags that place a pane this way. */
    List<String> flags() {
        return first ? List.of(axis, "-b") : List.of(axis);
    }
}

package io.github.libtmux;

import io.github.libtmux.exception.UnsupportedFeatureException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import kotlin.annotations.jvm.ReadOnly;
import org.jspecify.annotations.Nullable;

/**
 * How a pane should be split.
 *
 * <p>A description rather than an action: it can be built once, named, and applied to as many panes
 * as it suits. Nothing here contacts tmux, so a spec can be assembled on a machine that has none,
 * and the version rules it depends on are checked when it is applied rather than when it is written
 * — the same spec is legal against one server and not another.
 *
 * <p>A builder-built class rather than a record for the reason {@link ServerConfig} gives: a
 * record's canonical constructor is public API, and tmux keeps adding flags to {@code split-window}
 * — six of them in 3.7 alone.
 *
 * <pre>{@code
 * Pane side = pane.split(s -> s.toRight().percent(30));
 *
 * SplitSpec sidebar = SplitSpec.builder().toRight().percent(25).build();
 * left.split(sidebar);
 * right.split(sidebar);
 * }</pre>
 */
public final class SplitSpec {

    /**
     * Every option below was refused by 3.6 and accepted by 3.7 on a real server, and each flag
     * ({@code -k}, {@code -m}, {@code -s}, {@code -S}, {@code -R}) is likewise absent from 3.6's own
     * {@code list-commands} line for split-window and present in 3.7's. Kept as a constant rather
     * than a probe reading that line: {@code -l} is declared to take a value in {@code
     * cmd-split-window.c}'s args spec but still shows up in the generated line's boolean cluster too,
     * so the line is not a grammar a probe can trust without also parsing tmux's own args spec.
     */
    private static final TmuxVersion PANE_EXTRAS_SINCE = new TmuxVersion(3, 7, "");

    private final SplitDirection direction;
    private final @Nullable PaneSize size;
    private final PaneStart start;
    private final @Nullable Path directory;
    private final Map<String, String> environment;
    private final boolean detached;
    private final boolean fullWindow;
    private final boolean zoomed;
    private final boolean keepOnExit;
    private final @Nullable String exitMessage;
    private final @Nullable String style;
    private final @Nullable String activeBorderStyle;
    private final @Nullable String inactiveBorderStyle;

    private SplitSpec(Builder builder) {
        this.direction = builder.direction;
        this.size = builder.size;
        this.start = builder.start;
        this.directory = builder.directory;
        this.environment = Collections.unmodifiableMap(new LinkedHashMap<>(builder.environment));
        this.detached = builder.detached;
        this.fullWindow = builder.fullWindow;
        this.zoomed = builder.zoomed;
        this.keepOnExit = builder.keepOnExit;
        this.exitMessage = builder.exitMessage;
        this.style = builder.style;
        this.activeBorderStyle = builder.activeBorderStyle;
        this.inactiveBorderStyle = builder.inactiveBorderStyle;
    }

    /** A builder holding tmux's own defaults: below the target, half its size, running a shell. */
    public static Builder builder() {
        return new Builder();
    }

    /** Where the new pane goes. */
    public SplitDirection direction() {
        return direction;
    }

    /** How big the new pane should be, or empty to let tmux halve the target. */
    public Optional<PaneSize> size() {
        return Optional.ofNullable(size);
    }

    /** What runs in the new pane. */
    public PaneStart start() {
        return start;
    }

    /** Where the new pane starts, or empty to inherit. */
    public Optional<Path> directory() {
        return Optional.ofNullable(directory);
    }

    /** Variables set for the new pane, in the order they were given. */
    @ReadOnly
    public Map<String, String> environment() {
        return environment;
    }

    /**
     * Whether the new pane is left unfocused.
     *
     * <p>False by default, which is what {@code split-window} itself does. A session created through
     * {@link SessionSpec} is the opposite, because tmux cannot make one without attaching unless it
     * is told to detach.
     */
    public boolean detached() {
        return detached;
    }

    /** Whether the split spans the whole window rather than just the target pane. */
    public boolean fullWindow() {
        return fullWindow;
    }

    /** Whether the new pane is zoomed on arrival. */
    public boolean zoomed() {
        return zoomed;
    }

    /** Whether the pane stays after its command exits. Requires tmux 3.7. */
    public boolean keepOnExit() {
        return keepOnExit;
    }

    /** What a kept pane shows once its command has exited. Requires tmux 3.7. */
    public Optional<String> exitMessage() {
        return Optional.ofNullable(exitMessage);
    }

    /** The new pane's {@code window-style}. Requires tmux 3.7. */
    public Optional<String> style() {
        return Optional.ofNullable(style);
    }

    /** The new pane's {@code pane-active-border-style}. Requires tmux 3.7. */
    public Optional<String> activeBorderStyle() {
        return Optional.ofNullable(activeBorderStyle);
    }

    /** The new pane's {@code pane-border-style}. Requires tmux 3.7. */
    public Optional<String> inactiveBorderStyle() {
        return Optional.ofNullable(inactiveBorderStyle);
    }

    /**
     * The command that performs this split, reporting the new pane through {@code format}.
     *
     * @param target what to split, as a tmux target
     * @param format the row format the caller will read the result back with
     * @param running the version of the server about to run this
     * @throws UnsupportedFeatureException if the spec asks for something {@code running} does not have
     */
    List<String> argv(String target, String format, TmuxVersion running) {
        requireVersion(running);
        List<String> argv = new ArrayList<>(24);
        argv.add("split-window");
        argv.addAll(direction.flags());
        if (size != null) {
            argv.add("-l");
            argv.add(size.flagValue());
        }
        if (fullWindow) {
            argv.add("-f");
        }
        if (zoomed) {
            argv.add("-Z");
        }
        if (detached) {
            argv.add("-d");
        }
        if (directory != null) {
            argv.add("-c");
            argv.add(TmuxFormats.literal(directory.toAbsolutePath().toString()));
        }
        for (Map.Entry<String, String> variable : environment.entrySet()) {
            argv.add("-e");
            argv.add(variable.getKey() + "=" + variable.getValue());
        }
        if (wantsEmptyPane()) {
            argv.add("-E");
        }
        if (style != null) {
            argv.add("-s");
            argv.add(style);
        }
        if (activeBorderStyle != null) {
            argv.add("-S");
            argv.add(activeBorderStyle);
        }
        if (inactiveBorderStyle != null) {
            argv.add("-R");
            argv.add(inactiveBorderStyle);
        }
        if (exitMessage != null) {
            argv.add("-m");
            argv.add(exitMessage);
        } else if (keepOnExit) {
            // -m already implies remain-on-exit; sending both says the same thing twice.
            argv.add("-k");
        }
        argv.add("-t");
        argv.add(target);
        argv.add("-P");
        argv.add("-F");
        argv.add(format);
        List<String> command = trailingCommand();
        // Last, because everything after the command belongs to the command.
        if (!command.isEmpty()) {
            argv.add("--");
            argv.addAll(command);
        }
        return List.copyOf(argv);
    }

    /**
     * Whether tmux is being asked for a pane with no process.
     *
     * <p>A switch rather than an {@code instanceof} so that a fourth kind of start cannot be added
     * without the compiler pointing here.
     */
    private boolean wantsEmptyPane() {
        return switch (start) {
            case PaneStart.Shell shell -> false;
            case PaneStart.Command command -> false;
            case PaneStart.Empty empty -> true;
        };
    }

    /** What follows every flag, which only a command has. */
    private List<String> trailingCommand() {
        return switch (start) {
            case PaneStart.Shell shell -> List.of();
            case PaneStart.Command command -> command.argv();
            case PaneStart.Empty empty -> List.of();
        };
    }

    /**
     * Refuses before dispatch rather than letting tmux refuse.
     *
     * <p>Checked here and not in the builder because a spec is written without a server in sight,
     * and the same spec is legal against one server and not another.
     */
    private void requireVersion(TmuxVersion running) {
        if (running.atLeast(PANE_EXTRAS_SINCE)) {
            return;
        }
        String wanted = null;
        if (wantsEmptyPane()) {
            wanted = "an empty pane";
        } else if (exitMessage != null) {
            wanted = "an exit message";
        } else if (keepOnExit) {
            wanted = "keeping a pane after exit";
        } else if (style != null || activeBorderStyle != null || inactiveBorderStyle != null) {
            wanted = "pane styling on split";
        }
        if (wanted != null) {
            throw new UnsupportedFeatureException(wanted, PANE_EXTRAS_SINCE, running);
        }
    }

    @Override
    public String toString() {
        return "SplitSpec[" + direction + (size == null ? "" : " " + size.flagValue())
                + (start instanceof PaneStart.Shell ? "" : " " + start) + "]";
    }

    /** Collects the choices, each named for what it does rather than for the field it sets. */
    public static final class Builder {

        private SplitDirection direction = SplitDirection.BELOW;
        private @Nullable PaneSize size;
        private PaneStart start = PaneStart.shell();
        private @Nullable Path directory;
        private final Map<String, String> environment = new LinkedHashMap<>();
        private boolean detached;
        private boolean fullWindow;
        private boolean zoomed;
        private boolean keepOnExit;
        private @Nullable String exitMessage;
        private @Nullable String style;
        private @Nullable String activeBorderStyle;
        private @Nullable String inactiveBorderStyle;

        private Builder() {}

        /** Puts the new pane below the target, which is what tmux does by default. */
        public Builder below() {
            direction = SplitDirection.BELOW;
            return this;
        }

        /** Puts the new pane above the target. */
        public Builder above() {
            direction = SplitDirection.ABOVE;
            return this;
        }

        /** Puts the new pane to the right of the target. */
        public Builder toRight() {
            direction = SplitDirection.RIGHT;
            return this;
        }

        /** Puts the new pane to the left of the target. */
        public Builder toLeft() {
            direction = SplitDirection.LEFT;
            return this;
        }

        /** Gives the new pane this many terminal cells. */
        public Builder cells(int count) {
            size = PaneSize.cells(count);
            return this;
        }

        /** Gives the new pane this share of what is being split. */
        public Builder percent(int share) {
            size = PaneSize.percent(share);
            return this;
        }

        /**
         * Runs a command, which closes the pane when it exits unless {@link #keepOnExit} is set.
         *
         * <p>A command that exits fast enough races {@link Pane#split}'s own read-back: tmux can
         * destroy the pane before the second listing that confirms it runs, and the split then
         * throws {@code TargetGoneException} even though tmux made the pane and ran the
         * command in it. {@link #keepOnExit} removes the race by keeping the pane there to be read.
         *
         * <p>tmux also reports the pane before its process has become this command, so a read at once
         * can still see the process about to exec it: wait for the command with {@link Pane#await(java.util.function.Predicate, java.time.Duration)}.
         */
        public Builder running(String... argv) {
            start = PaneStart.command(argv);
            return this;
        }

        /** Creates a pane with no process in it. Requires tmux 3.7. */
        public Builder empty() {
            start = PaneStart.empty();
            return this;
        }

        /** Sets what runs, for a caller holding a {@link PaneStart} already. */
        public Builder start(PaneStart start) {
            this.start = Objects.requireNonNull(start, "start");
            return this;
        }

        /** Starts the new pane in this directory, resolved against this process's when relative. */
        public Builder in(Path directory) {
            this.directory = Objects.requireNonNull(directory, "directory");
            return this;
        }

        /** Sets one variable in the new pane's environment. */
        public Builder env(String name, String value) {
            environment.put(Objects.requireNonNull(name, "name"), Objects.requireNonNull(value, "value"));
            return this;
        }

        /** Adds several variables to the new pane's environment, keeping any already set. */
        public Builder environment(Map<String, String> variables) {
            variables.forEach(this::env);
            return this;
        }

        /** Leaves the target pane focused, where tmux would move to the new one. */
        public Builder detached() {
            detached = true;
            return this;
        }

        /** Splits the whole window rather than just the target pane. */
        public Builder fullWindow() {
            fullWindow = true;
            return this;
        }

        /** Zooms the new pane on arrival. */
        public Builder zoomed() {
            zoomed = true;
            return this;
        }

        /** Keeps the pane after its command exits. Requires tmux 3.7. */
        public Builder keepOnExit() {
            keepOnExit = true;
            return this;
        }

        /** Keeps the pane after its command exits and shows this. Requires tmux 3.7. */
        public Builder keepOnExit(String message) {
            exitMessage = Objects.requireNonNull(message, "message");
            keepOnExit = true;
            return this;
        }

        /** Sets the new pane's {@code window-style}. Requires tmux 3.7. */
        public Builder style(String style) {
            this.style = Objects.requireNonNull(style, "style");
            return this;
        }

        /** Sets the new pane's {@code pane-active-border-style}. Requires tmux 3.7. */
        public Builder activeBorderStyle(String style) {
            this.activeBorderStyle = Objects.requireNonNull(style, "style");
            return this;
        }

        /** Sets the new pane's {@code pane-border-style}. Requires tmux 3.7. */
        public Builder inactiveBorderStyle(String style) {
            this.inactiveBorderStyle = Objects.requireNonNull(style, "style");
            return this;
        }

        /** The finished spec. */
        public SplitSpec build() {
            return new SplitSpec(this);
        }
    }
}

package io.github.libtmux;

import java.util.Objects;

/** Shared validation for the sigil-prefixed ids tmux hands out. */
final class TargetIds {

    private TargetIds() {}

    /**
     * Rejects anything tmux would not read as an id of this kind.
     *
     * <p>A bare {@code 0} is the case worth catching: tmux would accept it as a target and resolve
     * it as a name or an index, silently addressing something else.
     */
    static void require(String value, char sigil, String kind) {
        Objects.requireNonNull(value, "value");
        boolean valid = value.length() >= 2 && value.charAt(0) == sigil;
        for (int index = 1; valid && index < value.length(); index++) {
            char digit = value.charAt(index);
            valid = digit >= '0' && digit <= '9';
        }
        if (!valid) {
            throw new IllegalArgumentException(
                    "not a " + kind + " id, expected " + sigil + " followed by digits: " + value);
        }
    }
}

package io.github.libtmux;

import java.nio.file.Path;
import java.util.Map;
import java.util.Optional;
import org.jspecify.annotations.Nullable;

/**
 * What tmux tells a program running inside one of its panes.
 *
 * <p>tmux exports {@code TMUX} as {@code <socket>,<server-pid>,<session>} and {@code TMUX_PANE} as
 * the pane's id. That is how a process discovers the server it is already inside, without being told
 * where to look.
 *
 * <pre>{@code
 * TmuxEnvironment here = TmuxEnvironment.current().orElseThrow();
 *
 * try (Server server = Server.open(here.config())) {
 *     Session mine = server.sessions().stream()
 *             .filter(session -> session.id().equals(here.session()))
 *             .findFirst()
 *             .orElseThrow();
 * }
 * }</pre>
 *
 * <p>Reading is separated from the environment itself, so the parsing is testable without a process
 * ever having to be started inside tmux: {@link #of} takes the variables, {@link #current} is the
 * one-line wrapper that fetches them.
 *
 * <p>A class rather than a record for the reason {@link ServerConfig} gives — and because the pane
 * is genuinely absent sometimes, which an {@link Optional} accessor says better than a nullable
 * record component.
 */
public final class TmuxEnvironment {

    private final Path socket;
    private final long serverPid;
    private final SessionId session;
    private final @Nullable PaneId pane;

    private TmuxEnvironment(Path socket, long serverPid, SessionId session, @Nullable PaneId pane) {
        this.socket = socket;
        this.serverPid = serverPid;
        this.session = session;
        this.pane = pane;
    }

    /**
     * Reads this process's own environment.
     *
     * @return what tmux said, or empty when this is not running inside tmux
     */
    public static Optional<TmuxEnvironment> current() {
        return of(System.getenv());
    }

    /**
     * Reads a set of environment variables.
     *
     * @param environment the variables to read, typically {@code System.getenv()}
     * @return what tmux said, or empty when {@code TMUX} is absent or unreadable
     */
    public static Optional<TmuxEnvironment> of(Map<String, String> environment) {
        String tmux = environment.get("TMUX");
        if (tmux == null || tmux.isEmpty()) {
            return Optional.empty();
        }
        // socket,pid,session — and a socket path may itself contain commas, so the two numeric
        // fields are taken from the end rather than the path from the start.
        int lastComma = tmux.lastIndexOf(',');
        int firstOfPair = tmux.lastIndexOf(',', lastComma - 1);
        if (lastComma < 0 || firstOfPair < 0) {
            return Optional.empty();
        }
        String socketField = tmux.substring(0, firstOfPair);
        String sessionField = tmux.substring(lastComma + 1);
        if (socketField.isEmpty() || sessionField.isEmpty()) {
            return Optional.empty();
        }
        try {
            long pid = Long.parseLong(tmux.substring(firstOfPair + 1, lastComma));
            if (pid <= 0) {
                return Optional.empty();
            }
            // tmux writes the session number bare, while every id elsewhere carries its sigil.
            // Without this the id would never equal one read back from a listing.
            SessionId session = new SessionId(sessionField.startsWith("$") ? sessionField : "$" + sessionField);
            String paneField = environment.get("TMUX_PANE");
            PaneId pane = paneField == null || paneField.isEmpty() ? null : new PaneId(paneField);
            return Optional.of(new TmuxEnvironment(Path.of(socketField), pid, session, pane));
        } catch (IllegalArgumentException e) {
            return Optional.empty();
        }
    }

    /** The socket the server is listening on. */
    public Path socket() {
        return socket;
    }

    /** The process id of the tmux server, which is not the pane's process. */
    public long serverPid() {
        return serverPid;
    }

    /** The session this process is running in. */
    public SessionId session() {
        return session;
    }

    /** The pane this process is running in, absent when {@code TMUX_PANE} was not set. */
    public Optional<PaneId> pane() {
        return Optional.ofNullable(pane);
    }

    /** A config addressing this server, ready for {@link Server#open}. */
    public ServerConfig config() {
        return ServerConfig.builder()
                .endpoint(ServerEndpoint.socketPath(socket))
                .build();
    }

    @Override
    public String toString() {
        return "TmuxEnvironment[" + socket + " " + session + (pane == null ? "" : " " + pane) + "]";
    }
}

package io.github.libtmux;

import java.util.Objects;

/**
 * Values handed to a tmux argument position that expands formats.
 *
 * <p>tmux expands {@code #{...}} and {@code #(...)} in many argument positions, and {@code #(...)}
 * runs a shell command. For the arguments this library composes itself — a window name, a pane
 * title, a working directory — it applies {@link #literal} at the construction boundary, so a
 * caller's {@code #} stays a {@code #}.
 *
 * <p>It cannot do that for an argument the caller composes: {@link Pane#pipeTo},
 * {@link Window#displayPopup}, {@link Shell#run}, {@link Shell#capturing} and {@link Shell#choose}
 * all take a whole shell command, where format expansion is a documented
 * tmux feature a caller may want — {@code #{pane_id}} in a filename, for instance. A caller
 * interpolating an untrusted value into one of those needs {@link #literal} on that value, which is
 * why this is public.
 *
 * <p>Shell quoting does not substitute for it. tmux expands the format <em>before</em> the shell
 * sees the string, so a {@code #(...)} inside single quotes still runs. Measured on tmux 3.7d, with
 * the interpolated value quoted as a careful caller would quote it: {@code run-shell} executed it,
 * and {@code pipe-pane -O} executed it as soon as the pane produced output.
 */
public final class TmuxFormats {

    private TmuxFormats() {}

    /**
     * Makes one caller value literal at one construction boundary.
     *
     * <p>Doubling {@code #} is tmux's own escape for it, so the value arrives as itself.
     *
     * @param value a value to be read as text rather than expanded
     * @return the value with every {@code #} doubled
     */
    public static String literal(String value) {
        return Objects.requireNonNull(value, "value").replace("#", "##");
    }

    private static final TmuxVersion DOLLAR_ESCAPED = new TmuxVersion(3, 4, "");

    private static final java.util.regex.Pattern ESCAPED_DOLLAR =
            java.util.regex.Pattern.compile("\\\\(?=\\$[A-Za-z_{])");

    /**
     * Text as tmux held it, from a line it printed.
     *
     * <p>tmux 3.4 alone puts a backslash before every {@code $} that an ASCII letter, {@code _}, or
     * <code>{</code> follows, in everything it prints: formats, listings, and {@code show-options
     * -v}. 3.5 stopped ({@code 692ce59b}). Each escape is exactly one backslash in that position, so
     * removing it restores the text on 3.4 and changes nothing elsewhere.
     *
     * <p>3.4 through 3.5a also print a control character as a C escape or three octal digits,
     * {@code \033} for ESC, and leave a backslash as it is. That is not undone: {@code \033} could as well be those
     * four characters, which a {@code terminal-overrides} entry often holds, so the text is left as
     * tmux printed it.
     */
    static String printed(String line, TmuxVersion version) {
        return version.equals(DOLLAR_ESCAPED) ? ESCAPED_DOLLAR.matcher(line).replaceAll("") : line;
    }

    /** As {@link #printed(String, TmuxVersion)}, for every line. */
    static java.util.List<String> printed(java.util.List<String> lines, TmuxVersion version) {
        return version.equals(DOLLAR_ESCAPED)
                ? lines.stream().map(line -> printed(line, version)).toList()
                : lines;
    }

    /** 3.7 refuses {@code .} and {@code :} in a name, 3.7a keeps them, and earlier releases store {@code _}. */
    private static final TmuxVersion DELIMITERS_KEPT_SINCE = new TmuxVersion(3, 7, "");

    /**
     * The names to look for when a caller names a session: the one this release stores for it, then
     * the name exactly as given, which is what {@link Session#name} already reports.
     *
     * <p>tmux doubles each backslash; 3.2a through 3.4 put a backslash before a {@code $} that a
     * letter, {@code _}, or <code>{</code> follows; 3.2a through 3.6 store {@code .} and {@code :}
     * as {@code _} and a control character as a C escape or three octal digits. 3.7 and later refuse
     * control characters. The stored form is an escaping, so it names at most one session; only a
     * name that is itself some other name's stored form is ambiguous, and the stored form wins.
     */
    static java.util.List<String> storedNames(String name, TmuxVersion version) {
        String mapped = version.atLeast(DELIMITERS_KEPT_SINCE)
                ? name
                : name.replace('.', '_').replace(':', '_');
        java.util.LinkedHashSet<String> forms = new java.util.LinkedHashSet<>();
        String stored = vis(mapped);
        // Before 3.5 the same escaping also put a backslash before a $ that a letter, _, or {
        // follows; 692ce59b limited that to double-quoted output.
        forms.add(
                version.atLeast(DOLLAR_KEPT_SINCE)
                        ? stored
                        : ESCAPABLE_DOLLAR.matcher(stored).replaceAll("\\\\\\$"));
        forms.add(name);
        return java.util.List.copyOf(forms);
    }

    private static final TmuxVersion DOLLAR_KEPT_SINCE = new TmuxVersion(3, 5, "");

    private static final java.util.regex.Pattern ESCAPABLE_DOLLAR =
            java.util.regex.Pattern.compile("\\$(?=[A-Za-z_{])");

    /** tmux's {@code vis(3)} with {@code VIS_CSTYLE | VIS_OCTAL | VIS_TAB | VIS_NL}. */
    private static String vis(String name) {
        StringBuilder out = new StringBuilder(name.length());
        for (int index = 0; index < name.length(); index++) {
            char character = name.charAt(index);
            switch (character) {
                case '\\' -> out.append("\\\\");
                case '\n' -> out.append("\\n");
                case '\t' -> out.append("\\t");
                case '\r' -> out.append("\\r");
                case '\b' -> out.append("\\b");
                case '\f' -> out.append("\\f");
                case 0x07 -> out.append("\\a");
                case 0x0b -> out.append("\\v");
                default -> {
                    if (character < 0x20 || character == 0x7f) {
                        out.append('\\').append(String.format(java.util.Locale.ROOT, "%03o", (int) character));
                    } else {
                        out.append(character);
                    }
                }
            }
        }
        return out.toString();
    }
}

package io.github.libtmux;

import java.util.Objects;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * A released tmux version, ordered the way tmux releases are.
 *
 * <p>tmux numbers a patch release with a letter rather than a third number: 3.7a follows 3.7, and
 * 3.2a follows 3.2. Comparing the text alone gets that wrong in both directions, and a feature gate
 * that gets it wrong reads a format the running tmux does not have.
 *
 * <p>Between releases, tmux reports itself as {@code next-M.m}: a development build tracking toward
 * the release named, not that release itself. It has everything the previous release shipped and
 * nothing later's patches guarantee, so it sorts strictly between the two — above every patch of the
 * release before it, below the release it names and every patch of that.
 *
 * <p>A release candidate, {@code 3.8-rc}, compares equal to the release it names. tmux freezes
 * features at the candidate, so it has everything the release will and differs only in fixes —
 * measured, not assumed: a 3.8 candidate writes JSON layouts and empties a dead pane's pid exactly
 * as 3.8 does, and a feature gated on 3.8 works on it. It is not {@code equals} to the release, and
 * it is written back exactly as tmux wrote it, which matters beyond display: every capture is
 * fenced on the version tmux reports, and a candidate printed as {@code 3.8} failed that fence on
 * every read.
 *
 * @param major the major number
 * @param minor the minor number
 * @param patch the patch letter, or empty for an unlettered release
 * @param development whether this is a {@code next-M.m} build rather than the release {@code M.m}
 *     itself
 * @param preRelease the release candidate this is, such as {@code rc} or {@code rc2}, or empty for a
 *     release
 */
public record TmuxVersion(int major, int minor, String patch, boolean development, String preRelease)
        implements Comparable<TmuxVersion> {

    private static final Pattern RELEASE = Pattern.compile("^(next-)?(\\d+)\\.(\\d+)([a-z]*)(?:-(rc\\d*))?");

    public TmuxVersion {
        Objects.requireNonNull(patch, "patch");
        Objects.requireNonNull(preRelease, "preRelease");
    }

    /** A release or a development build, without a release candidate. */
    public TmuxVersion(int major, int minor, String patch, boolean development) {
        this(major, minor, patch, development, "");
    }

    /** A released version — the ordinary case, and every version literal this library names. */
    public TmuxVersion(int major, int minor, String patch) {
        this(major, minor, patch, false, "");
    }

    /**
     * Reads what tmux reports for {@code #{version}}.
     *
     * @throws IllegalArgumentException if the text does not begin with a release number, optionally
     *     preceded by {@code next-}; a build that reports something else is one this cannot make
     *     version decisions about
     */
    public static TmuxVersion parse(String reported) {
        Matcher release = RELEASE.matcher(reported);
        if (!release.find()) {
            throw new IllegalArgumentException("not a tmux version: " + reported);
        }
        return new TmuxVersion(
                Integer.parseInt(release.group(2)),
                Integer.parseInt(release.group(3)),
                release.group(4),
                release.group(1) != null,
                release.group(5) == null ? "" : release.group(5));
    }

    /** Whether this version has everything the given one has. */
    public boolean atLeast(TmuxVersion other) {
        return compareTo(other) >= 0;
    }

    @Override
    public int compareTo(TmuxVersion other) {
        int byMajor = Integer.compare(major, other.major);
        if (byMajor != 0) {
            return byMajor;
        }
        int byMinor = Integer.compare(minor, other.minor);
        if (byMinor != 0) {
            return byMinor;
        }
        if (development != other.development) {
            // A next-M.m build has not shipped everything M.m's own patches will carry, so it
            // sorts below the release it names, whatever either side's patch letter is. A release
            // candidate is not ordered apart from its release at all: features are frozen at it.
            return development ? -1 : 1;
        }
        // An unlettered release precedes its own patches, which empty-string ordering already gives.
        return patch.compareTo(other.patch);
    }

    @Override
    public String toString() {
        return (development ? "next-" : "") + major + "." + minor + patch
                + (preRelease.isEmpty() ? "" : "-" + preRelease);
    }
}

package io.github.libtmux.transport;

import io.github.libtmux.internal.CommandStrings;
import io.github.libtmux.internal.Utf8;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import kotlin.annotations.jvm.ReadOnly;

/**
 * One tmux invocation: how to reach the server, then the commands to run there.
 *
 * <p>Commands are held literally. tmux ends a command at an argument whose last byte is {@code ;},
 * so a value ending in one would otherwise be truncated with no error; a transport encodes for the
 * parser it feeds, and {@link #commands()} answers with what the caller meant.
 *
 * <p>The timeout rides on the request instead of the transport because the same server serves both
 * a listing that should answer immediately and an attach that never returns.
 *
 * @param endpoint the tmux executable and its server selection, such as {@code [tmux, -S, path]}.
 *     tmux reads these before it parses commands, so they are passed through untouched
 * @param commands one or more tmux commands, each an argv of literal words. tmux runs them in
 *     order and discards the rest after the first failure
 * @param timeout how long the caller will wait for the whole invocation
 * @param input what the commands read from tmux's standard input, empty for the commands that
 *     read none. A tmux argument is bounded by MAX_IMSGSIZE, so text too large to be one
 *     travels here instead.
 */
public record CommandRequest(
        @ReadOnly List<String> endpoint, @ReadOnly List<List<String>> commands, Duration timeout, String input) {

    public CommandRequest {
        endpoint = List.copyOf(endpoint);
        commands = commands.stream().map(List::copyOf).toList();
        Objects.requireNonNull(timeout, "timeout");
        Objects.requireNonNull(input, "input");
        if (endpoint.isEmpty()) {
            throw new IllegalArgumentException("endpoint has no executable");
        }
        if (commands.isEmpty() || commands.stream().anyMatch(List::isEmpty)) {
            throw new IllegalArgumentException("a command has no words");
        }
        if (timeout.isZero() || timeout.isNegative()) {
            throw new IllegalArgumentException("timeout is not positive");
        }
        // The endpoint is tmux's own argv — which binary, which socket — and nothing but argv can
        // carry it, so text this JVM cannot encode there is refused here. The commands are not:
        // they are data a transport chooses how to deliver, and ProcessTransport delivers them over
        // standard input when this JVM cannot encode them as arguments.
        Utf8.requireEncodableArguments(endpoint);
    }

    /** A request for one command, which is every request but a batch. */
    public static CommandRequest of(List<String> endpoint, List<String> argv, Duration timeout) {
        return of(endpoint, argv, timeout, "");
    }

    /** A request for one command that reads {@code input} from tmux's standard input. */
    public static CommandRequest of(List<String> endpoint, List<String> argv, Duration timeout, String input) {
        return new CommandRequest(endpoint, List.of(argv), timeout, input);
    }

    /**
     * Whether sending this request twice leaves tmux as sending it once does: {@link
     * Idempotence#IDEMPOTENT} only when every command in it reads.
     */
    public Idempotence idempotence() {
        return Idempotence.of(commands);
    }

    /** The full argv to hand a process builder, encoded for tmux's own argv parser. */
    @ReadOnly
    public List<String> commandLine() {
        List<String> encoded = CommandStrings.arguments(commands);
        List<String> line = new ArrayList<>(endpoint.size() + encoded.size());
        line.addAll(endpoint);
        line.addAll(encoded);
        return Collections.unmodifiableList(line);
    }

    /**
     * Counts only. Commands carry pane content and socket paths, and this value reaches log lines
     * and failed assertions.
     */
    @Override
    public String toString() {
        return "CommandRequest[commandCount=" + commands.size() + ", timeout=" + timeout + "]";
    }
}

package io.github.libtmux.transport;

import java.util.List;
import kotlin.annotations.jvm.ReadOnly;

/**
 * One completed invocation.
 *
 * <p>A nonzero exit is data, not a failure. tmux reports an ordinary "no such pane" the same way it
 * reports a real problem, so only a higher-level method knows which one should raise.
 *
 * @param exitCode the process exit status
 * @param stdout stdout split at LF, preserving carriage returns and interior blanks
 * @param stderr stderr split into lines, with blanks dropped
 */
public record CommandResult(
        int exitCode,
        @ReadOnly List<String> stdout,
        @ReadOnly List<String> stderr) {

    public CommandResult {
        stdout = List.copyOf(stdout);
        stderr = List.copyOf(stderr);
    }

    /** Whether tmux reported success. */
    public boolean succeeded() {
        return exitCode == 0;
    }

    /** Counts only, because both channels carry captured terminal content. */
    @Override
    public String toString() {
        return "CommandResult[exitCode=" + exitCode + ", stdoutLines=" + stdout.size() + ", stderrLines="
                + stderr.size() + "]";
    }
}

package io.github.libtmux.transport;

import java.io.IOException;
import java.util.List;

/**
 * Starts a long-lived tmux process in a transport's realm.
 *
 * <p>A control client stays attached, so it cannot borrow a command permit. It still has to be
 * started by the same carrier as the commands, or a custom transport's realm is silently ignored
 * and the client attaches to whatever the local machine calls tmux.
 */
@FunctionalInterface
public interface ControlCarrier {

    /**
     * Starts the process. The caller owns it.
     *
     * @param command the tmux invocation, arguments already separate
     * @return the running process
     * @throws IOException if the process cannot be started
     */
    Process start(List<String> command) throws IOException;
}

package io.github.libtmux.transport;

/** How certain the transport is that tmux applied a request. */
public enum DispatchOutcome {
    /** The process never started, so tmux cannot have applied anything. */
    NOT_DISPATCHED,
    /** The process ran to completion and both channels were drained. */
    COMPLETE,
    /** tmux may already have applied the command; the result is not knowable. */
    UNKNOWN;

    /**
     * Whether the exact same request may be sent again after this outcome.
     *
     * <p>A request that never reached tmux may always be resent. One that may have reached it may be
     * resent only when it changes nothing. One that completed is not a dispatch question at all:
     * whether to act on tmux's answer is the caller's decision, so this answers {@code false}.
     *
     * @param idempotence whether every command in the request only reads
     */
    public boolean canRetryVerbatim(Idempotence idempotence) {
        return switch (this) {
            case NOT_DISPATCHED -> true;
            case COMPLETE -> false;
            case UNKNOWN -> idempotence == Idempotence.IDEMPOTENT;
        };
    }
}

package io.github.libtmux.transport;

import java.util.List;
import java.util.Set;

/**
 * Whether running a request twice leaves tmux as running it once does.
 *
 * <p>Decided from the commands themselves: a request is idempotent only when every command in it
 * reads and changes nothing. Anything this library cannot tell is a read counts as a change, so a
 * failure never reports a mutation as safe to resend.
 */
public enum Idempotence {
    /** Every command only reads; sending it again cannot change tmux. */
    IDEMPOTENT,
    /** At least one command may change tmux, so a second send may apply it twice. */
    NOT_IDEMPOTENT;

    // Full names and their aliases. display-message and capture-pane read only with -p, and are
    // decided below; every other verb, run-shell and if-shell included, is treated as a change.
    private static final Set<String> READS = Set.of(
            "has-session",
            "has",
            "list-buffers",
            "lsb",
            "list-clients",
            "lsc",
            "list-commands",
            "lscm",
            "list-keys",
            "lsk",
            "list-panes",
            "lsp",
            "list-sessions",
            "ls",
            "list-windows",
            "lsw",
            "server-info",
            "info",
            "show-buffer",
            "showb",
            "show-environment",
            "showenv",
            "show-hooks",
            "show-messages",
            "showmsgs",
            "show-options",
            "show",
            "show-prompt-history",
            "showphist",
            "show-window-options",
            "showw");

    /** The idempotence of a request made of {@code commands}, each an argv. */
    public static Idempotence of(List<? extends List<String>> commands) {
        return commands.stream().allMatch(Idempotence::reads) ? IDEMPOTENT : NOT_IDEMPOTENT;
    }

    private static boolean reads(List<String> argv) {
        if (argv.isEmpty()) {
            return false;
        }
        String verb = argv.get(0);
        return switch (verb) {
            case "display-message", "display", "capture-pane", "capturep" -> printsOnly(argv);
            case "if-shell", "if" -> guardedRead(argv);
            default -> READS.contains(verb);
        };
    }

    /** Whether flags ask for printing only: {@code -p}, and for a capture no {@code -b} buffer. */
    private static boolean printsOnly(List<String> argv) {
        boolean printing = false;
        for (String word : argv.subList(1, argv.size())) {
            if (!word.startsWith("-") || word.equals("--")) {
                break;
            }
            if (word.indexOf('b') > 0 && argv.get(0).startsWith("capture")) {
                return false;
            }
            printing |= word.indexOf('p') > 0;
        }
        return printing;
    }

    /**
     * {@code if-shell [-bF] [-t target] condition command [else]} as this library sends it: reads
     * when both branches are single read commands. A branch naming no command at all is how a stale
     * handle is refused, and runs nothing.
     */
    private static boolean guardedRead(List<String> argv) {
        int index = 1;
        while (index < argv.size() && argv.get(index).startsWith("-")) {
            if (argv.get(index).equals("-t")) {
                index++;
            }
            index++;
        }
        List<String> rest = argv.subList(Math.min(index + 1, argv.size()), argv.size());
        return !rest.isEmpty()
                && rest.size() <= 2
                && rest.stream().allMatch(branch -> branch.startsWith("libtmux-stale-") || readsText(branch));
    }

    private static boolean readsText(String command) {
        if (command.indexOf(';') >= 0) {
            return false;
        }
        return reads(List.of(command.strip().split("\\s+")));
    }
}

package io.github.libtmux.transport;

/**
 * Receives one {@link OperationReport} after each command.
 *
 * <p>The transport still throws on failure. This does not retry. A report whose {@link
 * OperationReport#certainty() certainty} is {@link DispatchOutcome#NOT_DISPATCHED} was never
 * applied. {@link DispatchOutcome#UNKNOWN} must not be sent again blindly.
 */
@FunctionalInterface
public interface OperationObserver {

    /** Does nothing. */
    OperationObserver NONE = report -> {};

    /**
     * Called once, after the command ends, on the thread that ran it.
     *
     * <p>An exception thrown here does not change the command's result, since the command has
     * already run: failing it would invite a retry of something tmux may have done. The exception is
     * logged at {@code WARNING}, with its stack trace, by the logger of the transport or control
     * client that ran the command.
     */
    void accept(OperationReport report);
}

package io.github.libtmux.transport;

import java.time.Duration;
import java.util.List;
import java.util.OptionalInt;
import kotlin.annotations.jvm.ReadOnly;

/**
 * One command a transport finished or failed to finish.
 *
 * <p>The verbs are the first word of each command. Arguments, standard input, and stdout are not
 * here: they carry session names, socket paths, and whatever a caller typed. {@link #boundedError()}
 * is stderr, cut off, and {@link #toString()} leaves it out.
 *
 * @param id a counter for this transport, so one call can be told from the next
 * @param verbs the commands, without their arguments
 * @param certainty whether tmux never started, finished, or might have applied the command
 * @param exitCode the process exit status, empty when the process did not finish
 * @param stdoutLines how many stdout lines came back
 * @param stderrLines how many stderr lines came back
 * @param boundedError stderr text, at most {@link #ERROR_LIMIT} characters
 * @param queued how long the call waited for a free process or writer slot
 * @param elapsed how long the command itself ran after that wait
 */
public record OperationReport(
        long id,
        @ReadOnly List<String> verbs,
        DispatchOutcome certainty,
        OptionalInt exitCode,
        int stdoutLines,
        int stderrLines,
        String boundedError,
        Duration queued,
        Duration elapsed) {

    /** How much stderr text a report keeps. */
    public static final int ERROR_LIMIT = 240;

    public OperationReport {
        verbs = List.copyOf(verbs);
        boundedError = bound(boundedError);
    }

    static String bound(String error) {
        if (error.length() <= ERROR_LIMIT) {
            return error;
        }
        return error.substring(0, ERROR_LIMIT);
    }

    /** Joins stderr lines and cuts them at {@link #ERROR_LIMIT}. */
    public static String bound(List<String> stderr) {
        return bound(String.join("\n", stderr));
    }

    /** Counts and timings only. The error text stays on {@link #boundedError()}. */
    @Override
    public String toString() {
        return "OperationReport[id=" + id + ", verbs=" + verbs + ", certainty=" + certainty + ", exit="
                + (exitCode.isPresent() ? exitCode.getAsInt() : "") + ", stdoutLines=" + stdoutLines
                + ", stderrLines=" + stderrLines + ", queued=" + queued + ", elapsed=" + elapsed + "]";
    }
}

package io.github.libtmux.transport;

import io.github.libtmux.internal.Utf8;
import java.util.ArrayList;
import java.util.List;

/**
 * Turns a drained pipe into lines while preserving tmux values.
 *
 * <p>tmux emits pane content, so the bytes are not guaranteed to be UTF-8. A malformed byte is
 * escaped as {@code \xNN} rather than replaced with U+FFFD, which keeps the original byte
 * recoverable and matches what CPython's {@code backslashreplace} produces.
 *
 * <p>tmux frames stdout with LF; CR is value data, including before LF. Stdout keeps interior blank
 * lines and drops trailing ones. Diagnostic stderr normalizes CRLF and CR to LF and drops all blanks.
 */
final class OutputDecoder {

    private OutputDecoder() {}

    static List<String> stdoutLines(byte[] bytes) {
        List<String> lines = split(Utf8.backslashReplace(bytes));
        int end = lines.size();
        while (end > 0 && lines.get(end - 1).isEmpty()) {
            end--;
        }
        return List.copyOf(lines.subList(0, end));
    }

    static List<String> stderrLines(byte[] bytes) {
        List<String> kept = new ArrayList<>();
        for (String line : split(decode(bytes))) {
            if (!line.isEmpty()) {
                kept.add(line);
            }
        }
        return List.copyOf(kept);
    }

    /** UTF-8 with {@code backslashreplace}, then universal newlines. */
    private static String decode(byte[] bytes) {
        String decoded = Utf8.backslashReplace(bytes);
        return decoded.indexOf('\r') < 0
                ? decoded
                : decoded.replace("\r\n", "\n").replace('\r', '\n');
    }

    private static List<String> split(String text) {
        List<String> lines = new ArrayList<>();
        int start = 0;
        int index;
        while ((index = text.indexOf('\n', start)) >= 0) {
            lines.add(text.substring(start, index));
            start = index + 1;
        }
        lines.add(text.substring(start));
        return lines;
    }
}

package io.github.libtmux.transport;

import io.github.libtmux.exception.DispatchException;
import io.github.libtmux.exception.ServerClosedException;
import io.github.libtmux.internal.CommandStrings;
import io.github.libtmux.internal.ProcessTree;
import io.github.libtmux.internal.Utf8;
import java.io.ByteArrayOutputStream;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.OptionalInt;
import java.util.Set;
import java.util.concurrent.Callable;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.Semaphore;
import java.util.concurrent.ThreadFactory;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;
import java.util.function.BooleanSupplier;
import java.util.function.LongSupplier;
import org.jspecify.annotations.Nullable;

/**
 * The default transport: one child process per call, drained by a bounded pool of platform threads.
 *
 * <p>A caller takes one admission permit before launching, and the pool holds exactly three workers
 * per permit, so holding a permit means both drains and the input pump are already free. Without
 * that coupling a caller can start a child whose pipes nobody is reading, or block forever writing
 * to one that stopped reading.
 *
 * <p>A request declared as waiting also takes one of all but one admission permits. The remaining
 * process stays available for the ordinary request that observes or releases those waits, without
 * increasing the total process or pump bound. An additional waiter is refused before dispatch, so
 * its caller knows it was never registered.
 *
 * <p>The caller itself may be a virtual thread: {@code Process.waitFor} releases its carrier. The
 * drains stay platform threads, although on JDK 25 neither a monitor nor a pipe read pins a virtual
 * thread any more. A virtual thread is always a daemon, and a drain has to finish the reply it is
 * reading rather than be dropped at exit; and a library does not own the scheduler, where a
 * caller's CPU-bound task that never blocks keeps its carrier and a drain waiting behind it lets
 * the pipe fill.
 *
 * <p>Launching and closing are ordered by an explicit gate rather than a flag, because checking a
 * flag and then acting on it lets a caller start a child after {@code close()} has already decided
 * there was nothing left to destroy.
 */
public final class ProcessTransport implements TmuxTransport {

    private static final int DEFAULT_BOUND = 4;
    private static final int DEFAULT_MAX_OUTPUT_BYTES = 16 * 1024 * 1024;
    private static final long RECLAIM_MILLIS = 5_000;
    private static final long TERMINATION_SECONDS = 60;

    /**
     * How long a pump with nothing to do keeps its thread, and so how long an unclosed transport
     * keeps a JVM alive after its last command. Long enough that an ordinary burst of commands
     * reuses threads rather than making new ones, short enough that a program which forgot to close
     * still exits promptly.
     */
    private static final long IDLE_PUMP_SECONDS = 10;

    private static final ProcessStarter SYSTEM_STARTER = command -> new ProcessBuilder(command).start();

    private static final System.Logger LOG = System.getLogger(ProcessTransport.class.getName());

    private final Semaphore admission;
    private final int bound;
    private final @Nullable Semaphore waitingAdmission;
    private final ThreadPoolExecutor pumps;
    private final int maxOutputBytes;
    private final ProcessStarter starter;
    private final LongSupplier nanoTime;
    private final AtomicLong ids = new AtomicLong();
    private volatile OperationObserver observer = OperationObserver.NONE;
    private final Set<RunningProcess> live = ConcurrentHashMap.newKeySet();
    private final Set<RunningProcess> killedByClose = ConcurrentHashMap.newKeySet();

    private final ReentrantLock gate = new ReentrantLock();
    private final Condition quiesced = gate.newCondition();
    private final Condition closeCompleted = gate.newCondition();
    private boolean closed;
    private boolean closeComplete;
    private @Nullable ResourceNotReclaimed closeFailure;
    private int launching;

    /** A transport allowing four concurrent tmux processes. */
    public ProcessTransport() {
        this(DEFAULT_BOUND, DEFAULT_MAX_OUTPUT_BYTES);
    }

    /**
     * @param maxConcurrentProcesses how many tmux processes may run at once
     *     ({@code executeWaiting} requires at least two)
     */
    public ProcessTransport(int maxConcurrentProcesses) {
        this(maxConcurrentProcesses, DEFAULT_MAX_OUTPUT_BYTES);
    }

    /**
     * @param maxConcurrentProcesses how many tmux processes may run at once
     * @param maxOutputBytes maximum bytes accepted from each output channel of one process
     */
    public ProcessTransport(int maxConcurrentProcesses, int maxOutputBytes) {
        this(maxConcurrentProcesses, maxOutputBytes, SYSTEM_STARTER, System::nanoTime);
    }

    ProcessTransport(int maxConcurrentProcesses, int maxOutputBytes, ProcessStarter starter, LongSupplier nanoTime) {
        this(maxConcurrentProcesses, maxOutputBytes, starter, nanoTime, TimeUnit.SECONDS.toNanos(IDLE_PUMP_SECONDS));
    }

    /** As above, with the idle-pump timeout a test can shorten rather than wait out. */
    ProcessTransport(
            int maxConcurrentProcesses,
            int maxOutputBytes,
            ProcessStarter starter,
            LongSupplier nanoTime,
            long idlePumpNanos) {
        if (maxConcurrentProcesses < 1) {
            throw new IllegalArgumentException("maxConcurrentProcesses is not positive");
        }
        if (maxOutputBytes < 1) {
            throw new IllegalArgumentException("maxOutputBytes is not positive");
        }
        this.bound = maxConcurrentProcesses;
        this.admission = new Semaphore(maxConcurrentProcesses);
        this.waitingAdmission = maxConcurrentProcesses == 1 ? null : new Semaphore(maxConcurrentProcesses - 1);
        this.pumps = (ThreadPoolExecutor) Executors.newFixedThreadPool(3 * maxConcurrentProcesses, factory());
        // An idle pump lets go of the JVM. The threads are not daemons on purpose — work in flight
        // has to finish, and a drain abandoned halfway is a truncated reply reported as a whole one
        // — but "in flight" is the point, not "ever used". Without this a caller who forgot to
        // close a transport kept a JVM alive forever after its last command, which for a
        // command-line program is indistinguishable from a deadlock. A pump that is running holds
        // the JVM exactly as before; one that has had nothing to do for this long does not, and the
        // pool makes another the moment there is work.
        this.pumps.setKeepAliveTime(idlePumpNanos, TimeUnit.NANOSECONDS);
        this.pumps.allowCoreThreadTimeOut(true);
        this.maxOutputBytes = maxOutputBytes;
        this.starter = Objects.requireNonNull(starter, "starter");
        this.nanoTime = Objects.requireNonNull(nanoTime, "nanoTime");
    }

    @Override
    public Optional<ControlCarrier> controlCarrier() {
        return Optional.of(command -> {
            requireOpen();
            return starter.start(command);
        });
    }

    @Override
    public int admissionBound() {
        return bound;
    }

    @Override
    public void observe(OperationObserver observer) {
        this.observer = Objects.requireNonNull(observer, "observer");
    }

    @Override
    public CommandResult execute(CommandRequest request) {
        return execute(request, false);
    }

    @Override
    public CommandResult executeWaiting(CommandRequest request) {
        return execute(request, true);
    }

    /**
     * Runs one request, and says so at {@code DEBUG} on this class's {@link System.Logger}.
     *
     * <p>The seam is the JDK's own, so it costs a consumer no dependency and reaches whatever they
     * already route logging to: {@code java.util.logging} by default, SLF4J or Log4j through their
     * {@code System.LoggerFinder} bridges. Enable {@code DEBUG} on {@code io.github.libtmux} to see
     * every command tmux ran, how long it took and how it ended.
     *
     * <p>Only the command verbs are written, never their arguments. An argument carries session
     * names, pane contents and whatever a caller typed — a password sent to a prompt among them —
     * and none of that belongs in a log a library opens on a caller's behalf.
     */
    private CommandResult execute(CommandRequest asked, boolean waiting) {
        long started = nanoTime.getAsLong();
        Span span = new Span();
        try {
            CommandResult result = dispatch(asked, waiting, span);
            if (LOG.isLoggable(System.Logger.Level.DEBUG)) {
                LOG.log(
                        System.Logger.Level.DEBUG,
                        "tmux {0} exited {1} in {2} ms",
                        verbs(asked),
                        result.exitCode(),
                        elapsedMillis(started));
            }
            report(asked, DispatchOutcome.COMPLETE, OptionalInt.of(result.exitCode()), result, span);
            return result;
        } catch (RuntimeException failure) {
            if (LOG.isLoggable(System.Logger.Level.DEBUG)) {
                String outcome = failure instanceof DispatchException transport
                        ? transport
                                .outcome()
                                .name()
                                .toLowerCase(java.util.Locale.ROOT)
                                .replace('_', ' ')
                        : failure.getClass().getSimpleName();
                LOG.log(
                        System.Logger.Level.DEBUG,
                        "tmux {0} failed ({1}) after {2} ms",
                        verbs(asked),
                        outcome,
                        elapsedMillis(started));
            }
            DispatchOutcome certainty =
                    failure instanceof DispatchException transport ? transport.outcome() : DispatchOutcome.UNKNOWN;
            report(asked, certainty, OptionalInt.empty(), null, span);
            throw failure;
        }
    }

    private void report(
            CommandRequest request,
            DispatchOutcome certainty,
            OptionalInt exitCode,
            @Nullable CommandResult result,
            Span span) {
        List<String> verbs =
                request.commands().stream().map(command -> command.get(0)).toList();
        int stdoutLines = result == null ? 0 : result.stdout().size();
        int stderrLines = result == null ? 0 : result.stderr().size();
        String error = result == null ? "" : OperationReport.bound(result.stderr());
        try {
            observer.accept(new OperationReport(
                    ids.incrementAndGet(),
                    verbs,
                    certainty,
                    exitCode,
                    stdoutLines,
                    stderrLines,
                    error,
                    Duration.ofNanos(Math.max(0, span.queuedNanos)),
                    Duration.ofNanos(Math.max(0, span.runNanos))));
        } catch (RuntimeException failure) {
            LOG.log(System.Logger.Level.WARNING, "operation observer failed", failure);
        }
    }

    private static final class Span {
        private long queuedNanos;
        private long runNanos;
    }

    /** The first word of each command: what ran, without anything a caller put in it. */
    private static String verbs(CommandRequest request) {
        return request.commands().stream()
                .map(command -> command.get(0))
                .collect(java.util.stream.Collectors.joining(" then "));
    }

    private static long elapsedMillis(long startedNanos) {
        return TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - startedNanos);
    }

    private CommandResult dispatch(CommandRequest asked, boolean waiting, Span span) {
        requireOpen();
        requireDispatchable(asked.commands());
        CommandRequest request = carriable(asked);
        @Nullable Semaphore waitingPermit = waiting ? waitingAdmission : null;
        if (waiting && waitingPermit == null) {
            throw new DispatchException.Failed(
                    "transport capacity leaves no process for ordinary work", DispatchOutcome.NOT_DISPATCHED, null);
        }
        long deadline = deadlineAfter(request.timeout());
        long queueStart = nanoTime.getAsLong();
        if (waitingPermit != null) {
            admitWaiting(waitingPermit);
        }
        try {
            admit(admission, deadline, "admission timed out");
        } catch (RuntimeException | Error failure) {
            span.queuedNanos = nanoTime.getAsLong() - queueStart;
            release(waitingPermit);
            throw failure;
        }
        span.queuedNanos = nanoTime.getAsLong() - queueStart;
        long runStart = nanoTime.getAsLong();
        RunningProcess process;
        try {
            process = launch(request, deadline);
        } catch (RuntimeException | Error failure) {
            span.runNanos = nanoTime.getAsLong() - runStart;
            admission.release();
            release(waitingPermit);
            throw failure;
        }
        Pumps runningPumps = null;
        try {
            runningPumps = submit(process, request.input());
            return complete(process, runningPumps, deadline);
        } finally {
            span.runNanos = nanoTime.getAsLong() - runStart;
            live.remove(process);
            killedByClose.remove(process);
            // A permit asserts that three workers are free, so it goes back only once they are. A
            // cancelled FutureTask reports itself done while its worker is still inside the read.
            if (runningPumps == null || runningPumps.reclaimed()) {
                admission.release();
                release(waitingPermit);
            }
        }
    }

    @Override
    public void close() {
        AtomicBoolean interrupted = new AtomicBoolean(Thread.interrupted());
        boolean closeOwner;
        @Nullable ResourceNotReclaimed observedFailure;
        gate.lock();
        try {
            if (closed) {
                awaitWhile(closeCompleted, () -> !closeComplete, interrupted);
                closeOwner = false;
                observedFailure = closeFailure;
            } else {
                closed = true;
                awaitWhile(quiesced, () -> launching > 0, interrupted);
                closeOwner = true;
                observedFailure = null;
            }
        } finally {
            gate.unlock();
        }

        if (!closeOwner) {
            restoreInterrupt(interrupted);
            if (observedFailure != null) {
                throw observedFailure;
            }
            return;
        }

        @Nullable ResourceNotReclaimed failure;
        try {
            failure = closeResources(interrupted);
        } catch (RuntimeException e) {
            failure = recordFailure(null, "unexpected failure while closing transport", e);
        }
        gate.lock();
        try {
            closeFailure = failure;
            closeComplete = true;
            closeCompleted.signalAll();
        } finally {
            gate.unlock();
        }
        restoreInterrupt(interrupted);
        if (failure != null) {
            throw failure;
        }
    }

    private @Nullable ResourceNotReclaimed closeResources(AtomicBoolean interrupted) {
        @Nullable ResourceNotReclaimed failure = null;
        for (RunningProcess process : live) {
            // Published before the kill, so the caller parked in waitFor can tell our signal from tmux's.
            killedByClose.add(process);
            try {
                if (!process.tree().terminate()) {
                    failure = recordFailure(failure, "tmux process tree was not reclaimed", null);
                }
            } catch (RuntimeException e) {
                failure = recordFailure(failure, "could not destroy tmux", e);
            }
        }
        try {
            pumps.shutdownNow();
        } catch (RuntimeException e) {
            failure = recordFailure(failure, "could not stop pump workers", e);
        }
        if (!awaitTermination(pumps, TERMINATION_SECONDS, interrupted)) {
            failure = recordFailure(failure, "pump workers did not terminate", null);
        }
        return failure;
    }

    // ---------------------------------------------------------------------------- admission

    private void requireOpen() {
        gate.lock();
        try {
            if (closed) {
                throw new ServerClosedException("transport is closed", DispatchOutcome.NOT_DISPATCHED);
            }
        } finally {
            gate.unlock();
        }
    }

    /**
     * The request as a process this JVM starts can carry it.
     *
     * <p>A JVM encodes a child's arguments with the platform's encoding, which the locale decides
     * before {@code main} and nothing changes afterwards. Under {@code LANG=C} — the default in most
     * container images — that is ASCII, and {@code é} would reach tmux as {@code ?}. Standard input
     * has no such limit: this library writes it as UTF-8 itself. So when the commands cannot travel
     * as arguments they travel as a script tmux reads there with {@code source-file -}, which is on
     * every supported release, answers with the same output, exit status and error, and reaches an
     * absent daemon the same way without starting one.
     *
     * <p>Written as one line, quoted as {@code if-shell} already quotes every handle command, so tmux
     * stops at the first failure exactly as it does for arguments: a batch means the same thing
     * either way. Only when standard input is already carrying something is there no second route,
     * and then the text is refused rather than corrupted.
     */
    private static CommandRequest carriable(CommandRequest request) {
        if (request.commands().stream().allMatch(Utf8::encodable)) {
            return request;
        }
        if (!request.input().isEmpty()) {
            for (List<String> command : request.commands()) {
                Utf8.requireEncodableArguments(command);
            }
        }
        return new CommandRequest(
                request.endpoint(),
                List.of(List.of("source-file", "-")),
                request.timeout(),
                CommandStrings.group(request.commands()) + "\n");
    }

    /** POSIX {@code execve} takes NUL-terminated strings, so an embedded NUL cannot survive. */
    private static void requireDispatchable(List<List<String>> commands) {
        for (List<String> argv : commands) {
            for (int index = 0; index < argv.size(); index++) {
                if (argv.get(index).indexOf('\0') >= 0) {
                    throw new IllegalArgumentException("embedded null byte in argv element " + index);
                }
            }
        }
    }

    private void admit(Semaphore permits, long deadline, String timeoutMessage) {
        long remaining = remainingNanos(deadline);
        if (remaining == 0) {
            throw admissionTimeout(timeoutMessage);
        }
        try {
            if (!permits.tryAcquire(remaining, TimeUnit.NANOSECONDS)) {
                throw admissionTimeout(timeoutMessage);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new DispatchException.Failed("interrupted before dispatch", DispatchOutcome.NOT_DISPATCHED, e);
        }
        if (remainingNanos(deadline) == 0) {
            permits.release();
            throw admissionTimeout(timeoutMessage);
        }
    }

    private static void admitWaiting(Semaphore permits) {
        if (!permits.tryAcquire()) {
            throw new DispatchException.Failed(
                    "waiting capacity is full; retry after another wait ends", DispatchOutcome.NOT_DISPATCHED, null);
        }
    }

    private static void release(@Nullable Semaphore permit) {
        if (permit != null) {
            permit.release();
        }
    }

    /** Starts and registers the child atomically with respect to {@link #close()}. */
    private RunningProcess launch(CommandRequest request, long deadline) {
        gate.lock();
        try {
            if (closed) {
                throw new ServerClosedException("transport closed before dispatch", DispatchOutcome.NOT_DISPATCHED);
            }
            if (remainingNanos(deadline) == 0) {
                throw admissionTimeout("admission timed out");
            }
            launching++;
        } finally {
            gate.unlock();
        }
        try {
            Process process = starter.start(request.commandLine());
            RunningProcess running = new RunningProcess(process, new ProcessTree(process), request.idempotence());
            live.add(running);
            return running;
        } catch (IOException e) {
            // The JDK's own message already names the binary and the errno text; dropping it is how a
            // misconfigured binary that fails to exec at all reads as a bare, contentless refusal.
            throw new DispatchException.Failed(
                    "could not start tmux: " + e.getMessage(), DispatchOutcome.NOT_DISPATCHED, e);
        } finally {
            gate.lock();
            try {
                if (--launching == 0) {
                    quiesced.signalAll();
                }
            } finally {
                gate.unlock();
            }
        }
    }

    // ------------------------------------------------------------------------------ draining

    private Pumps submit(RunningProcess process, String input) {
        CountDownLatch finished = new CountDownLatch(3);
        CompletableFuture<Throwable> failure = new CompletableFuture<>();
        try {
            return new Pumps(
                    pumps.submit(new Pump(process.process().getInputStream(), maxOutputBytes, finished, failure)),
                    pumps.submit(new Pump(process.process().getErrorStream(), maxOutputBytes, finished, failure)),
                    pumps.submit(new InputPump(process.process().getOutputStream(), input, finished)),
                    finished,
                    failure);
        } catch (RejectedExecutionException e) {
            throw terminate(process, "transport closed before draining", e);
        }
    }

    private CommandResult complete(RunningProcess process, Pumps runningPumps, long deadline) {
        awaitExitOrFailure(process, runningPumps, deadline);
        if (killedByClose.contains(process)) {
            // This exit status is ours, not tmux's; returning it would read as tmux dying on a signal.
            throw new ServerClosedException("transport closed while tmux was running", DispatchOutcome.UNKNOWN);
        }
        byte[] out = collect(runningPumps.stdout(), process, deadline);
        byte[] err = collect(runningPumps.stderr(), process, deadline);
        return new CommandResult(
                process.process().exitValue(), OutputDecoder.stdoutLines(out), OutputDecoder.stderrLines(err));
    }

    private void awaitExitOrFailure(RunningProcess process, Pumps runningPumps, long deadline) {
        try {
            CompletableFuture.anyOf(process.process().onExit(), runningPumps.failure())
                    .get(remainingNanos(deadline), TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw terminate(process, "interrupted while awaiting tmux", e);
        } catch (TimeoutException e) {
            throw timeout(process, "tmux exceeded its deadline", e);
        } catch (ExecutionException e) {
            throw terminate(process, "could not await tmux", e.getCause());
        }
        Throwable failure = runningPumps.failure().getNow(null);
        if (failure != null) {
            String message =
                    failure instanceof OutputLimitExceeded exceeded ? exceeded.description() : "could not drain tmux";
            throw terminate(process, message, failure);
        }
    }

    private byte[] collect(Future<byte[]> drain, RunningProcess process, long deadline) {
        try {
            return drain.get(remainingNanos(deadline), TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw terminate(process, "interrupted while draining tmux", e);
        } catch (TimeoutException e) {
            throw timeout(process, "draining tmux exceeded its deadline", e);
        } catch (ExecutionException e) {
            Throwable cause = e.getCause();
            String message =
                    cause instanceof OutputLimitExceeded exceeded ? exceeded.description() : "could not drain tmux";
            throw terminate(process, message, cause);
        }
    }

    private long deadlineAfter(Duration timeout) {
        long timeoutNanos;
        try {
            timeoutNanos = timeout.toNanos();
        } catch (ArithmeticException e) {
            timeoutNanos = Long.MAX_VALUE;
        }
        return nanoTime.getAsLong() + timeoutNanos;
    }

    private long remainingNanos(long deadline) {
        return Math.max(0, deadline - nanoTime.getAsLong());
    }

    private static DispatchException.TimedOut admissionTimeout(String message) {
        return new DispatchException.TimedOut(message, DispatchOutcome.NOT_DISPATCHED, null);
    }

    // --------------------------------------------------------------------------- destruction

    /** Pumps are deliberately not cancelled: killing the child is what actually ends pipe I/O. */
    private DispatchException terminate(RunningProcess process, String message, @Nullable Throwable cause) {
        return reclaim(
                process, new DispatchException.Failed(message, DispatchOutcome.UNKNOWN, process.idempotence(), cause));
    }

    private DispatchException.TimedOut timeout(RunningProcess process, String message, @Nullable Throwable cause) {
        return reclaim(
                process,
                new DispatchException.TimedOut(message, DispatchOutcome.UNKNOWN, process.idempotence(), cause));
    }

    private <T extends DispatchException> T reclaim(RunningProcess process, T failure) {
        if (!process.tree().terminate()) {
            failure.addSuppressed(new ResourceNotReclaimed("tmux process tree was not reclaimed"));
        }
        return failure;
    }

    private static void awaitWhile(Condition condition, BooleanSupplier waiting, AtomicBoolean interrupted) {
        while (waiting.getAsBoolean()) {
            try {
                condition.await();
            } catch (InterruptedException e) {
                interrupted.set(true);
            }
        }
    }

    private static boolean awaitTermination(ThreadPoolExecutor executor, long seconds, AtomicBoolean interrupted) {
        long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(seconds);
        while (true) {
            long left = deadline - System.nanoTime();
            if (left <= 0) {
                return executor.isTerminated();
            }
            try {
                return executor.awaitTermination(left, TimeUnit.NANOSECONDS);
            } catch (InterruptedException e) {
                interrupted.set(true);
            }
        }
    }

    private static ResourceNotReclaimed recordFailure(
            @Nullable ResourceNotReclaimed failure, String message, @Nullable Throwable cause) {
        ResourceNotReclaimed recorded = new ResourceNotReclaimed(message);
        if (cause != null) {
            recorded.addSuppressed(cause);
        }
        if (failure == null) {
            return recorded;
        }
        failure.addSuppressed(recorded);
        return failure;
    }

    private static void restoreInterrupt(AtomicBoolean interrupted) {
        if (interrupted.get()) {
            Thread.currentThread().interrupt();
        }
    }

    private static void closeQuietly(Closeable stream, @Nullable DispatchException failure) {
        try {
            stream.close();
        } catch (IOException e) {
            if (failure != null) {
                failure.addSuppressed(e);
            }
        }
    }

    /**
     * Non-daemon, so a drain in flight finishes rather than being abandoned halfway and reported as
     * a whole reply. An idle one times out instead, so forgetting to close still lets a JVM exit.
     */
    private static ThreadFactory factory() {
        AtomicInteger index = new AtomicInteger();
        return runnable -> {
            Thread worker = new Thread(runnable, "libtmux-pump-" + index.incrementAndGet());
            worker.setDaemon(false);
            return worker;
        };
    }

    private record Pumps(
            Future<byte[]> stdout,
            Future<byte[]> stderr,
            Future<?> stdin,
            CountDownLatch finished,
            CompletableFuture<Throwable> failure) {
        boolean reclaimed() {
            boolean interrupted = Thread.interrupted();
            long deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(RECLAIM_MILLIS);
            try {
                while (finished.getCount() > 0) {
                    long left = deadline - System.nanoTime();
                    if (left <= 0) {
                        return false;
                    }
                    try {
                        if (finished.await(left, TimeUnit.NANOSECONDS)) {
                            return true;
                        }
                    } catch (InterruptedException e) {
                        interrupted = true;
                    }
                }
                return true;
            } finally {
                if (interrupted) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }

    private record RunningProcess(Process process, ProcessTree tree, Idempotence idempotence) {}

    @FunctionalInterface
    interface ProcessStarter {
        Process start(List<String> command) throws IOException;
    }

    private record Pump(InputStream source, int limit, CountDownLatch finished, CompletableFuture<Throwable> failure)
            implements Callable<byte[]> {
        @Override
        public byte[] call() throws IOException {
            try {
                ByteArrayOutputStream output = new ByteArrayOutputStream(Math.min(limit, 8_192));
                byte[] buffer = new byte[8_192];
                int total = 0;
                int read;
                while ((read = source.read(buffer)) >= 0) {
                    if (read > limit - total) {
                        throw new OutputLimitExceeded(limit);
                    }
                    output.write(buffer, 0, read);
                    total += read;
                }
                byte[] result = output.toByteArray();
                source.close();
                return result;
            } catch (IOException | RuntimeException e) {
                failure.complete(e);
                throw e;
            } finally {
                finished.countDown();
            }
        }
    }

    private record InputPump(OutputStream target, String input, CountDownLatch finished) implements Runnable {
        @Override
        public void run() {
            try {
                if (!input.isEmpty()) {
                    target.write(input.getBytes(StandardCharsets.UTF_8));
                    target.flush();
                }
            } catch (IOException stoppedReading) {
                // The exit status and stderr say what the child made of incomplete input.
            } finally {
                closeQuietly(target, null);
                finished.countDown();
            }
        }
    }

    private static final class OutputLimitExceeded extends IOException {
        private static final long serialVersionUID = 1L;
        private final int limit;

        OutputLimitExceeded(int limit) {
            super("tmux output exceeded the " + limit + " byte channel limit");
            this.limit = limit;
        }

        String description() {
            return "tmux output exceeded the " + limit + " byte channel limit";
        }
    }

    /**
     * A worker could not be recovered. Distinct from {@link IllegalStateException}, which this
     * transport reserves for use after close.
     */
    static final class ResourceNotReclaimed extends IllegalStateException {
        private static final long serialVersionUID = 1L;

        ResourceNotReclaimed(String message) {
            super(message);
        }
    }
}

package io.github.libtmux.transport;

import io.github.libtmux.exception.DispatchException;
import java.util.Optional;

/**
 * Runs one tmux command and blocks until it has an answer.
 *
 * <p>Implementations are thread-safe and {@link #close()} is idempotent. A call begun before close
 * either completes under the documented contract or fails with its dispatch certainty intact; a
 * call begun after close fails with {@link io.github.libtmux.exception.ServerClosedException}, an
 * {@link IllegalStateException}.
 */
public interface TmuxTransport extends AutoCloseable {

    /**
     * Runs the request to completion.
     *
     * <p>An implementation writes {@link CommandRequest#input()} to tmux's standard input and
     * closes it. A command that reads standard input and is given none reads end of file, which
     * tmux reports as success over an empty result rather than as a failure.
     *
     * @param request what to run, what it reads, and how long to wait
     * @return the exit status and both channels; a nonzero exit is a result, not a failure
     * @throws DispatchException if the command could not be run to completion, carrying how
     *     certain it is that tmux applied it
     * @throws IllegalStateException if this transport is closed
     */
    CommandResult execute(CommandRequest request);

    /**
     * Runs a request expected to remain blocked until another request through this transport
     * releases it.
     *
     * <p>The default shares ordinary admission. A transport with bounded concurrency may override
     * this to keep release and observation requests from queuing behind every waiter.
     */
    default CommandResult executeWaiting(CommandRequest request) {
        return execute(request);
    }

    /**
     * Names the execution realm this transport reaches tmux through.
     *
     * <p>Entity identity is scoped by it. Two unrelated realms can both hold a server at the same
     * socket path, and entities from them must not compare equal, so a transport that reaches a
     * different machine, container or user should return something stable and distinct.
     *
     * @return a stable realm name; the default is the local process's own view of the filesystem
     */
    default String realm() {
        return "local";
    }

    /**
     * How this transport starts a process that stays attached.
     *
     * <p>Empty when the transport cannot. A command-only fake is in that set, and so is any realm
     * that has not said how its processes are born. Callers that need a control client then fail
     * instead of starting one on the local machine.
     */
    default Optional<ControlCarrier> controlCarrier() {
        return Optional.empty();
    }

    /**
     * Receives a report after each command this transport runs.
     *
     * <p>The default ignores it. A transport that cannot see its own commands leaves the observer
     * unset rather than inventing timings.
     */
    default void observe(OperationObserver observer) {}

    /**
     * How many requests this transport runs at once; the rest wait for a turn.
     *
     * @return the bound, or {@link Integer#MAX_VALUE} for a transport that sets none
     */
    default int admissionBound() {
        return Integer.MAX_VALUE;
    }

    /** Releases every resource and destroys every child still running. Idempotent. */
    @Override
    void close();
}

package io.github.libtmux;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import kotlin.annotations.jvm.ReadOnly;

/**
 * Discounts input recorded by this library when reading a pane's output.
 *
 * <p>Create one instance per wait. Each read refreshes pending input and retains submitted echoes
 * already observed, even after the shared record expires. This mutable view is not thread-safe.
 */
public final class TypedText {

    private final Server server;
    private final ServerIdentity identity;
    private final PaneId paneId;

    /** Every finished line this watch has ever seen, growing for as long as this instance lives. */
    private final Set<String> recentSoFar = new LinkedHashSet<>();

    private TypedText(Server server, ServerIdentity identity, PaneId paneId) {
        this.server = server;
        this.identity = identity;
        this.paneId = paneId;
    }

    /** What this library has typed into the pane recently enough to still be on its screen. */
    public static TypedText in(Pane pane) {
        Objects.requireNonNull(pane, "pane");
        return new TypedText(pane.server(), pane.server().identity(pane.snapshot()), pane.id());
    }

    /**
     * The lines with each recorded echo taken out, wherever it stands as an echo does.
     *
     * <p>An occurrence is taken out only where it is not part of a longer word on either side. That is
     * what keeps the answer when the answer merely contains the question — {@code id} comes off
     * {@code $ id} and stays inside {@code uid=1000} — while still taking out every copy of an echo a
     * shell drew more than once, and one a shell drew something straight after. A row the echo shared
     * with real output keeps that output.
     *
     * <p>What no rule can do is tell an echo from output that repeats the whole typed line as a line
     * of its own. Wait for something the command prints rather than something it says.
     *
     * <p>The lines are scanned as one string, so an echo the terminal broke across rows is still
     * found. Pass lines with wrapping already rejoined when the text being watched for can itself be
     * broken across rows. A shell redraw or truncated capture that retains only part of an echo
     * cannot be recognized reliably.
     */
    @ReadOnly
    public List<String> withoutEcho(List<String> lines) {
        Objects.requireNonNull(lines, "lines");
        PaneEcho.Live live = server.echo().liveFor(identity, paneId);
        recentSoFar.addAll(live.recent());
        if (recentSoFar.isEmpty() && live.pending().isEmpty()) {
            return lines;
        }
        List<String> discount =
                new ArrayList<>(recentSoFar.size() + live.pending().size());
        discount.addAll(recentSoFar);
        discount.addAll(live.pending());
        return PaneEcho.withoutEcho(lines, discount);
    }

    /** Whether anything typed into the pane is live enough, right now, to still be discounted. */
    public boolean isEmpty() {
        if (!recentSoFar.isEmpty()) {
            return false;
        }
        PaneEcho.Live live = server.echo().liveFor(identity, paneId);
        return live.pending().isEmpty() && live.recent().isEmpty();
    }

    @Override
    public String toString() {
        return "TypedText" + server.echo().liveFor(identity, paneId);
    }
}

package io.github.libtmux;

/**
 * Why a wait on a tmux channel ended.
 *
 * <p>An enum rather than a boolean, and rather than nothing at all, because tmux's own
 * {@code wait-for} cannot distinguish these: it exits successfully both when the channel is
 * signalled and when the server dies underneath the waiter.
 */
public enum WakeReason {
    /** The channel was signalled. */
    SIGNALLED,
    /** Nothing signalled the channel before the caller's deadline. */
    TIMED_OUT,
    /**
     * The server is gone. tmux reports this as a successful wake, so it is checked for rather than
     * believed; a caller cannot rely on anything the wait was guarding.
     */
    SERVER_GONE
}

package io.github.libtmux;

import com.google.errorprone.annotations.CheckReturnValue;
import io.github.libtmux.catalog.Kind;
import io.github.libtmux.catalog.Operation;
import io.github.libtmux.exception.LibTmuxException;
import io.github.libtmux.exception.MalformedResponseException;
import io.github.libtmux.exception.ServerUnavailableException;
import io.github.libtmux.exception.TargetGoneException;
import io.github.libtmux.exception.UnsupportedFeatureException;
import io.github.libtmux.snapshot.ServerSnapshot;
import io.github.libtmux.snapshot.WindowContext;
import io.github.libtmux.snapshot.WindowState;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.function.Consumer;
import kotlin.annotations.jvm.ReadOnly;

/**
 * One tmux window at one of its positions, as one capture saw it.
 *
 * <p>Identity is the winlink: the server, the session, the index and the window. A window linked
 * into two sessions is one window and two handles, because tmux orders and addresses those
 * positions separately. {@link #id()} stays available for asking whether two links are the same
 * underlying window.
 *
 * <p>A method named for a captured field returns what {@link #info()} holds and does no I/O;
 * {@link #refresh()} reads again. Every other method asks tmux now.
 */
public final class Window {

    private final Server server;
    private final ServerSnapshot snapshot;
    private final WindowState state;

    Window(Server server, ServerSnapshot snapshot, WindowState state) {
        this.server = server;
        this.snapshot = snapshot;
        this.state = state;
    }

    /** The fields this capture stored. A later rename is not visible here. */
    @Operation(Kind.CAPTURED)
    public WindowState info() {
        return state;
    }

    /** The underlying window, shared by every link to it. */
    @Operation(Kind.CAPTURED)
    public WindowId id() {
        return state.context().window();
    }

    /** Where this link sits in its session. */
    @Operation(Kind.CAPTURED)
    public WindowIndex index() {
        return state.context().index();
    }

    /** The winlink this handle addresses. */
    @Operation(Kind.CAPTURED)
    public WindowContext context() {
        return state.context();
    }

    /** The window name. */
    @Operation(Kind.CAPTURED)
    public String name() {
        return state.name();
    }

    /** Whether this was its session's active window when captured. */
    @Operation(Kind.CAPTURED)
    public boolean active() {
        return state.active();
    }

    /** Whether the underlying window is linked into more than one session. */
    @Operation(Kind.CAPTURED)
    public boolean linked() {
        return state.linked();
    }

    /** How large the window was when captured, in terminal cells. */
    @Operation(Kind.CAPTURED)
    public Dimensions size() {
        return state.size();
    }

    /**
     * tmux's own layout for this window, in whichever form this server writes it.
     *
     * <p>Classic before tmux 3.8 and JSON from it, and the type says which. Hand it back with {@link
     * #applyLayout(WindowLayout)}.
     */
    @Operation(Kind.CAPTURED)
    public WindowLayout layout() {
        return WindowLayout.of(state.layout());
    }

    /**
     * The pane tmux had active here. A pure read of the capture.
     *
     * <p>Empty only when the capture holds no pane marked active for this window, which a complete
     * capture of a live window does not.
     */
    @Operation(Kind.CAPTURED)
    public Optional<Pane> activePane() {
        return panes().stream().filter(Pane::active).findFirst();
    }

    /** Makes this the active window of its session. */
    @Operation(Kind.MUTATION)
    public void select() {
        server.run(snapshot, state.context(), List.of("select-window", "-t", linkTarget()));
    }

    /** The server this window lives on. */
    @Operation(Kind.CAPTURED)
    public Server server() {
        return server;
    }

    ServerSnapshot snapshot() {
        return snapshot;
    }

    /** The session this link belongs to. A pure read of the capture. */
    @Operation(Kind.CAPTURED)
    public Session session() {
        return snapshot.session(state.context().session())
                .map(session -> new Session(server, snapshot, session))
                .orElseThrow(
                        () -> new MalformedResponseException("the capture holds a window whose session it never saw"));
    }

    /** This window's own hooks, which every link to it shares. */
    @Operation(Kind.CAPTURED)
    public Hooks hooks() {
        return Hooks.window(server, snapshot, id());
    }

    /** This window's own options, which every link to it shares. */
    @Operation(Kind.CAPTURED)
    public Options options() {
        return Options.window(server, snapshot, id());
    }

    /** This link's panes, in tmux's order. A pure read of the capture. */
    @ReadOnly
    @Operation(Kind.CAPTURED)
    public List<Pane> panes() {
        return snapshot.panesOf(state.context()).stream()
                .map(pane -> new Pane(server, snapshot, pane))
                .toList();
    }

    /**
     * Splits this window's active pane in half, putting the new one below it.
     *
     * @return the pane that appeared
     */
    @Operation(Kind.MUTATION)
    public Pane split() {
        return split(SplitSpec.builder().build());
    }

    /**
     * Splits this window's active pane as described.
     *
     * @param configure receives a builder holding tmux's defaults
     * @return the pane that appeared
     * @throws UnsupportedFeatureException if the spec asks for something this server does not have
     */
    @Operation(Kind.MUTATION)
    public Pane split(Consumer<SplitSpec.Builder> configure) {
        SplitSpec.Builder builder = SplitSpec.builder();
        configure.accept(builder);
        return split(builder.build());
    }

    /**
     * Splits this window's active pane according to a spec, which may be reused across windows.
     *
     * @return the pane that appeared
     * @throws UnsupportedFeatureException if the spec asks for something this server does not have
     */
    @Operation(Kind.MUTATION)
    public Pane split(SplitSpec spec) {
        return Pane.created(server, snapshot, spec.argv(target(), Pane.createdFormat(), server.version(snapshot)));
    }

    /**
     * Expands a tmux format in this window's context, and answers with what it came to.
     *
     * <p>The same escape hatch {@link Pane#expand} gives, resolved against this window.
     *
     * @param format a tmux format, usually of the shape {@code #{name}}
     * @return the expansion, whole when it spans lines and empty when the format expanded to
     *     nothing
     */
    @Operation(Kind.READ)
    public String expand(String format) {
        Objects.requireNonNull(format, "format");
        return PrintedText.printed(server.run(
                        snapshot,
                        state.context(),
                        List.of("display-message", "-p", "-t", linkTarget(), "--", PrintedText.expansion(format)))
                .stdout());
    }

    /**
     * Renames this window and returns its replacement capture.
     *
     * <p>Retain the result to read the changed name. This handle keeps its original captured state.
     *
     * <p>A {@code :} or {@code .} is kept as written on every supported release but 3.7, which
     * refuses the name. A kept delimiter cannot then address the window, since a target splits on
     * both. Unlike a session name, a window name is never rewritten.
     */
    @CheckReturnValue
    @Operation(Kind.MUTATION)
    public Window rename(String name) {
        server.run(snapshot, List.of("rename-window", "-t", target(), "--", TmuxFormats.literal(name)));
        return refresh();
    }

    /** Links this window into another session, so one window sits in both. */
    @Operation(Kind.MUTATION)
    public void linkTo(Session session) {
        Objects.requireNonNull(session, "session");
        server.requireSameIncarnation(snapshot, session.server(), session.snapshot());
        server.run(
                snapshot,
                List.of("link-window", "-s", target(), "-t", session.id().value()));
    }

    /**
     * Removes this link, leaving the window wherever else it is linked.
     *
     * @throws LibTmuxException if this is the window's only link, which tmux refuses to remove
     */
    @Operation(Kind.MUTATION)
    public void unlink() {
        server.run(snapshot, state.context(), List.of("unlink-window", "-t", linkTarget()));
    }

    /** Moves this window into another session. */
    @Operation(Kind.MUTATION)
    public void moveTo(Session session) {
        Objects.requireNonNull(session, "session");
        server.requireSameIncarnation(snapshot, session.server(), session.snapshot());
        server.run(
                snapshot,
                state.context(),
                List.of("move-window", "-s", linkTarget(), "-t", session.id().value()));
    }

    /** Moves this window to an exact index in another session. */
    @Operation(Kind.MUTATION)
    public void moveTo(Session session, int index) {
        if (index < 0) {
            throw new IllegalArgumentException("window index is negative: " + index);
        }
        Objects.requireNonNull(session, "session");
        server.requireSameIncarnation(snapshot, session.server(), session.snapshot());
        server.run(
                snapshot,
                state.context(),
                List.of("move-window", "-s", linkTarget(), "-t", session.id().value() + ":" + index));
    }

    /** Resizes this window in terminal cells. */
    @Operation(Kind.MUTATION)
    public void resizeTo(Dimensions size) {
        Objects.requireNonNull(size, "size");
        server.run(
                snapshot,
                List.of(
                        "resize-window",
                        "-t",
                        target(),
                        "-x",
                        Integer.toString(size.width()),
                        "-y",
                        Integer.toString(size.height())));
    }

    /**
     * Copies input to one pane into every pane in this window, until {@link #stopSynchronizingPanes}.
     *
     * <p>A verb pair rather than a boolean parameter, so a call site says which it means — as
     * {@link Pane#pipeTo} and {@link Pane#stopPiping} already do for the other state a window
     * carries.
     */
    @Operation(Kind.MUTATION)
    public void synchronizePanes() {
        options().set("synchronize-panes", "on");
    }

    /** Stops copying input between this window's panes. */
    @Operation(Kind.MUTATION)
    public void stopSynchronizingPanes() {
        options().set("synchronize-panes", "off");
    }

    /** Rotates the panes within this window. */
    @Operation(Kind.MUTATION)
    public void rotate() {
        server.run(snapshot, List.of("rotate-window", "-t", target()));
    }

    /**
     * Rearranges this window's panes into one of tmux's built-in layouts.
     *
     * @throws UnsupportedFeatureException if the layout arrived after the release this server runs
     */
    @Operation(Kind.MUTATION)
    public void selectLayout(Layout layout) {
        Objects.requireNonNull(layout, "layout");
        layout.requireSupported(server.version(snapshot));
        server.run(snapshot, List.of("select-layout", "-t", target(), layout.tmuxName()));
    }

    /** Moves to the next built-in layout, as tmux's own binding does. */
    @Operation(Kind.MUTATION)
    public void nextLayout() {
        server.run(snapshot, List.of("next-layout", "-t", target()));
    }

    /** Moves to the previous built-in layout, as tmux's own binding does. */
    @Operation(Kind.MUTATION)
    public void previousLayout() {
        server.run(snapshot, List.of("previous-layout", "-t", target()));
    }

    /**
     * Restores an exact arrangement previously read from {@link #layout()}.
     *
     * <p>The string is checked here rather than by tmux, because tmux 3.3a does not survive being
     * handed one it cannot parse: it ends the server and every session on the socket. Every other
     * supported release answers {@code invalid layout}. The classic form carries tmux's own
     * checksum, so a wrong one is detectable without asking; since 3.8 tmux may instead hand back
     * JSON, which carries no checksum, so that shape is only trusted from a server new enough to
     * have written it.
     *
     * <p>"Exact" holds in full only for a JSON layout, since that is the one form carrying each
     * pane's id. A classic string — every release before 3.8, or an older reader against a newer
     * server — restores the geometry but names no pane, so which process lands in which cell can
     * differ from where it started; whether it does depends on whether the pane list still happens
     * to match the order the layout was saved in. Confirmed by hand on 3.2a and 3.7c.
     *
     * @throws IllegalArgumentException if the string is not a layout tmux wrote
     * @throws UnsupportedFeatureException if it is JSON-shaped but this server predates JSON
     *     layouts
     */
    @Operation(Kind.MUTATION)
    public void applyLayout(WindowLayout layout) {
        Objects.requireNonNull(layout, "layout");
        applyLayout(layout.value());
    }

    /**
     * As {@link #applyLayout(WindowLayout)}, for a layout held as text — one saved to a file, say.
     *
     * @throws IllegalArgumentException if the string is not a layout tmux wrote
     * @throws UnsupportedFeatureException if it is JSON-shaped but this server predates JSON
     *     layouts
     */
    @Operation(Kind.MUTATION)
    public void applyLayout(String layout) {
        Objects.requireNonNull(layout, "layout");
        server.run(
                snapshot,
                List.of("select-layout", "-t", target(), Layouts.requireSerialized(layout, server.version(snapshot))));
    }

    /** Kills what is running in this window and starts it again. */
    @Operation(Kind.MUTATION)
    public void respawn() {
        server.run(snapshot, List.of("respawn-window", "-k", "-t", target()));
    }

    /**
     * Shows a popup over this window, running a command in it.
     *
     * <p>tmux draws a popup for a client, so this needs one attached; on a detached session tmux
     * reports that it has no current client.
     *
     * <p>tmux expands {@code #(...)} in this command before a shell sees it, and shell quoting does
     * not prevent that. Pass any interpolated value through {@link TmuxFormats#literal} unless you
     * mean it to be expanded.
     */
    @Operation(Kind.MUTATION)
    public void displayPopup(String shellCommand) {
        server.run(snapshot, List.of("display-popup", "-E", "-t", target(), "--", shellCommand));
    }

    /** Closes this window. */
    @Operation(Kind.MUTATION)
    public void kill() {
        server.run(snapshot, List.of("kill-window", "-t", target()));
    }

    /**
     * Takes a new capture and returns this winlink as it is now.
     *
     * @throws TargetGoneException if this window is no longer linked here, from a server
     *     that still answers
     * @throws ServerUnavailableException if no daemon is running
     */
    @CheckReturnValue
    @Operation(Kind.READ)
    public Window refresh() {
        ServerSnapshot fresh = server.refresh(snapshot);
        return fresh.window(state.context())
                .map(window -> new Window(server, fresh, window))
                .orElseThrow(() -> new TargetGoneException("window " + id() + " no longer exists here"));
    }

    /** Addresses the underlying window, which every link to it shares. */
    private String target() {
        return state.context().window().value();
    }

    /** Addresses this exact link, even when its underlying window appears twice in one session. */
    private String linkTarget() {
        return state.context().session().value() + ":" + state.context().index().value();
    }

    @Override
    public boolean equals(Object other) {
        return other instanceof Window that
                && server.identity(snapshot).equals(that.server.identity(that.snapshot))
                && state.context().equals(that.state.context());
    }

    @Override
    public int hashCode() {
        return Objects.hash(server.identity(snapshot), state.context());
    }

    @Override
    public String toString() {
        return "Window[" + state.context().session() + ":" + state.context().index() + " " + state.name() + "]";
    }
}

package io.github.libtmux;

/**
 * A tmux window id, such as {@code @1}.
 *
 * <p>Identifies the window itself, not where it sits. A window linked into two sessions has one id
 * and two positions, so this is what to compare when asking whether two links are the same window.
 *
 * @param value the id including its {@code @} sigil
 */
public record WindowId(String value) {

    public WindowId {
        TargetIds.require(value, '@', "window");
    }

    @Override
    public String toString() {
        return value;
    }
}

package io.github.libtmux;

/**
 * Where a window sits in one session.
 *
 * <p>A position, not an identity: tmux renumbering moves a window to a different index, and the
 * same window linked into two sessions can hold a different index in each.
 *
 * @param value the index, as tmux reports it
 */
public record WindowIndex(int value) {

    public WindowIndex {
        if (value < 0) {
            throw new IllegalArgumentException("window index is negative: " + value);
        }
    }

    @Override
    public String toString() {
        return Integer.toString(value);
    }
}

package io.github.libtmux;

import java.util.Objects;

/**
 * A window's layout as tmux reported it, in whichever of its two forms it used.
 *
 * <p>tmux writes a layout in its classic checksummed form — {@code c3a4,80x24,0,0,1} — on every
 * release before 3.8, and as JSON from 3.8, which also names the pane in each cell. The same window
 * therefore reports a differently shaped string depending on the server, and a caller that parses it
 * needs to know which it has. This says, so the compiler can carry what used to be a comment:
 *
 * <pre>{@code
 * switch (window.layout()) {
 *     case WindowLayout.Json json -> restorePanes(json.value());
 *     case WindowLayout.Classic classic -> restoreGeometry(classic.value());
 * }
 * }</pre>
 *
 * <p>Either form is an opaque token to hand back to tmux, which {@link Window#applyLayout(WindowLayout)}
 * does; parsing one is tmux's job, and {@link #value()} is the text for a caller who wants to anyway.
 */
public sealed interface WindowLayout {

    /** The layout exactly as tmux reported it. */
    String value();

    /** The checksummed form every release writes before 3.8. It carries geometry and no pane ids. */
    record Classic(String value) implements WindowLayout {

        public Classic {
            Objects.requireNonNull(value, "value");
        }
    }

    /** The JSON form tmux writes from 3.8, which names the pane in each cell. */
    record Json(String value) implements WindowLayout {

        public Json {
            Objects.requireNonNull(value, "value");
        }
    }

    /**
     * Which form a reported layout is in.
     *
     * <p>Decided as tmux decides it, on whether the first non-blank character opens a JSON object —
     * {@code layout_construct} in {@code layout-custom.c} dispatches on nothing more.
     */
    static WindowLayout of(String reported) {
        Objects.requireNonNull(reported, "reported");
        return reported.strip().startsWith("{") ? new Json(reported) : new Classic(reported);
    }
}

package io.github.libtmux;

/**
 * Where a new window is inserted relative to the current one.
 *
 * <p>Absent rather than a third constant when the caller does not care: tmux picking the next free
 * index is a different thing from being asked for a particular side, and a {@code DEFAULT} member
 * would have no flag to produce.
 */
public enum WindowPlacement {
    AFTER("-a"),
    BEFORE("-b");

    private final String flag;

    WindowPlacement(String flag) {
        this.flag = flag;
    }

    /** The tmux flag that places a window this way. */
    String flag() {
        return flag;
    }
}

package io.github.libtmux;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import kotlin.annotations.jvm.ReadOnly;
import org.jspecify.annotations.Nullable;

/**
 * How a window should be made.
 *
 * <p>The shape {@link SplitSpec} uses, for the same reasons: a description that contacts nothing, so
 * it can be named, reused, and applied wherever it fits.
 *
 * <pre>{@code
 * Window logs = session.newWindow(w -> w.named("logs").running("journalctl", "-f"));
 * }</pre>
 */
public final class WindowSpec {

    private final @Nullable String name;
    private final @Nullable Path directory;
    private final Map<String, String> environment;
    private final boolean detached;
    private final @Nullable WindowPlacement placement;
    private final @Nullable Integer index;
    private final boolean replaceExisting;
    private final boolean reuseExisting;
    private final List<String> command;

    private WindowSpec(Builder builder) {
        this.name = builder.name;
        this.directory = builder.directory;
        this.environment = Collections.unmodifiableMap(new LinkedHashMap<>(builder.environment));
        this.detached = builder.detached;
        this.placement = builder.placement;
        this.index = builder.index;
        this.replaceExisting = builder.replaceExisting;
        this.reuseExisting = builder.reuseExisting;
        this.command = List.copyOf(builder.command);
    }

    /** A builder holding tmux's own defaults: a detached window at the end, running a shell. */
    public static Builder builder() {
        return new Builder();
    }

    /** The name the window is created with, or empty to let tmux choose. */
    public Optional<String> name() {
        return Optional.ofNullable(name);
    }

    /** Where the window's first pane starts, or empty to inherit. */
    public Optional<Path> directory() {
        return Optional.ofNullable(directory);
    }

    /** Variables set for the new window, in the order they were given. */
    @ReadOnly
    public Map<String, String> environment() {
        return environment;
    }

    /**
     * Whether the window is left unselected.
     *
     * <p>False by default, which is what {@code new-window} itself does.
     */
    public boolean detached() {
        return detached;
    }

    /** Where the window is inserted, or empty for tmux's own choice of index. */
    public Optional<WindowPlacement> placement() {
        return Optional.ofNullable(placement);
    }

    /** The index the window is created at, or empty for the next one tmux has free. */
    public Optional<Integer> index() {
        return Optional.ofNullable(index);
    }

    /**
     * Whether a window already at the target index is destroyed to make room.
     *
     * <p>Only means anything alongside {@link Builder#atIndex}: tmux has nothing to replace when it
     * is choosing the index itself.
     */
    public boolean replaceExisting() {
        return replaceExisting;
    }

    /** Whether a window that already carries this name is selected instead of a second being made. */
    public boolean reuseExisting() {
        return reuseExisting;
    }

    /** What the window's first pane runs, empty for the session's shell. */
    @ReadOnly
    public List<String> command() {
        return command;
    }

    /**
     * The command that makes this window, reporting it through {@code format}.
     *
     * @param target the session, or the index, to create in
     * @param format the row format the caller will read the result back with
     */
    List<String> argv(String target, String format) {
        List<String> argv = new ArrayList<>(20);
        argv.add("new-window");
        if (detached) {
            argv.add("-d");
        }
        if (placement != null) {
            argv.add(placement.flag());
        }
        if (replaceExisting) {
            argv.add("-k");
        }
        if (reuseExisting) {
            argv.add("-S");
        }
        if (name != null) {
            argv.add("-n");
            argv.add(TmuxFormats.literal(name));
        }
        if (directory != null) {
            argv.add("-c");
            argv.add(TmuxFormats.literal(directory.toAbsolutePath().toString()));
        }
        for (Map.Entry<String, String> variable : environment.entrySet()) {
            argv.add("-e");
            argv.add(variable.getKey() + "=" + variable.getValue());
        }
        argv.add("-t");
        // An index makes the target a winlink rather than the session, which is what -k replaces
        // and what tmux otherwise chooses for itself.
        argv.add(index == null ? target : target + ":" + index);
        argv.add("-P");
        argv.add("-F");
        argv.add(format);
        // Last, because everything after the command belongs to the command.
        if (!command.isEmpty()) {
            argv.add("--");
            argv.addAll(command);
        }
        return List.copyOf(argv);
    }

    @Override
    public String toString() {
        return "WindowSpec[" + (name == null ? "unnamed" : name) + (placement == null ? "" : " " + placement) + "]";
    }

    /** Collects the choices, each named for what it does rather than for the field it sets. */
    public static final class Builder {

        private @Nullable String name;
        private @Nullable Path directory;
        private final Map<String, String> environment = new LinkedHashMap<>();
        private boolean detached;
        private @Nullable WindowPlacement placement;
        private @Nullable Integer index;
        private boolean replaceExisting;
        private boolean reuseExisting;
        private List<String> command = List.of();

        private Builder() {}

        /** Names the window, where tmux would otherwise name it after what runs in it. */
        public Builder named(String name) {
            this.name = Objects.requireNonNull(name, "name");
            return this;
        }

        /** Puts the window immediately after the current one. */
        public Builder after() {
            placement = WindowPlacement.AFTER;
            return this;
        }

        /** Puts the window immediately before the current one. */
        public Builder before() {
            placement = WindowPlacement.BEFORE;
            return this;
        }

        /**
         * Runs a command instead of the session's shell. tmux reports the window before the command
         * has started, so wait for its pane's command with {@link Pane#await(java.util.function.Predicate, java.time.Duration)} rather than reading it at once.
         */
        public Builder running(String... argv) {
            List<String> given = List.of(argv);
            if (given.isEmpty()) {
                throw new IllegalArgumentException("command is empty");
            }
            command = given;
            return this;
        }

        /**
         * Starts the window in this directory. A relative one resolves against this process's working
         * directory, on every release: tmux 3.2a would resolve it against the server's.
         */
        public Builder in(Path directory) {
            this.directory = Objects.requireNonNull(directory, "directory");
            return this;
        }

        /** Sets one variable in the new window's environment. */
        public Builder env(String name, String value) {
            environment.put(Objects.requireNonNull(name, "name"), Objects.requireNonNull(value, "value"));
            return this;
        }

        /** Adds several variables to the new window's environment, keeping any already set. */
        public Builder environment(Map<String, String> variables) {
            variables.forEach(this::env);
            return this;
        }

        /** Leaves the current window selected, where tmux would move to the new one. */
        public Builder detached() {
            detached = true;
            return this;
        }

        /** Creates the window at a chosen index rather than the next one tmux has free. */
        public Builder atIndex(int index) {
            if (index < 0) {
                throw new IllegalArgumentException("index is negative: " + index);
            }
            this.index = index;
            return this;
        }

        /** Destroys whatever window already sits at the index chosen by {@link #atIndex}. */
        public Builder replaceExisting() {
            replaceExisting = true;
            return this;
        }

        /**
         * Selects a window that already carries this name rather than making a second.
         *
         * <p>tmux reports nothing when it reuses one, so the answer comes from a lookup. Every other
         * creating call in this library is told what it made; this is the exception.
         */
        public Builder reuseExisting() {
            reuseExisting = true;
            return this;
        }

        /** The finished spec. */
        public WindowSpec build() {
            return new WindowSpec(this);
        }
    }
}
